UPDATE public.dictionary_words SET example_hanzi = '夜市裡有很多地攤,賣的東西很便宜。', example_pinyin = 'yè shì lǐ yǒu hěn duō dì tān, mài de dōng xi hěn pián yi。', example_vietnamese = 'Trong chợ đêm có rất nhiều quầy hàng rong, đồ bán rất rẻ.' WHERE level = 'B1' AND hanzi = '地攤' AND pinyin = 'dìtān' AND vietnamese = 'Hàng rong, vỉa hè';
UPDATE public.dictionary_words SET example_hanzi = '他在公司裡的地位很重要。', example_pinyin = 'tā zài gōng sī lǐ de dì wèi hěn zhòng yào。', example_vietnamese = 'Vị trí của anh ấy trong công ty rất quan trọng.' WHERE level = 'B1' AND hanzi = '地位' AND pinyin = 'dìwèi' AND vietnamese = 'Vị trí';
UPDATE public.dictionary_words SET example_hanzi = '這條路的地下有一個大型停車場。', example_pinyin = 'zhè tiáo lù de dì xià yǒu yí gè dà xíng tíng chē chǎng。', example_vietnamese = 'Dưới lòng đất của con đường này có một bãi đỗ xe lớn.' WHERE level = 'B1' AND hanzi = '地下' AND pinyin = 'dìxià' AND vietnamese = 'Ngầm, trong lòng đất';
UPDATE public.dictionary_words SET example_hanzi = '台灣的地形以山地為主。', example_pinyin = 'Tái wān de dì xíng yǐ shān dì wéi zhǔ。', example_vietnamese = 'Địa hình của Đài Loan chủ yếu là núi.' WHERE level = 'B1' AND hanzi = '地形' AND pinyin = 'dìxíng' AND vietnamese = 'Địa hình';
UPDATE public.dictionary_words SET example_hanzi = '她的臉上有幾點雀斑,看起來很可愛。', example_pinyin = 'tā de liǎn shang yǒu jǐ diǎn què bān, kàn qǐ lai hěn kě ài。', example_vietnamese = 'Trên mặt cô ấy có vài chấm tàn nhang, trông rất dễ thương.' WHERE level = 'B1' AND hanzi = '點' AND pinyin = 'diăn' AND vietnamese = 'Giọt, hạt, chấm';
UPDATE public.dictionary_words SET example_hanzi = '現在是下午三點,我們該出發了。', example_pinyin = 'xiàn zài shì xià wǔ sān diǎn, wǒ men gāi chū fā le。', example_vietnamese = 'Bây giờ là ba giờ chiều, chúng ta nên xuất phát rồi.' WHERE level = 'B1' AND hanzi = '點' AND pinyin = 'diăn' AND vietnamese = 'Điểm';
UPDATE public.dictionary_words SET example_hanzi = '服務生走過來問我們要點什麼菜。', example_pinyin = 'fú wù shēng zǒu guò lái wèn wǒ men yào diǎn shén me cài。', example_vietnamese = 'Nhân viên phục vụ đi tới hỏi chúng tôi muốn gọi món gì.' WHERE level = 'B1' AND hanzi = '點' AND pinyin = 'diăn' AND vietnamese = 'Ít, chút ít';
UPDATE public.dictionary_words SET example_hanzi = '你可以再說慢一點兒嗎?我聽不太懂。', example_pinyin = 'nǐ kě yǐ zài shuō màn yì diǎnr ma? wǒ tīng bú tài dǒng。', example_vietnamese = 'Bạn có thể nói chậm một chút nữa được không? Tôi nghe không hiểu lắm.' WHERE level = 'B1' AND hanzi = '點/點兒' AND pinyin = 'diǍn/diǍnr' AND vietnamese = 'Một chút';
UPDATE public.dictionary_words SET example_hanzi = '昨天晚上突然停電,整棟大樓都變黑了。', example_pinyin = 'zuó tiān wǎn shang tū rán tíng diàn, zhěng dòng dà lóu dōu biàn hēi le。', example_vietnamese = 'Tối qua đột nhiên mất điện, cả tòa nhà đều tối om.' WHERE level = 'B1' AND hanzi = '電' AND pinyin = 'diàn' AND vietnamese = 'Điện';
UPDATE public.dictionary_words SET example_hanzi = '這座城市的電車系統又乾淨又準時。', example_pinyin = 'zhè zuò chéng shì de diàn chē xì tǒng yòu gān jìng yòu zhǔn shí。', example_vietnamese = 'Hệ thống tàu điện của thành phố này vừa sạch sẽ vừa đúng giờ.' WHERE level = 'B1' AND hanzi = '電車' AND pinyin = 'diànchē' AND vietnamese = 'Tàu điện, xe điện';
UPDATE public.dictionary_words SET example_hanzi = '我的手機電池快沒電了,得趕快充電。', example_pinyin = 'wǒ de shǒu jī diàn chí kuài méi diàn le, děi gǎn kuài chōng diàn。', example_vietnamese = 'Pin điện thoại của tôi sắp hết rồi, phải sạc gấp thôi.' WHERE level = 'B1' AND hanzi = '電池' AND pinyin = 'diànchí' AND vietnamese = 'Pin, bình điện, ắc-quy';
UPDATE public.dictionary_words SET example_hanzi = '房間裡的電燈壞了,晚上黑漆漆的。', example_pinyin = 'fáng jiān lǐ de diàn dēng huài le, wǎn shang hēi qī qī de。', example_vietnamese = 'Đèn điện trong phòng bị hỏng, buổi tối tối om.' WHERE level = 'B1' AND hanzi = '電燈' AND pinyin = 'diàndēng' AND vietnamese = 'Đèn điện';
UPDATE public.dictionary_words SET example_hanzi = '店員很熱情地幫我介紹新產品。', example_pinyin = 'diàn yuán hěn rè qíng de bāng wǒ jiè shào xīn chǎn pǐn。', example_vietnamese = 'Nhân viên cửa hàng nhiệt tình giới thiệu cho tôi sản phẩm mới.' WHERE level = 'B1' AND hanzi = '店員' AND pinyin = 'diànyuán' AND vietnamese = 'Nhân viên cửa hàng';
UPDATE public.dictionary_words SET example_hanzi = '警方正在調查這起車禍的原因。', example_pinyin = 'jǐng fāng zhèng zài diào chá zhè qǐ chē huò de yuán yīn。', example_vietnamese = 'Cảnh sát đang điều tra nguyên nhân vụ tai nạn xe này.' WHERE level = 'B1' AND hanzi = '調查' AND pinyin = 'diàochá' AND vietnamese = 'Điều tra';
UPDATE public.dictionary_words SET example_hanzi = '我已經訂好下星期去日本的機票了。', example_pinyin = 'wǒ yǐ jīng dìng hǎo xià xīng qī qù Rì běn de jī piào le。', example_vietnamese = 'Tôi đã đặt xong vé máy bay đi Nhật Bản tuần sau rồi.' WHERE level = 'B1' AND hanzi = '訂' AND pinyin = 'dìng' AND vietnamese = 'đặt';
UPDATE public.dictionary_words SET example_hanzi = '她不小心把鑰匙丟了,只好找鎖匠開門。', example_pinyin = 'tā bù xiǎo xīn bǎ yào shi diū le, zhǐ hǎo zhǎo suǒ jiang kāi mén。', example_vietnamese = 'Cô ấy vô ý làm mất chìa khóa, đành phải tìm thợ khóa mở cửa.' WHERE level = 'B1' AND hanzi = '丟' AND pinyin = 'diū' AND vietnamese = 'Mất, thất lạc';
UPDATE public.dictionary_words SET example_hanzi = '冬天的時候,東北地區常常下大雪。', example_pinyin = 'dōng tiān de shí hou, dōng běi dì qū cháng cháng xià dà xuě。', example_vietnamese = 'Vào mùa đông, khu vực đông bắc thường có tuyết lớn.' WHERE level = 'B1' AND hanzi = '東北' AND pinyin = 'dōngběi' AND vietnamese = 'Đông bắc';
UPDATE public.dictionary_words SET example_hanzi = '太陽從東方升起,照亮了整片大地。', example_pinyin = 'tài yáng cóng dōng fāng shēng qǐ, zhào liàng le zhěng piàn dà dì。', example_vietnamese = 'Mặt trời mọc từ phương đông, chiếu sáng cả một vùng đất.' WHERE level = 'B1' AND hanzi = '東方' AND pinyin = 'dōngfāng' AND vietnamese = 'Phương Đông';
UPDATE public.dictionary_words SET example_hanzi = '這班飛機是飛往東南亞的。', example_pinyin = 'zhè bān fēi jī shì fēi wǎng dōng nán yà de。', example_vietnamese = 'Chuyến bay này bay tới Đông Nam Á.' WHERE level = 'B1' AND hanzi = '東南' AND pinyin = 'dōngnán' AND vietnamese = 'Đông nam';
UPDATE public.dictionary_words SET example_hanzi = '這個孩子才五歲就很懂事,會自己收拾玩具。', example_pinyin = 'zhè ge hái zi cái wǔ suì jiù hěn dǒng shì, huì zì jǐ shōu shi wán jù。', example_vietnamese = 'Đứa trẻ này mới năm tuổi mà đã rất hiểu chuyện, biết tự dọn đồ chơi.' WHERE level = 'B1' AND hanzi = '懂事' AND pinyin = 'dǒngshì' AND vietnamese = 'Hiểu việc';
UPDATE public.dictionary_words SET example_hanzi = '弟弟總是喜歡逗妹妹笑。', example_pinyin = 'dì di zǒng shì xǐ huan dòu mèi mei xiào。', example_vietnamese = 'Em trai luôn thích chọc cho em gái cười.' WHERE level = 'B1' AND hanzi = '逗' AND pinyin = 'dòu' AND vietnamese = 'Đùa, giỡn';
UPDATE public.dictionary_words SET example_hanzi = '媽媽今天煮了一道麻婆豆腐,又香又辣。', example_pinyin = 'mā ma jīn tiān zhǔ le yí dào má pó dòu fu, yòu xiāng yòu là。', example_vietnamese = 'Hôm nay mẹ nấu một món đậu phụ Tứ Xuyên, vừa thơm vừa cay.' WHERE level = 'B1' AND hanzi = '豆腐' AND pinyin = 'dòufu' AND vietnamese = 'Đậu phụ';
UPDATE public.dictionary_words SET example_hanzi = '台灣人早餐常常喝豆漿配油條。', example_pinyin = 'Tái wān rén zǎo cān cháng cháng hē dòu jiāng pèi yóu tiáo。', example_vietnamese = 'Người Đài Loan thường uống sữa đậu nành kèm quẩy vào bữa sáng.' WHERE level = 'B1' AND hanzi = '豆漿' AND pinyin = 'dòujiāng' AND vietnamese = 'Sữa đậu nành';
UPDATE public.dictionary_words SET example_hanzi = '越來越多的年輕人選擇搬到都市生活。', example_pinyin = 'yuè lái yuè duō de nián qīng rén xuǎn zé bān dào dū shì shēng huó。', example_vietnamese = 'Ngày càng nhiều người trẻ chọn chuyển đến đô thị sinh sống.' WHERE level = 'B1' AND hanzi = '都市' AND pinyin = 'dūshì' AND vietnamese = 'Đô thị';
UPDATE public.dictionary_words SET example_hanzi = '政府呼籲大家遠離毒品。', example_pinyin = 'zhèng fǔ hū yù dà jiā yuǎn lí dú pǐn。', example_vietnamese = 'Chính phủ kêu gọi mọi người tránh xa ma túy.' WHERE level = 'B1' AND hanzi = '毒品' AND pinyin = 'dúpĭn' AND vietnamese = 'Chất độc hại';
UPDATE public.dictionary_words SET example_hanzi = '這家餐廳的裝潢風格很獨特。', example_pinyin = 'zhè jiā cān tīng de zhuāng huáng fēng gé hěn dú tè。', example_vietnamese = 'Phong cách trang trí của nhà hàng này rất độc đáo.' WHERE level = 'B1' AND hanzi = '獨特' AND pinyin = 'dútè' AND vietnamese = 'Đặc biệt';
UPDATE public.dictionary_words SET example_hanzi = '這本小說吸引了大批讀者。', example_pinyin = 'zhè běn xiǎo shuō xī yǐn le dà pī dú zhě。', example_vietnamese = 'Cuốn tiểu thuyết này thu hút một lượng lớn độc giả.' WHERE level = 'B1' AND hanzi = '讀者' AND pinyin = 'dúzhě' AND vietnamese = 'Độc giả, người đọc';
UPDATE public.dictionary_words SET example_hanzi = '請大家仔細讀一下這段文章。', example_pinyin = 'qǐng dà jiā zǐ xì dú yí xià zhè duàn wén zhāng。', example_vietnamese = 'Mời mọi người đọc kỹ đoạn văn này.' WHERE level = 'B1' AND hanzi = '段' AND pinyin = 'duàn' AND vietnamese = 'Đoạn, quãng, khúc';
UPDATE public.dictionary_words SET example_hanzi = '桌上堆了一堆還沒整理的文件。', example_pinyin = 'zhuō shang duī le yì duī hái méi zhěng lǐ de wén jiàn。', example_vietnamese = 'Trên bàn chất một đống tài liệu chưa sắp xếp.' WHERE level = 'B1' AND hanzi = '堆' AND pinyin = 'duī' AND vietnamese = 'đống';
UPDATE public.dictionary_words SET example_hanzi = '公園裡有一對夫妻正在散步。', example_pinyin = 'gōng yuán lǐ yǒu yí duì fū qī zhèng zài sàn bù。', example_vietnamese = 'Trong công viên có một đôi vợ chồng đang đi dạo.' WHERE level = 'B1' AND hanzi = '對' AND pinyin = 'duì' AND vietnamese = 'Đối với';
UPDATE public.dictionary_words SET example_hanzi = '老師對學生一向很有耐心。', example_pinyin = 'lǎo shī duì xué sheng yí xiàng hěn yǒu nài xīn。', example_vietnamese = 'Thầy giáo luôn kiên nhẫn với học sinh.' WHERE level = 'B1' AND hanzi = '對' AND pinyin = 'duì' AND vietnamese = 'Hướng về';
UPDATE public.dictionary_words SET example_hanzi = '你把帳單金額跟收據對一下,看看有沒有錯。', example_pinyin = 'nǐ bǎ zhàng dān jīn é gēn shōu jù duì yí xià, kàn kan yǒu méi yǒu cuò。', example_vietnamese = 'Bạn đối chiếu số tiền trên hóa đơn với biên lai xem có sai không.' WHERE level = 'B1' AND hanzi = '對' AND pinyin = 'duì' AND vietnamese = 'Đối chiếu';
UPDATE public.dictionary_words SET example_hanzi = '談判的時候要先了解對方的需求。', example_pinyin = 'tán pàn de shí hou yào xiān liǎo jiě duì fāng de xū qiú。', example_vietnamese = 'Khi đàm phán cần hiểu nhu cầu của đối phương trước.' WHERE level = 'B1' AND hanzi = '對方' AND pinyin = 'duìfāng' AND vietnamese = 'Đối phương';
UPDATE public.dictionary_words SET example_hanzi = '兩國領袖透過視訊進行了一場對話。', example_pinyin = 'liǎng guó lǐng xiù tòu guò shì xùn jìn xíng le yì chǎng duì huà。', example_vietnamese = 'Lãnh đạo hai nước đã tiến hành một cuộc đối thoại qua video.' WHERE level = 'B1' AND hanzi = '對話' AND pinyin = 'duìhuà' AND vietnamese = 'Đối thoại';
UPDATE public.dictionary_words SET example_hanzi = '對了,你上次借我的書我還沒還你呢。', example_pinyin = 'duì le, nǐ shàng cì jiè wǒ de shū wǒ hái méi huán nǐ ne。', example_vietnamese = 'À đúng rồi, quyển sách bạn cho mượn lần trước tôi vẫn chưa trả lại bạn.' WHERE level = 'B1' AND hanzi = '對了' AND pinyin = 'duìle' AND vietnamese = 'Đúng rồi';
UPDATE public.dictionary_words SET example_hanzi = '這個活動的參加對象是大學生。', example_pinyin = 'zhè ge huó dòng de cān jiā duì xiàng shì dà xué shēng。', example_vietnamese = 'Đối tượng tham gia hoạt động này là sinh viên đại học.' WHERE level = 'B1' AND hanzi = '對象' AND pinyin = 'duìxiàng' AND vietnamese = 'Đối tượng';
UPDATE public.dictionary_words SET example_hanzi = '這次的失敗,多多少少跟準備不足有關。', example_pinyin = 'zhè cì de shī bài, duō duo shǎo shǎo gēn zhǔn bèi bù zú yǒu guān。', example_vietnamese = 'Thất bại lần này, ít nhiều có liên quan đến việc chuẩn bị chưa đủ.' WHERE level = 'B1' AND hanzi = '多多少少' AND pinyin = 'duōduoshăoshăo' AND vietnamese = 'Hoặc nhiều hoặc ít';
UPDATE public.dictionary_words SET example_hanzi = '你知道我當時多麼緊張嗎?', example_pinyin = 'nǐ zhī dào wǒ dāng shí duō me jǐn zhāng ma?', example_vietnamese = 'Bạn có biết lúc đó tôi căng thẳng biết bao không?' WHERE level = 'B1' AND hanzi = '多麼' AND pinyin = 'duōme' AND vietnamese = 'Bao nhiêu, biết bao';
UPDATE public.dictionary_words SET example_hanzi = '花園裡開了幾朵美麗的玫瑰。', example_pinyin = 'huā yuán lǐ kāi le jǐ duǒ měi lì de méi gui。', example_vietnamese = 'Trong vườn hoa nở vài đóa hồng xinh đẹp.' WHERE level = 'B1' AND hanzi = '朵' AND pinyin = 'duǒ' AND vietnamese = 'Đóa, đám';
UPDATE public.dictionary_words SET example_hanzi = '我們今天中午吃了一頓豐盛的午餐。', example_pinyin = 'wǒ men jīn tiān zhōng wǔ chī le yí dùn fēng shèng de wǔ cān。', example_vietnamese = 'Trưa nay chúng tôi đã ăn một bữa trưa thịnh soạn.' WHERE level = 'B1' AND hanzi = '頓' AND pinyin = 'dùn' AND vietnamese = 'Đống';
UPDATE public.dictionary_words SET example_hanzi = '嗯,我再考慮一下,明天給你答覆。', example_pinyin = 'en, wǒ zài kǎo lǜ yí xià, míng tiān gěi nǐ dá fù。', example_vietnamese = 'Ừm, để tôi suy nghĩ thêm chút, mai trả lời bạn.' WHERE level = 'B1' AND hanzi = '嗯' AND pinyin = 'en' AND vietnamese = 'ừm';
UPDATE public.dictionary_words SET example_hanzi = '這個方法簡單而有效。', example_pinyin = 'zhè ge fāng fǎ jiǎn dān ér yǒu xiào。', example_vietnamese = 'Phương pháp này đơn giản mà hiệu quả.' WHERE level = 'B1' AND hanzi = '而' AND pinyin = 'ér' AND vietnamese = 'Và';
UPDATE public.dictionary_words SET example_hanzi = '這座公園特別設計了一區兒童遊樂場。', example_pinyin = 'zhè zuò gōng yuán tè bié shè jì le yì qū ér tóng yóu lè chǎng。', example_vietnamese = 'Công viên này đặc biệt thiết kế một khu vui chơi dành cho trẻ em.' WHERE level = 'B1' AND hanzi = '兒童' AND pinyin = 'értóng' AND vietnamese = 'Nhi đồng';
UPDATE public.dictionary_words SET example_hanzi = '老師把考卷發給大家。', example_pinyin = 'lǎo shī bǎ kǎo juàn fā gěi dà jiā。', example_vietnamese = 'Thầy giáo phát bài kiểm tra cho mọi người.' WHERE level = 'B1' AND hanzi = '發' AND pinyin = 'fā' AND vietnamese = 'phát ra';
UPDATE public.dictionary_words SET example_hanzi = '他明天要在會議上發表一篇論文。', example_pinyin = 'tā míng tiān yào zài huì yì shang fā biǎo yì piān lùn wén。', example_vietnamese = 'Ngày mai anh ấy sẽ trình bày một bài luận văn tại hội nghị.' WHERE level = 'B1' AND hanzi = '發表' AND pinyin = 'fābiăo' AND vietnamese = 'Phát biểu';
UPDATE public.dictionary_words SET example_hanzi = '過年的時候大家都會說「恭喜發財」。', example_pinyin = 'guò nián de shí hou dà jiā dōu huì shuō “gōng xǐ fā cái”。', example_vietnamese = 'Vào dịp Tết mọi người đều nói "chúc phát tài".' WHERE level = 'B1' AND hanzi = '發財' AND pinyin = 'fācái' AND vietnamese = 'Phát tài';
UPDATE public.dictionary_words SET example_hanzi = '這台機器突然發出奇怪的聲音。', example_pinyin = 'zhè tái jī qì tū rán fā chū qí guài de shēng yīn。', example_vietnamese = 'Cái máy này đột nhiên phát ra âm thanh kỳ lạ.' WHERE level = 'B1' AND hanzi = '發出' AND pinyin = 'fāchū' AND vietnamese = 'Phát sinh';
UPDATE public.dictionary_words SET example_hanzi = '這個地區的科技產業非常發達。', example_pinyin = 'zhè ge dì qū de kē jì chǎn yè fēi cháng fā dá。', example_vietnamese = 'Ngành công nghiệp công nghệ của khu vực này rất phát đạt.' WHERE level = 'B1' AND hanzi = '發達' AND pinyin = 'fādá' AND vietnamese = 'Phát đạt';
UPDATE public.dictionary_words SET example_hanzi = '教練希望球員能在比賽中發揮實力。', example_pinyin = 'jiào liàn xī wàng qiú yuán néng zài bǐ sài zhōng fā huī shí lì。', example_vietnamese = 'Huấn luyện viên hy vọng cầu thủ có thể phát huy thực lực trong trận đấu.' WHERE level = 'B1' AND hanzi = '發揮' AND pinyin = 'fāhuī' AND vietnamese = 'Phát huy';
UPDATE public.dictionary_words SET example_hanzi = '我後來才發覺自己弄錯了時間。', example_pinyin = 'wǒ hòu lái cái fā jué zì jǐ nòng cuò le shí jiān。', example_vietnamese = 'Sau đó tôi mới phát hiện ra mình đã nhầm giờ.' WHERE level = 'B1' AND hanzi = '發覺' AND pinyin = 'fājué' AND vietnamese = 'Phát giác';
UPDATE public.dictionary_words SET example_hanzi = '電話是一項改變世界的偉大發明。', example_pinyin = 'diàn huà shì yí xiàng gǎi biàn shì jiè de wěi dà fā míng。', example_vietnamese = 'Điện thoại là một phát minh vĩ đại làm thay đổi thế giới.' WHERE level = 'B1' AND hanzi = '發明' AND pinyin = 'fāmíng' AND vietnamese = 'Phát minh';
UPDATE public.dictionary_words SET example_hanzi = '這位科學家發明了一種新型電池。', example_pinyin = 'zhè wèi kē xué jiā fā míng le yì zhǒng xīn xíng diàn chí。', example_vietnamese = 'Nhà khoa học này đã sáng chế ra một loại pin kiểu mới.' WHERE level = 'B1' AND hanzi = '發明' AND pinyin = 'fāmíng' AND vietnamese = 'Sáng chế';
UPDATE public.dictionary_words SET example_hanzi = '他一遇到不順心的事就愛發脾氣。', example_pinyin = 'tā yí yù dào bú shùn xīn de shì jiù ài fā pí qi。', example_vietnamese = 'Anh ấy hễ gặp chuyện không vừa ý là hay nổi nóng.' WHERE level = 'B1' AND hanzi = '發脾氣' AND pinyin = 'fāpíqi' AND vietnamese = 'Nổi nóng';
UPDATE public.dictionary_words SET example_hanzi = '買東西的時候記得跟店員拿發票。', example_pinyin = 'mǎi dōng xi de shí hou jì de gēn diàn yuán ná fā piào。', example_vietnamese = 'Khi mua đồ nhớ lấy hóa đơn từ nhân viên bán hàng.' WHERE level = 'B1' AND hanzi = '發票' AND pinyin = 'fāpiào' AND vietnamese = 'Hóa đơn';
UPDATE public.dictionary_words SET example_hanzi = '每個人都應該遵守法律。', example_pinyin = 'měi gè rén dōu yīng gāi zūn shǒu fǎ lǜ。', example_vietnamese = 'Mỗi người đều nên tuân thủ pháp luật.' WHERE level = 'B1' AND hanzi = '法律' AND pinyin = 'fălǜ' AND vietnamese = 'Pháp luật';
UPDATE public.dictionary_words SET example_hanzi = '他隨手把書翻到最後一頁。', example_pinyin = 'tā suí shǒu bǎ shū fān dào zuì hòu yí yè。', example_vietnamese = 'Anh ấy tiện tay lật sách đến trang cuối cùng.' WHERE level = 'B1' AND hanzi = '翻' AND pinyin = 'fān' AND vietnamese = 'Lật, đổ';
UPDATE public.dictionary_words SET example_hanzi = '這本書已經被翻譯成好幾種語言。', example_pinyin = 'zhè běn shū yǐ jīng bèi fān yì chéng hǎo jǐ zhǒng yǔ yán。', example_vietnamese = 'Cuốn sách này đã được dịch sang nhiều thứ tiếng.' WHERE level = 'B1' AND hanzi = '翻譯' AND pinyin = 'fānyì' AND vietnamese = 'Phiên dịch';
UPDATE public.dictionary_words SET example_hanzi = '最近工作上的問題讓她很煩惱。', example_pinyin = 'zuì jìn gōng zuò shàng de wèn tí ràng tā hěn fán nǎo。', example_vietnamese = 'Vấn đề công việc gần đây khiến cô ấy rất phiền não.' WHERE level = 'B1' AND hanzi = '煩惱' AND pinyin = 'fánnăo' AND vietnamese = 'Phiền não';
UPDATE public.dictionary_words SET example_hanzi = '他不但沒生氣,反而笑了出來。', example_pinyin = 'tā bú dàn méi shēng qì, fǎn ér xiào le chū lái。', example_vietnamese = 'Anh ấy không những không tức giận mà ngược lại còn cười.' WHERE level = 'B1' AND hanzi = '反而' AND pinyin = 'fănér' AND vietnamese = 'Ngược lại';
UPDATE public.dictionary_words SET example_hanzi = '觀眾對這部電影的反應非常熱烈。', example_pinyin = 'guān zhòng duì zhè bù diàn yǐng de fǎn yìng fēi cháng rè liè。', example_vietnamese = 'Phản ứng của khán giả đối với bộ phim này rất nồng nhiệt.' WHERE level = 'B1' AND hanzi = '反應' AND pinyin = 'fănyìng' AND vietnamese = 'Phản ứng';
UPDATE public.dictionary_words SET example_hanzi = '每個人都可能犯錯,重要的是知道改進。', example_pinyin = 'měi gè rén dōu kě néng fàn cuò, zhòng yào de shì zhī dào gǎi jìn。', example_vietnamese = 'Ai cũng có thể phạm sai lầm, quan trọng là biết cải thiện.' WHERE level = 'B1' AND hanzi = '犯' AND pinyin = 'fàn' AND vietnamese = 'Phạm (pháp)';
UPDATE public.dictionary_words SET example_hanzi = '這次考試的範圍是第一課到第五課。', example_pinyin = 'zhè cì kǎo shì de fàn wéi shì dì yī kè dào dì wǔ kè。', example_vietnamese = 'Phạm vi của kỳ thi lần này là từ bài một đến bài năm.' WHERE level = 'B1' AND hanzi = '範圍' AND pinyin = 'fànwéi' AND vietnamese = 'Phạm vi';
UPDATE public.dictionary_words SET example_hanzi = '在健康方面,他一直很注意飲食。', example_pinyin = 'zài jiàn kāng fāng miàn, tā yì zhí hěn zhù yì yǐn shí。', example_vietnamese = 'Về phương diện sức khỏe, anh ấy luôn chú ý đến ăn uống.' WHERE level = 'B1' AND hanzi = '方面' AND pinyin = 'fāngmiàn' AND vietnamese = 'Phương diện';
UPDATE public.dictionary_words SET example_hanzi = '每個人學習語言的方式都不一樣。', example_pinyin = 'měi gè rén xué xí yǔ yán de fāng shì dōu bù yí yàng。', example_vietnamese = 'Phương thức học ngoại ngữ của mỗi người đều khác nhau.' WHERE level = 'B1' AND hanzi = '方式' AND pinyin = 'fāngshì' AND vietnamese = 'Phương thức, cách thức';
UPDATE public.dictionary_words SET example_hanzi = '房東下個月要調漲房租。', example_pinyin = 'fáng dōng xià gè yuè yào tiáo zhǎng fáng zū。', example_vietnamese = 'Chủ nhà tháng sau sẽ tăng tiền thuê nhà.' WHERE level = 'B1' AND hanzi = '房東' AND pinyin = 'fángdōng' AND vietnamese = 'Chủ cho thuê nhà';
UPDATE public.dictionary_words SET example_hanzi = '這棟公寓的房客大多是外國留學生。', example_pinyin = 'zhè dòng gōng yù de fáng kè dà duō shì wài guó liú xué shēng。', example_vietnamese = 'Người thuê nhà của căn hộ này phần lớn là du học sinh nước ngoài.' WHERE level = 'B1' AND hanzi = '房客' AND pinyin = 'fángkè' AND vietnamese = 'Khách thuê nhà';
UPDATE public.dictionary_words SET example_hanzi = '這一帶的房屋價格這幾年漲了不少。', example_pinyin = 'zhè yí dài de fáng wū jià gé zhè jǐ nián zhǎng le bù shǎo。', example_vietnamese = 'Giá nhà ở khu vực này mấy năm nay đã tăng lên khá nhiều.' WHERE level = 'B1' AND hanzi = '房屋' AND pinyin = 'fángwū' AND vietnamese = 'Nhà, tòa nhà';
UPDATE public.dictionary_words SET example_hanzi = '記者訪問了這位得獎的作家。', example_pinyin = 'jì zhě fǎng wèn le zhè wèi dé jiǎng de zuò jiā。', example_vietnamese = 'Phóng viên đã phỏng vấn nhà văn đoạt giải này.' WHERE level = 'B1' AND hanzi = '訪問' AND pinyin = 'fǎngwèn' AND vietnamese = 'Phỏng vấn';
UPDATE public.dictionary_words SET example_hanzi = '你放心,我一定會把事情處理好。', example_pinyin = 'nǐ fàng xīn, wǒ yí dìng huì bǎ shì qing chǔ lǐ hǎo。', example_vietnamese = 'Bạn yên tâm, tôi nhất định sẽ xử lý việc đó cho tốt.' WHERE level = 'B1' AND hanzi = '放心' AND pinyin = 'fàngxīn' AND vietnamese = 'Yên tâm';
UPDATE public.dictionary_words SET example_hanzi = '這件事非我能力所及。', example_pinyin = 'zhè jiàn shì fēi wǒ néng lì suǒ jí。', example_vietnamese = 'Việc này không phải là năng lực của tôi có thể làm được.' WHERE level = 'B1' AND hanzi = '非' AND pinyin = 'fēi' AND vietnamese = 'Không phải';
UPDATE public.dictionary_words SET example_hanzi = '我們應該分清是非對錯。', example_pinyin = 'wǒ men yīng gāi fēn qīng shì fēi duì cuò。', example_vietnamese = 'Chúng ta nên phân biệt rõ đúng sai.' WHERE level = 'B1' AND hanzi = '非' AND pinyin = 'fēi' AND vietnamese = 'Sai, trái';
UPDATE public.dictionary_words SET example_hanzi = '一群鳥從天空飛過。', example_pinyin = 'yì qún niǎo cóng tiān kōng fēi guò。', example_vietnamese = 'Một đàn chim bay ngang qua bầu trời.' WHERE level = 'B1' AND hanzi = '飛' AND pinyin = 'fēi' AND vietnamese = 'Bay';
UPDATE public.dictionary_words SET example_hanzi = '這趟旅行的費用比預期高出不少。', example_pinyin = 'zhè tàng lǚ xíng de fèi yòng bǐ yù qī gāo chū bù shǎo。', example_vietnamese = 'Chi phí chuyến du lịch này cao hơn dự kiến khá nhiều.' WHERE level = 'B1' AND hanzi = '費用' AND pinyin = 'fèiyòng' AND vietnamese = 'Chi phí';
UPDATE public.dictionary_words SET example_hanzi = '他們畢業後就各自分開,很少聯絡了。', example_pinyin = 'tā men bì yè hòu jiù gè zì fēn kāi, hěn shǎo lián luò le。', example_vietnamese = 'Sau khi tốt nghiệp họ đều chia tay nhau, hiếm khi liên lạc.' WHERE level = 'B1' AND hanzi = '分開' AND pinyin = 'fēnkāi' AND vietnamese = 'Xa nhau, tách biệt';
UPDATE public.dictionary_words SET example_hanzi = '請幫我準備兩份文件。', example_pinyin = 'qǐng bāng wǒ zhǔn bèi liǎng fèn wén jiàn。', example_vietnamese = 'Xin giúp tôi chuẩn bị hai bản tài liệu.' WHERE level = 'B1' AND hanzi = '份' AND pinyin = 'fèn' AND vietnamese = 'Tách ra';
UPDATE public.dictionary_words SET example_hanzi = '我昨天寄了一封信給老朋友。', example_pinyin = 'wǒ zuó tiān jì le yì fēng xìn gěi lǎo péng you。', example_vietnamese = 'Hôm qua tôi đã gửi một bức thư cho người bạn cũ.' WHERE level = 'B1' AND hanzi = '封' AND pinyin = 'fēng' AND vietnamese = 'Phong tước';
UPDATE public.dictionary_words SET example_hanzi = '這本雜誌的內容非常豐富。', example_pinyin = 'zhè běn zá zhì de nèi róng fēi cháng fēng fù。', example_vietnamese = 'Nội dung của tạp chí này rất phong phú.' WHERE level = 'B1' AND hanzi = '豐富' AND pinyin = 'fēngfù' AND vietnamese = 'Phong phú';
UPDATE public.dictionary_words SET example_hanzi = '這位設計師的作品有很強烈的個人風格。', example_pinyin = 'zhè wèi shè jì shī de zuò pǐn yǒu hěn qiáng liè de gè rén fēng gé。', example_vietnamese = 'Tác phẩm của nhà thiết kế này có phong cách cá nhân rất mạnh mẽ.' WHERE level = 'B1' AND hanzi = '風格' AND pinyin = 'fēnggé' AND vietnamese = 'Phong cách';
UPDATE public.dictionary_words SET example_hanzi = '不同地方有不同的風俗習慣。', example_pinyin = 'bù tóng dì fang yǒu bù tóng de fēng sú xí guàn。', example_vietnamese = 'Những nơi khác nhau có phong tục tập quán khác nhau.' WHERE level = 'B1' AND hanzi = '風俗' AND pinyin = 'fēngsú' AND vietnamese = 'Phong tục';
UPDATE public.dictionary_words SET example_hanzi = '佛教在亞洲有很長的歷史。', example_pinyin = 'Fó jiào zài Yà zhōu yǒu hěn cháng de lì shǐ。', example_vietnamese = 'Phật giáo có lịch sử lâu đời ở châu Á.' WHERE level = 'B1' AND hanzi = '佛教' AND pinyin = 'Fójiào' AND vietnamese = 'Phật giáo';
UPDATE public.dictionary_words SET example_hanzi = '你得快點出門,否則會趕不上火車。', example_pinyin = 'nǐ děi kuài diǎn chū mén, fǒu zé huì gǎn bu shàng huǒ chē。', example_vietnamese = 'Bạn phải ra khỏi nhà nhanh lên, nếu không sẽ không kịp chuyến tàu.' WHERE level = 'B1' AND hanzi = '否則' AND pinyin = 'fŏuzé' AND vietnamese = 'Nếu không, bằng không thì';
UPDATE public.dictionary_words SET example_hanzi = '隔壁那對夫婦感情很好。', example_pinyin = 'gé bì nà duì fū fù gǎn qíng hěn hǎo。', example_vietnamese = 'Cặp vợ chồng nhà bên cạnh tình cảm rất tốt.' WHERE level = 'B1' AND hanzi = '夫婦' AND pinyin = 'fūfù' AND vietnamese = 'Vợ chồng';
UPDATE public.dictionary_words SET example_hanzi = '這份工作的條件完全符合我的期望。', example_pinyin = 'zhè fèn gōng zuò de tiáo jiàn wán quán fú hé wǒ de qī wàng。', example_vietnamese = 'Điều kiện của công việc này hoàn toàn phù hợp với kỳ vọng của tôi.' WHERE level = 'B1' AND hanzi = '符合' AND pinyin = 'fúhé' AND vietnamese = 'Phù hợp';
UPDATE public.dictionary_words SET example_hanzi = '這家公司的員工福利很不錯。', example_pinyin = 'zhè jiā gōng sī de yuán gōng fú lì hěn bú cuò。', example_vietnamese = 'Phúc lợi nhân viên của công ty này khá tốt.' WHERE level = 'B1' AND hanzi = '福利' AND pinyin = 'fúlì' AND vietnamese = 'phúc lợi';
UPDATE public.dictionary_words SET example_hanzi = '這場表演的服裝設計得很漂亮。', example_pinyin = 'zhè chǎng biǎo yǎn de fú zhuāng shè jì de hěn piào liang。', example_vietnamese = 'Trang phục của buổi biểu diễn này được thiết kế rất đẹp.' WHERE level = 'B1' AND hanzi = '服裝' AND pinyin = 'fúzhuāng' AND vietnamese = 'Trang phục';
UPDATE public.dictionary_words SET example_hanzi = '這個政府因為腐敗而失去人民的信任。', example_pinyin = 'zhè ge zhèng fǔ yīn wèi fǔ bài ér shī qù rén mín de xìn rèn。', example_vietnamese = 'Chính quyền này vì tha hóa mà mất đi lòng tin của người dân.' WHERE level = 'B1' AND hanzi = '腐敗' AND pinyin = 'fŭbài' AND vietnamese = 'Hủ bại, mục nát';
UPDATE public.dictionary_words SET example_hanzi = '為了這個目標,他付出了很多努力。', example_pinyin = 'wèi le zhè ge mù biāo, tā fù chū le hěn duō nǔ lì。', example_vietnamese = 'Vì mục tiêu này, anh ấy đã bỏ ra rất nhiều nỗ lực.' WHERE level = 'B1' AND hanzi = '付出' AND pinyin = 'fùchū' AND vietnamese = 'Trả giá';
UPDATE public.dictionary_words SET example_hanzi = '高額的學費成了家裡沉重的負擔。', example_pinyin = 'gāo é de xué fèi chéng le jiā lǐ chén zhòng de fù dān。', example_vietnamese = 'Học phí cao trở thành gánh nặng đè nặng cho gia đình.' WHERE level = 'B1' AND hanzi = '負擔' AND pinyin = 'fùdān' AND vietnamese = 'Gánh nặng';
UPDATE public.dictionary_words SET example_hanzi = '這筆費用由公司負擔。', example_pinyin = 'zhè bǐ fèi yòng yóu gōng sī fù dān。', example_vietnamese = 'Khoản chi phí này do công ty gánh chịu.' WHERE level = 'B1' AND hanzi = '負擔' AND pinyin = 'fùdān' AND vietnamese = 'Gánh vác, đảm nhiệm';
UPDATE public.dictionary_words SET example_hanzi = '這個專案由他負責。', example_pinyin = 'zhè ge zhuān àn yóu tā fù zé。', example_vietnamese = 'Dự án này do anh ấy phụ trách.' WHERE level = 'B1' AND hanzi = '負責' AND pinyin = 'fùzé' AND vietnamese = 'Chịu trách nhiệm';
UPDATE public.dictionary_words SET example_hanzi = '考試前一定要好好複習。', example_pinyin = 'kǎo shì qián yí dìng yào hǎo hǎo fù xí。', example_vietnamese = 'Trước khi thi nhất định phải ôn tập cho kỹ.' WHERE level = 'B1' AND hanzi = '複習' AND pinyin = 'fùxí' AND vietnamese = 'Ôn tập';
UPDATE public.dictionary_words SET example_hanzi = '時間不早了,我們該回家了。', example_pinyin = 'shí jiān bù zǎo le, wǒ men gāi huí jiā le。', example_vietnamese = 'Muộn rồi, chúng ta nên về nhà thôi.' WHERE level = 'B1' AND hanzi = '該' AND pinyin = 'gāi' AND vietnamese = 'Nên';
UPDATE public.dictionary_words SET example_hanzi = '老師把我作文裡的錯字都改過來了。', example_pinyin = 'lǎo shī bǎ wǒ zuò wén lǐ de cuò zì dōu gǎi guò lái le。', example_vietnamese = 'Thầy giáo đã sửa hết những chữ sai trong bài văn của tôi.' WHERE level = 'B1' AND hanzi = '改' AND pinyin = 'gǎi' AND vietnamese = 'Thay đổi';
UPDATE public.dictionary_words SET example_hanzi = '這幾年城市的樣貌有了很大的改變。', example_pinyin = 'zhè jǐ nián chéng shì de yàng mào yǒu le hěn dà de gǎi biàn。', example_vietnamese = 'Mấy năm nay diện mạo của thành phố đã có sự thay đổi lớn.' WHERE level = 'B1' AND hanzi = '改變' AND pinyin = 'gǎibiàn' AND vietnamese = 'Biến động, biến đổi';
UPDATE public.dictionary_words SET example_hanzi = '一場大病改變了他對人生的看法。', example_pinyin = 'yì chǎng dà bìng gǎi biàn le tā duì rén shēng de kàn fǎ。', example_vietnamese = 'Một trận ốm nặng đã thay đổi cách nhìn của anh ấy về cuộc sống.' WHERE level = 'B1' AND hanzi = '改變' AND pinyin = 'gǎibiàn' AND vietnamese = 'Cải biên, sửa đổi';
UPDATE public.dictionary_words SET example_hanzi = '公司決定改進產品的品質。', example_pinyin = 'gōng sī jué dìng gǎi jìn chǎn pǐn de pǐn zhí。', example_vietnamese = 'Công ty quyết định cải tiến chất lượng sản phẩm.' WHERE level = 'B1' AND hanzi = '改進' AND pinyin = 'găijìn' AND vietnamese = 'Cải tiến';
UPDATE public.dictionary_words SET example_hanzi = '政府努力改善交通狀況。', example_pinyin = 'zhèng fǔ nǔ lì gǎi shàn jiāo tōng zhuàng kuàng。', example_vietnamese = 'Chính phủ nỗ lực cải thiện tình hình giao thông.' WHERE level = 'B1' AND hanzi = '改善' AND pinyin = 'găishàn' AND vietnamese = 'Cải thiện';
UPDATE public.dictionary_words SET example_hanzi = '今天有點忙,我們改天再約吧。', example_pinyin = 'jīn tiān yǒu diǎn máng, wǒ men gǎi tiān zài yuē ba。', example_vietnamese = 'Hôm nay hơi bận, chúng ta hẹn ngày khác nhé.' WHERE level = 'B1' AND hanzi = '改天' AND pinyin = 'găitiān' AND vietnamese = 'Ngày khác, hôm khác';
UPDATE public.dictionary_words SET example_hanzi = '他們準備在山上蓋一棟小木屋。', example_pinyin = 'tā men zhǔn bèi zài shān shàng gài yí dòng xiǎo mù wū。', example_vietnamese = 'Họ chuẩn bị xây một ngôi nhà gỗ nhỏ trên núi.' WHERE level = 'B1' AND hanzi = '蓋' AND pinyin = 'gài' AND vietnamese = 'Nắp, vung';
UPDATE public.dictionary_words SET example_hanzi = '這個理論對很多人來說是個新概念。', example_pinyin = 'zhè ge lǐ lùn duì hěn duō rén lái shuō shì gè xīn gài niàn。', example_vietnamese = 'Lý thuyết này là một khái niệm mới đối với nhiều người.' WHERE level = 'B1' AND hanzi = '概念' AND pinyin = 'gàiniàn' AND vietnamese = 'Khái niệm';
UPDATE public.dictionary_words SET example_hanzi = '他不敢一個人走夜路。', example_pinyin = 'tā bù gǎn yí gè rén zǒu yè lù。', example_vietnamese = 'Anh ấy không dám đi một mình vào ban đêm.' WHERE level = 'B1' AND hanzi = '敢' AND pinyin = 'gǎn' AND vietnamese = 'Dám';
UPDATE public.dictionary_words SET example_hanzi = '我得趕在下班前把報告寫完。', example_pinyin = 'wǒ děi gǎn zài xià bān qián bǎ bào gào xiě wán。', example_vietnamese = 'Tôi phải gấp rút viết xong báo cáo trước khi tan làm.' WHERE level = 'B1' AND hanzi = '趕' AND pinyin = 'găn' AND vietnamese = 'Đuổi theo, gấp, vội vàng';
UPDATE public.dictionary_words SET example_hanzi = '快遲到了,你趕快出門吧!', example_pinyin = 'kuài chí dào le, nǐ gǎn kuài chū mén ba!', example_vietnamese = 'Sắp muộn rồi, bạn ra khỏi nhà nhanh lên đi!' WHERE level = 'B1' AND hanzi = '趕快' AND pinyin = 'gǎnkuài' AND vietnamese = 'Khẩn trương, vội vã';
UPDATE public.dictionary_words SET example_hanzi = '我們跑得很快,終於趕上了公車。', example_pinyin = 'wǒ men pǎo de hěn kuài, zhōng yú gǎn shàng le gōng chē。', example_vietnamese = 'Chúng tôi chạy rất nhanh, cuối cùng đã kịp lên xe buýt.' WHERE level = 'B1' AND hanzi = '趕上' AND pinyin = 'gănshàng' AND vietnamese = 'Đuổi kịp';
UPDATE public.dictionary_words SET example_hanzi = '這部電影的結局讓很多觀眾感動得流淚。', example_pinyin = 'zhè bù diàn yǐng de jié jú ràng hěn duō guān zhòng gǎn dòng de liú lèi。', example_vietnamese = 'Cái kết của bộ phim này khiến nhiều khán giả cảm động đến rơi nước mắt.' WHERE level = 'B1' AND hanzi = '感動' AND pinyin = 'găndòng' AND vietnamese = 'Cảm động, xúc động';
UPDATE public.dictionary_words SET example_hanzi = '看完這場演講,你有什麼感想?', example_pinyin = 'kàn wán zhè chǎng yǎn jiǎng, nǐ yǒu shén me gǎn xiǎng?', example_vietnamese = 'Xem xong buổi diễn thuyết này, bạn có cảm tưởng gì?' WHERE level = 'B1' AND hanzi = '感想' AND pinyin = 'gănxiăng' AND vietnamese = 'Cảm tưởng, cảm nghĩ';
UPDATE public.dictionary_words SET example_hanzi = '我對學習中文一直很感興趣。', example_pinyin = 'wǒ duì xué xí Zhōng wén yì zhí hěn gǎn xìng qù。', example_vietnamese = 'Tôi luôn có hứng thú với việc học tiếng Trung.' WHERE level = 'B1' AND hanzi = '感興趣' AND pinyin = 'gănxìngqù' AND vietnamese = 'Có hứng thú với';
UPDATE public.dictionary_words SET example_hanzi = '我剛到公司,還沒開始工作。', example_pinyin = 'wǒ gāng dào gōng sī, hái méi kāi shǐ gōng zuò。', example_vietnamese = 'Tôi vừa mới đến công ty, chưa bắt đầu làm việc.' WHERE level = 'B1' AND hanzi = '剛' AND pinyin = 'gāng' AND vietnamese = 'Chỉ vừa, vừa mới';
UPDATE public.dictionary_words SET example_hanzi = '我們開上高速公路後,大概一小時就能到。', example_pinyin = 'wǒ men kāi shàng gāo sù gōng lù hòu, dà gài yì xiǎo shí jiù néng dào。', example_vietnamese = 'Sau khi chúng tôi lên đường cao tốc, khoảng một tiếng là đến nơi.' WHERE level = 'B1' AND hanzi = '高速' AND pinyin = 'gāosù' AND vietnamese = 'Cao tốc, cực nhanh';
UPDATE public.dictionary_words SET example_hanzi = '我妹妹今年剛上高中。', example_pinyin = 'wǒ mèi mei jīn nián gāng shàng gāo zhōng。', example_vietnamese = 'Em gái tôi năm nay vừa vào cấp ba.' WHERE level = 'B1' AND hanzi = '高中' AND pinyin = 'gāozhōng' AND vietnamese = 'Cấp 3, trung học phổ thông';
UPDATE public.dictionary_words SET example_hanzi = '你到底在搞什麼,怎麼弄得亂七八糟的?', example_pinyin = 'nǐ dào dǐ zài gǎo shén me, zěn me nòng de luàn qī bā zāo de?', example_vietnamese = 'Rốt cuộc bạn đang làm gì thế, sao lại làm rối tung lên vậy?' WHERE level = 'B1' AND hanzi = '搞' AND pinyin = 'găo' AND vietnamese = 'Làm, tạo ra';
UPDATE public.dictionary_words SET example_hanzi = '這首歌曲的旋律很好聽。', example_pinyin = 'zhè shǒu gē qǔ de xuán lǜ hěn hǎo tīng。', example_vietnamese = 'Giai điệu của ca khúc này rất hay.' WHERE level = 'B1' AND hanzi = '歌曲' AND pinyin = 'gēqŭ' AND vietnamese = 'Ca khúc, bài hát';
UPDATE public.dictionary_words SET example_hanzi = '這位歌星昨天在台北開了演唱會。', example_pinyin = 'zhè wèi gē xīng zuó tiān zài Tái běi kāi le yǎn chàng huì。', example_vietnamese = 'Ngôi sao ca nhạc này hôm qua đã tổ chức buổi hòa nhạc tại Đài Bắc.' WHERE level = 'B1' AND hanzi = '歌星' AND pinyin = 'gēxīng' AND vietnamese = 'Ngôi sao ca nhạc';
UPDATE public.dictionary_words SET example_hanzi = '隔壁新搬來一戶人家。', example_pinyin = 'gé bì xīn bān lái yí hù rén jiā。', example_vietnamese = 'Nhà bên cạnh mới chuyển đến một hộ gia đình.' WHERE level = 'B1' AND hanzi = '隔壁' AND pinyin = 'gébì' AND vietnamese = 'Sát vách, bên cạnh';
UPDATE public.dictionary_words SET example_hanzi = '這項新技術可以說是為整個產業帶來了革命。', example_pinyin = 'zhè xiàng xīn jì shù kě yǐ shuō shì wèi zhěng gè chǎn yè dài lái le gé mìng。', example_vietnamese = 'Công nghệ mới này có thể nói là đã mang lại một cuộc cách mạng cho toàn ngành.' WHERE level = 'B1' AND hanzi = '革命' AND pinyin = 'gémìng' AND vietnamese = 'Cách mạng';
UPDATE public.dictionary_words SET example_hanzi = '這只是我個人的看法,僅供參考。', example_pinyin = 'zhè zhǐ shì wǒ gè rén de kàn fǎ, jǐn gōng cān kǎo。', example_vietnamese = 'Đây chỉ là ý kiến cá nhân của tôi, chỉ để tham khảo.' WHERE level = 'B1' AND hanzi = '個人' AND pinyin = 'gèrén' AND vietnamese = 'Cá nhân';
UPDATE public.dictionary_words SET example_hanzi = '他個子很高,打籃球很有優勢。', example_pinyin = 'tā gè zi hěn gāo, dǎ lán qiú hěn yǒu yōu shì。', example_vietnamese = 'Anh ấy vóc dáng rất cao, chơi bóng rổ rất có lợi thế.' WHERE level = 'B1' AND hanzi = '個子/個兒' AND pinyin = 'gèzi/gèr' AND vietnamese = 'Vóc dáng, vóc người';
UPDATE public.dictionary_words SET example_hanzi = '夜市裡賣著各式各樣的小吃。', example_pinyin = 'yè shì lǐ mài zhe gè shì gè yàng de xiǎo chī。', example_vietnamese = 'Trong chợ đêm bán đủ loại đồ ăn vặt.' WHERE level = 'B1' AND hanzi = '各式各樣' AND pinyin = 'gèshìgèyàng' AND vietnamese = 'Đủ kiểu đủ loại';
UPDATE public.dictionary_words SET example_hanzi = '各位觀眾,晚安!歡迎收看今天的新聞。', example_pinyin = 'gè wèi guān zhòng, wǎn ān! huān yíng shōu kàn jīn tiān de xīn wén。', example_vietnamese = 'Kính chào quý khán giả! Chào mừng theo dõi bản tin hôm nay.' WHERE level = 'B1' AND hanzi = '各位' AND pinyin = 'gèwèi' AND vietnamese = 'Các vị, mọi người';
UPDATE public.dictionary_words SET example_hanzi = '桌上放著一個蘋果。', example_pinyin = 'zhuō shang fàng zhe yí ge píng guǒ。', example_vietnamese = 'Trên bàn để một quả táo.' WHERE level = 'B1' AND hanzi = '個' AND pinyin = 'ge' AND vietnamese = 'Cái';
UPDATE public.dictionary_words SET example_hanzi = '我買了一份禮物給媽媽。', example_pinyin = 'wǒ mǎi le yí fèn lǐ wù gěi mā ma。', example_vietnamese = 'Tôi đã mua một món quà cho mẹ.' WHERE level = 'B1' AND hanzi = '給' AND pinyin = 'gěi' AND vietnamese = 'Cho, cung cấp';
UPDATE public.dictionary_words SET example_hanzi = '我週末常跟朋友去爬山。', example_pinyin = 'wǒ zhōu mò cháng gēn péng you qù pá shān。', example_vietnamese = 'Cuối tuần tôi thường cùng bạn bè đi leo núi.' WHERE level = 'B1' AND hanzi = '跟' AND pinyin = 'gēn' AND vietnamese = 'Với, cùng với';
UPDATE public.dictionary_words SET example_hanzi = '小狗一直跟在主人後面。', example_pinyin = 'xiǎo gǒu yì zhí gēn zài zhǔ rén hòu miàn。', example_vietnamese = 'Chú chó nhỏ luôn đi theo sau chủ.' WHERE level = 'B1' AND hanzi = '跟' AND pinyin = 'gēn' AND vietnamese = 'Đi theo';
UPDATE public.dictionary_words SET example_hanzi = '她發現頭上多了一根白頭髮。', example_pinyin = 'tā fā xiàn tóu shàng duō le yì gēn bái tóu fa。', example_vietnamese = 'Cô ấy phát hiện trên đầu có thêm một sợi tóc bạc.' WHERE level = 'B1' AND hanzi = '根' AND pinyin = 'gēn' AND vietnamese = 'Cuống, gốc';
UPDATE public.dictionary_words SET example_hanzi = '這棵大樹的根扎得很深。', example_pinyin = 'zhè kē dà shù de gēn zhā de hěn shēn。', example_vietnamese = 'Rễ của cây to này cắm rất sâu.' WHERE level = 'B1' AND hanzi = '根' AND pinyin = 'gēn' AND vietnamese = 'Rễ, rễ cây';
UPDATE public.dictionary_words SET example_hanzi = '根據天氣預報,明天會下雨。', example_pinyin = 'gēn jù tiān qì yù bào, míng tiān huì xià yǔ。', example_vietnamese = 'Căn cứ theo dự báo thời tiết, ngày mai sẽ có mưa.' WHERE level = 'B1' AND hanzi = '根據' AND pinyin = 'gēnjù' AND vietnamese = 'Căn cứ vào, dựa vào';
UPDATE public.dictionary_words SET example_hanzi = '有了大家的幫忙,工作進行得更加順利。', example_pinyin = 'yǒu le dà jiā de bāng máng, gōng zuò jìn xíng de gèng jiā shùn lì。', example_vietnamese = 'Có sự giúp đỡ của mọi người, công việc tiến hành càng thêm suôn sẻ.' WHERE level = 'B1' AND hanzi = '更加' AND pinyin = 'gèngjiā' AND vietnamese = 'Hơn nữa, thêm';
UPDATE public.dictionary_words SET example_hanzi = '這座橋長約三百公尺。', example_pinyin = 'zhè zuò qiáo cháng yuē sān bǎi gōng chǐ。', example_vietnamese = 'Cây cầu này dài khoảng ba trăm mét.' WHERE level = 'B1' AND hanzi = '公尺' AND pinyin = 'gōngchĭ' AND vietnamese = 'Mét (đơn vị chiều dài)';
UPDATE public.dictionary_words SET example_hanzi = '這張桌子高七十五公分。', example_pinyin = 'zhè zhāng zhuō zi gāo qī shí wǔ gōng fēn。', example_vietnamese = 'Chiếc bàn này cao bảy mươi lăm xen-ti-mét.' WHERE level = 'B1' AND hanzi = '公分' AND pinyin = 'gōngfēn' AND vietnamese = 'Cen-ti-mét';
UPDATE public.dictionary_words SET example_hanzi = '這裡是公共場所,請不要大聲喧嘩。', example_pinyin = 'zhè lǐ shì gōng gòng chǎng suǒ, qǐng bú yào dà shēng xuān huá。', example_vietnamese = 'Đây là nơi công cộng, xin đừng gây ồn ào.' WHERE level = 'B1' AND hanzi = '公共' AND pinyin = 'gōnggòng' AND vietnamese = 'Công cộng';
UPDATE public.dictionary_words SET example_hanzi = '這包糖重五百公克。', example_pinyin = 'zhè bāo táng zhòng wǔ bǎi gōng kè。', example_vietnamese = 'Gói đường này nặng năm trăm gam.' WHERE level = 'B1' AND hanzi = '公克' AND pinyin = 'gōngkè' AND vietnamese = 'Gram';
UPDATE public.dictionary_words SET example_hanzi = '這條公路連接了南北兩座城市。', example_pinyin = 'zhè tiáo gōng lù lián jiē le nán běi liǎng zuò chéng shì。', example_vietnamese = 'Con đường quốc lộ này nối liền hai thành phố nam bắc.' WHERE level = 'B1' AND hanzi = '公路' AND pinyin = 'gōnglù' AND vietnamese = 'Đường cái, quốc lộ';
UPDATE public.dictionary_words SET example_hanzi = '他花了不少功夫才把這篇報告寫好。', example_pinyin = 'tā huā le bù shǎo gōng fu cái bǎ zhè piān bào gào xiě hǎo。', example_vietnamese = 'Anh ấy đã bỏ ra không ít công sức mới viết xong bản báo cáo này.' WHERE level = 'B1' AND hanzi = '功夫' AND pinyin = 'gōngfu' AND vietnamese = 'Bản lĩnh, công sức';
UPDATE public.dictionary_words SET example_hanzi = '這支手機的相機功能很強大。', example_pinyin = 'zhè zhī shǒu jī de xiàng jī gōng néng hěn qiáng dà。', example_vietnamese = 'Chức năng máy ảnh của chiếc điện thoại này rất mạnh.' WHERE level = 'B1' AND hanzi = '功能' AND pinyin = 'gōngnéng' AND vietnamese = 'Công năng, tác dụng';
UPDATE public.dictionary_words SET example_hanzi = '電腦已經成為現代人工作不可或缺的工具。', example_pinyin = 'diàn nǎo yǐ jīng chéng wéi xiàn dài rén gōng zuò bù kě huò quē de gōng jù。', example_vietnamese = 'Máy tính đã trở thành công cụ không thể thiếu trong công việc của người hiện đại.' WHERE level = 'B1' AND hanzi = '工具' AND pinyin = 'gōngjù' AND vietnamese = 'Công cụ';
UPDATE public.dictionary_words SET example_hanzi = '這個城市早期以重工業為主。', example_pinyin = 'zhè ge chéng shì zǎo qī yǐ zhòng gōng yè wéi zhǔ。', example_vietnamese = 'Thành phố này thời kỳ đầu chủ yếu là công nghiệp nặng.' WHERE level = 'B1' AND hanzi = '工業' AND pinyin = 'gōngyè' AND vietnamese = 'Công nghiệp';
UPDATE public.dictionary_words SET example_hanzi = '他每天工作到很晚才回家。', example_pinyin = 'tā měi tiān gōng zuò dào hěn wǎn cái huí jiā。', example_vietnamese = 'Hằng ngày anh ấy làm việc đến rất muộn mới về nhà.' WHERE level = 'B1' AND hanzi = '工作' AND pinyin = 'gōngzuò' AND vietnamese = 'Công việc';
UPDATE public.dictionary_words SET example_hanzi = '恭喜你順利通過考試!', example_pinyin = 'gōng xǐ nǐ shùn lì tōng guò kǎo shì!', example_vietnamese = 'Chúc mừng bạn đã vượt qua kỳ thi thuận lợi!' WHERE level = 'B1' AND hanzi = '恭喜' AND pinyin = 'gōngxǐ' AND vietnamese = 'Chúc mừng';
UPDATE public.dictionary_words SET example_hanzi = '這次旅行我們一共花了三萬元。', example_pinyin = 'zhè cì lǚ xíng wǒ men yí gòng huā le sān wàn yuán。', example_vietnamese = 'Chuyến du lịch này chúng tôi tổng cộng đã tiêu ba mươi nghìn tệ.' WHERE level = 'B1' AND hanzi = '共' AND pinyin = 'gòng' AND vietnamese = 'Chung, cùng nhau';
UPDATE public.dictionary_words SET example_hanzi = '保護環境是大家共同的責任。', example_pinyin = 'bǎo hù huán jìng shì dà jiā gòng tóng de zé rèn。', example_vietnamese = 'Bảo vệ môi trường là trách nhiệm chung của mọi người.' WHERE level = 'B1' AND hanzi = '共同' AND pinyin = 'gòngtóng' AND vietnamese = 'Cộng đồng, chung';
UPDATE public.dictionary_words SET example_hanzi = '他對這個社會做出了很大的貢獻。', example_pinyin = 'tā duì zhè ge shè huì zuò chū le hěn dà de gòng xiàn。', example_vietnamese = 'Anh ấy đã có những cống hiến to lớn cho xã hội này.' WHERE level = 'B1' AND hanzi = '貢獻' AND pinyin = 'gòngxiàn' AND vietnamese = 'Cống hiến, sự đóng góp';
UPDATE public.dictionary_words SET example_hanzi = '他把一生都貢獻給了教育事業。', example_pinyin = 'tā bǎ yì shēng dōu gòng xiàn gěi le jiào yù shì yè。', example_vietnamese = 'Anh ấy đã cống hiến cả cuộc đời cho sự nghiệp giáo dục.' WHERE level = 'B1' AND hanzi = '貢獻' AND pinyin = 'gòngxiàn' AND vietnamese = 'Cống hiến';
UPDATE public.dictionary_words SET example_hanzi = '遇到問題時,雙方應該好好溝通。', example_pinyin = 'yù dào wèn tí shí, shuāng fāng yīng gāi hǎo hǎo gōu tōng。', example_vietnamese = 'Khi gặp vấn đề, hai bên nên giao tiếp với nhau cho tốt.' WHERE level = 'B1' AND hanzi = '溝通' AND pinyin = 'gōutōng' AND vietnamese = 'Trao đổi, giao tiếp';
UPDATE public.dictionary_words SET example_hanzi = '這些錢應該夠我們付房租了。', example_pinyin = 'zhè xiē qián yīng gāi gòu wǒ men fù fáng zū le。', example_vietnamese = 'Số tiền này chắc đủ để chúng ta trả tiền thuê nhà rồi.' WHERE level = 'B1' AND hanzi = '夠' AND pinyin = 'gòu' AND vietnamese = 'Đủ, đầy đủ';
UPDATE public.dictionary_words SET example_hanzi = '越來越多人選擇在網路上購買日用品。', example_pinyin = 'yuè lái yuè duō rén xuǎn zé zài wǎng lù shàng gòu mǎi rì yòng pǐn。', example_vietnamese = 'Ngày càng nhiều người chọn mua đồ dùng hàng ngày trên mạng.' WHERE level = 'B1' AND hanzi = '購買' AND pinyin = 'gòumăi' AND vietnamese = 'Mua, mua sắm';
UPDATE public.dictionary_words SET example_hanzi = '那位姑娘穿著一件紅色的洋裝。', example_pinyin = 'nà wèi gū niáng chuān zhe yí jiàn hóng sè de yáng zhuāng。', example_vietnamese = 'Cô gái đó mặc một chiếc váy đầm màu đỏ.' WHERE level = 'B1' AND hanzi = '姑娘' AND pinyin = 'gūniáng' AND vietnamese = 'Cô gái';
UPDATE public.dictionary_words SET example_hanzi = '這座古城已經有一千多年的歷史。', example_pinyin = 'zhè zuò gǔ chéng yǐ jīng yǒu yì qiān duō nián de lì shǐ。', example_vietnamese = 'Thành cổ này đã có lịch sử hơn một nghìn năm.' WHERE level = 'B1' AND hanzi = '古' AND pinyin = 'gŭ' AND vietnamese = 'Cổ, cổ xưa';
UPDATE public.dictionary_words SET example_hanzi = '古代的人沒有手機,靠寫信聯絡。', example_pinyin = 'gǔ dài de rén méi yǒu shǒu jī, kào xiě xìn lián luò。', example_vietnamese = 'Người thời cổ đại không có điện thoại, phải viết thư để liên lạc.' WHERE level = 'B1' AND hanzi = '古代' AND pinyin = 'gŭdài' AND vietnamese = 'Cổ đại';
UPDATE public.dictionary_words SET example_hanzi = '這座城市保存了不少歷史古蹟。', example_pinyin = 'zhè zuò chéng shì bǎo cún le bù shǎo lì shǐ gǔ jī。', example_vietnamese = 'Thành phố này còn lưu giữ khá nhiều di tích lịch sử.' WHERE level = 'B1' AND hanzi = '古蹟' AND pinyin = 'gŭjī' AND vietnamese = 'Cổ tích';
UPDATE public.dictionary_words SET example_hanzi = '村子裡有一棵古老的大樹。', example_pinyin = 'cūn zi lǐ yǒu yì kē gǔ lǎo de dà shù。', example_vietnamese = 'Trong làng có một cây cổ thụ lâu năm.' WHERE level = 'B1' AND hanzi = '古老' AND pinyin = 'gŭlăo' AND vietnamese = 'Cổ kính, cũ xưa';
UPDATE public.dictionary_words SET example_hanzi = '他忙得連吃飯都顧不上。', example_pinyin = 'tā máng de lián chī fàn dōu gù bu shàng。', example_vietnamese = 'Anh ấy bận đến mức ăn cơm cũng không kịp để ý.' WHERE level = 'B1' AND hanzi = '顧' AND pinyin = 'gù' AND vietnamese = 'Ngoảnh lại nhìn';
UPDATE public.dictionary_words SET example_hanzi = '對不起,我不是故意要弄壞你的東西。', example_pinyin = 'duì bu qǐ, wǒ bú shì gù yì yào nòng huài nǐ de dōng xi。', example_vietnamese = 'Xin lỗi, tôi không cố ý làm hỏng đồ của bạn.' WHERE level = 'B1' AND hanzi = '故意' AND pinyin = 'gùyì' AND vietnamese = 'Cố ý, cố tình';
UPDATE public.dictionary_words SET example_hanzi = '他每天早上都會刮鬍子。', example_pinyin = 'tā měi tiān zǎo shang dōu huì guā hú zi。', example_vietnamese = 'Sáng nào anh ấy cũng cạo râu.' WHERE level = 'B1' AND hanzi = '刮' AND pinyin = 'guā' AND vietnamese = 'Cạo';
UPDATE public.dictionary_words SET example_hanzi = '這隻小狗很乖,從不亂叫。', example_pinyin = 'zhè zhī xiǎo gǒu hěn guāi, cóng bú luàn jiào。', example_vietnamese = 'Chú chó nhỏ này rất ngoan, chưa bao giờ sủa bậy.' WHERE level = 'B1' AND hanzi = '乖' AND pinyin = 'guāi' AND vietnamese = 'Ngoan ngoãn';
UPDATE public.dictionary_words SET example_hanzi = '這件事不能怪他,是我沒說清楚。', example_pinyin = 'zhè jiàn shì bù néng guài tā, shì wǒ méi shuō qīng chu。', example_vietnamese = 'Chuyện này không thể trách anh ấy, là tại tôi nói không rõ.' WHERE level = 'B1' AND hanzi = '怪' AND pinyin = 'guài' AND vietnamese = 'Kỳ quái';
UPDATE public.dictionary_words SET example_hanzi = '這裡的氣味有點怪。', example_pinyin = 'zhè lǐ de qì wèi yǒu diǎn guài。', example_vietnamese = 'Mùi ở đây hơi kỳ lạ.' WHERE level = 'B1' AND hanzi = '怪' AND pinyin = 'guài' AND vietnamese = 'Cực kỳ, vô cùng';
UPDATE public.dictionary_words SET example_hanzi = '出門前記得把窗戶關好。', example_pinyin = 'chū mén qián jì de bǎ chuāng hu guān hǎo。', example_vietnamese = 'Trước khi ra khỏi nhà nhớ đóng cửa sổ cho kỹ.' WHERE level = 'B1' AND hanzi = '關' AND pinyin = 'guān' AND vietnamese = 'Đóng lại, khép lại';
UPDATE public.dictionary_words SET example_hanzi = '科學家花了好幾年觀察這種鳥類的行為。', example_pinyin = 'kē xué jiā huā le hǎo jǐ nián guān chá zhè zhǒng niǎo lèi de xíng wéi。', example_vietnamese = 'Nhà khoa học đã mất mấy năm quan sát tập tính của loài chim này.' WHERE level = 'B1' AND hanzi = '觀察' AND pinyin = 'guānchá' AND vietnamese = 'Quan sát, xem xét';
UPDATE public.dictionary_words SET example_hanzi = '每個人對這件事的觀點都不太一樣。', example_pinyin = 'měi gè rén duì zhè jiàn shì de guān diǎn dōu bú tài yí yàng。', example_vietnamese = 'Mỗi người có quan điểm khá khác nhau về việc này.' WHERE level = 'B1' AND hanzi = '觀點' AND pinyin = 'guāndiăn' AND vietnamese = 'Quan điểm';
UPDATE public.dictionary_words SET example_hanzi = '年輕一代的婚姻觀念跟以前不太一樣了。', example_pinyin = 'nián qīng yí dài de hūn yīn guān niàn gēn yǐ qián bú tài yí yàng le。', example_vietnamese = 'Quan niệm hôn nhân của thế hệ trẻ đã khác trước khá nhiều.' WHERE level = 'B1' AND hanzi = '觀念' AND pinyin = 'guānniàn' AND vietnamese = 'Quan niệm';
UPDATE public.dictionary_words SET example_hanzi = '演唱會現場擠滿了熱情的觀眾。', example_pinyin = 'yǎn chàng huì xiàn chǎng jǐ mǎn le rè qíng de guān zhòng。', example_vietnamese = 'Hiện trường buổi hòa nhạc chật kín khán giả nhiệt tình.' WHERE level = 'B1' AND hanzi = '觀眾' AND pinyin = 'guānzhòng' AND vietnamese = 'Quần chúng';
UPDATE public.dictionary_words SET example_hanzi = '這裡的事情由我來管就好。', example_pinyin = 'zhè lǐ de shì qing yóu wǒ lái guǎn jiù hǎo。', example_vietnamese = 'Việc ở đây cứ để tôi quản lý là được.' WHERE level = 'B1' AND hanzi = '管' AND pinyin = 'guăn' AND vietnamese = 'Quản lý, cai quản';
UPDATE public.dictionary_words SET example_hanzi = '冰箱裡還有兩罐可樂。', example_pinyin = 'bīng xiāng lǐ hái yǒu liǎng guàn kě lè。', example_vietnamese = 'Trong tủ lạnh còn hai lon Coca.' WHERE level = 'B1' AND hanzi = '罐' AND pinyin = 'guàn' AND vietnamese = 'Hộp, vại, lọ';
UPDATE public.dictionary_words SET example_hanzi = '我每天開車上班都會聽廣播。', example_pinyin = 'wǒ měi tiān kāi chē shàng bān dōu huì tīng guǎng bò。', example_vietnamese = 'Ngày nào lái xe đi làm tôi cũng nghe chương trình phát thanh.' WHERE level = 'B1' AND hanzi = '廣播' AND pinyin = 'guǎngbò' AND vietnamese = 'Chương trình phát thanh';
UPDATE public.dictionary_words SET example_hanzi = '機場正在廣播班機延誤的消息。', example_pinyin = 'jī chǎng zhèng zài guǎng bò bān jī yán wù de xiāo xi。', example_vietnamese = 'Sân bay đang phát thanh thông báo chuyến bay bị trễ.' WHERE level = 'B1' AND hanzi = '廣播' AND pinyin = 'guǎngbò' AND vietnamese = 'Phát thanh';
UPDATE public.dictionary_words SET example_hanzi = '每到假日,廣場上都擠滿了人。', example_pinyin = 'měi dào jià rì, guǎng chǎng shàng dōu jǐ mǎn le rén。', example_vietnamese = 'Mỗi dịp lễ, quảng trường luôn đông nghịt người.' WHERE level = 'B1' AND hanzi = '廣場' AND pinyin = 'guăngchăng' AND vietnamese = 'Quảng trường';
UPDATE public.dictionary_words SET example_hanzi = '電視上一直重複播放同一個廣告。', example_pinyin = 'diàn shì shàng yì zhí chóng fù bò fàng tóng yí gè guǎng gào。', example_vietnamese = 'Trên tivi cứ phát đi phát lại một đoạn quảng cáo giống nhau.' WHERE level = 'B1' AND hanzi = '廣告' AND pinyin = 'guănggào' AND vietnamese = 'Quảng cáo';
UPDATE public.dictionary_words SET example_hanzi = '週末我喜歡到市場逛一逛。', example_pinyin = 'zhōu mò wǒ xǐ huan dào shì chǎng guàng yi guàng。', example_vietnamese = 'Cuối tuần tôi thích đi dạo ở chợ một chút.' WHERE level = 'B1' AND hanzi = '逛' AND pinyin = 'guàng' AND vietnamese = 'Đi dạo, đi bách bộ';
UPDATE public.dictionary_words SET example_hanzi = '我們下午打算去逛街,順便買雙鞋。', example_pinyin = 'wǒ men xià wǔ dǎ suàn qù guàng jiē, shùn biàn mǎi shuāng xié。', example_vietnamese = 'Chiều nay chúng tôi định đi dạo phố, tiện thể mua đôi giày.' WHERE level = 'B1' AND hanzi = '逛街' AND pinyin = 'guàngjiē' AND vietnamese = 'Tản bộ, dạo phố';
UPDATE public.dictionary_words SET example_hanzi = '這家餐廳的用餐規矩比較嚴格。', example_pinyin = 'zhè jiā cān tīng de yòng cān guī ju bǐ jiào yán gé。', example_vietnamese = 'Quy tắc ăn uống của nhà hàng này khá nghiêm ngặt.' WHERE level = 'B1' AND hanzi = '規矩' AND pinyin = 'guījŭ' AND vietnamese = 'quy củ';
UPDATE public.dictionary_words SET example_hanzi = '這家公司的規模比我想像中大很多。', example_pinyin = 'zhè jiā gōng sī de guī mó bǐ wǒ xiǎng xiàng zhōng dà hěn duō。', example_vietnamese = 'Quy mô của công ty này lớn hơn tôi tưởng tượng rất nhiều.' WHERE level = 'B1' AND hanzi = '規模' AND pinyin = 'guīmó' AND vietnamese = 'Quy mô';
UPDATE public.dictionary_words SET example_hanzi = '小時候我很怕黑,總覺得房間裡有鬼。', example_pinyin = 'xiǎo shí hou wǒ hěn pà hēi, zǒng jué de fáng jiān lǐ yǒu guǐ。', example_vietnamese = 'Hồi nhỏ tôi rất sợ bóng tối, cứ cảm thấy trong phòng có ma.' WHERE level = 'B1' AND hanzi = '鬼' AND pinyin = 'guǐ' AND vietnamese = 'Ma quỷ';
UPDATE public.dictionary_words SET example_hanzi = '請問您貴姓?', example_pinyin = 'qǐng wèn nín guì xìng?', example_vietnamese = 'Xin hỏi quý danh của ngài là gì?' WHERE level = 'B1' AND hanzi = '貴姓' AND pinyin = 'guìxìng' AND vietnamese = 'Quý danh, tên họ';
UPDATE public.dictionary_words SET example_hanzi = '這個櫃子可以用來放衣服。', example_pinyin = 'zhè ge guì zi kě yǐ yòng lái fàng yī fu。', example_vietnamese = 'Cái tủ này có thể dùng để đựng quần áo.' WHERE level = 'B1' AND hanzi = '櫃子' AND pinyin = 'guìzi' AND vietnamese = 'Cái tủ';
UPDATE public.dictionary_words SET example_hanzi = '今年暑假我們決定在國內旅行就好。', example_pinyin = 'jīn nián shǔ jià wǒ men jué dìng zài guó nèi lǚ xíng jiù hǎo。', example_vietnamese = 'Hè năm nay chúng tôi quyết định chỉ du lịch trong nước thôi.' WHERE level = 'B1' AND hanzi = '國內' AND pinyin = 'guónèi' AND vietnamese = 'Quốc nội, trong nước';
UPDATE public.dictionary_words SET example_hanzi = '他大學畢業後就到國外留學了。', example_pinyin = 'tā dà xué bì yè hòu jiù dào guó wài liú xué le。', example_vietnamese = 'Sau khi tốt nghiệp đại học anh ấy đã đi du học nước ngoài.' WHERE level = 'B1' AND hanzi = '國外' AND pinyin = 'guówài' AND vietnamese = 'Nước ngoài';
UPDATE public.dictionary_words SET example_hanzi = '這個故事描述了一位善良的國王。', example_pinyin = 'zhè ge gù shi miáo shù le yí wèi shàn liáng de guó wáng。', example_vietnamese = 'Câu chuyện này kể về một vị quốc vương nhân hậu.' WHERE level = 'B1' AND hanzi = '國王' AND pinyin = 'guówáng' AND vietnamese = 'Quốc vương, vua';
UPDATE public.dictionary_words SET example_hanzi = '在台灣,大部分人都會說國語。', example_pinyin = 'zài Tái wān, dà bù fen rén dōu huì shuō guó yǔ。', example_vietnamese = 'Ở Đài Loan, phần lớn mọi người đều biết nói tiếng phổ thông.' WHERE level = 'B1' AND hanzi = '國語' AND pinyin = 'guóyŭ' AND vietnamese = 'Quốc ngữ';
UPDATE public.dictionary_words SET example_hanzi = '別總是活在過去,要往前看。', example_pinyin = 'bié zǒng shì huó zài guò qù, yào wǎng qián kàn。', example_vietnamese = 'Đừng cứ mãi sống trong quá khứ, hãy nhìn về phía trước.' WHERE level = 'B1' AND hanzi = '過去' AND pinyin = 'guòqù' AND vietnamese = 'Đã qua, quá khứ';
UPDATE public.dictionary_words SET example_hanzi = '只要一家人平平安安,怎麼過日子都好。', example_pinyin = 'zhǐ yào yì jiā rén píng píng ān ān, zěn me guò rì zi dōu hǎo。', example_vietnamese = 'Chỉ cần cả nhà bình an, sống thế nào cũng tốt.' WHERE level = 'B1' AND hanzi = '過日子' AND pinyin = 'guòrìzi' AND vietnamese = 'Sống, sinh hoạt';
UPDATE public.dictionary_words SET example_hanzi = '嗨,別提了,今天真是倒楣的一天。', example_pinyin = 'hāi, bié tí le, jīn tiān zhēn shi dǎo méi de yì tiān。', example_vietnamese = 'Haizz, đừng nhắc nữa, hôm nay đúng là một ngày xui xẻo.' WHERE level = 'B1' AND hanzi = '嗨' AND pinyin = 'hāi' AND vietnamese = 'Haizz (thở dài)';
UPDATE public.dictionary_words SET example_hanzi = '「你考得怎麼樣?」「還好,沒有想像中難。」', example_pinyin = '“nǐ kǎo de zěn me yàng?” “hái hǎo, méi yǒu xiǎng xiàng zhōng nán。”', example_vietnamese = '"Bạn thi thế nào?" "Cũng tạm ổn, không khó như tưởng tượng."' WHERE level = 'B1' AND hanzi = '還好' AND pinyin = 'háihăo' AND vietnamese = 'Khá tốt, tàm tạm';
UPDATE public.dictionary_words SET example_hanzi = '過了這麼多年,他還是老樣子。', example_pinyin = 'guò le zhè me duō nián, tā hái shì lǎo yàng zi。', example_vietnamese = 'Đã bao nhiêu năm trôi qua, anh ấy vẫn như xưa.' WHERE level = 'B1' AND hanzi = '還是' AND pinyin = 'háishì' AND vietnamese = 'Vẫn còn';
UPDATE public.dictionary_words SET example_hanzi = '寫完作業以後,我還要複習明天的考試。', example_pinyin = 'xiě wán zuò yè yǐ hòu, wǒ hái yào fù xí míng tiān de kǎo shì。', example_vietnamese = 'Sau khi làm xong bài tập, tôi còn phải ôn tập cho kỳ thi ngày mai.' WHERE level = 'B1' AND hanzi = '還要' AND pinyin = 'háiyào' AND vietnamese = 'Cần phải';
UPDATE public.dictionary_words SET example_hanzi = '牆上貼著一張電影海報。', example_pinyin = 'qiáng shàng tiē zhe yì zhāng diàn yǐng hǎi bào。', example_vietnamese = 'Trên tường dán một tấm áp phích phim.' WHERE level = 'B1' AND hanzi = '海報' AND pinyin = 'hăibào' AND vietnamese = 'Áp phích';
UPDATE public.dictionary_words SET example_hanzi = '我們在海灘上堆了一座沙堡。', example_pinyin = 'wǒ men zài hǎi tān shàng duī le yí zuò shā bǎo。', example_vietnamese = 'Chúng tôi đã đắp một tòa lâu đài cát trên bãi biển.' WHERE level = 'B1' AND hanzi = '海灘' AND pinyin = 'hăitān' AND vietnamese = 'Bãi biển';
UPDATE public.dictionary_words SET example_hanzi = '海洋裡有許多我們還不了解的生物。', example_pinyin = 'hǎi yáng lǐ yǒu xǔ duō wǒ men hái bù liǎo jiě de shēng wù。', example_vietnamese = 'Trong đại dương có rất nhiều sinh vật mà chúng ta còn chưa hiểu rõ.' WHERE level = 'B1' AND hanzi = '海洋' AND pinyin = 'hǎiyáng' AND vietnamese = 'Hải dương, biển cả';
UPDATE public.dictionary_words SET example_hanzi = '抽菸不只害自己,也害了身邊的人。', example_pinyin = 'chōu yān bù zhǐ hài zì jǐ, yě hài le shēn biān de rén。', example_vietnamese = 'Hút thuốc không chỉ hại bản thân, mà còn hại cả người xung quanh.' WHERE level = 'B1' AND hanzi = '害' AND pinyin = 'hài' AND vietnamese = 'Hại, có hại';
UPDATE public.dictionary_words SET example_hanzi = '小孩子看到打雷常常會害怕。', example_pinyin = 'xiǎo hái zi kàn dào dǎ léi cháng cháng huì hài pà。', example_vietnamese = 'Trẻ con thấy sấm sét thường hay sợ hãi.' WHERE level = 'B1' AND hanzi = '害怕' AND pinyin = 'hàipà' AND vietnamese = 'Sợ hãi';
UPDATE public.dictionary_words SET example_hanzi = '他在銀行這一行做了二十年。', example_pinyin = 'tā zài yín háng zhè yì háng zuò le èr shí nián。', example_vietnamese = 'Anh ấy đã làm trong ngành ngân hàng này hai mươi năm.' WHERE level = 'B1' AND hanzi = '行' AND pinyin = 'háng' AND vietnamese = 'Hàng lối, ngành nghề';
UPDATE public.dictionary_words SET example_hanzi = '我這次是搭長榮航空回台灣的。', example_pinyin = 'wǒ zhè cì shì dā Cháng róng háng kōng huí Tái wān de。', example_vietnamese = 'Lần này tôi về Đài Loan bằng hãng hàng không EVA Air.' WHERE level = 'B1' AND hanzi = '航空' AND pinyin = 'hángkōng' AND vietnamese = 'Hàng không';
UPDATE public.dictionary_words SET example_hanzi = '這裡的居民非常好客,常常邀請旅客到家裡作客。', example_pinyin = 'zhè lǐ de jū mín fēi cháng hào kè, cháng cháng yāo qǐng lǚ kè dào jiā lǐ zuò kè。', example_vietnamese = 'Người dân ở đây rất hiếu khách, thường mời du khách đến nhà chơi.' WHERE level = 'B1' AND hanzi = '好' AND pinyin = 'hào' AND vietnamese = 'thích, ham thích';
UPDATE public.dictionary_words SET example_hanzi = '每天運動對身體有很多好處。', example_pinyin = 'měi tiān yùn dòng duì shēn tǐ yǒu hěn duō hǎo chù。', example_vietnamese = 'Tập thể dục hàng ngày có rất nhiều lợi ích cho cơ thể.' WHERE level = 'B1' AND hanzi = '好處' AND pinyin = 'hǎochù' AND vietnamese = 'Có lợi, có ích';
UPDATE public.dictionary_words SET example_hanzi = '你要好好照顧自己,別太累了。', example_pinyin = 'nǐ yào hǎo hǎo zhào gù zì jǐ, bié tài lèi le。', example_vietnamese = 'Bạn phải chăm sóc bản thân cho tốt, đừng để quá mệt.' WHERE level = 'B1' AND hanzi = '好好/好好兒' AND pinyin = 'hǎohǎo/hǎohǎor' AND vietnamese = 'Tốt lành, cẩn thận';
UPDATE public.dictionary_words SET example_hanzi = '這件事我已經跟你說了好幾次了。', example_pinyin = 'zhè jiàn shì wǒ yǐ jīng gēn nǐ shuō le hǎo jǐ cì le。', example_vietnamese = 'Chuyện này tôi đã nói với bạn mấy lần rồi.' WHERE level = 'B1' AND hanzi = '好幾' AND pinyin = 'hǎojǐ' AND vietnamese = 'Nhiều, mấy';
UPDATE public.dictionary_words SET example_hanzi = '好了,別再吵了,大家都累了。', example_pinyin = 'hǎo le, bié zài chǎo le, dà jiā dōu lèi le。', example_vietnamese = 'Được rồi, đừng cãi nhau nữa, mọi người đều mệt rồi.' WHERE level = 'B1' AND hanzi = '好了' AND pinyin = 'hǎole' AND vietnamese = 'Được rồi, OK';
UPDATE public.dictionary_words SET example_hanzi = '書架上還有好些書沒看完。', example_pinyin = 'shū jià shàng hái yǒu hǎo xiē shū méi kàn wán。', example_vietnamese = 'Trên giá sách vẫn còn khá nhiều sách chưa đọc xong.' WHERE level = 'B1' AND hanzi = '好些' AND pinyin = 'hǎoxiē' AND vietnamese = 'Nhiều, rất nhiều';
UPDATE public.dictionary_words SET example_hanzi = '桌上放著紙和筆。', example_pinyin = 'zhuō shang fàng zhe zhǐ hé bǐ。', example_vietnamese = 'Trên bàn để giấy và bút.' WHERE level = 'B1' AND hanzi = '和' AND pinyin = 'hé' AND vietnamese = 'Và';
UPDATE public.dictionary_words SET example_hanzi = '她送了我一盒巧克力。', example_pinyin = 'tā sòng le wǒ yì hé qiǎo kè lì。', example_vietnamese = 'Cô ấy đã tặng tôi một hộp sô-cô-la.' WHERE level = 'B1' AND hanzi = '盒' AND pinyin = 'hé' AND vietnamese = 'Hộp';
UPDATE public.dictionary_words SET example_hanzi = '這件衣服的尺寸很合身。', example_pinyin = 'zhè jiàn yī fu de chǐ cùn hěn hé shēn。', example_vietnamese = 'Kích cỡ của chiếc áo này rất vừa vặn.' WHERE level = 'B1' AND hanzi = '合' AND pinyin = 'hé' AND vietnamese = 'hợp, phù hợp';
UPDATE public.dictionary_words SET example_hanzi = '學生們一起合唱了一首畢業歌。', example_pinyin = 'xué sheng men yì qǐ hé chàng le yì shǒu bì yè gē。', example_vietnamese = 'Các học sinh cùng nhau đồng ca một bài hát tốt nghiệp.' WHERE level = 'B1' AND hanzi = '合唱' AND pinyin = 'héchàng' AND vietnamese = 'Hợp xướng, đồng ca';
UPDATE public.dictionary_words SET example_hanzi = '這兩家公司決定合作開發新產品。', example_pinyin = 'zhè liǎng jiā gōng sī jué dìng hé zuò kāi fā xīn chǎn pǐn。', example_vietnamese = 'Hai công ty này quyết định hợp tác phát triển sản phẩm mới.' WHERE level = 'B1' AND hanzi = '合作' AND pinyin = 'hézuò' AND vietnamese = 'Hợp tác';
UPDATE public.dictionary_words SET example_hanzi = '天已經黑了,我們該回家了。', example_pinyin = 'tiān yǐ jīng hēi le, wǒ men gāi huí jiā le。', example_vietnamese = 'Trời đã tối rồi, chúng ta nên về nhà thôi.' WHERE level = 'B1' AND hanzi = '黑' AND pinyin = 'hēi' AND vietnamese = 'Đen, đen tối';
UPDATE public.dictionary_words SET example_hanzi = '她一點都不恨當年拋棄她的父親。', example_pinyin = 'tā yì diǎn dōu bú hèn dāng nián pāo qì tā de fù qīn。', example_vietnamese = 'Cô ấy không hề oán hận người cha đã bỏ rơi mình năm xưa.' WHERE level = 'B1' AND hanzi = '恨' AND pinyin = 'hèn' AND vietnamese = 'Hận, thù hận';
UPDATE public.dictionary_words SET example_hanzi = '放假前她恨不得馬上飛回家鄉。', example_pinyin = 'fàng jià qián tā hèn bu de mǎ shàng fēi huí jiā xiāng。', example_vietnamese = 'Trước kỳ nghỉ cô ấy chỉ mong lập tức bay về quê nhà.' WHERE level = 'B1' AND hanzi = '恨不得' AND pinyin = 'hènbude' AND vietnamese = 'Mong muốn, khao khát';
UPDATE public.dictionary_words SET example_hanzi = '她害羞得臉都紅了。', example_pinyin = 'tā hài xiū de liǎn dōu hóng le。', example_vietnamese = 'Cô ấy ngại ngùng đến mức mặt đỏ bừng.' WHERE level = 'B1' AND hanzi = '紅' AND pinyin = 'hóng' AND vietnamese = 'Đỏ';
UPDATE public.dictionary_words SET example_hanzi = '過年的時候長輩會給小孩紅包。', example_pinyin = 'guò nián de shí hou zhǎng bèi huì gěi xiǎo hái hóng bāo。', example_vietnamese = 'Vào dịp Tết người lớn thường lì xì cho trẻ nhỏ.' WHERE level = 'B1' AND hanzi = '紅包' AND pinyin = 'hóngbāo' AND vietnamese = 'Tiền lì xì';
UPDATE public.dictionary_words SET example_hanzi = '我最喜歡吃紅豆做的甜湯。', example_pinyin = 'wǒ zuì xǐ huan chī hóng dòu zuò de tián tāng。', example_vietnamese = 'Tôi thích nhất là ăn chè làm từ đậu đỏ.' WHERE level = 'B1' AND hanzi = '紅豆' AND pinyin = 'hóngdòu' AND vietnamese = 'Đậu đỏ';
UPDATE public.dictionary_words SET example_hanzi = '冬天要穿厚一點的外套才不會冷。', example_pinyin = 'dōng tiān yào chuān hòu yì diǎn de wài tào cái bú huì lěng。', example_vietnamese = 'Mùa đông phải mặc áo khoác dày hơn một chút mới không bị lạnh.' WHERE level = 'B1' AND hanzi = '厚' AND pinyin = 'hòu' AND vietnamese = 'Dày';
UPDATE public.dictionary_words SET example_hanzi = '我打算後年出國念書。', example_pinyin = 'wǒ dǎ suàn hòu nián chū guó niàn shū。', example_vietnamese = 'Tôi định năm sau nữa sẽ đi du học nước ngoài.' WHERE level = 'B1' AND hanzi = '後' AND pinyin = 'hòu' AND vietnamese = 'Sau';
UPDATE public.dictionary_words SET example_hanzi = '請大家往後站一點。', example_pinyin = 'qǐng dà jiā wǎng hòu zhàn yì diǎn。', example_vietnamese = 'Mời mọi người lùi về phía sau một chút.' WHERE level = 'B1' AND hanzi = '後' AND pinyin = 'hòu' AND vietnamese = 'Phía sau';
UPDATE public.dictionary_words SET example_hanzi = '天空忽然下起大雨,大家都沒帶傘。', example_pinyin = 'tiān kōng hū rán xià qǐ dà yǔ, dà jiā dōu méi dài sǎn。', example_vietnamese = 'Bầu trời đột nhiên đổ mưa lớn, mọi người đều không mang ô.' WHERE level = 'B1' AND hanzi = '忽然' AND pinyin = 'hūrán' AND vietnamese = 'Bỗng nhiên, đột nhiên';
UPDATE public.dictionary_words SET example_hanzi = '爺爺年紀大了,做事變得有點糊塗。', example_pinyin = 'yé ye nián jì dà le, zuò shì biàn de yǒu diǎn hú tu。', example_vietnamese = 'Ông tuổi đã cao, làm việc trở nên hơi lú lẫn.' WHERE level = 'B1' AND hanzi = '糊塗' AND pinyin = 'hútú' AND vietnamese = 'Hồ đồ';
UPDATE public.dictionary_words SET example_hanzi = '朋友之間應該互相幫助。', example_pinyin = 'péng you zhī jiān yīng gāi hù xiāng bāng zhù。', example_vietnamese = 'Bạn bè với nhau nên giúp đỡ lẫn nhau.' WHERE level = 'B1' AND hanzi = '互相' AND pinyin = 'hùxiāng' AND vietnamese = 'Lẫn nhau, với nhau';
UPDATE public.dictionary_words SET example_hanzi = '這台電腦花了我三萬塊。', example_pinyin = 'zhè tái diàn nǎo huā le wǒ sān wàn kuài。', example_vietnamese = 'Chiếc máy tính này đã tốn của tôi ba mươi nghìn tệ.' WHERE level = 'B1' AND hanzi = '花' AND pinyin = 'huā' AND vietnamese = 'Tiêu (tiền/thời gian)';
UPDATE public.dictionary_words SET example_hanzi = '大家都知道他很花心,交過好幾個女朋友。', example_pinyin = 'dà jiā dōu zhī dào tā hěn huā xīn, jiāo guò hǎo jǐ gè nǚ péng you。', example_vietnamese = 'Mọi người đều biết anh ấy rất lăng nhăng, đã yêu qua mấy cô bạn gái.' WHERE level = 'B1' AND hanzi = '花心' AND pinyin = 'huāxīn' AND vietnamese = 'Lăng nhăng';
UPDATE public.dictionary_words SET example_hanzi = '每年冬天他們都會去日本滑雪。', example_pinyin = 'měi nián dōng tiān tā men dōu huì qù Rì běn huá xuě。', example_vietnamese = 'Mỗi mùa đông họ đều đi trượt tuyết ở Nhật Bản.' WHERE level = 'B1' AND hanzi = '滑雪' AND pinyin = 'huáxuě' AND vietnamese = 'Trượt tuyết';
UPDATE public.dictionary_words SET example_hanzi = '這位畫家的作品充滿了想像力。', example_pinyin = 'zhè wèi huà jiā de zuò pǐn chōng mǎn le xiǎng xiàng lì。', example_vietnamese = 'Tác phẩm của họa sĩ này tràn đầy sức tưởng tượng.' WHERE level = 'B1' AND hanzi = '畫家' AND pinyin = 'huàjiā' AND vietnamese = 'Họa sĩ';
UPDATE public.dictionary_words SET example_hanzi = '話說回來,我們還是先解決眼前的問題吧。', example_pinyin = 'huà shuō huí lái, wǒ men hái shi xiān jiě jué yǎn qián de wèn tí ba。', example_vietnamese = 'Quay lại chuyện chính, chúng ta vẫn nên giải quyết vấn đề trước mắt trước đã.' WHERE level = 'B1' AND hanzi = '話說回來' AND pinyin = 'huàshuōhuílái' AND vietnamese = 'Quay lại chủ đề chính…';
UPDATE public.dictionary_words SET example_hanzi = '這件新聞最近成了大家討論的話題。', example_pinyin = 'zhè jiàn xīn wén zuì jìn chéng le dà jiā tǎo lùn de huà tí。', example_vietnamese = 'Tin tức này gần đây đã trở thành đề tài mà mọi người bàn luận.' WHERE level = 'B1' AND hanzi = '話題' AND pinyin = 'huàtí' AND vietnamese = 'Đề tài, chủ đề';
UPDATE public.dictionary_words SET example_hanzi = '她的化妝品都是從國外買回來的。', example_pinyin = 'tā de huà zhuāng pǐn dōu shì cóng guó wài mǎi huí lái de。', example_vietnamese = 'Mỹ phẩm của cô ấy đều được mua từ nước ngoài về.' WHERE level = 'B1' AND hanzi = '化妝品' AND pinyin = 'huàzhuāngpĭn' AND vietnamese = 'Đồ trang điểm';
UPDATE public.dictionary_words SET example_hanzi = '熬夜對身體有很多壞處。', example_pinyin = 'áo yè duì shēn tǐ yǒu hěn duō huài chù。', example_vietnamese = 'Thức khuya có rất nhiều tác hại đối với cơ thể.' WHERE level = 'B1' AND hanzi = '壞處' AND pinyin = 'huàichù' AND vietnamese = 'Chỗ hỏng, điều có hại';
UPDATE public.dictionary_words SET example_hanzi = '我下星期就會把錢還給你。', example_pinyin = 'wǒ xià xīng qī jiù huì bǎ qián huán gěi nǐ。', example_vietnamese = 'Tuần sau tôi sẽ trả lại tiền cho bạn.' WHERE level = 'B1' AND hanzi = '還' AND pinyin = 'huán' AND vietnamese = 'Hoán đổi';
UPDATE public.dictionary_words SET example_hanzi = '大家越來越重視環保議題。', example_pinyin = 'dà jiā yuè lái yuè zhòng shì huán bǎo yì tí。', example_vietnamese = 'Mọi người ngày càng coi trọng vấn đề bảo vệ môi trường.' WHERE level = 'B1' AND hanzi = '環保' AND pinyin = 'huánbăo' AND vietnamese = 'Bảo vệ môi trường';
UPDATE public.dictionary_words SET example_hanzi = '秋天到了,樹葉都變黃了。', example_pinyin = 'qiū tiān dào le, shù yè dōu biàn huáng le。', example_vietnamese = 'Mùa thu đến rồi, lá cây đều chuyển sang màu vàng.' WHERE level = 'B1' AND hanzi = '黃' AND pinyin = 'huáng' AND vietnamese = 'Vàng';
UPDATE public.dictionary_words SET example_hanzi = '這部電影我已經看過三回了。', example_pinyin = 'zhè bù diàn yǐng wǒ yǐ jīng kàn guò sān huí le。', example_vietnamese = 'Bộ phim này tôi đã xem qua ba lần rồi.' WHERE level = 'B1' AND hanzi = '回' AND pinyin = 'huí' AND vietnamese = 'Lần';
UPDATE public.dictionary_words SET example_hanzi = '他的回答讓大家都很滿意。', example_pinyin = 'tā de huí dá ràng dà jiā dōu hěn mǎn yì。', example_vietnamese = 'Câu trả lời của anh ấy khiến mọi người đều hài lòng.' WHERE level = 'B1' AND hanzi = '回答' AND pinyin = 'huídá' AND vietnamese = 'Trả lời, đáp lại';
UPDATE public.dictionary_words SET example_hanzi = '每次回想起大學生活,她都會微笑。', example_pinyin = 'měi cì huí xiǎng qǐ dà xué shēng huó, tā dōu huì wēi xiào。', example_vietnamese = 'Mỗi lần hồi tưởng lại cuộc sống đại học, cô ấy đều mỉm cười.' WHERE level = 'B1' AND hanzi = '回想' AND pinyin = 'huíxiăng' AND vietnamese = 'Hồi tưởng, nhớ lại';
UPDATE public.dictionary_words SET example_hanzi = '明天下午三點有一場會,別忘了。', example_pinyin = 'míng tiān xià wǔ sān diǎn yǒu yì chǎng huì, bié wàng le。', example_vietnamese = 'Ba giờ chiều mai có một buổi họp, đừng quên nhé.' WHERE level = 'B1' AND hanzi = '會' AND pinyin = 'huì' AND vietnamese = 'hội, buổi họp';
UPDATE public.dictionary_words SET example_hanzi = '會場已經坐滿了前來聽演講的人。', example_pinyin = 'huì chǎng yǐ jīng zuò mǎn le qián lái tīng yǎn jiǎng de rén。', example_vietnamese = 'Hội trường đã chật kín những người đến nghe diễn thuyết.' WHERE level = 'B1' AND hanzi = '會場' AND pinyin = 'huìchăng' AND vietnamese = 'Hội trường';
UPDATE public.dictionary_words SET example_hanzi = '這堂課主要練習日常生活的會話。', example_pinyin = 'zhè táng kè zhǔ yào liàn xí rì cháng shēng huó de huì huà。', example_vietnamese = 'Buổi học này chủ yếu luyện tập hội thoại trong cuộc sống hàng ngày.' WHERE level = 'B1' AND hanzi = '會話' AND pinyin = 'huìhuà' AND vietnamese = 'Hội họa';
UPDATE public.dictionary_words SET example_hanzi = '老闆臨時取消了今天的會議。', example_pinyin = 'lǎo bǎn lín shí qǔ xiāo le jīn tiān de huì yì。', example_vietnamese = 'Sếp đột xuất hủy bỏ cuộc họp hôm nay.' WHERE level = 'B1' AND hanzi = '會議' AND pinyin = 'huìyì' AND vietnamese = 'Hội nghị';
UPDATE public.dictionary_words SET example_hanzi = '他們的婚禮辦得非常浪漫。', example_pinyin = 'tā men de hūn lǐ bàn de fēi cháng làng màn。', example_vietnamese = 'Đám cưới của họ được tổ chức rất lãng mạn.' WHERE level = 'B1' AND hanzi = '婚禮' AND pinyin = 'hūnlǐ' AND vietnamese = 'Hôn lễ, đám cưới';
UPDATE public.dictionary_words SET example_hanzi = '良好的溝通是幸福婚姻的基礎。', example_pinyin = 'liáng hǎo de gōu tōng shì xìng fú hūn yīn de jī chǔ。', example_vietnamese = 'Giao tiếp tốt là nền tảng của một cuộc hôn nhân hạnh phúc.' WHERE level = 'B1' AND hanzi = '婚姻' AND pinyin = 'hūnyīn' AND vietnamese = 'Hôn nhân';
UPDATE public.dictionary_words SET example_hanzi = '地震發生後,整個城市一片混亂。', example_pinyin = 'dì zhèn fā shēng hòu, zhěng gè chéng shì yí piàn hùn luàn。', example_vietnamese = 'Sau khi động đất xảy ra, cả thành phố trở nên hỗn loạn.' WHERE level = 'B1' AND hanzi = '混亂' AND pinyin = 'hùnluàn' AND vietnamese = 'Hỗn loạn, lẫn lộn';
UPDATE public.dictionary_words SET example_hanzi = '這家餐廳的水族箱裡有很多活魚。', example_pinyin = 'zhè jiā cān tīng de shuǐ zú xiāng lǐ yǒu hěn duō huó yú。', example_vietnamese = 'Trong bể cá của nhà hàng này có rất nhiều cá còn sống.' WHERE level = 'B1' AND hanzi = '活' AND pinyin = 'huó' AND vietnamese = 'Sống, sinh sống';
UPDATE public.dictionary_words SET example_hanzi = '學校下週會舉辦一場運動會活動。', example_pinyin = 'xué xiào xià zhōu huì jǔ bàn yì chǎng yùn dòng huì huó dòng。', example_vietnamese = 'Tuần sau trường sẽ tổ chức một hoạt động ngày hội thể thao.' WHERE level = 'B1' AND hanzi = '活動' AND pinyin = 'huódòng' AND vietnamese = 'Hoạt động';
UPDATE public.dictionary_words SET example_hanzi = '或許再等幾天,情況就會好轉。', example_pinyin = 'huò xǔ zài děng jǐ tiān, qíng kuàng jiù huì hǎo zhuǎn。', example_vietnamese = 'Có lẽ đợi thêm vài ngày nữa, tình hình sẽ chuyển biến tốt hơn.' WHERE level = 'B1' AND hanzi = '或許' AND pinyin = 'huòxŭ' AND vietnamese = 'Có thể, có lẽ là';
UPDATE public.dictionary_words SET example_hanzi = '這是做人最基本的道理。', example_pinyin = 'zhè shì zuò rén zuì jī běn de dào lǐ。', example_vietnamese = 'Đây là đạo lý căn bản nhất trong cách sống làm người.' WHERE level = 'B1' AND hanzi = '基本' AND pinyin = 'jīběn' AND vietnamese = 'Căn bản, cơ bản';
UPDATE public.dictionary_words SET example_hanzi = '這個問題基本上已經解決了。', example_pinyin = 'zhè ge wèn tí jī běn shàng yǐ jīng jiě jué le。', example_vietnamese = 'Vấn đề này về cơ bản đã được giải quyết rồi.' WHERE level = 'B1' AND hanzi = '基本' AND pinyin = 'jīběn' AND vietnamese = 'Chủ yếu';
UPDATE public.dictionary_words SET example_hanzi = '良好的基礎對學習語言很重要。', example_pinyin = 'liáng hǎo de jī chǔ duì xué xí yǔ yán hěn zhòng yào。', example_vietnamese = 'Nền tảng vững chắc rất quan trọng đối với việc học ngoại ngữ.' WHERE level = 'B1' AND hanzi = '基礎' AND pinyin = 'jīchŭ' AND vietnamese = 'Nền móng, cơ sở';
UPDATE public.dictionary_words SET example_hanzi = '他從小在基督教家庭長大。', example_pinyin = 'tā cóng xiǎo zài Jī dū jiào jiā tíng zhǎng dà。', example_vietnamese = 'Anh ấy lớn lên trong một gia đình theo đạo Cơ Đốc từ nhỏ.' WHERE level = 'B1' AND hanzi = '基督教' AND pinyin = 'Jīdūjiào' AND vietnamese = 'Cơ đốc giáo';
UPDATE public.dictionary_words SET example_hanzi = '聽到這個好消息,她激動得說不出話來。', example_pinyin = 'tīng dào zhè ge hǎo xiāo xi, tā jī dòng de shuō bu chū huà lái。', example_vietnamese = 'Nghe được tin tốt này, cô ấy xúc động đến mức không nói nên lời.' WHERE level = 'B1' AND hanzi = '激動' AND pinyin = 'jīdòng' AND vietnamese = 'Xúc động';
UPDATE public.dictionary_words SET example_hanzi = '這場比賽的競爭非常激烈。', example_pinyin = 'zhè chǎng bǐ sài de jìng zhēng fēi cháng jī liè。', example_vietnamese = 'Sự cạnh tranh trong trận đấu này vô cùng quyết liệt.' WHERE level = 'B1' AND hanzi = '激烈' AND pinyin = 'jīliè' AND vietnamese = 'Quyết liệt, dữ dội';
UPDATE public.dictionary_words SET example_hanzi = '他工作一向很積極,從不推卸責任。', example_pinyin = 'tā gōng zuò yí xiàng hěn jī jí, cóng bù tuī xiè zé rèn。', example_vietnamese = 'Anh ấy làm việc luôn rất tích cực, chưa bao giờ đùn đẩy trách nhiệm.' WHERE level = 'B1' AND hanzi = '積極' AND pinyin = 'jījí' AND vietnamese = 'Tích cực, hăng hái';
UPDATE public.dictionary_words SET example_hanzi = '工廠裡的機器一天到晚都在運轉。', example_pinyin = 'gōng chǎng lǐ de jī qì yì tiān dào wǎn dōu zài yùn zhuǎn。', example_vietnamese = 'Máy móc trong nhà máy hoạt động suốt cả ngày.' WHERE level = 'B1' AND hanzi = '機器' AND pinyin = 'jīqì' AND vietnamese = 'Cơ khí, máy móc';
UPDATE public.dictionary_words SET example_hanzi = '這次會議會討論薪水以及福利的問題。', example_pinyin = 'zhè cì huì yì huì tǎo lùn xīn shuǐ yǐ jí fú lì de wèn tí。', example_vietnamese = 'Cuộc họp lần này sẽ bàn về vấn đề lương và phúc lợi.' WHERE level = 'B1' AND hanzi = '及' AND pinyin = 'jí' AND vietnamese = 'Đạt đến';
UPDATE public.dictionary_words SET example_hanzi = '別急,慢慢說,我聽得懂。', example_pinyin = 'bié jí, màn màn shuō, wǒ tīng de dǒng。', example_vietnamese = 'Đừng vội, từ từ nói, tôi nghe hiểu mà.' WHERE level = 'B1' AND hanzi = '急' AND pinyin = 'jí' AND vietnamese = 'Gấp, vội';
UPDATE public.dictionary_words SET example_hanzi = '這道菜的味道極好,大家都讚不絕口。', example_pinyin = 'zhè dào cài de wèi dào jí hǎo, dà jiā dōu zàn bù jué kǒu。', example_vietnamese = 'Hương vị món ăn này cực kỳ ngon, mọi người đều tấm tắc khen ngợi.' WHERE level = 'B1' AND hanzi = '極' AND pinyin = 'jí' AND vietnamese = 'Đỉnh điểm';
UPDATE public.dictionary_words SET example_hanzi = '今天的天氣好極了,適合出去走走。', example_pinyin = 'jīn tiān de tiān qì hǎo jí le, shì hé chū qù zǒu zou。', example_vietnamese = 'Thời tiết hôm nay đẹp cực kỳ, thích hợp để ra ngoài dạo chơi.' WHERE level = 'B1' AND hanzi = '極了' AND pinyin = 'jíle' AND vietnamese = 'Vô cùng, cực kỳ';
UPDATE public.dictionary_words SET example_hanzi = '公車上人很多，大家擠來擠去的。', example_pinyin = 'gōng chē shàng rén hěn duō, dà jiā jǐ lái jǐ qù de。', example_vietnamese = 'Trên xe buýt rất đông người, mọi người chen chúc qua lại.' WHERE level = 'B1' AND hanzi = '擠' AND pinyin = 'jǐ' AND vietnamese = 'Chen chúc';
UPDATE public.dictionary_words SET example_hanzi = '下班時間的捷運站總是擠得水洩不通。', example_pinyin = 'xià bān shí jiān de jié yùn zhàn zǒng shì jǐ de shuǐ xiè bù tōng。', example_vietnamese = 'Vào giờ tan tầm, ga tàu điện ngầm luôn chật cứng người.' WHERE level = 'B1' AND hanzi = '擠' AND pinyin = 'jǐ' AND vietnamese = 'Dồn lại';
UPDATE public.dictionary_words SET example_hanzi = '這件衣服既漂亮又便宜，我決定買下來。', example_pinyin = 'zhè jiàn yī fu jì piào liang yòu pián yi, wǒ jué dìng mǎi xià lái。', example_vietnamese = 'Bộ quần áo này vừa đẹp vừa rẻ, tôi quyết định mua nó.' WHERE level = 'B1' AND hanzi = '既' AND pinyin = 'jì' AND vietnamese = 'Đã, phàm đã…';
UPDATE public.dictionary_words SET example_hanzi = '你一定要記住他的名字，下次見面才不會叫錯。', example_pinyin = 'nǐ yí dìng yào jì zhù tā de míng zi, xià cì jiàn miàn cái bú huì jiào cuò。', example_vietnamese = 'Bạn nhất định phải nhớ tên anh ấy, để lần sau gặp mặt không gọi nhầm.' WHERE level = 'B1' AND hanzi = '記' AND pinyin = 'jì' AND vietnamese = 'Nhớ, ghi chép lại';
UPDATE public.dictionary_words SET example_hanzi = '這場會議的記錄已經整理好了，你可以先看一下。', example_pinyin = 'zhè chǎng huì yì de jì lù yǐ jīng zhěng lǐ hǎo le, nǐ kě yǐ xiān kàn yí xià。', example_vietnamese = 'Biên bản cuộc họp này đã được sắp xếp xong, bạn có thể xem trước.' WHERE level = 'B1' AND hanzi = '記錄' AND pinyin = 'jìlù' AND vietnamese = 'Biên bản';
UPDATE public.dictionary_words SET example_hanzi = '老師要求我們把每天的心得記錄下來。', example_pinyin = 'lǎo shī yāo qiú wǒ men bǎ měi tiān de xīn dé jì lù xià lái。', example_vietnamese = 'Giáo viên yêu cầu chúng tôi ghi chép lại cảm nhận mỗi ngày.' WHERE level = 'B1' AND hanzi = '記錄' AND pinyin = 'jìlù' AND vietnamese = 'Ghi chép lại';
UPDATE public.dictionary_words SET example_hanzi = '小時候在鄉下的生活是我最美好的記憶。', example_pinyin = 'xiǎo shí hou zài xiāng xià de shēng huó shì wǒ zuì měi hǎo de jì yì。', example_vietnamese = 'Cuộc sống ở quê hồi nhỏ là ký ức đẹp nhất của tôi.' WHERE level = 'B1' AND hanzi = '記憶' AND pinyin = 'jìyì' AND vietnamese = 'Hồi tưởng, ký ức';
UPDATE public.dictionary_words SET example_hanzi = '秋天是台灣天氣最舒服的季節。', example_pinyin = 'qiū tiān shì tái wān tiān qì zuì shū fu de jì jié。', example_vietnamese = 'Mùa thu là mùa có thời tiết dễ chịu nhất ở Đài Loan.' WHERE level = 'B1' AND hanzi = '季節' AND pinyin = 'jìjié' AND vietnamese = 'Mùa, mùa vụ';
UPDATE public.dictionary_words SET example_hanzi = '這條項鍊是媽媽送我的畢業紀念。', example_pinyin = 'zhè tiáo xiàng liàn shì mā ma sòng wǒ de bì yè jì niàn。', example_vietnamese = 'Chiếc dây chuyền này là món quà kỷ niệm tốt nghiệp mẹ tặng tôi.' WHERE level = 'B1' AND hanzi = '紀念' AND pinyin = 'jìniàn' AND vietnamese = 'Đồ kỷ niệm';
UPDATE public.dictionary_words SET example_hanzi = '為了紀念這段友情，我們拍了一張合照。', example_pinyin = 'wèi le jì niàn zhè duàn yǒu qíng, wǒ men pāi le yì zhāng hé zhào。', example_vietnamese = 'Để tưởng niệm tình bạn này, chúng tôi đã chụp một tấm ảnh chung.' WHERE level = 'B1' AND hanzi = '紀念' AND pinyin = 'jìniàn' AND vietnamese = 'Tưởng niệm';
UPDATE public.dictionary_words SET example_hanzi = '學好一種語言需要不少練習的技巧。', example_pinyin = 'xué hǎo yì zhǒng yǔ yán xū yào bù shǎo liàn xí de jì qiǎo。', example_vietnamese = 'Học giỏi một ngôn ngữ cần không ít kỹ xảo luyện tập.' WHERE level = 'B1' AND hanzi = '技巧' AND pinyin = 'jìqiăo' AND vietnamese = 'Kỹ xảo';
UPDATE public.dictionary_words SET example_hanzi = '雖然很累，他還是決定繼續完成這份工作。', example_pinyin = 'suī rán hěn lèi, tā hái shì jué dìng jì xù wán chéng zhè fèn gōng zuò。', example_vietnamese = 'Dù rất mệt, anh ấy vẫn quyết định tiếp tục hoàn thành công việc này.' WHERE level = 'B1' AND hanzi = '繼續' AND pinyin = 'jìxù' AND vietnamese = 'Tiếp tục';
UPDATE public.dictionary_words SET example_hanzi = '這杯咖啡可以幫我加一點牛奶嗎？', example_pinyin = 'zhè bēi kā fēi kě yǐ bāng wǒ jiā yì diǎn niú nǎi ma？', example_vietnamese = 'Ly cà phê này có thể giúp tôi thêm chút sữa được không?' WHERE level = 'B1' AND hanzi = '加' AND pinyin = 'jiā' AND vietnamese = 'Cộng, tăng thêm';
UPDATE public.dictionary_words SET example_hanzi = '為了考試，他每天加強練習聽力。', example_pinyin = 'wèi le kǎo shì, tā měi tiān jiā qiáng liàn xí tīng lì。', example_vietnamese = 'Để chuẩn bị cho kỳ thi, anh ấy tăng cường luyện nghe mỗi ngày.' WHERE level = 'B1' AND hanzi = '加強' AND pinyin = 'jiāqiáng' AND vietnamese = 'Tăng cường';
UPDATE public.dictionary_words SET example_hanzi = '她決定加入學校的籃球隊。', example_pinyin = 'tā jué dìng jiā rù xué xiào de lán qiú duì。', example_vietnamese = 'Cô ấy quyết định tham gia đội bóng rổ của trường.' WHERE level = 'B1' AND hanzi = '加入' AND pinyin = 'jiārù' AND vietnamese = 'Thêm vào, tham gia vào';
UPDATE public.dictionary_words SET example_hanzi = '這道菜加上一點醬油會更好吃。', example_pinyin = 'zhè dào cài jiā shàng yì diǎn jiàng yóu huì gèng hǎo chī。', example_vietnamese = 'Món ăn này thêm một chút nước tương vào sẽ ngon hơn.' WHERE level = 'B1' AND hanzi = '加上' AND pinyin = 'jiāshàng' AND vietnamese = 'Cộng vào, thêm vào đó';
UPDATE public.dictionary_words SET example_hanzi = '比賽快開始了，大家一起為他加油吧！', example_pinyin = 'bǐ sài kuài kāi shǐ le, dà jiā yì qǐ wèi tā jiā yóu ba！', example_vietnamese = 'Trận đấu sắp bắt đầu rồi, mọi người cùng cổ vũ cho anh ấy nào!' WHERE level = 'B1' AND hanzi = '加油' AND pinyin = 'jiāyóu' AND vietnamese = 'Cố lên!';
UPDATE public.dictionary_words SET example_hanzi = '這附近新開了一家很有名的火鍋店。', example_pinyin = 'zhè fù jìn xīn kāi le yì jiā hěn yǒu míng de huǒ guō diàn。', example_vietnamese = 'Gần đây mới mở một quán lẩu rất nổi tiếng.' WHERE level = 'B1' AND hanzi = '家' AND pinyin = 'jiā' AND vietnamese = 'Nhà, gia đình';
UPDATE public.dictionary_words SET example_hanzi = '每逢過年，他都會回家鄉看望父母。', example_pinyin = 'měi féng guò nián, tā dōu huì huí jiā xiāng kàn wàng fù mǔ。', example_vietnamese = 'Cứ mỗi dịp Tết, anh ấy đều về quê thăm bố mẹ.' WHERE level = 'B1' AND hanzi = '家鄉' AND pinyin = 'jiāxiāng' AND vietnamese = 'Quê nhà, quê hương';
UPDATE public.dictionary_words SET example_hanzi = '學校今天邀請家長來參加親子活動。', example_pinyin = 'xué xiào jīn tiān yāo qǐng jiā zhǎng lái cān jiā qīn zǐ huó dòng。', example_vietnamese = 'Hôm nay trường mời phụ huynh đến tham gia hoạt động gia đình.' WHERE level = 'B1' AND hanzi = '家長' AND pinyin = 'jiāzhăng' AND vietnamese = 'Phụ huynh';
UPDATE public.dictionary_words SET example_hanzi = '這個名牌包是假的，做工一看就知道。', example_pinyin = 'zhè ge míng pái bāo shì jiǎ de, zuò gōng yí kàn jiù zhī dào。', example_vietnamese = 'Chiếc túi hàng hiệu này là giả, nhìn đường may là biết ngay.' WHERE level = 'B1' AND hanzi = '假' AND pinyin = 'jiă' AND vietnamese = 'Giả, không thật';
UPDATE public.dictionary_words SET example_hanzi = '假如明天下雨，我們就取消爬山的計畫。', example_pinyin = 'jiǎ rú míng tiān xià yǔ, wǒ men jiù qǔ xiāo pá shān de jì huà。', example_vietnamese = 'Nếu ngày mai trời mưa, chúng tôi sẽ hủy kế hoạch leo núi.' WHERE level = 'B1' AND hanzi = '假如' AND pinyin = 'jiărú' AND vietnamese = 'Giá như, nếu như';
UPDATE public.dictionary_words SET example_hanzi = '他明明很難過，卻假裝什麼事都沒發生。', example_pinyin = 'tā míng míng hěn nán guò, què jiǎ zhuāng shén me shì dōu méi fā shēng。', example_vietnamese = 'Anh ấy rõ ràng rất buồn, nhưng lại giả vờ như không có chuyện gì xảy ra.' WHERE level = 'B1' AND hanzi = '假裝' AND pinyin = 'jiăzhuāng' AND vietnamese = 'Giả vờ';
UPDATE public.dictionary_words SET example_hanzi = '機場跑道上停著好幾架飛機。', example_pinyin = 'jī chǎng pǎo dào shàng tíng zhe hǎo jǐ jià fēi jī。', example_vietnamese = 'Trên đường băng sân bay đang đậu mấy chiếc máy bay.' WHERE level = 'B1' AND hanzi = '架' AND pinyin = 'jià' AND vietnamese = 'Cái giá, khung';
UPDATE public.dictionary_words SET example_hanzi = '假日的百貨公司總是擠滿了人。', example_pinyin = 'jià rì de bǎi huò gōng sī zǒng shì jǐ mǎn le rén。', example_vietnamese = 'Vào ngày nghỉ, trung tâm mua sắm luôn chật kín người.' WHERE level = 'B1' AND hanzi = '假日' AND pinyin = 'jiàrì' AND vietnamese = 'Ngày nghỉ';
UPDATE public.dictionary_words SET example_hanzi = '這幅畫雖然舊，但很有收藏價值。', example_pinyin = 'zhè fú huà suī rán jiù, dàn hěn yǒu shōu cáng jià zhí。', example_vietnamese = 'Bức tranh này tuy cũ nhưng rất có giá trị sưu tầm.' WHERE level = 'B1' AND hanzi = '價值' AND pinyin = 'jiàzhí' AND vietnamese = 'Giá trị (hàng hóa)';
UPDATE public.dictionary_words SET example_hanzi = '背了一天的背包，我的肩膀又痠又痛。', example_pinyin = 'bēi le yì tiān de bēi bāo, wǒ de jiān bǎng yòu suān yòu tòng。', example_vietnamese = 'Đeo ba lô cả ngày, vai tôi vừa mỏi vừa đau.' WHERE level = 'B1' AND hanzi = '肩膀' AND pinyin = 'jiānbăng' AND vietnamese = 'Bờ vài';
UPDATE public.dictionary_words SET example_hanzi = '不管多困難，她都堅持每天早起運動。', example_pinyin = 'bù guǎn duō kùn nán, tā dōu jiān chí měi tiān zǎo qǐ yùn dòng。', example_vietnamese = 'Dù khó khăn thế nào, cô ấy vẫn kiên trì dậy sớm tập thể dục mỗi ngày.' WHERE level = 'B1' AND hanzi = '堅持' AND pinyin = 'jiānchí' AND vietnamese = 'Kiên trì';
UPDATE public.dictionary_words SET example_hanzi = '經歷了那麼多打擊，她變得比以前堅強多了。', example_pinyin = 'jīng lì le nà me duō dǎ jī, tā biàn de bǐ yǐ qián jiān qiáng duō le。', example_vietnamese = 'Trải qua bao nhiêu cú sốc, cô ấy trở nên kiên cường hơn trước nhiều.' WHERE level = 'B1' AND hanzi = '堅強' AND pinyin = 'jiānqiáng' AND vietnamese = 'Kiên cường';
UPDATE public.dictionary_words SET example_hanzi = '醫生建議他減少鹽分，把體重減一點。', example_pinyin = 'yī shēng jiàn yì tā jiǎn shǎo yán fèn, bǎ tǐ zhòng jiǎn yì diǎn。', example_vietnamese = 'Bác sĩ khuyên anh ấy giảm bớt muối, giảm cân một chút.' WHERE level = 'B1' AND hanzi = '減' AND pinyin = 'jiăn' AND vietnamese = 'Giảm, trừ bớt';
UPDATE public.dictionary_words SET example_hanzi = '這種藥可以有效減輕頭痛的症狀。', example_pinyin = 'zhè zhǒng yào kě yǐ yǒu xiào jiǎn qīng tóu tòng de zhèng zhuàng。', example_vietnamese = 'Loại thuốc này có thể giảm nhẹ hiệu quả triệu chứng đau đầu.' WHERE level = 'B1' AND hanzi = '減輕' AND pinyin = 'jiănqīng' AND vietnamese = 'Giảm nhẹ';
UPDATE public.dictionary_words SET example_hanzi = '政府呼籲大家減少使用塑膠袋。', example_pinyin = 'zhèng fǔ hū yù dà jiā jiǎn shǎo shǐ yòng sù jiāo dài。', example_vietnamese = 'Chính phủ kêu gọi mọi người giảm sử dụng túi nhựa.' WHERE level = 'B1' AND hanzi = '減少' AND pinyin = 'jiănshăo' AND vietnamese = 'Giảm thiểu';
UPDATE public.dictionary_words SET example_hanzi = '這道菜辣得簡直讓人受不了。', example_pinyin = 'zhè dào cài là de jiǎn zhí ràng rén shòu bù liǎo。', example_vietnamese = 'Món ăn này cay đến mức quả thật khiến người ta chịu không nổi.' WHERE level = 'B1' AND hanzi = '簡直' AND pinyin = 'jiănzhí' AND vietnamese = 'Quả thật là';
UPDATE public.dictionary_words SET example_hanzi = '我昨天在夜市見到了我的高中同學。', example_pinyin = 'wǒ zuó tiān zài yè shì jiàn dào le wǒ de gāo zhōng tóng xué。', example_vietnamese = 'Hôm qua tôi đã gặp bạn học cấp ba của mình ở chợ đêm.' WHERE level = 'B1' AND hanzi = '見' AND pinyin = 'jiàn' AND vietnamese = 'Trông thấy';
UPDATE public.dictionary_words SET example_hanzi = '兩家公司決定建立長期的合作關係。', example_pinyin = 'liǎng jiā gōng sī jué dìng jiàn lì cháng qī de hé zuò guān xì。', example_vietnamese = 'Hai công ty quyết định xây dựng mối quan hệ hợp tác lâu dài.' WHERE level = 'B1' AND hanzi = '建立' AND pinyin = 'jiànlì' AND vietnamese = 'Xây dựng';
UPDATE public.dictionary_words SET example_hanzi = '這座城市的公共建設這幾年進步很多。', example_pinyin = 'zhè zuò chéng shì de gōng gòng jiàn shè zhè jǐ nián jìn bù hěn duō。', example_vietnamese = 'Cơ sở hạ tầng công cộng của thành phố này mấy năm nay tiến bộ rất nhiều.' WHERE level = 'B1' AND hanzi = '建設' AND pinyin = 'jiànshè' AND vietnamese = 'Kiến thiết';
UPDATE public.dictionary_words SET example_hanzi = '政府計劃在郊區建設一座新的公園。', example_pinyin = 'zhèng fǔ jì huà zài jiāo qū jiàn shè yí zuò xīn de gōng yuán。', example_vietnamese = 'Chính phủ lên kế hoạch xây dựng một công viên mới ở vùng ngoại ô.' WHERE level = 'B1' AND hanzi = '建設' AND pinyin = 'jiànshè' AND vietnamese = 'Xây dựng, lập nên';
UPDATE public.dictionary_words SET example_hanzi = '謝謝你的建議，我會認真考慮的。', example_pinyin = 'xiè xie nǐ de jiàn yì, wǒ huì rèn zhēn kǎo lǜ de。', example_vietnamese = 'Cảm ơn đề nghị của bạn, tôi sẽ cân nhắc nghiêm túc.' WHERE level = 'B1' AND hanzi = '建議' AND pinyin = 'jiànyì' AND vietnamese = 'Đề nghị, đề xuất';
UPDATE public.dictionary_words SET example_hanzi = '醫生建議我多喝水、少熬夜。', example_pinyin = 'yī shēng jiàn yì wǒ duō hē shuǐ, shǎo áo yè。', example_vietnamese = 'Bác sĩ khuyên tôi uống nhiều nước, ít thức khuya.' WHERE level = 'B1' AND hanzi = '建議' AND pinyin = 'jiànyì' AND vietnamese = 'Đưa ra lời khuyên';
UPDATE public.dictionary_words SET example_hanzi = '他希望將來能當一名醫生。', example_pinyin = 'tā xī wàng jiāng lái néng dāng yì míng yī shēng。', example_vietnamese = 'Anh ấy hy vọng sau này có thể trở thành bác sĩ.' WHERE level = 'B1' AND hanzi = '將來' AND pinyin = 'jiānglái' AND vietnamese = 'Tương lai, sau này';
UPDATE public.dictionary_words SET example_hanzi = '在傳統市場買東西可以跟老闆講價。', example_pinyin = 'zài chuán tǒng shì chǎng mǎi dōng xi kě yǐ gēn lǎo bǎn jiǎng jià。', example_vietnamese = 'Mua đồ ở chợ truyền thống có thể mặc cả với ông chủ.' WHERE level = 'B1' AND hanzi = '講價' AND pinyin = 'jiăngjià' AND vietnamese = 'Mặc cả, trả giá';
UPDATE public.dictionary_words SET example_hanzi = '這家餐廳對食材的新鮮度非常講究。', example_pinyin = 'zhè jiā cān tīng duì shí cái de xīn xiān dù fēi cháng jiǎng jiu。', example_vietnamese = 'Nhà hàng này rất chú trọng đến độ tươi của nguyên liệu.' WHERE level = 'B1' AND hanzi = '講究' AND pinyin = 'jiăngjiu' AND vietnamese = 'Chú trọng, chú ý';
UPDATE public.dictionary_words SET example_hanzi = '他成績優秀，申請到了學校的獎學金。', example_pinyin = 'tā chéng jì yōu xiù, shēn qǐng dào le xué xiào de jiǎng xué jīn。', example_vietnamese = 'Anh ấy học giỏi nên xin được học bổng của trường.' WHERE level = 'B1' AND hanzi = '獎學金' AND pinyin = 'jiăngxuéjīn' AND vietnamese = 'Học bổng';
UPDATE public.dictionary_words SET example_hanzi = '這家店最近把商品的價格降低了不少。', example_pinyin = 'zhè jiā diàn zuì jìn bǎ shāng pǐn de jià gé jiàng dī le bù shǎo。', example_vietnamese = 'Cửa hàng này gần đây đã hạ giá sản phẩm xuống khá nhiều.' WHERE level = 'B1' AND hanzi = '降低' AND pinyin = 'jiàngdī' AND vietnamese = 'Hạ thấp';
UPDATE public.dictionary_words SET example_hanzi = '媽媽炒菜的時候喜歡加一點醬油調味。', example_pinyin = 'mā ma chǎo cài de shí hou xǐ huan jiā yì diǎn jiàng yóu tiáo wèi。', example_vietnamese = 'Khi xào rau, mẹ thích thêm chút nước tương để nêm gia vị.' WHERE level = 'B1' AND hanzi = '醬油' AND pinyin = 'jiàngyóu' AND vietnamese = 'Nước tương, xì dầu';
UPDATE public.dictionary_words SET example_hanzi = '報告明天要交，你寫完了嗎？', example_pinyin = 'bào gào míng tiān yào jiāo, nǐ xiě wán le ma？', example_vietnamese = 'Ngày mai phải nộp báo cáo rồi, bạn viết xong chưa?' WHERE level = 'B1' AND hanzi = '交' AND pinyin = 'jiāo' AND vietnamese = 'Giao nộp';
UPDATE public.dictionary_words SET example_hanzi = '這次交換學生的活動讓我們有機會跟外國學生交流。', example_pinyin = 'zhè cì jiāo huàn xué shēng de huó dòng ràng wǒ men yǒu jī huì gēn wài guó xué shēng jiāo liú。', example_vietnamese = 'Hoạt động trao đổi sinh viên lần này cho chúng tôi cơ hội giao lưu với sinh viên nước ngoài.' WHERE level = 'B1' AND hanzi = '交流' AND pinyin = 'jiāoliú' AND vietnamese = 'Giao lưu, trao đổi';
UPDATE public.dictionary_words SET example_hanzi = '現在很多年輕人喜歡透過網路交友。', example_pinyin = 'xiàn zài hěn duō nián qīng rén xǐ huan tòu guò wǎng lù jiāo yǒu。', example_vietnamese = 'Hiện nay nhiều bạn trẻ thích kết bạn qua mạng.' WHERE level = 'B1' AND hanzi = '交友' AND pinyin = 'jiāoyǒu' AND vietnamese = 'Kết bạn';
UPDATE public.dictionary_words SET example_hanzi = '得了第一名以後，他變得有點驕傲。', example_pinyin = 'dé le dì yī míng yǐ hòu, tā biàn de yǒu diǎn jiāo ào。', example_vietnamese = 'Sau khi được hạng nhất, anh ấy trở nên hơi kiêu ngạo.' WHERE level = 'B1' AND hanzi = '驕傲' AND pinyin = 'jiāoào' AND vietnamese = 'Kiêu ngạo, kiêu căng';
UPDATE public.dictionary_words SET example_hanzi = '為了空間大一點，他們搬到郊區居住。', example_pinyin = 'wèi le kōng jiān dà yì diǎn, tā men bān dào jiāo qū jū zhù。', example_vietnamese = 'Để có không gian rộng hơn, họ chuyển đến sống ở vùng ngoại ô.' WHERE level = 'B1' AND hanzi = '郊區' AND pinyin = 'jiāoqū' AND vietnamese = 'Vùng ngoại ô';
UPDATE public.dictionary_words SET example_hanzi = '從不同的角度來看，這件事情有好也有壞。', example_pinyin = 'cóng bù tóng de jiǎo dù lái kàn, zhè jiàn shì qíng yǒu hǎo yě yǒu huài。', example_vietnamese = 'Nhìn từ những góc độ khác nhau, việc này vừa có mặt tốt vừa có mặt xấu.' WHERE level = 'B1' AND hanzi = '角度' AND pinyin = 'jiăodù' AND vietnamese = 'Góc độ, quan điểm';
UPDATE public.dictionary_words SET example_hanzi = '她在這部電影裡扮演一個很重要的角色。', example_pinyin = 'tā zài zhè bù diàn yǐng lǐ bàn yǎn yí ge hěn zhòng yào de jué sè。', example_vietnamese = 'Cô ấy đóng một vai rất quan trọng trong bộ phim này.' WHERE level = 'B1' AND hanzi = '角色' AND pinyin = 'jiăo/juésè' AND vietnamese = 'Nhân vật, kiểu người';
UPDATE public.dictionary_words SET example_hanzi = '媽媽在門口大聲叫我回家吃飯。', example_pinyin = 'mā ma zài mén kǒu dà shēng jiào wǒ huí jiā chī fàn。', example_vietnamese = 'Mẹ đứng ở cửa gọi to bảo tôi về nhà ăn cơm.' WHERE level = 'B1' AND hanzi = '叫' AND pinyin = 'jiào' AND vietnamese = 'Kêu, gọi';
UPDATE public.dictionary_words SET example_hanzi = '他痛得大叫一聲，嚇了大家一跳。', example_pinyin = 'tā tòng de dà jiào yì shēng, xià le dà jiā yí tiào。', example_vietnamese = 'Anh ấy đau đến mức hét lên một tiếng, làm mọi người giật mình.' WHERE level = 'B1' AND hanzi = '叫' AND pinyin = 'jiào' AND vietnamese = 'Hô hoán';
UPDATE public.dictionary_words SET example_hanzi = '這兩個方案，我比較喜歡第二個。', example_pinyin = 'zhè liǎng ge fāng àn, wǒ bǐ jiào xǐ huan dì èr ge。', example_vietnamese = 'Trong hai phương án này, tôi thích phương án thứ hai hơn.' WHERE level = 'B1' AND hanzi = '較' AND pinyin = 'jiào' AND vietnamese = 'So sánh';
UPDATE public.dictionary_words SET example_hanzi = '王老師教我們中文已經三年了。', example_pinyin = 'wáng lǎo shī jiào wǒ men zhōng wén yǐ jīng sān nián le。', example_vietnamese = 'Thầy Vương đã dạy chúng tôi tiếng Trung được ba năm rồi.' WHERE level = 'B1' AND hanzi = '教' AND pinyin = 'jiào' AND vietnamese = 'Dạy dỗ';
UPDATE public.dictionary_words SET example_hanzi = '這套教材內容豐富，很適合初學者。', example_pinyin = 'zhè tào jiào cái nèi róng fēng fù, hěn shì hé chū xué zhě。', example_vietnamese = 'Bộ tài liệu giảng dạy này nội dung phong phú, rất phù hợp cho người mới học.' WHERE level = 'B1' AND hanzi = '教材' AND pinyin = 'jiàocái' AND vietnamese = 'Tài liệu giảng dạy';
UPDATE public.dictionary_words SET example_hanzi = '老師耐心地教導每一位學生。', example_pinyin = 'lǎo shī nài xīn de jiào dǎo měi yí wèi xué shēng。', example_vietnamese = 'Thầy giáo kiên nhẫn chỉ bảo từng học sinh một.' WHERE level = 'B1' AND hanzi = '教導' AND pinyin = 'jiàodăo' AND vietnamese = 'Chỉ bảo, dạy bảo';
UPDATE public.dictionary_words SET example_hanzi = '這位老師的教法很活潑，學生都很喜歡上他的課。', example_pinyin = 'zhè wèi lǎo shī de jiào fǎ hěn huó po, xué shēng dōu hěn xǐ huan shàng tā de kè。', example_vietnamese = 'Phương pháp giảng dạy của thầy này rất sinh động, học sinh đều rất thích giờ học của thầy.' WHERE level = 'B1' AND hanzi = '教法' AND pinyin = 'jiàofă' AND vietnamese = 'Phương pháp giảng dạy';
UPDATE public.dictionary_words SET example_hanzi = '籃球隊的教練要求我們每天練習兩小時。', example_pinyin = 'lán qiú duì de jiào liàn yāo qiú wǒ men měi tiān liàn xí liǎng xiǎo shí。', example_vietnamese = 'Huấn luyện viên đội bóng rổ yêu cầu chúng tôi luyện tập hai tiếng mỗi ngày.' WHERE level = 'B1' AND hanzi = '教練' AND pinyin = 'jiàoliàn' AND vietnamese = 'Huấn luyện viên';
UPDATE public.dictionary_words SET example_hanzi = '這位教授在課堂上教授語言學的基礎知識。', example_pinyin = 'zhè wèi jiào shòu zài kè táng shàng jiāo shòu yǔ yán xué de jī chǔ zhī shi。', example_vietnamese = 'Vị giáo sư này giảng dạy kiến thức cơ bản về ngôn ngữ học trên lớp.' WHERE level = 'B1' AND hanzi = '教授' AND pinyin = 'jiàoshòu' AND vietnamese = 'Truyền thụ';
UPDATE public.dictionary_words SET example_hanzi = '這次失敗給了他一個很大的教訓。', example_pinyin = 'zhè cì shī bài gěi le tā yí ge hěn dà de jiào xun。', example_vietnamese = 'Thất bại lần này đã cho anh ấy một bài học lớn.' WHERE level = 'B1' AND hanzi = '教訓' AND pinyin = 'jiàoxun' AND vietnamese = 'Giáo huấn, dạy dỗ';
UPDATE public.dictionary_words SET example_hanzi = '這首歌很好聽。', example_pinyin = 'zhè shǒu gē hěn hǎotīng。', example_vietnamese = 'Bài hát này rất hay.' WHERE level = 'B1' AND hanzi = '首' AND pinyin = 'shǒu' AND vietnamese = 'Đầu, đứng đầu';
UPDATE public.dictionary_words SET example_hanzi = '冬天出門的時候，我會戴上手套。', example_pinyin = 'dōngtiān chūmén de shíhou，wǒ huì dàishàng shǒutào。', example_vietnamese = 'Vào mùa đông khi ra ngoài, tôi sẽ đeo găng tay.' WHERE level = 'B1' AND hanzi = '手套' AND pinyin = 'shŏutào' AND vietnamese = 'Găng tay, bao tay';
UPDATE public.dictionary_words SET example_hanzi = '辦簽證的手續有點麻煩。', example_pinyin = 'bàn qiānzhèng de shǒuxù yǒudiǎn máfan。', example_vietnamese = 'Thủ tục làm visa hơi phiền phức.' WHERE level = 'B1' AND hanzi = '手續' AND pinyin = 'shŏuxù' AND vietnamese = 'Thủ tục';
UPDATE public.dictionary_words SET example_hanzi = '你受得了這麼辣的食物嗎？', example_pinyin = 'nǐ shòudeliǎo zhème là de shíwù ma？', example_vietnamese = 'Bạn có chịu được đồ ăn cay như vậy không?' WHERE level = 'B1' AND hanzi = '受得了' AND pinyin = 'shòudeliao' AND vietnamese = 'Có thể chịu được';
UPDATE public.dictionary_words SET example_hanzi = '他把書包放在椅子上。', example_pinyin = 'tā bǎ shūbāo fàng zài yǐzi shàng。', example_vietnamese = 'Anh ấy đặt cặp sách lên ghế.' WHERE level = 'B1' AND hanzi = '書包' AND pinyin = 'shūbāo' AND vietnamese = 'Túi sách, cặp sách';
UPDATE public.dictionary_words SET example_hanzi = '這個書架上擺滿了小說。', example_pinyin = 'zhège shūjià shàng bǎimǎnle xiǎoshuō。', example_vietnamese = 'Giá sách này bày đầy tiểu thuyết.' WHERE level = 'B1' AND hanzi = '書架' AND pinyin = 'shūjià' AND vietnamese = 'Giá sách';
UPDATE public.dictionary_words SET example_hanzi = '醫生建議我多吃蔬菜，少吃肉。', example_pinyin = 'yīshēng jiànyì wǒ duō chī shūcài，shǎo chī ròu。', example_vietnamese = 'Bác sĩ khuyên tôi ăn nhiều rau, ít ăn thịt.' WHERE level = 'B1' AND hanzi = '蔬菜' AND pinyin = 'shūcài' AND vietnamese = 'Rau, rau cải';
UPDATE public.dictionary_words SET example_hanzi = '這家旅館的房間很舒適。', example_pinyin = 'zhè jiā lǚguǎn de fángjiān hěn shūshì。', example_vietnamese = 'Phòng của khách sạn này rất thoải mái.' WHERE level = 'B1' AND hanzi = '舒適' AND pinyin = 'shūshì' AND vietnamese = 'Dễ chịu, thoải mái';
UPDATE public.dictionary_words SET example_hanzi = '我叔叔在銀行工作。', example_pinyin = 'wǒ shúshu zài yínháng gōngzuò。', example_vietnamese = 'Chú tôi làm việc ở ngân hàng.' WHERE level = 'B1' AND hanzi = '叔叔' AND pinyin = 'shúshu' AND vietnamese = 'Chú';
UPDATE public.dictionary_words SET example_hanzi = '我對這座城市非常熟悉。', example_pinyin = 'wǒ duì zhè zuò chéngshì fēicháng shúxī。', example_vietnamese = 'Tôi rất quen thuộc với thành phố này.' WHERE level = 'B1' AND hanzi = '熟悉' AND pinyin = 'shoúxī' AND vietnamese = 'Hiểu rõ, quen thuộc';
UPDATE public.dictionary_words SET example_hanzi = '媽媽正在數桌上的錢。', example_pinyin = 'māma zhèngzài shǔ zhuō shàng de qián。', example_vietnamese = 'Mẹ đang đếm tiền trên bàn.' WHERE level = 'B1' AND hanzi = '數' AND pinyin = 'shŭ' AND vietnamese = 'Đếm';
UPDATE public.dictionary_words SET example_hanzi = '這張表格上的數字都對嗎？', example_pinyin = 'zhè zhāng biǎogé shàng de shùzì dōu duì ma？', example_vietnamese = 'Những con số trên tờ biểu này đều đúng chứ?' WHERE level = 'B1' AND hanzi = '數字' AND pinyin = 'shùzì' AND vietnamese = 'Chữ số, con số';
UPDATE public.dictionary_words SET example_hanzi = '公園裡的樹木長得很茂盛。', example_pinyin = 'gōngyuán lǐ de shùmù zhǎng de hěn màoshèng。', example_vietnamese = 'Cây cối trong công viên mọc rất um tùm.' WHERE level = 'B1' AND hanzi = '樹木' AND pinyin = 'shùmù' AND vietnamese = 'Cây cối';
UPDATE public.dictionary_words SET example_hanzi = '睡覺前一定要刷牙。', example_pinyin = 'shuìjiào qián yídìng yào shuāyá。', example_vietnamese = 'Trước khi ngủ nhất định phải đánh răng.' WHERE level = 'B1' AND hanzi = '刷牙' AND pinyin = 'shuāyá' AND vietnamese = 'Đánh răng';
UPDATE public.dictionary_words SET example_hanzi = '那個新來的老師長得很帥。', example_pinyin = 'nàge xīnlái de lǎoshī zhǎng de hěn shuài。', example_vietnamese = 'Thầy giáo mới đến đó trông rất đẹp trai.' WHERE level = 'B1' AND hanzi = '帥' AND pinyin = 'shuài' AND vietnamese = 'Đẹp trai';
UPDATE public.dictionary_words SET example_hanzi = '媽媽送我一雙新鞋。', example_pinyin = 'māma sòng wǒ yì shuāng xīn xié。', example_vietnamese = 'Mẹ tặng tôi một đôi giày mới.' WHERE level = 'B1' AND hanzi = '雙' AND pinyin = 'shuāng' AND vietnamese = 'Đôi, gấp đôi';
UPDATE public.dictionary_words SET example_hanzi = '我最喜歡吃媽媽包的水餃。', example_pinyin = 'wǒ zuì xǐhuan chī māma bāo de shuǐjiǎo。', example_vietnamese = 'Tôi thích nhất ăn sủi cảo mẹ gói.' WHERE level = 'B1' AND hanzi = '水餃' AND pinyin = 'shuĭjiăo' AND vietnamese = 'Bánh sủi cảo';
UPDATE public.dictionary_words SET example_hanzi = '他的中文水平已經很高了。', example_pinyin = 'tā de zhōngwén shuǐpíng yǐjīng hěn gāo le。', example_vietnamese = 'Trình độ tiếng Trung của anh ấy đã rất cao rồi.' WHERE level = 'B1' AND hanzi = '水平' AND pinyin = 'shuĭpíng' AND vietnamese = 'Trình độ';
UPDATE public.dictionary_words SET example_hanzi = '這場演唱會的水準非常高。', example_pinyin = 'zhè chǎng yǎnchànghuì de shuǐzhǔn fēicháng gāo。', example_vietnamese = 'Trình độ của buổi hòa nhạc này rất cao.' WHERE level = 'B1' AND hanzi = '水準' AND pinyin = 'shuĭzhŭn' AND vietnamese = 'Mực nước';
UPDATE public.dictionary_words SET example_hanzi = '我昨晚很晚才睡著。', example_pinyin = 'wǒ zuówǎn hěn wǎn cái shuìzháo。', example_vietnamese = 'Tối qua tôi rất muộn mới ngủ được.' WHERE level = 'B1' AND hanzi = '睡著' AND pinyin = 'shuìzháo' AND vietnamese = 'Ngủ';
UPDATE public.dictionary_words SET example_hanzi = '你去超市的話，順便幫我買瓶牛奶。', example_pinyin = 'nǐ qù chāoshì dehuà，shùnbiàn bāng wǒ mǎi píng niúnǎi。', example_vietnamese = 'Nếu bạn đi siêu thị, tiện thể mua giúp tôi một chai sữa.' WHERE level = 'B1' AND hanzi = '順便' AND pinyin = 'shùnbiàn' AND vietnamese = 'Thuận tiện, tiện thể';
UPDATE public.dictionary_words SET example_hanzi = '希望你的考試一切順利。', example_pinyin = 'xīwàng nǐ de kǎoshì yíqiè shùnlì。', example_vietnamese = 'Hy vọng kỳ thi của bạn mọi việc đều suôn sẻ.' WHERE level = 'B1' AND hanzi = '順利' AND pinyin = 'shùnlì' AND vietnamese = 'Thuận lợi, suôn sẻ';
UPDATE public.dictionary_words SET example_hanzi = '對於這件事，大家有不同的說法。', example_pinyin = 'duìyú zhè jiàn shì，dàjiā yǒu bùtóng de shuōfǎ。', example_vietnamese = 'Về việc này, mọi người có những cách nói khác nhau.' WHERE level = 'B1' AND hanzi = '說法' AND pinyin = 'shuōfă' AND vietnamese = 'Cách nói';
UPDATE public.dictionary_words SET example_hanzi = '請仔細閱讀產品上的說明。', example_pinyin = 'qǐng zǐxì yuèdú chǎnpǐn shàng de shuōmíng。', example_vietnamese = 'Xin hãy đọc kỹ phần thuyết minh trên sản phẩm.' WHERE level = 'B1' AND hanzi = '說明' AND pinyin = 'shuōmíng' AND vietnamese = 'Lời thuyết minh';
UPDATE public.dictionary_words SET example_hanzi = '老師詳細地說明了這個文法。', example_pinyin = 'lǎoshī xiángxì de shuōmíngle zhège wénfǎ。', example_vietnamese = 'Thầy giáo đã giải thích rõ ngữ pháp này một cách chi tiết.' WHERE level = 'B1' AND hanzi = '說明' AND pinyin = 'shuōmíng' AND vietnamese = 'Giải thích rõ, nói rõ';
UPDATE public.dictionary_words SET example_hanzi = '說起來，我們已經三年沒見面了。', example_pinyin = 'shuōqǐlái，wǒmen yǐjīng sān nián méi jiànmiàn le。', example_vietnamese = 'Nói đến thì, chúng tôi đã ba năm không gặp nhau rồi.' WHERE level = 'B1' AND hanzi = '說起來' AND pinyin = 'shuōqilai' AND vietnamese = 'Nói về, nói đến…';
UPDATE public.dictionary_words SET example_hanzi = '這個問題值得我們好好思考。', example_pinyin = 'zhège wèntí zhíde wǒmen hǎohǎo sīkǎo。', example_vietnamese = 'Vấn đề này đáng để chúng ta suy nghĩ kỹ.' WHERE level = 'B1' AND hanzi = '思考' AND pinyin = 'sīkăo' AND vietnamese = 'Suy xét, suy nghĩ';
UPDATE public.dictionary_words SET example_hanzi = '這本書介紹了很多西方哲學家的思想。', example_pinyin = 'zhè běn shū jièshàole hěn duō xīfāng zhéxuéjiā de sīxiǎng。', example_vietnamese = 'Cuốn sách này giới thiệu tư tưởng của nhiều triết gia phương Tây.' WHERE level = 'B1' AND hanzi = '思想' AND pinyin = 'sīxiăng' AND vietnamese = 'Tư tưởng, ý nghĩ';
UPDATE public.dictionary_words SET example_hanzi = '他今天似乎心情不太好。', example_pinyin = 'tā jīntiān sìhū xīnqíng bú tài hǎo。', example_vietnamese = 'Hôm nay anh ấy dường như tâm trạng không tốt lắm.' WHERE level = 'B1' AND hanzi = '似乎' AND pinyin = 'sìhū' AND vietnamese = 'Hình như, dường như';
UPDATE public.dictionary_words SET example_hanzi = '每逢過年，很多人會去寺廟拜拜。', example_pinyin = 'měiféng guònián，hěn duō rén huì qù sìmiào bàibài。', example_vietnamese = 'Mỗi dịp Tết, nhiều người sẽ đi chùa lễ bái.' WHERE level = 'B1' AND hanzi = '寺廟' AND pinyin = 'sìmiào' AND vietnamese = 'Chùa miếu';
UPDATE public.dictionary_words SET example_hanzi = '這輛車的速度太快了，很危險。', example_pinyin = 'zhè liàng chē de sùdù tài kuài le，hěn wēixiǎn。', example_vietnamese = 'Tốc độ của chiếc xe này quá nhanh, rất nguy hiểm.' WHERE level = 'B1' AND hanzi = '速度' AND pinyin = 'sùdù' AND vietnamese = 'Tốc độ';
UPDATE public.dictionary_words SET example_hanzi = '他不想道歉，算了，我們就別管了。', example_pinyin = 'tā bù xiǎng dàoqiàn，suànle，wǒmen jiù bié guǎn le。', example_vietnamese = 'Anh ta không muốn xin lỗi, thôi bỏ qua đi, chúng ta đừng để ý nữa.' WHERE level = 'B1' AND hanzi = '算了' AND pinyin = 'suànle' AND vietnamese = 'Để nó trôi qua đi, quên nó đi';
UPDATE public.dictionary_words SET example_hanzi = '你想吃什麼都可以，我隨便。', example_pinyin = 'nǐ xiǎng chī shénme dōu kěyǐ，wǒ suíbiàn。', example_vietnamese = 'Bạn muốn ăn gì cũng được, tôi tùy ý.' WHERE level = 'B1' AND hanzi = '隨便' AND pinyin = 'suíbiàn' AND vietnamese = 'Tùy thích, tùy ý';
UPDATE public.dictionary_words SET example_hanzi = '有問題可以隨時打電話給我。', example_pinyin = 'yǒu wèntí kěyǐ suíshí dǎ diànhuà gěi wǒ。', example_vietnamese = 'Có vấn đề gì có thể gọi điện cho tôi bất cứ lúc nào.' WHERE level = 'B1' AND hanzi = '隨時' AND pinyin = 'suíshí' AND vietnamese = 'Bất cứ lúc nào';
UPDATE public.dictionary_words SET example_hanzi = '這是我所知道的一切。', example_pinyin = 'zhè shì wǒ suǒ zhīdào de yíqiè。', example_vietnamese = 'Đây là tất cả những gì tôi biết.' WHERE level = 'B1' AND hanzi = '所' AND pinyin = 'suǒ' AND vietnamese = 'Chỗ, nơi, chốn';
UPDATE public.dictionary_words SET example_hanzi = '這所大學的歷史很悠久。', example_pinyin = 'zhè suǒ dàxué de lìshǐ hěn yōujiǔ。', example_vietnamese = 'Ngôi trường đại học này có lịch sử rất lâu đời.' WHERE level = 'B1' AND hanzi = '所' AND pinyin = 'suŏ' AND vietnamese = 'Ngôi, nhà, gian';
UPDATE public.dictionary_words SET example_hanzi = '所謂的成功，其實對每個人來說意義都不同。', example_pinyin = 'suǒwèi de chénggōng，qíshí duì měi ge rén láishuō yìyì dōu bùtóng。', example_vietnamese = 'Cái gọi là thành công, thực ra với mỗi người có ý nghĩa khác nhau.' WHERE level = 'B1' AND hanzi = '所謂' AND pinyin = 'suŏwèi' AND vietnamese = 'Cái gọi là, điều mà họ gọi là';
