UPDATE public.dictionary_words SET example_hanzi = '他買了一台新電腦。', example_pinyin = 'tā mǎile yì tái xīn diànnǎo。', example_vietnamese = 'Anh ấy đã mua một cái máy tính mới.' WHERE level = 'B1' AND hanzi = '台' AND pinyin = 'tái' AND vietnamese = 'Cái đài, bục, sân khấu';
