UPDATE public.dictionary_words SET example_hanzi = '聽說明天有颱風，學校決定停課。', example_pinyin = 'tīngshuō míngtiān yǒu táifēng，xuéxiào juédìng tíngkè。', example_vietnamese = 'Nghe nói ngày mai có bão, trường quyết định nghỉ học.' WHERE level = 'B1' AND hanzi = '颱風' AND pinyin = 'táifēng' AND vietnamese = 'Bão';
