UPDATE public.dictionary_words SET example_hanzi = '我最討厭下雨天出門。', example_pinyin = 'wǒ zuì tǎoyàn xiàyǔtiān chūmén。', example_vietnamese = 'Tôi ghét nhất là ra ngoài vào ngày mưa.' WHERE level = 'B1' AND hanzi = '討厭' AND pinyin = 'tǎoyàn' AND vietnamese = 'Ghét';
UPDATE public.dictionary_words SET example_hanzi = '她買了一套新衣服。', example_pinyin = 'tā mǎile yí tào xīn yīfu。', example_vietnamese = 'Cô ấy đã mua một bộ quần áo mới.' WHERE level = 'B1' AND hanzi = '套' AND pinyin = 'tào' AND vietnamese = 'Bộ, căn';
