UPDATE public.dictionary_words SET example_hanzi = '老師剛才提到的那本書我還沒看過。', example_pinyin = 'lǎoshī gāngcái tídào de nà běn shū wǒ hái méi kànguò。', example_vietnamese = 'Cuốn sách mà thầy vừa đề cập đến tôi vẫn chưa đọc.' WHERE level = 'B1' AND hanzi = '提到' AND pinyin = 'tídào' AND vietnamese = 'Đề cập đến';
UPDATE public.dictionary_words SET example_hanzi = '為了提高成績，他每天都努力讀書。', example_pinyin = 'wèile tígāo chéngjì，tā měitiān dōu nǔlì dúshū。', example_vietnamese = 'Để nâng cao thành tích, anh ấy ngày nào cũng chăm chỉ học bài.' WHERE level = 'B1' AND hanzi = '提高' AND pinyin = 'tígāo' AND vietnamese = 'Đề cao, nâng cao';
UPDATE public.dictionary_words SET example_hanzi = '學校提供免費的午餐給學生。', example_pinyin = 'xuéxiào tígōng miǎnfèi de wǔcān gěi xuésheng。', example_vietnamese = 'Trường cung cấp bữa trưa miễn phí cho học sinh.' WHERE level = 'B1' AND hanzi = '提供' AND pinyin = 'tígōng' AND vietnamese = 'Cung cấp';
UPDATE public.dictionary_words SET example_hanzi = '這部電影的題材很特別。', example_pinyin = 'zhè bù diànyǐng de tícái hěn tèbié。', example_vietnamese = 'Đề tài của bộ phim này rất đặc biệt.' WHERE level = 'B1' AND hanzi = '題材' AND pinyin = 'tícái' AND vietnamese = 'Đề tài';
UPDATE public.dictionary_words SET example_hanzi = '這次考試的題目有點難。', example_pinyin = 'zhè cì kǎoshì de tímù yǒudiǎn nán。', example_vietnamese = 'Đề thi lần này hơi khó.' WHERE level = 'B1' AND hanzi = '題目' AND pinyin = 'tímù' AND vietnamese = 'Đề mục, đầu đề';
UPDATE public.dictionary_words SET example_hanzi = '只有自己經歷過，才能真正體會那種痛苦。', example_pinyin = 'zhǐyǒu zìjǐ jīnglìguò，cái néng zhēnzhèng tǐhuì nà zhǒng tòngkǔ。', example_vietnamese = 'Chỉ khi tự mình trải qua, mới có thể thực sự lĩnh hội nỗi đau đó.' WHERE level = 'B1' AND hanzi = '體會' AND pinyin = 'tĭhuì' AND vietnamese = 'Hiểu, lĩnh hội';
