UPDATE public.dictionary_words SET example_hanzi = '他是一個很體貼的男朋友。', example_pinyin = 'tā shì yí ge hěn tǐtiē de nánpéngyou。', example_vietnamese = 'Anh ấy là một người bạn trai rất biết quan tâm.' WHERE level = 'B1' AND hanzi = '體貼' AND pinyin = 'tĭtiē' AND vietnamese = 'Săn sóc, quan tâm';
UPDATE public.dictionary_words SET example_hanzi = '她最近在減肥，體重輕了不少。', example_pinyin = 'tā zuìjìn zài jiǎnféi，tǐzhòng qīngle bùshǎo。', example_vietnamese = 'Gần đây cô ấy đang giảm cân, thể trọng nhẹ đi khá nhiều.' WHERE level = 'B1' AND hanzi = '體重' AND pinyin = 'tĭzhòng' AND vietnamese = 'Thể trọng, trọng lượng';
