UPDATE public.dictionary_words SET example_hanzi = '這個海邊簡直就像天堂一樣美。', example_pinyin = 'zhège hǎibiān jiǎnzhí jiù xiàng tiāntáng yíyàng měi。', example_vietnamese = 'Bãi biển này đẹp giống hệt như thiên đường.' WHERE level = 'B1' AND hanzi = '天堂' AND pinyin = 'tiāntáng' AND vietnamese = 'Thiên đường';
UPDATE public.dictionary_words SET example_hanzi = '他天天早上都去公園運動。', example_pinyin = 'tā tiāntiān zǎoshang dōu qù gōngyuán yùndòng。', example_vietnamese = 'Anh ấy sáng nào cũng đi tập thể dục ở công viên.' WHERE level = 'B1' AND hanzi = '天天' AND pinyin = 'tiāntiān' AND vietnamese = 'Mỗi ngày, hàng ngày';
UPDATE public.dictionary_words SET example_hanzi = '這件事很快就傳遍天下了。', example_pinyin = 'zhè jiàn shì hěn kuài jiù chuánbiàn tiānxià le。', example_vietnamese = 'Chuyện này rất nhanh đã lan truyền khắp thiên hạ.' WHERE level = 'B1' AND hanzi = '天下' AND pinyin = 'tiānxià' AND vietnamese = 'Thiên hạ';
UPDATE public.dictionary_words SET example_hanzi = '農夫每天都要去田裡工作。', example_pinyin = 'nóngfū měitiān dōu yào qù tián lǐ gōngzuò。', example_vietnamese = 'Người nông dân ngày nào cũng phải ra ruộng làm việc.' WHERE level = 'B1' AND hanzi = '田' AND pinyin = 'tián' AND vietnamese = 'Ruộng, đồng';
UPDATE public.dictionary_words SET example_hanzi = '請在這張表格上填上你的名字。', example_pinyin = 'qǐng zài zhè zhāng biǎogé shàng tiánshàng nǐ de míngzi。', example_vietnamese = 'Xin hãy điền tên của bạn vào tờ biểu này.' WHERE level = 'B1' AND hanzi = '填' AND pinyin = 'tián' AND vietnamese = 'Điền vào, ghi vào';
