UPDATE public.dictionary_words SET example_hanzi = '這個問題我同樣也不知道答案。', example_pinyin = 'zhège wèntí wǒ tóngyàng yě bù zhīdào dá''àn。', example_vietnamese = 'Vấn đề này tôi cũng không biết đáp án, giống như bạn vậy.' WHERE level = 'B1' AND hanzi = '同樣' AND pinyin = 'tóngyàng' AND vietnamese = 'Giống nhau, như nhau';
