UPDATE public.dictionary_words SET example_hanzi = '失去親人是一件非常痛苦的事。', example_pinyin = 'shīqù qīnrén shì yí jiàn fēicháng tòngkǔ de shì。', example_vietnamese = 'Mất đi người thân là một chuyện vô cùng đau khổ.' WHERE level = 'B1' AND hanzi = '痛苦' AND pinyin = 'tòngkǔ' AND vietnamese = 'Đau khổ';
UPDATE public.dictionary_words SET example_hanzi = '他把垃圾投進垃圾桶。', example_pinyin = 'tā bǎ lèsè tóujìn lèsètǒng。', example_vietnamese = 'Anh ấy ném rác vào thùng rác.' WHERE level = 'B1' AND hanzi = '投' AND pinyin = 'tóu' AND vietnamese = 'Ném, quăng, bỏ vào';
UPDATE public.dictionary_words SET example_hanzi = '他決定把錢投資在房地產上。', example_pinyin = 'tā juédìng bǎ qián tóuzī zài fángdìchǎn shàng。', example_vietnamese = 'Anh ấy quyết định đầu tư tiền vào bất động sản.' WHERE level = 'B1' AND hanzi = '投資' AND pinyin = 'tóuzī' AND vietnamese = 'Đầu tư';
UPDATE public.dictionary_words SET example_hanzi = '頭幾天他還不太習慣新工作。', example_pinyin = 'tóu jǐ tiān tā hái bú tài xíguàn xīn gōngzuò。', example_vietnamese = 'Mấy ngày đầu anh ấy vẫn chưa quen lắm với công việc mới.' WHERE level = 'B1' AND hanzi = '頭' AND pinyin = 'tóu' AND vietnamese = 'Đầu';
UPDATE public.dictionary_words SET example_hanzi = '我今天有點頭痛，想早點休息。', example_pinyin = 'wǒ jīntiān yǒudiǎn tóutòng，xiǎng zǎodiǎn xiūxi。', example_vietnamese = 'Hôm nay tôi hơi đau đầu, muốn nghỉ sớm một chút.' WHERE level = 'B1' AND hanzi = '頭痛' AND pinyin = 'tóutòng' AND vietnamese = 'Đau đầu, nhức đầu';
