UPDATE public.dictionary_words SET example_hanzi = '他突然站起來，嚇了大家一跳。', example_pinyin = 'tā tūrán zhàn qǐlái，xiàle dàjiā yí tiào。', example_vietnamese = 'Anh ấy đột nhiên đứng dậy, làm mọi người giật mình.' WHERE level = 'B1' AND hanzi = '突然' AND pinyin = 'túrán' AND vietnamese = 'Đột nhiên, bỗng nhiên';
UPDATE public.dictionary_words SET example_hanzi = '這裡的土很適合種菜。', example_pinyin = 'zhèlǐ de tǔ hěn shìhé zhòngcài。', example_vietnamese = 'Đất ở đây rất thích hợp để trồng rau.' WHERE level = 'B1' AND hanzi = '土' AND pinyin = 'tǔ' AND vietnamese = 'Đất đai';
UPDATE public.dictionary_words SET example_hanzi = '這片土地是他爺爺留下來的。', example_pinyin = 'zhè piàn tǔdì shì tā yéye liú xiàlái de。', example_vietnamese = 'Mảnh đất đai này là ông nội anh ấy để lại.' WHERE level = 'B1' AND hanzi = '土地' AND pinyin = 'tǔdì' AND vietnamese = 'Ruộng đất, đất đai';
