UPDATE public.dictionary_words SET example_hanzi = '過年的時候，一家人終於團圓了。', example_pinyin = 'guònián de shíhou，yì jiā rén zhōngyú tuányuán le。', example_vietnamese = 'Vào dịp Tết, cả nhà cuối cùng cũng được đoàn viên.' WHERE level = 'B1' AND hanzi = '團圓' AND pinyin = 'tuányuán' AND vietnamese = 'Đoàn viên, sum họp';
UPDATE public.dictionary_words SET example_hanzi = '他用力推開了那扇門。', example_pinyin = 'tā yònglì tuīkāile nà shàn mén。', example_vietnamese = 'Anh ấy dùng sức đẩy mở cánh cửa đó.' WHERE level = 'B1' AND hanzi = '推' AND pinyin = 'tuī' AND vietnamese = 'Đẩy';
UPDATE public.dictionary_words SET example_hanzi = '你可以推薦一家好吃的餐廳嗎？', example_pinyin = 'nǐ kěyǐ tuījiàn yì jiā hǎochī de cāntīng ma？', example_vietnamese = 'Bạn có thể giới thiệu một nhà hàng ngon không?' WHERE level = 'B1' AND hanzi = '推薦' AND pinyin = 'tuījiàn' AND vietnamese = 'Tiến cử, đề xuất, giới thiệu';
