UPDATE public.dictionary_words SET example_hanzi = '他最近的成績退步了不少。', example_pinyin = 'tā zuìjìn de chéngjì tuìbùle bùshǎo。', example_vietnamese = 'Thành tích gần đây của anh ấy giảm sút khá nhiều.' WHERE level = 'B1' AND hanzi = '退步' AND pinyin = 'tuìbù' AND vietnamese = 'Nhượng bộ, lùi bước';
