UPDATE public.dictionary_words SET example_hanzi = '進門前請先脫鞋。', example_pinyin = 'jìnmén qián qǐng xiān tuō xié。', example_vietnamese = 'Trước khi vào nhà xin hãy cởi giày trước.' WHERE level = 'B1' AND hanzi = '脫' AND pinyin = 'tuō' AND vietnamese = 'Rụng, tróc, cởi ra';
UPDATE public.dictionary_words SET example_hanzi = '妹妹每天晚上都抱著娃娃睡覺。', example_pinyin = 'mèimei měitiān wǎnshang dōu bàozhe wáwa shuìjiào。', example_vietnamese = 'Em gái tối nào cũng ôm búp bê để ngủ.' WHERE level = 'B1' AND hanzi = '娃娃' AND pinyin = 'wáwa' AND vietnamese = 'Em bé, búp bê';
UPDATE public.dictionary_words SET example_hanzi = '外邊在下雨，你先別出去。', example_pinyin = 'wàibiān zài xiàyǔ，nǐ xiān bié chūqù。', example_vietnamese = 'Bên ngoài đang mưa, bạn đừng ra ngoài vội.' WHERE level = 'B1' AND hanzi = '外邊' AND pinyin = 'wàibiān' AND vietnamese = 'Bên ngoài';
UPDATE public.dictionary_words SET example_hanzi = '我外公喜歡在院子裡種花。', example_pinyin = 'wǒ wàigōng xǐhuan zài yuànzi lǐ zhòng huā。', example_vietnamese = 'Ông ngoại tôi thích trồng hoa trong sân.' WHERE level = 'B1' AND hanzi = '外公' AND pinyin = 'wàigōng' AND vietnamese = 'Ông ngoại';
UPDATE public.dictionary_words SET example_hanzi = '每年暑假我都會去外婆家住幾天。', example_pinyin = 'měinián shǔjià wǒ dōu huì qù wàipó jiā zhù jǐ tiān。', example_vietnamese = 'Mỗi kỳ nghỉ hè tôi đều đến nhà bà ngoại ở vài ngày.' WHERE level = 'B1' AND hanzi = '外婆' AND pinyin = 'wàipó' AND vietnamese = 'Bà ngoại';
UPDATE public.dictionary_words SET example_hanzi = '這本書是用外文寫的，我看不太懂。', example_pinyin = 'zhè běn shū shì yòng wàiwén xiě de，wǒ kàn bú tài dǒng。', example_vietnamese = 'Cuốn sách này được viết bằng ngoại văn, tôi đọc không hiểu lắm.' WHERE level = 'B1' AND hanzi = '外文' AND pinyin = 'wàiwén' AND vietnamese = 'Ngoại văn, chữ nước ngoài';
UPDATE public.dictionary_words SET example_hanzi = '學好一門外語需要花很多時間。', example_pinyin = 'xuéhǎo yì mén wàiyǔ xūyào huā hěn duō shíjiān。', example_vietnamese = 'Học giỏi một ngoại ngữ cần tốn rất nhiều thời gian.' WHERE level = 'B1' AND hanzi = '外語' AND pinyin = 'wàiyǔ' AND vietnamese = 'Ngoại ngữ';
UPDATE public.dictionary_words SET example_hanzi = '他終於在期限前完成了報告。', example_pinyin = 'tā zhōngyú zài qīxiàn qián wánchéngle bàogào。', example_vietnamese = 'Anh ấy cuối cùng đã hoàn thành báo cáo trước thời hạn.' WHERE level = 'B1' AND hanzi = '完成' AND pinyin = 'wánchéng' AND vietnamese = 'Hoàn thành';
UPDATE public.dictionary_words SET example_hanzi = '我完全不知道發生了什麼事。', example_pinyin = 'wǒ wánquán bù zhīdào fāshēngle shénme shì。', example_vietnamese = 'Tôi hoàn toàn không biết đã xảy ra chuyện gì.' WHERE level = 'B1' AND hanzi = '完全' AND pinyin = 'wánquán' AND vietnamese = 'Đầy đủ, trọn vẹn';
UPDATE public.dictionary_words SET example_hanzi = '弟弟的房間裡堆滿了玩具。', example_pinyin = 'dìdi de fángjiān lǐ duīmǎnle wánjù。', example_vietnamese = 'Phòng của em trai chất đầy đồ chơi.' WHERE level = 'B1' AND hanzi = '玩具' AND pinyin = 'wánjù' AND vietnamese = 'Đồ chơi';
UPDATE public.dictionary_words SET example_hanzi = '對不起，我今天出門晚了，所以遲到了。', example_pinyin = 'duìbuqǐ，wǒ jīntiān chūmén wǎnle，suǒyǐ chídào le。', example_vietnamese = 'Xin lỗi, hôm nay tôi ra khỏi nhà trễ nên bị muộn.' WHERE level = 'B1' AND hanzi = '晚' AND pinyin = 'wǎn' AND vietnamese = 'Tối, muộn, trễ';
UPDATE public.dictionary_words SET example_hanzi = '你出門記得帶傘，萬一下雨呢。', example_pinyin = 'nǐ chūmén jìde dài sǎn，wànyī xiàyǔ ne。', example_vietnamese = 'Bạn ra ngoài nhớ mang ô, nhỡ đâu trời mưa.' WHERE level = 'B1' AND hanzi = '萬一' AND pinyin = 'wànyī' AND vietnamese = 'Nhỡ đâu, ngộ nhỡ';
UPDATE public.dictionary_words SET example_hanzi = '漁夫把網撒進海裡。', example_pinyin = 'yúfū bǎ wǎng sājìn hǎilǐ。', example_vietnamese = 'Người ngư dân thả lưới xuống biển.' WHERE level = 'B1' AND hanzi = '網' AND pinyin = 'wăng' AND vietnamese = 'Lưới';
UPDATE public.dictionary_words SET example_hanzi = '這裡的網路速度很慢。', example_pinyin = 'zhèlǐ de wǎnglù sùdù hěn màn。', example_vietnamese = 'Tốc độ mạng ở đây rất chậm.' WHERE level = 'B1' AND hanzi = '網路' AND pinyin = 'wănglù' AND vietnamese = 'Mạng lưới';
UPDATE public.dictionary_words SET example_hanzi = '忙起來的時候，他往往會忘記吃飯。', example_pinyin = 'máng qǐlái de shíhou，tā wǎngwǎng huì wàngjì chīfàn。', example_vietnamese = 'Khi bận rộn, anh ấy thường hay quên ăn cơm.' WHERE level = 'B1' AND hanzi = '往往' AND pinyin = 'wăngwăng' AND vietnamese = 'Thường thường';
UPDATE public.dictionary_words SET example_hanzi = '我忘記帶鑰匙了，進不去家門。', example_pinyin = 'wǒ wàngjì dài yàoshi le，jìnbúqù jiāmén。', example_vietnamese = 'Tôi quên mang chìa khóa rồi, không vào được cửa nhà.' WHERE level = 'B1' AND hanzi = '忘記' AND pinyin = 'wàngjì' AND vietnamese = 'Quên, không nhớ';
UPDATE public.dictionary_words SET example_hanzi = '他每天運動，努力維持身材。', example_pinyin = 'tā měitiān yùndòng，nǔlì wéichí shēncái。', example_vietnamese = 'Anh ấy tập thể dục mỗi ngày, cố gắng duy trì vóc dáng.' WHERE level = 'B1' AND hanzi = '維持' AND pinyin = 'wéichí' AND vietnamese = 'Duy trì';
UPDATE public.dictionary_words SET example_hanzi = '她對著鏡子練習微笑。', example_pinyin = 'tā duìzhe jìngzi liànxí wéixiào。', example_vietnamese = 'Cô ấy tập mỉm cười trước gương.' WHERE level = 'B1' AND hanzi = '微笑' AND pinyin = 'wéixiào' AND vietnamese = 'Mỉm cười';
UPDATE public.dictionary_words SET example_hanzi = '這家店的菜以川菜為主。', example_pinyin = 'zhè jiā diàn de cài yǐ chuāncài wéizhǔ。', example_vietnamese = 'Món ăn của quán này chủ yếu là món Tứ Xuyên.' WHERE level = 'B1' AND hanzi = '為主' AND pinyin = 'wéizhŭ' AND vietnamese = 'Chủ yếu dựa vào';
UPDATE public.dictionary_words SET example_hanzi = '這位科學家對人類做出了偉大的貢獻。', example_pinyin = 'zhè wèi kēxuéjiā duì rénlèi zuòchūle wěidà de gòngxiàn。', example_vietnamese = 'Nhà khoa học này đã có những cống hiến vĩ đại cho nhân loại.' WHERE level = 'B1' AND hanzi = '偉大' AND pinyin = 'wěidà' AND vietnamese = 'Vĩ đại, lớn lao';
UPDATE public.dictionary_words SET example_hanzi = '大家都選她為代表。', example_pinyin = 'dàjiā dōu xuǎn tā wéi dàibiǎo。', example_vietnamese = 'Mọi người đều bầu chọn cô ấy làm đại diện.' WHERE level = 'B1' AND hanzi = '為' AND pinyin = 'wèi' AND vietnamese = 'Thành, biến thành';
UPDATE public.dictionary_words SET example_hanzi = '沒有人知道未來會發生什麼事。', example_pinyin = 'méiyǒu rén zhīdào wèilái huì fāshēng shénme shì。', example_vietnamese = 'Không ai biết tương lai sẽ xảy ra chuyện gì.' WHERE level = 'B1' AND hanzi = '未來' AND pinyin = 'wèilái' AND vietnamese = 'Tương lai';
UPDATE public.dictionary_words SET example_hanzi = '這家店的位置很方便，離捷運站很近。', example_pinyin = 'zhè jiā diàn de wèizhì hěn fāngbiàn，lí jiéyùnzhàn hěn jìn。', example_vietnamese = 'Vị trí của cửa hàng này rất tiện, gần ga tàu điện ngầm.' WHERE level = 'B1' AND hanzi = '位置' AND pinyin = 'wèizhì' AND vietnamese = 'Vị trí';
UPDATE public.dictionary_words SET example_hanzi = '電影院裡還有幾個空位子。', example_pinyin = 'diànyǐngyuàn lǐ hái yǒu jǐ ge kòng wèizi。', example_vietnamese = 'Trong rạp chiếu phim vẫn còn vài chỗ trống.' WHERE level = 'B1' AND hanzi = '位子' AND pinyin = 'wèizi' AND vietnamese = 'Chỗ ngồi';
UPDATE public.dictionary_words SET example_hanzi = '她說話的語氣總是很溫柔。', example_pinyin = 'tā shuōhuà de yǔqì zǒngshì hěn wēnróu。', example_vietnamese = 'Giọng nói của cô ấy luôn rất dịu dàng.' WHERE level = 'B1' AND hanzi = '溫柔' AND pinyin = 'wēnróu' AND vietnamese = 'Dịu dàng';
UPDATE public.dictionary_words SET example_hanzi = '請把這些文件放在我的桌上。', example_pinyin = 'qǐng bǎ zhèxiē wénjiàn fàng zài wǒ de zhuō shàng。', example_vietnamese = 'Xin hãy để những tài liệu này lên bàn của tôi.' WHERE level = 'B1' AND hanzi = '文件' AND pinyin = 'wénjiàn' AND vietnamese = 'Văn kiện, tài liệu';
UPDATE public.dictionary_words SET example_hanzi = '她大學主修中國文學。', example_pinyin = 'tā dàxué zhǔxiū zhōngguó wénxué。', example_vietnamese = 'Cô ấy học chuyên ngành văn học Trung Quốc ở đại học.' WHERE level = 'B1' AND hanzi = '文學' AND pinyin = 'wénxué' AND vietnamese = 'Văn học';
UPDATE public.dictionary_words SET example_hanzi = '這種古老的文字現在很少人懂。', example_pinyin = 'zhè zhǒng gǔlǎo de wénzì xiànzài hěn shǎo rén dǒng。', example_vietnamese = 'Loại chữ viết cổ này bây giờ rất ít người hiểu.' WHERE level = 'B1' AND hanzi = '文字' AND pinyin = 'wénzì' AND vietnamese = 'Chữ viết';
UPDATE public.dictionary_words SET example_hanzi = '我聞到廚房傳來陣陣香味。', example_pinyin = 'wǒ wéndào chúfáng chuánlái zhènzhèn xiāngwèi。', example_vietnamese = 'Tôi ngửi thấy mùi thơm nồng nàn tỏa ra từ bếp.' WHERE level = 'B1' AND hanzi = '聞' AND pinyin = 'wén' AND vietnamese = 'Nghe thấy';
UPDATE public.dictionary_words SET example_hanzi = '現在的工作雖然辛苦，但收入很穩定。', example_pinyin = 'xiànzài de gōngzuò suīrán xīnkǔ，dàn shōurù hěn wěndìng。', example_vietnamese = 'Công việc hiện tại tuy vất vả nhưng thu nhập rất ổn định.' WHERE level = 'B1' AND hanzi = '穩定' AND pinyin = 'wěndìng' AND vietnamese = 'ổn định';
UPDATE public.dictionary_words SET example_hanzi = '見到老師的時候，記得要問好。', example_pinyin = 'jiàndào lǎoshī de shíhou，jìde yào wènhǎo。', example_vietnamese = 'Khi gặp thầy cô, nhớ phải chào hỏi.' WHERE level = 'B1' AND hanzi = '問好' AND pinyin = 'wènhăo' AND vietnamese = 'Chào hỏi, gửi lời hỏi thăm';
UPDATE public.dictionary_words SET example_hanzi = '過年的時候，親戚朋友會互相問候。', example_pinyin = 'guònián de shíhou，qīnqi péngyou huì hùxiāng wènhòu。', example_vietnamese = 'Vào dịp Tết, họ hàng bạn bè sẽ hỏi thăm lẫn nhau.' WHERE level = 'B1' AND hanzi = '問候' AND pinyin = 'wènhòu' AND vietnamese = 'Chào hỏi, gửi lời hỏi thăm';
UPDATE public.dictionary_words SET example_hanzi = '兩位總統見面時互相握手。', example_pinyin = 'liǎng wèi zǒngtǒng jiànmiàn shí hùxiāng wòshǒu。', example_vietnamese = 'Hai vị tổng thống khi gặp nhau đã bắt tay nhau.' WHERE level = 'B1' AND hanzi = '握手' AND pinyin = 'wòshǒu' AND vietnamese = 'Bắt tay, cầm tay';
UPDATE public.dictionary_words SET example_hanzi = '這間屋子雖然小，但很溫馨。', example_pinyin = 'zhè jiān wūzi suīrán xiǎo，dàn hěn wēnxīn。', example_vietnamese = 'Căn phòng này tuy nhỏ nhưng rất ấm cúng.' WHERE level = 'B1' AND hanzi = '屋子' AND pinyin = 'wūzi' AND vietnamese = 'Gian nhà, gian phòng';
UPDATE public.dictionary_words SET example_hanzi = '他對這件事無話可說。', example_pinyin = 'tā duì zhè jiàn shì wú huà kě shuō。', example_vietnamese = 'Về việc này anh ấy không có gì để nói.' WHERE level = 'B1' AND hanzi = '無' AND pinyin = 'wú' AND vietnamese = 'Không có';
UPDATE public.dictionary_words SET example_hanzi = '我無法接受這樣的結果。', example_pinyin = 'wǒ wúfǎ jiēshòu zhèyàng de jiéguǒ。', example_vietnamese = 'Tôi không thể chấp nhận kết quả như vậy.' WHERE level = 'B1' AND hanzi = '無法' AND pinyin = 'wúfă' AND vietnamese = 'Vô phương, không còn cách nào';
UPDATE public.dictionary_words SET example_hanzi = '無論如何，我都會支持你的決定。', example_pinyin = 'wúlùn rúhé，wǒ dōu huì zhīchí nǐ de juédìng。', example_vietnamese = 'Dù thế nào đi nữa, tôi cũng sẽ ủng hộ quyết định của bạn.' WHERE level = 'B1' AND hanzi = '無論如何' AND pinyin = 'wúlùnrúhé' AND vietnamese = 'Bất kể như thế nào';
UPDATE public.dictionary_words SET example_hanzi = '大自然的美麗是無窮的。', example_pinyin = 'dà zìrán de měilì shì wúqióng de。', example_vietnamese = 'Vẻ đẹp của thiên nhiên là vô tận.' WHERE level = 'B1' AND hanzi = '無窮' AND pinyin = 'wúqióng' AND vietnamese = 'Vô cùng, vô hạn';
UPDATE public.dictionary_words SET example_hanzi = '你要選哪一家餐廳都無所謂，我都可以。', example_pinyin = 'nǐ yào xuǎn nǎ yì jiā cāntīng dōu wúsuǒwèi，wǒ dōu kěyǐ。', example_vietnamese = 'Bạn chọn nhà hàng nào cũng không sao, tôi đều được.' WHERE level = 'B1' AND hanzi = '無所謂' AND pinyin = 'wúsuŏwèi' AND vietnamese = 'Không sao cả, không quan trọng';
UPDATE public.dictionary_words SET example_hanzi = '這只是一場誤會，我沒有生氣。', example_pinyin = 'zhè zhǐshì yì chǎng wùhuì，wǒ méiyǒu shēngqì。', example_vietnamese = 'Đây chỉ là một sự hiểu lầm, tôi không giận đâu.' WHERE level = 'B1' AND hanzi = '誤會' AND pinyin = 'wùhuì' AND vietnamese = 'Sự hiểu lầm';
UPDATE public.dictionary_words SET example_hanzi = '最近物價一直上漲，生活壓力變大了。', example_pinyin = 'zuìjìn wùjià yìzhí shàngzhǎng，shēnghuó yālì biàn dà le。', example_vietnamese = 'Gần đây vật giá liên tục tăng, áp lực cuộc sống trở nên lớn hơn.' WHERE level = 'B1' AND hanzi = '物價' AND pinyin = 'wùjià' AND vietnamese = 'Vật giá, giá cả';
UPDATE public.dictionary_words SET example_hanzi = '這股冷氣團是從西北方來的。', example_pinyin = 'zhè gǔ lěngqìtuán shì cóng xīběifāng lái de。', example_vietnamese = 'Đợt không khí lạnh này đến từ hướng tây bắc.' WHERE level = 'B1' AND hanzi = '西北' AND pinyin = 'xīběi' AND vietnamese = 'Tây bắc';
UPDATE public.dictionary_words SET example_hanzi = '她第一次約會就選了一家西餐廳。', example_pinyin = 'tā dìyīcì yuēhuì jiù xuǎnle yì jiā xīcāntīng。', example_vietnamese = 'Lần hẹn hò đầu tiên cô ấy đã chọn một nhà hàng món Tây.' WHERE level = 'B1' AND hanzi = '西餐' AND pinyin = 'xīcān' AND vietnamese = 'Món Tây';
UPDATE public.dictionary_words SET example_hanzi = '這種節日習俗來自西方國家。', example_pinyin = 'zhè zhǒng jiérì xísú láizì xīfāng guójiā。', example_vietnamese = 'Phong tục lễ hội này bắt nguồn từ các nước phương Tây.' WHERE level = 'B1' AND hanzi = '西方' AND pinyin = 'xīfāng' AND vietnamese = 'Phương Tây';
UPDATE public.dictionary_words SET example_hanzi = '颱風正朝西南方向移動。', example_pinyin = 'táifēng zhèng cháo xīnán fāngxiàng yídòng。', example_vietnamese = 'Cơn bão đang di chuyển theo hướng tây nam.' WHERE level = 'B1' AND hanzi = '西南' AND pinyin = 'xīnán' AND vietnamese = 'Tây Nam';
UPDATE public.dictionary_words SET example_hanzi = '吸毒對身體的傷害非常大。', example_pinyin = 'xīdú duì shēntǐ de shānghài fēicháng dà。', example_vietnamese = 'Hút ma túy gây tổn hại rất lớn cho cơ thể.' WHERE level = 'B1' AND hanzi = '吸毒' AND pinyin = 'xīdú' AND vietnamese = 'Hút (chích) ma túy';
UPDATE public.dictionary_words SET example_hanzi = '多喝水有助於身體吸收營養。', example_pinyin = 'duō hē shuǐ yǒuzhùyú shēntǐ xīshōu yíngyǎng。', example_vietnamese = 'Uống nhiều nước giúp cơ thể hấp thu dinh dưỡng.' WHERE level = 'B1' AND hanzi = '吸收' AND pinyin = 'xīshōu' AND vietnamese = 'Hấp thu';
UPDATE public.dictionary_words SET example_hanzi = '這家店的櫥窗設計吸引了不少路人。', example_pinyin = 'zhè jiā diàn de chúchuāng shèjì xīyǐnle bùshǎo lùrén。', example_vietnamese = 'Thiết kế tủ kính của cửa hàng này thu hút không ít người đi đường.' WHERE level = 'B1' AND hanzi = '吸引' AND pinyin = 'xīyĭn' AND vietnamese = 'Hấp dẫn, thu hút';
UPDATE public.dictionary_words SET example_hanzi = '父母為了孩子往往願意犧牲自己的時間。', example_pinyin = 'fùmǔ wèile háizi wǎngwǎng yuànyì xīshēng zìjǐ de shíjiān。', example_vietnamese = 'Cha mẹ vì con cái thường sẵn lòng hy sinh thời gian của mình.' WHERE level = 'B1' AND hanzi = '犧牲' AND pinyin = 'xīshēng' AND vietnamese = 'Hi sinh';
UPDATE public.dictionary_words SET example_hanzi = '他心裡還抱著一絲希望。', example_pinyin = 'tā xīnlǐ hái bàozhe yì sī xīwàng。', example_vietnamese = 'Trong lòng anh ấy vẫn còn ôm một tia hy vọng.' WHERE level = 'B1' AND hanzi = '希望' AND pinyin = 'xīwàng' AND vietnamese = 'Hi vọng, mong muốn';
UPDATE public.dictionary_words SET example_hanzi = '這部卡通深受小朋友的喜愛。', example_pinyin = 'zhè bù kǎtōng shēn shòu xiǎopéngyǒu de xǐài。', example_vietnamese = 'Bộ phim hoạt hình này được các em nhỏ rất yêu thích.' WHERE level = 'B1' AND hanzi = '喜愛' AND pinyin = 'xĭài' AND vietnamese = 'Yêu thích, quý mến';
UPDATE public.dictionary_words SET example_hanzi = '她的手指又細又長。', example_pinyin = 'tā de shǒuzhǐ yòu xì yòu cháng。', example_vietnamese = 'Ngón tay của cô ấy vừa mảnh vừa dài.' WHERE level = 'B1' AND hanzi = '細' AND pinyin = 'xì' AND vietnamese = 'Nhỏ, mảnh';
UPDATE public.dictionary_words SET example_hanzi = '護士細心地照顧每一位病人。', example_pinyin = 'hùshi xìxīn de zhàogù měi yí wèi bìngrén。', example_vietnamese = 'Y tá chăm sóc từng bệnh nhân một cách tỉ mỉ.' WHERE level = 'B1' AND hanzi = '細心' AND pinyin = 'xìxīn' AND vietnamese = 'Cẩn thận, tỉ mỉ';
UPDATE public.dictionary_words SET example_hanzi = '這齣戲的劇情十分感人。', example_pinyin = 'zhè chū xì de jùqíng shífēn gǎnrén。', example_vietnamese = 'Nội dung vở kịch này vô cùng cảm động.' WHERE level = 'B1' AND hanzi = '戲' AND pinyin = 'xì' AND vietnamese = 'Trò chơi';
UPDATE public.dictionary_words SET example_hanzi = '他從小就對戲劇表演很有興趣。', example_pinyin = 'tā cóngxiǎo jiù duì xìjù biǎoyǎn hěn yǒu xìngqù。', example_vietnamese = 'Anh ấy từ nhỏ đã rất hứng thú với biểu diễn kịch nghệ.' WHERE level = 'B1' AND hanzi = '戲劇' AND pinyin = 'xìjù' AND vietnamese = 'Kịch, hí kịch';
UPDATE public.dictionary_words SET example_hanzi = '公司的電腦系統昨天當機了。', example_pinyin = 'gōngsī de diànnǎo xìtǒng zuótiān dāngjī le。', example_vietnamese = 'Hệ thống máy tính của công ty hôm qua bị treo máy.' WHERE level = 'B1' AND hanzi = '系統' AND pinyin = 'xìtŏng' AND vietnamese = 'Hệ thống';
UPDATE public.dictionary_words SET example_hanzi = '我們下個月要搬新家了。', example_pinyin = 'wǒmen xià ge yuè yào bān xīn jiā le。', example_vietnamese = 'Tháng sau chúng tôi sẽ chuyển đến nhà mới.' WHERE level = 'B1' AND hanzi = '下' AND pinyin = 'xià' AND vietnamese = 'Dưới';
UPDATE public.dictionary_words SET example_hanzi = '他在門上敲了兩下。', example_pinyin = 'tā zài mén shàng qiāole liǎng xià。', example_vietnamese = 'Anh ấy gõ cửa hai cái.' WHERE level = 'B1' AND hanzi = '下' AND pinyin = 'xià' AND vietnamese = 'Lần, cái';
UPDATE public.dictionary_words SET example_hanzi = '你先坐下，慢慢說。', example_pinyin = 'nǐ xiān zuòxià，mànman shuō。', example_vietnamese = 'Bạn ngồi xuống trước đã, từ từ nói.' WHERE level = 'B1' AND hanzi = '下' AND pinyin = 'xià' AND vietnamese = 'xuống, đặt xuống';
UPDATE public.dictionary_words SET example_hanzi = '外面下雪了，好漂亮。', example_pinyin = 'wàimiàn xiàxuě le，hǎo piàoliang。', example_vietnamese = 'Bên ngoài tuyết rơi rồi, đẹp quá.' WHERE level = 'B1' AND hanzi = '下' AND pinyin = 'xià' AND vietnamese = 'Hạ xuống';
UPDATE public.dictionary_words SET example_hanzi = '他慢慢地從樓梯走下來。', example_pinyin = 'tā mànman de cóng lóutī zǒu xiàlai。', example_vietnamese = 'Anh ấy từ từ đi xuống từ cầu thang.' WHERE level = 'B1' AND hanzi = '下來' AND pinyin = 'xiàlai' AND vietnamese = 'Xuống';
UPDATE public.dictionary_words SET example_hanzi = '那部恐怖片把我嚇壞了。', example_pinyin = 'nà bù kǒngbùpiàn bǎ wǒ xiàhuài le。', example_vietnamese = 'Bộ phim kinh dị đó làm tôi sợ chết khiếp.' WHERE level = 'B1' AND hanzi = '嚇' AND pinyin = 'xià' AND vietnamese = 'Dọa dẫm';
UPDATE public.dictionary_words SET example_hanzi = '看到帳單金額，我嚇了一跳。', example_pinyin = 'kàndào zhàngdān jīn''é，wǒ xiàle yí tiào。', example_vietnamese = 'Nhìn thấy số tiền trên hóa đơn, tôi giật cả mình.' WHERE level = 'B1' AND hanzi = '嚇一跳' AND pinyin = 'xiàyítiào' AND vietnamese = 'Giật mình, sợ hãi';
UPDATE public.dictionary_words SET example_hanzi = '這件毛衣的線斷了一條。', example_pinyin = 'zhè jiàn máoyī de xiàn duànle yì tiáo。', example_vietnamese = 'Áo len này bị đứt một sợi chỉ.' WHERE level = 'B1' AND hanzi = '線' AND pinyin = 'xiàn' AND vietnamese = 'Sợi, đường';
UPDATE public.dictionary_words SET example_hanzi = '這棟建築結合了傳統與現代的風格。', example_pinyin = 'zhè dòng jiànzhú jiéhéle chuántǒng yǔ xiàndài de fēnggé。', example_vietnamese = 'Tòa nhà này kết hợp phong cách truyền thống và hiện đại.' WHERE level = 'B1' AND hanzi = '現代' AND pinyin = 'xiàndài' AND vietnamese = 'Hiện đại';
UPDATE public.dictionary_words SET example_hanzi = '電影和現實畢竟是不一樣的。', example_pinyin = 'diànyǐng hé xiànshí bìjìng shì bù yíyàng de。', example_vietnamese = 'Phim ảnh và hiện thực dù sao cũng khác nhau.' WHERE level = 'B1' AND hanzi = '現實' AND pinyin = 'xiànshí' AND vietnamese = 'Hiện thực, thực tại';
UPDATE public.dictionary_words SET example_hanzi = '這個計畫聽起來不太現實。', example_pinyin = 'zhège jìhuà tīngqǐlái bú tài xiànshí。', example_vietnamese = 'Kế hoạch này nghe có vẻ không thực tế lắm.' WHERE level = 'B1' AND hanzi = '現實' AND pinyin = 'xiànshí' AND vietnamese = 'Hiện thực';
UPDATE public.dictionary_words SET example_hanzi = '塞車已經成了這個城市常見的現象。', example_pinyin = 'sāichē yǐjīng chéngle zhège chéngshì chángjiàn de xiànxiàng。', example_vietnamese = 'Kẹt xe đã trở thành hiện tượng thường thấy ở thành phố này.' WHERE level = 'B1' AND hanzi = '現象' AND pinyin = 'xiànxiàng' AND vietnamese = 'Hiện tạng';
UPDATE public.dictionary_words SET example_hanzi = '這個公園對遊客的人數有限制。', example_pinyin = 'zhège gōngyuán duì yóukè de rénshù yǒu xiànzhì。', example_vietnamese = 'Công viên này có hạn chế về số lượng du khách.' WHERE level = 'B1' AND hanzi = '限制' AND pinyin = 'xiànzhì' AND vietnamese = 'Hạn chế, giới hạn';
UPDATE public.dictionary_words SET example_hanzi = '這次考試的難度相當高。', example_pinyin = 'zhè cì kǎoshì de nándù xiāngdāng gāo。', example_vietnamese = 'Độ khó của kỳ thi lần này khá cao.' WHERE level = 'B1' AND hanzi = '相當' AND pinyin = 'xiāngdāng' AND vietnamese = 'Tương đương, ngang nhau';
UPDATE public.dictionary_words SET example_hanzi = '跟大城市比起來，這裡的物價相對便宜。', example_pinyin = 'gēn dà chéngshì bǐ qǐlái，zhèlǐ de wùjià xiāngduì piányi。', example_vietnamese = 'So với thành phố lớn, vật giá ở đây tương đối rẻ.' WHERE level = 'B1' AND hanzi = '相對' AND pinyin = 'xiāngduì' AND vietnamese = 'Trái ngược, đối lập nhau';
UPDATE public.dictionary_words SET example_hanzi = '他的個性跟哥哥完全相反。', example_pinyin = 'tā de gèxìng gēn gēge wánquán xiāngfǎn。', example_vietnamese = 'Tính cách của anh ấy hoàn toàn trái ngược với anh trai.' WHERE level = 'B1' AND hanzi = '相反' AND pinyin = 'xiāngfăn' AND vietnamese = 'Tương phản, trái ngược';
UPDATE public.dictionary_words SET example_hanzi = '這份資料跟這次的研究相關。', example_pinyin = 'zhè fèn zīliào gēn zhè cì de yánjiù xiāngguān。', example_vietnamese = 'Tài liệu này có liên quan đến nghiên cứu lần này.' WHERE level = 'B1' AND hanzi = '相關' AND pinyin = 'xiāngguān' AND vietnamese = 'Liên quan';
UPDATE public.dictionary_words SET example_hanzi = '我們兩個人的想法很相同。', example_pinyin = 'wǒmen liǎng ge rén de xiǎngfǎ hěn xiāngtóng。', example_vietnamese = 'Suy nghĩ của hai chúng tôi rất giống nhau.' WHERE level = 'B1' AND hanzi = '相同' AND pinyin = 'xiāngtóng' AND vietnamese = 'Tương đồng, giống nhau';
UPDATE public.dictionary_words SET example_hanzi = '這個箱子裡裝的都是舊書。', example_pinyin = 'zhège xiāngzi lǐ zhuāng de dōu shì jiù shū。', example_vietnamese = 'Trong cái hòm này chứa toàn là sách cũ.' WHERE level = 'B1' AND hanzi = '箱子' AND pinyin = 'xiāngzi' AND vietnamese = 'Hòm, rương';
UPDATE public.dictionary_words SET example_hanzi = '她今天噴了一點香水。', example_pinyin = 'tā jīntiān pēnle yìdiǎn xiāngshuǐ。', example_vietnamese = 'Hôm nay cô ấy xịt một chút nước hoa.' WHERE level = 'B1' AND hanzi = '香水' AND pinyin = 'xiāngshuĭ' AND vietnamese = 'Nước hoa, dầu thơm';
UPDATE public.dictionary_words SET example_hanzi = '請你詳細地說明整個過程。', example_pinyin = 'qǐng nǐ xiángxì de shuōmíng zhěnggè guòchéng。', example_vietnamese = 'Xin bạn hãy giải thích tỉ mỉ toàn bộ quá trình.' WHERE level = 'B1' AND hanzi = '詳細' AND pinyin = 'xiángxì' AND vietnamese = 'Kỹ càng tỉ mỉ';
UPDATE public.dictionary_words SET example_hanzi = '電話突然響了起來。', example_pinyin = 'diànhuà tūrán xiǎngle qǐlái。', example_vietnamese = 'Điện thoại đột nhiên reo lên.' WHERE level = 'B1' AND hanzi = '響' AND pinyin = 'xiǎng' AND vietnamese = 'Vang lên, kêu';
UPDATE public.dictionary_words SET example_hanzi = '我沒想到會在這裡遇見你。', example_pinyin = 'wǒ méi xiǎngdào huì zài zhèlǐ yùjiàn nǐ。', example_vietnamese = 'Tôi không ngờ lại gặp bạn ở đây.' WHERE level = 'B1' AND hanzi = '想到' AND pinyin = 'xiăngdào' AND vietnamese = 'Nghĩ đến, nghĩ về';
UPDATE public.dictionary_words SET example_hanzi = '每個人對這件事都有不同的想法。', example_pinyin = 'měi ge rén duì zhè jiàn shì dōu yǒu bùtóng de xiǎngfǎ。', example_vietnamese = 'Mỗi người đều có suy nghĩ khác nhau về việc này.' WHERE level = 'B1' AND hanzi = '想法' AND pinyin = 'xiǎngfǎ' AND vietnamese = 'Ý nghĩ, nhận xét';
UPDATE public.dictionary_words SET example_hanzi = '這孩子有豐富的想像力。', example_pinyin = 'zhè háizi yǒu fēngfù de xiǎngxiànglì。', example_vietnamese = 'Đứa trẻ này có trí tưởng tượng phong phú.' WHERE level = 'B1' AND hanzi = '想像' AND pinyin = 'xiăngxiàng' AND vietnamese = 'Trí tưởng tượng';
UPDATE public.dictionary_words SET example_hanzi = '我無法想像沒有網路的生活。', example_pinyin = 'wǒ wúfǎ xiǎngxiàng méiyǒu wǎnglù de shēnghuó。', example_vietnamese = 'Tôi không thể tưởng tượng cuộc sống không có internet.' WHERE level = 'B1' AND hanzi = '想像' AND pinyin = 'xiăngxiàng' AND vietnamese = 'Tưởng tượng, nghĩ ra';
UPDATE public.dictionary_words SET example_hanzi = '這項研究花了三年時間才完成。', example_pinyin = 'zhè xiàng yánjiù huāle sān nián shíjiān cái wánchéng。', example_vietnamese = 'Nghiên cứu này mất ba năm mới hoàn thành.' WHERE level = 'B1' AND hanzi = '項' AND pinyin = 'xiàng' AND vietnamese = 'Hạng mục';
UPDATE public.dictionary_words SET example_hanzi = '出去玩別忘了帶相機。', example_pinyin = 'chūqù wán bié wàngle dài xiàngjī。', example_vietnamese = 'Đi chơi đừng quên mang theo máy ảnh.' WHERE level = 'B1' AND hanzi = '相機' AND pinyin = 'xiàngjī' AND vietnamese = 'Máy chụp hình';
UPDATE public.dictionary_words SET example_hanzi = '爺爺很喜歡聽相聲。', example_pinyin = 'yéye hěn xǐhuan tīng xiàngshēng。', example_vietnamese = 'Ông nội rất thích nghe tấu hài truyền thống.' WHERE level = 'B1' AND hanzi = '相聲' AND pinyin = 'xiàngshēng' AND vietnamese = 'kịch nói';
UPDATE public.dictionary_words SET example_hanzi = '夜市裡有各式各樣的小吃。', example_pinyin = 'yèshì lǐ yǒu gèshìgèyàng de xiǎochī。', example_vietnamese = 'Trong chợ đêm có đủ loại đồ ăn vặt.' WHERE level = 'B1' AND hanzi = '小吃' AND pinyin = 'xiăochī' AND vietnamese = 'đồ ăn vặt';
UPDATE public.dictionary_words SET example_hanzi = '公園裡有很多小朋友在玩耍。', example_pinyin = 'gōngyuán lǐ yǒu hěn duō xiǎopéngyǒu zài wánshuǎ。', example_vietnamese = 'Trong công viên có rất nhiều trẻ em đang chơi đùa.' WHERE level = 'B1' AND hanzi = '小朋友' AND pinyin = 'xiǎopéngyǒu' AND vietnamese = 'Trẻ em, bạn nhỏ';
UPDATE public.dictionary_words SET example_hanzi = '老師把全班分成五個小組。', example_pinyin = 'lǎoshī bǎ quánbān fēnchéng wǔ ge xiǎozǔ。', example_vietnamese = 'Thầy giáo chia cả lớp thành năm nhóm nhỏ.' WHERE level = 'B1' AND hanzi = '小組' AND pinyin = 'xiăozŭ' AND vietnamese = 'Tổ, nhóm nhỏ';
UPDATE public.dictionary_words SET example_hanzi = '這種減肥方法的效果不太明顯。', example_pinyin = 'zhè zhǒng jiǎnféi fāngfǎ de xiàoguǒ bú tài míngxiǎn。', example_vietnamese = 'Hiệu quả của phương pháp giảm cân này không rõ rệt lắm.' WHERE level = 'B1' AND hanzi = '效果' AND pinyin = 'xiàoguŏ' AND vietnamese = 'Hiệu quả';
UPDATE public.dictionary_words SET example_hanzi = '他常常講笑話逗大家開心。', example_pinyin = 'tā chángcháng jiǎng xiàohuà dòu dàjiā kāixīn。', example_vietnamese = 'Anh ấy thường kể chuyện cười làm mọi người vui.' WHERE level = 'B1' AND hanzi = '笑話' AND pinyin = 'xiàohuà' AND vietnamese = 'Truyện cười';
UPDATE public.dictionary_words SET example_hanzi = '他對父母很孝順。', example_pinyin = 'tā duì fùmǔ hěn xiàoshùn。', example_vietnamese = 'Anh ấy rất hiếu thảo với cha mẹ.' WHERE level = 'B1' AND hanzi = '孝順' AND pinyin = 'xiàoshùn' AND vietnamese = 'Hiếu thảo';
UPDATE public.dictionary_words SET example_hanzi = '桌上有一些水果。', example_pinyin = 'zhuō shàng yǒu yìxiē shuǐguǒ。', example_vietnamese = 'Trên bàn có một ít trái cây.' WHERE level = 'B1' AND hanzi = '些' AND pinyin = '些' AND vietnamese = 'Một ít, một vài';
UPDATE public.dictionary_words SET example_hanzi = '謝謝你協助我完成這個計畫。', example_pinyin = 'xièxie nǐ xiézhù wǒ wánchéng zhège jìhuà。', example_vietnamese = 'Cảm ơn bạn đã giúp đỡ tôi hoàn thành kế hoạch này.' WHERE level = 'B1' AND hanzi = '協助' AND pinyin = 'xiézhù' AND vietnamese = 'Giúp đỡ, trợ giúp';
UPDATE public.dictionary_words SET example_hanzi = '他不小心割傷了手，流了一點血。', example_pinyin = 'tā bù xiǎoxīn gēshāngle shǒu，liúle yìdiǎn xiě。', example_vietnamese = 'Anh ấy sơ ý bị đứt tay, chảy một chút máu.' WHERE level = 'B1' AND hanzi = '血' AND pinyin = 'xiě' AND vietnamese = 'Máu, ruột thịt';
UPDATE public.dictionary_words SET example_hanzi = '多謝你的幫忙，我才順利完成工作。', example_pinyin = 'duōxiè nǐ de bāngmáng，wǒ cái shùnlì wánchéng gōngzuò。', example_vietnamese = 'Cảm ơn nhiều vì sự giúp đỡ của bạn, tôi mới hoàn thành công việc suôn sẻ.' WHERE level = 'B1' AND hanzi = '謝' AND pinyin = 'xiè' AND vietnamese = 'Cảm ơn';
UPDATE public.dictionary_words SET example_hanzi = '看完這本書後，寫下你的心得。', example_pinyin = 'kànwán zhè běn shū hòu，xiěxià nǐ de xīndé。', example_vietnamese = 'Sau khi đọc xong cuốn sách này, hãy viết lại cảm nhận của bạn.' WHERE level = 'B1' AND hanzi = '心得' AND pinyin = 'xīndé' AND vietnamese = 'Tâm đắc';
UPDATE public.dictionary_words SET example_hanzi = '考試前的緊張是很正常的心理反應。', example_pinyin = 'kǎoshì qián de jǐnzhāng shì hěn zhèngcháng de xīnlǐ fǎnyìng。', example_vietnamese = 'Căng thẳng trước kỳ thi là phản ứng tâm lý rất bình thường.' WHERE level = 'B1' AND hanzi = '心理' AND pinyin = 'xīnlĭ' AND vietnamese = 'Tâm lý';
UPDATE public.dictionary_words SET example_hanzi = '禮物不貴沒關係，重要的是心意。', example_pinyin = 'lǐwù bú guì méi guānxi，zhòngyào de shì xīnyì。', example_vietnamese = 'Quà không đắt cũng không sao, quan trọng là tấm lòng.' WHERE level = 'B1' AND hanzi = '心意' AND pinyin = 'xīnyì' AND vietnamese = 'Tâm ý, tấm lòng';
UPDATE public.dictionary_words SET example_hanzi = '我們坐在河邊欣賞夜景。', example_pinyin = 'wǒmen zuò zài hébiān xīnshǎng yèjǐng。', example_vietnamese = 'Chúng tôi ngồi bên bờ sông thưởng thức cảnh đêm.' WHERE level = 'B1' AND hanzi = '欣賞' AND pinyin = 'xīnshăng' AND vietnamese = 'Thưởng thức';
UPDATE public.dictionary_words SET example_hanzi = '今天是大一新生的入學典禮。', example_pinyin = 'jīntiān shì dàyī xīnshēng de rùxué diǎnlǐ。', example_vietnamese = 'Hôm nay là lễ nhập học của tân sinh viên năm nhất.' WHERE level = 'B1' AND hanzi = '新生' AND pinyin = 'xīnshēng' AND vietnamese = 'Mới ra đời';
UPDATE public.dictionary_words SET example_hanzi = '我信你，你一定不會騙我。', example_pinyin = 'wǒ xìn nǐ，nǐ yídìng bú huì piàn wǒ。', example_vietnamese = 'Tôi tin bạn, bạn nhất định sẽ không lừa tôi.' WHERE level = 'B1' AND hanzi = '信' AND pinyin = 'xìn' AND vietnamese = 'Tin tưởng';
UPDATE public.dictionary_words SET example_hanzi = '記得每天檢查一下電子信箱。', example_pinyin = 'jìde měitiān jiǎnchá yíxià diànzǐ xìnxiāng。', example_vietnamese = 'Nhớ kiểm tra hộp thư điện tử mỗi ngày.' WHERE level = 'B1' AND hanzi = '信箱' AND pinyin = 'xìnxiāng' AND vietnamese = 'Thùng thư, hòm thư';
UPDATE public.dictionary_words SET example_hanzi = '這次比賽他很有信心會拿第一名。', example_pinyin = 'zhè cì bǐsài tā hěn yǒu xìnxīn huì ná dìyī míng。', example_vietnamese = 'Cuộc thi lần này anh ấy rất tự tin sẽ giành hạng nhất.' WHERE level = 'B1' AND hanzi = '信心' AND pinyin = 'xìnxīn' AND vietnamese = 'Lòng tin, tự tin';
UPDATE public.dictionary_words SET example_hanzi = '聽到這個好消息，大家都很興奮。', example_pinyin = 'tīngdào zhège hǎo xiāoxi，dàjiā dōu hěn xīngfèn。', example_vietnamese = 'Nghe được tin tốt này, mọi người đều rất phấn khích.' WHERE level = 'B1' AND hanzi = '興奮' AND pinyin = 'xīngfèn' AND vietnamese = 'Phấn khởi, hăng hái';
UPDATE public.dictionary_words SET example_hanzi = '這樣安排可以嗎？行，沒問題。', example_pinyin = 'zhèyàng ānpái kěyǐ ma？xíng，méi wèntí。', example_vietnamese = 'Sắp xếp như vậy được không? Được, không vấn đề gì.' WHERE level = 'B1' AND hanzi = '行' AND pinyin = 'xíng' AND vietnamese = 'Đi';
UPDATE public.dictionary_words SET example_hanzi = '與其一直說，不如馬上採取行動。', example_pinyin = 'yǔqí yìzhí shuō，bùrú mǎshàng cǎiqǔ xíngdòng。', example_vietnamese = 'Thay vì cứ nói mãi, chi bằng lập tức hành động.' WHERE level = 'B1' AND hanzi = '行動' AND pinyin = 'xíngdòng' AND vietnamese = 'Hành vi, cử động';
UPDATE public.dictionary_words SET example_hanzi = '這種行為在公共場合是不禮貌的。', example_pinyin = 'zhè zhǒng xíngwéi zài gōnggòng chǎnghé shì bù lǐmào de。', example_vietnamese = 'Hành vi này ở nơi công cộng là không lịch sự.' WHERE level = 'B1' AND hanzi = '行為' AND pinyin = 'xíngwéi' AND vietnamese = 'Hành vi';
UPDATE public.dictionary_words SET example_hanzi = '我不知道該怎麼形容那種感覺。', example_pinyin = 'wǒ bù zhīdào gāi zěnme xíngróng nà zhǒng gǎnjué。', example_vietnamese = 'Tôi không biết nên miêu tả cảm giác đó như thế nào.' WHERE level = 'B1' AND hanzi = '形容' AND pinyin = 'xíngróng' AND vietnamese = 'Hình dung, miêu tả';
UPDATE public.dictionary_words SET example_hanzi = '他昨晚喝多了，到現在都還沒醒。', example_pinyin = 'tā zuówǎn hēduō le，dào xiànzài dōu hái méi xǐng。', example_vietnamese = 'Tối qua anh ấy uống nhiều quá, đến giờ vẫn chưa tỉnh.' WHERE level = 'B1' AND hanzi = '醒' AND pinyin = 'xĭng' AND vietnamese = 'Tỉnh, tỉnh ngộ';
UPDATE public.dictionary_words SET example_hanzi = '我今天早上七點就醒來了。', example_pinyin = 'wǒ jīntiān zǎoshang qī diǎn jiù xǐnglái le。', example_vietnamese = 'Sáng nay tôi đã thức dậy lúc bảy giờ.' WHERE level = 'B1' AND hanzi = '醒來' AND pinyin = 'xĭnglái' AND vietnamese = 'Đánh thức';
UPDATE public.dictionary_words SET example_hanzi = '請問你貴姓？', example_pinyin = 'qǐngwèn nǐ guì xìng？', example_vietnamese = 'Xin hỏi quý danh của bạn là gì?' WHERE level = 'B1' AND hanzi = '姓' AND pinyin = 'xìng' AND vietnamese = 'Họ';
UPDATE public.dictionary_words SET example_hanzi = '這份工作不限制性別，男女都可以應徵。', example_pinyin = 'zhè fèn gōngzuò bú xiànzhì xìngbié，nánnǚ dōu kěyǐ yìngzhēng。', example_vietnamese = 'Công việc này không giới hạn giới tính, nam nữ đều có thể ứng tuyển.' WHERE level = 'B1' AND hanzi = '性別' AND pinyin = 'xìngbié' AND vietnamese = 'Giới tính';
UPDATE public.dictionary_words SET example_hanzi = '她的性格開朗又樂觀。', example_pinyin = 'tā de xìnggé kāilǎng yòu lèguān。', example_vietnamese = 'Tính cách của cô ấy vừa cởi mở vừa lạc quan.' WHERE level = 'B1' AND hanzi = '性格' AND pinyin = 'xìnggé' AND vietnamese = 'Tính cách';
UPDATE public.dictionary_words SET example_hanzi = '幸好我帶了傘，不然就淋濕了。', example_pinyin = 'xìnghǎo wǒ dàile sǎn，bùrán jiù línshī le。', example_vietnamese = 'May mà tôi mang ô, nếu không thì đã bị ướt.' WHERE level = 'B1' AND hanzi = '幸好' AND pinyin = 'xìnghăo' AND vietnamese = 'May mắn, may mà';
UPDATE public.dictionary_words SET example_hanzi = '幸虧你提醒我，不然我就忘記開會了。', example_pinyin = 'xìngkuī nǐ tíxǐng wǒ，bùrán wǒ jiù wàngjì kāihuì le。', example_vietnamese = 'May mà bạn nhắc tôi, nếu không tôi đã quên cuộc họp rồi.' WHERE level = 'B1' AND hanzi = '幸虧' AND pinyin = 'xìngkuī' AND vietnamese = 'May mà';
UPDATE public.dictionary_words SET example_hanzi = '能認識你，我覺得自己很幸運。', example_pinyin = 'néng rènshi nǐ，wǒ juéde zìjǐ hěn xìngyùn。', example_vietnamese = 'Có thể quen biết bạn, tôi cảm thấy mình rất may mắn.' WHERE level = 'B1' AND hanzi = '幸運' AND pinyin = 'xìngyùn' AND vietnamese = 'Vận may';
UPDATE public.dictionary_words SET example_hanzi = '那隻狗看起來很兇，我們還是繞路走吧。', example_pinyin = 'nà zhī gǒu kànqǐlái hěn xiōng，wǒmen háishì ràolù zǒu ba。', example_vietnamese = 'Con chó đó trông có vẻ hung dữ, chúng ta vẫn nên đi đường vòng thôi.' WHERE level = 'B1' AND hanzi = '兇' AND pinyin = 'xiōng' AND vietnamese = 'Hung ác';
UPDATE public.dictionary_words SET example_hanzi = '他們兄弟三人感情非常好。', example_pinyin = 'tāmen xiōngdì sān rén gǎnqíng fēicháng hǎo。', example_vietnamese = 'Ba anh em họ tình cảm rất tốt.' WHERE level = 'B1' AND hanzi = '兄弟' AND pinyin = 'xiōngdì' AND vietnamese = 'Người anh em';
UPDATE public.dictionary_words SET example_hanzi = '動物園裡最受歡迎的就是熊貓。', example_pinyin = 'dòngwùyuán lǐ zuì shòu huānyíng de jiùshì xióngmāo。', example_vietnamese = 'Loài được yêu thích nhất trong sở thú chính là gấu trúc.' WHERE level = 'B1' AND hanzi = '熊貓' AND pinyin = 'xióngmāo' AND vietnamese = 'Gấu trúc';
UPDATE public.dictionary_words SET example_hanzi = '這台腳踏車壞了，得拿去修。', example_pinyin = 'zhè tái jiǎotàchē huài le，děi ná qù xiū。', example_vietnamese = 'Chiếc xe đạp này hỏng rồi, phải mang đi sửa.' WHERE level = 'B1' AND hanzi = '修' AND pinyin = 'xiū' AND vietnamese = 'Sửa';
UPDATE public.dictionary_words SET example_hanzi = '老師要我把作文再修改一次。', example_pinyin = 'lǎoshī yào wǒ bǎ zuòwén zài xiūgǎi yí cì。', example_vietnamese = 'Thầy giáo yêu cầu tôi sửa lại bài văn một lần nữa.' WHERE level = 'B1' AND hanzi = '修改' AND pinyin = 'xiūgăi' AND vietnamese = 'Sửa chữa';
UPDATE public.dictionary_words SET example_hanzi = '冷氣壞了，我請師傅來修理。', example_pinyin = 'lěngqì huài le，wǒ qǐng shīfu lái xiūlǐ。', example_vietnamese = 'Máy lạnh bị hỏng, tôi mời thợ đến sửa.' WHERE level = 'B1' AND hanzi = '修理' AND pinyin = 'xiūlĭ' AND vietnamese = 'Cắt sửa';
UPDATE public.dictionary_words SET example_hanzi = '這款產品是為了滿足消費者的需求而設計的。', example_pinyin = 'zhè kuǎn chǎnpǐn shì wèile mǎnzú xiāofèizhě de xūqiú ér shèjì de。', example_vietnamese = 'Sản phẩm này được thiết kế để đáp ứng nhu cầu của người tiêu dùng.' WHERE level = 'B1' AND hanzi = '需求' AND pinyin = 'xūqiú' AND vietnamese = 'Nhu cầu';
UPDATE public.dictionary_words SET example_hanzi = '每個人的需要都不一樣。', example_pinyin = 'měi ge rén de xūyào dōu bù yíyàng。', example_vietnamese = 'Nhu cầu của mỗi người đều không giống nhau.' WHERE level = 'B1' AND hanzi = '需要' AND pinyin = 'xūyào' AND vietnamese = 'Yêu cầu';
UPDATE public.dictionary_words SET example_hanzi = '你可以在這幾種顏色裡選一個。', example_pinyin = 'nǐ kěyǐ zài zhè jǐ zhǒng yánsè lǐ xuǎn yí ge。', example_vietnamese = 'Bạn có thể chọn một trong mấy màu này.' WHERE level = 'B1' AND hanzi = '選' AND pinyin = 'xuǎn' AND vietnamese = 'Chọn, lựa chọn';
UPDATE public.dictionary_words SET example_hanzi = '今年年底有一場重要的選舉。', example_pinyin = 'jīnnián niándǐ yǒu yì chǎng zhòngyào de xuǎnjǔ。', example_vietnamese = 'Cuối năm nay có một cuộc bầu cử quan trọng.' WHERE level = 'B1' AND hanzi = '選舉' AND pinyin = 'xuănjŭ' AND vietnamese = 'Tuyển cử';
UPDATE public.dictionary_words SET example_hanzi = '人生充滿了各種選擇。', example_pinyin = 'rénshēng chōngmǎnle gèzhǒng xuǎnzé。', example_vietnamese = 'Cuộc đời đầy rẫy những sự lựa chọn.' WHERE level = 'B1' AND hanzi = '選擇' AND pinyin = 'xuǎnzé' AND vietnamese = 'Sự lựa chọn';
UPDATE public.dictionary_words SET example_hanzi = '最後他選擇了留在家鄉工作。', example_pinyin = 'zuìhòu tā xuǎnzéle liú zài jiāxiāng gōngzuò。', example_vietnamese = 'Cuối cùng anh ấy chọn ở lại quê nhà làm việc.' WHERE level = 'B1' AND hanzi = '選擇' AND pinyin = 'xuǎnzé' AND vietnamese = 'Tuyển chọn';
UPDATE public.dictionary_words SET example_hanzi = '我終於學會怎麼騎腳踏車了。', example_pinyin = 'wǒ zhōngyú xuéhuì zěnme qí jiǎotàchē le。', example_vietnamese = 'Cuối cùng tôi đã học được cách đi xe đạp.' WHERE level = 'B1' AND hanzi = '學會' AND pinyin = 'xuéhuì' AND vietnamese = 'Học cách';
UPDATE public.dictionary_words SET example_hanzi = '他是一個很有學問的人。', example_pinyin = 'tā shì yí ge hěn yǒu xuéwèn de rén。', example_vietnamese = 'Anh ấy là một người rất có học vấn.' WHERE level = 'B1' AND hanzi = '學問' AND pinyin = 'xuéwèn' AND vietnamese = 'Học vấn';
UPDATE public.dictionary_words SET example_hanzi = '他一直在尋找適合自己的工作。', example_pinyin = 'tā yìzhí zài xúnzhǎo shìhé zìjǐ de gōngzuò。', example_vietnamese = 'Anh ấy vẫn luôn tìm kiếm công việc phù hợp với mình.' WHERE level = 'B1' AND hanzi = '尋找' AND pinyin = 'xúnzhăo' AND vietnamese = 'Tìm kiếm';
UPDATE public.dictionary_words SET example_hanzi = '教練每天都嚴格地訓練選手。', example_pinyin = 'jiàoliàn měitiān dōu yángé de xùnliàn xuǎnshǒu。', example_vietnamese = 'Huấn luyện viên ngày nào cũng huấn luyện các vận động viên một cách nghiêm khắc.' WHERE level = 'B1' AND hanzi = '訓練' AND pinyin = 'xùnliàn' AND vietnamese = 'Huấn luyện, tập luyện';
UPDATE public.dictionary_words SET example_hanzi = '這件衣服真漂亮呀！', example_pinyin = 'zhè jiàn yīfu zhēn piàoliang ya！', example_vietnamese = 'Bộ quần áo này đẹp thật đấy!' WHERE level = 'B1' AND hanzi = '呀' AND pinyin = 'yā' AND vietnamese = 'A, à, nhé';
UPDATE public.dictionary_words SET example_hanzi = '河邊有一群鴨子在游泳。', example_pinyin = 'hébiān yǒu yì qún yāzi zài yóuyǒng。', example_vietnamese = 'Bên bờ sông có một đàn vịt đang bơi.' WHERE level = 'B1' AND hanzi = '鴨(子)' AND pinyin = 'yā(zi)' AND vietnamese = 'Con vịt';
UPDATE public.dictionary_words SET example_hanzi = '租房子通常要先付一個月的押金。', example_pinyin = 'zū fángzi tōngcháng yào xiān fù yí ge yuè de yājīn。', example_vietnamese = 'Thuê nhà thường phải trả trước tiền cọc một tháng.' WHERE level = 'B1' AND hanzi = '押金' AND pinyin = 'yājīn' AND vietnamese = 'Tiền thế chấp, tiền cọc';
UPDATE public.dictionary_words SET example_hanzi = '他這顆牙已經蛀了，得去看牙醫。', example_pinyin = 'tā zhè kē yá yǐjīng zhùle，děi qù kàn yáyī。', example_vietnamese = 'Cái răng này của anh ấy đã bị sâu rồi, phải đi khám nha sĩ.' WHERE level = 'B1' AND hanzi = '牙' AND pinyin = 'yá' AND vietnamese = 'Răng, ngà voi';
UPDATE public.dictionary_words SET example_hanzi = '記得吃完飯要刷牙齒。', example_pinyin = 'jìde chīwán fàn yào shuā yáchǐ。', example_vietnamese = 'Nhớ ăn cơm xong phải đánh răng.' WHERE level = 'B1' AND hanzi = '牙齒' AND pinyin = 'yáchĭ' AND vietnamese = 'Răng';
UPDATE public.dictionary_words SET example_hanzi = '跨年夜大家都會去看煙火。', example_pinyin = 'kuànián yè dàjiā dōu huì qù kàn yānhuǒ。', example_vietnamese = 'Đêm giao thừa mọi người đều sẽ đi xem pháo hoa.' WHERE level = 'B1' AND hanzi = '煙火' AND pinyin = 'yānhuŏ' AND vietnamese = 'Pháo hoa';
UPDATE public.dictionary_words SET example_hanzi = '這篇研究對癌症治療有重大意義。', example_pinyin = 'zhè piān yánjiù duì áizhèng zhìliáo yǒu zhòngdà yìyì。', example_vietnamese = 'Bài nghiên cứu này có ý nghĩa quan trọng đối với việc điều trị ung thư.' WHERE level = 'B1' AND hanzi = '研究' AND pinyin = 'yánjiù' AND vietnamese = 'Nghiên cứu';
UPDATE public.dictionary_words SET example_hanzi = '他正在研究如何改善這個問題。', example_pinyin = 'tā zhèngzài yánjiù rúhé gǎishàn zhège wèntí。', example_vietnamese = 'Anh ấy đang nghiên cứu cách cải thiện vấn đề này.' WHERE level = 'B1' AND hanzi = '研究' AND pinyin = 'yánjiù' AND vietnamese = 'Tìm tòi học hỏi';
UPDATE public.dictionary_words SET example_hanzi = '這次車禍造成的傷害相當嚴重。', example_pinyin = 'zhè cì chēhuò zàochéng de shānghài xiāngdāng yánzhòng。', example_vietnamese = 'Thiệt hại do vụ tai nạn xe lần này gây ra khá nghiêm trọng.' WHERE level = 'B1' AND hanzi = '嚴重' AND pinyin = 'yánzhòng' AND vietnamese = 'Nghiêm trọng';
UPDATE public.dictionary_words SET example_hanzi = '這部電影是他第一次演主角。', example_pinyin = 'zhè bù diànyǐng shì tā dì-yī cì yǎn zhǔjué。', example_vietnamese = 'Bộ phim này là lần đầu tiên anh ấy đóng vai chính.' WHERE level = 'B1' AND hanzi = '演' AND pinyin = 'yăn' AND vietnamese = 'Diễn';
UPDATE public.dictionary_words SET example_hanzi = '這場音樂會的演出非常精彩。', example_pinyin = 'zhè chǎng yīnyuèhuì de yǎnchū fēicháng jīngcǎi。', example_vietnamese = 'Buổi biểu diễn của buổi hòa nhạc này vô cùng đặc sắc.' WHERE level = 'B1' AND hanzi = '演出' AND pinyin = 'yănchū' AND vietnamese = 'Diễn xuất';
UPDATE public.dictionary_words SET example_hanzi = '他明天要在學校演講。', example_pinyin = 'tā míngtiān yào zài xuéxiào yǎnjiǎng。', example_vietnamese = 'Ngày mai anh ấy sẽ diễn thuyết ở trường.' WHERE level = 'B1' AND hanzi = '演講' AND pinyin = 'yănjiăng' AND vietnamese = 'Diễn thuyết';
UPDATE public.dictionary_words SET example_hanzi = '她是一位很有名的演員。', example_pinyin = 'tā shì yí wèi hěn yǒumíng de yǎnyuán。', example_vietnamese = 'Cô ấy là một diễn viên rất nổi tiếng.' WHERE level = 'B1' AND hanzi = '演員' AND pinyin = 'yănyuán' AND vietnamese = 'Diễn viên';
UPDATE public.dictionary_words SET example_hanzi = '她挑選衣服的眼光很好。', example_pinyin = 'tā tiāoxuǎn yīfu de yǎnguāng hěn hǎo。', example_vietnamese = 'Con mắt thẩm mỹ chọn quần áo của cô ấy rất tốt.' WHERE level = 'B1' AND hanzi = '眼光' AND pinyin = 'yănguāng' AND vietnamese = 'Ánh mắt';
UPDATE public.dictionary_words SET example_hanzi = '聽到這個消息，她忍不住流下眼淚。', example_pinyin = 'tīngdào zhège xiāoxi，tā rěnbúzhù liúxià yǎnlèi。', example_vietnamese = 'Nghe được tin này, cô ấy không kìm được mà rơi nước mắt.' WHERE level = 'B1' AND hanzi = '眼淚' AND pinyin = 'yănlèi' AND vietnamese = 'Nước mắt';
UPDATE public.dictionary_words SET example_hanzi = '星期天早上的陽光很溫暖。', example_pinyin = 'xīngqítiān zǎoshang de yángguāng hěn wēnnuǎn。', example_vietnamese = 'Ánh nắng buổi sáng chủ nhật rất ấm áp.' WHERE level = 'B1' AND hanzi = '陽光' AND pinyin = 'yángguāng' AND vietnamese = 'Ánh nắng';
UPDATE public.dictionary_words SET example_hanzi = '他從小就養了一隻狗。', example_pinyin = 'tā cóng xiǎo jiù yǎng le yì zhī gǒu。', example_vietnamese = 'Anh ấy nuôi một con chó từ nhỏ.' WHERE level = 'B1' AND hanzi = '養' AND pinyin = 'yăng' AND vietnamese = 'Nuôi dưỡng';
UPDATE public.dictionary_words SET example_hanzi = '這家店賣好幾樣點心。', example_pinyin = 'zhè jiā diàn mài hǎo jǐ yàng diǎnxīn。', example_vietnamese = 'Cửa hàng này bán mấy loại điểm tâm.' WHERE level = 'B1' AND hanzi = '樣' AND pinyin = 'yàng' AND vietnamese = 'Hình dáng, kiểu';
UPDATE public.dictionary_words SET example_hanzi = '她做事樣樣都很認真。', example_pinyin = 'tā zuò shì yàngyàng dōu hěn rènzhēn。', example_vietnamese = 'Việc gì cô ấy làm cũng đều rất nghiêm túc.' WHERE level = 'B1' AND hanzi = '樣樣' AND pinyin = 'yàngyàng' AND vietnamese = 'Tất cả các loại';
UPDATE public.dictionary_words SET example_hanzi = '我邀請朋友來家裡吃晚飯。', example_pinyin = 'wǒ yāoqǐng péngyou lái jiālǐ chī wǎnfàn。', example_vietnamese = 'Tôi mời bạn bè đến nhà ăn cơm tối.' WHERE level = 'B1' AND hanzi = '邀請' AND pinyin = 'yāoqĭng' AND vietnamese = 'Mời';
UPDATE public.dictionary_words SET example_hanzi = '這份工作對英文能力的要求很高。', example_pinyin = 'zhè fèn gōngzuò duì yīngwén nénglì de yāoqiú hěn gāo。', example_vietnamese = 'Công việc này có yêu cầu rất cao về khả năng tiếng Anh.' WHERE level = 'B1' AND hanzi = '要求' AND pinyin = 'yāoqiú' AND vietnamese = 'Nguyện vọng';
UPDATE public.dictionary_words SET example_hanzi = '老闆要求大家準時上班。', example_pinyin = 'lǎobǎn yāoqiú dàjiā zhǔnshí shàngbān。', example_vietnamese = 'Sếp yêu cầu mọi người đi làm đúng giờ.' WHERE level = 'B1' AND hanzi = '要求' AND pinyin = 'yāoqiú' AND vietnamese = 'Yêu cầu';
UPDATE public.dictionary_words SET example_hanzi = '小心!那隻狗會咬人。', example_pinyin = 'xiǎoxīn! nà zhī gǒu huì yǎo rén。', example_vietnamese = 'Cẩn thận! Con chó đó sẽ cắn người đấy.' WHERE level = 'B1' AND hanzi = '咬' AND pinyin = 'yăo' AND vietnamese = 'Cắn, kẹp chặt';
UPDATE public.dictionary_words SET example_hanzi = '我要一杯熱咖啡。', example_pinyin = 'wǒ yào yì bēi rè kāfēi。', example_vietnamese = 'Tôi cần một ly cà phê nóng.' WHERE level = 'B1' AND hanzi = '要' AND pinyin = 'yào' AND vietnamese = 'Cần,';
UPDATE public.dictionary_words SET example_hanzi = '你快一點出門,要不然會遲到。', example_pinyin = 'nǐ kuài yìdiǎn chūmén, yàobùrán huì chídào。', example_vietnamese = 'Bạn ra khỏi nhà nhanh lên, nếu không sẽ trễ đấy.' WHERE level = 'B1' AND hanzi = '要不然' AND pinyin = 'yàobùrán' AND vietnamese = 'Nếu không';
UPDATE public.dictionary_words SET example_hanzi = '要不是你提醒我,我就忘了這件事。', example_pinyin = 'yàobúshì nǐ tíxǐng wǒ, wǒ jiù wàng le zhè jiàn shì。', example_vietnamese = 'Nếu không phải bạn nhắc tôi thì tôi đã quên mất chuyện này rồi.' WHERE level = 'B1' AND hanzi = '要不是' AND pinyin = 'yàobúshì' AND vietnamese = 'Nếu nó không phải';
UPDATE public.dictionary_words SET example_hanzi = '沒關係,這不是什麼要緊的事。', example_pinyin = 'méi guānxi, zhè bú shì shénme yàojǐn de shì。', example_vietnamese = 'Không sao, đây không phải chuyện gì quan trọng.' WHERE level = 'B1' AND hanzi = '要緊' AND pinyin = 'yàojĭn' AND vietnamese = 'Quan trọng, gấp rút';
UPDATE public.dictionary_words SET example_hanzi = '週末我們打算去公園野餐。', example_pinyin = 'zhōumò wǒmen dǎsuàn qù gōngyuán yěcān。', example_vietnamese = 'Cuối tuần chúng tôi định đi công viên ăn dã ngoại.' WHERE level = 'B1' AND hanzi = '野餐' AND pinyin = 'yěcān' AND vietnamese = 'Bữa cơm dã ngoại';
UPDATE public.dictionary_words SET example_hanzi = '你想留在家裡也好,反正外面在下雨。', example_pinyin = 'nǐ xiǎng liú zài jiālǐ yě hǎo, fǎnzhèng wàimiàn zài xià yǔ。', example_vietnamese = 'Bạn muốn ở nhà cũng được, dù sao ngoài trời cũng đang mưa.' WHERE level = 'B1' AND hanzi = '也好' AND pinyin = 'yěhăo' AND vietnamese = 'Cũng tốt';
UPDATE public.dictionary_words SET example_hanzi = '這本書一共有三百頁。', example_pinyin = 'zhè běn shū yígòng yǒu sān bǎi yè。', example_vietnamese = 'Cuốn sách này tổng cộng có ba trăm trang.' WHERE level = 'B1' AND hanzi = '頁' AND pinyin = 'yè' AND vietnamese = 'Tờ, trang (giấy)';
UPDATE public.dictionary_words SET example_hanzi = '他常常夜裡一個人在書房看書。', example_pinyin = 'tā chángcháng yèlǐ yí gè rén zài shūfáng kàn shū。', example_vietnamese = 'Anh ấy thường một mình đọc sách trong phòng sách vào ban đêm.' WHERE level = 'B1' AND hanzi = '夜裡/裏' AND pinyin = 'yèli/li' AND vietnamese = 'Ban đêm';
UPDATE public.dictionary_words SET example_hanzi = '台灣的夜市有很多好吃的小吃。', example_pinyin = 'táiwān de yèshì yǒu hěn duō hǎochī de xiǎochī。', example_vietnamese = 'Chợ đêm ở Đài Loan có rất nhiều món ăn vặt ngon.' WHERE level = 'B1' AND hanzi = '夜市' AND pinyin = 'yèshì' AND vietnamese = 'Chợ đêm';
UPDATE public.dictionary_words SET example_hanzi = '天氣一下子就變冷了。', example_pinyin = 'tiānqì yíxiàzi jiù biàn lěng le。', example_vietnamese = 'Thời tiết trong chốc lát đã trở lạnh.' WHERE level = 'B1' AND hanzi = '一下子/一下子兒' AND pinyin = 'yīxiàzi/ yīxiàzir' AND vietnamese = 'Trong chốc lát';
UPDATE public.dictionary_words SET example_hanzi = '她把衣服都掛進衣櫃裡了。', example_pinyin = 'tā bǎ yīfu dōu guà jìn yīguì lǐ le。', example_vietnamese = 'Cô ấy đã treo hết quần áo vào tủ.' WHERE level = 'B1' AND hanzi = '衣櫃' AND pinyin = 'yīguì' AND vietnamese = 'Tủ quần áo';
UPDATE public.dictionary_words SET example_hanzi = '遇到困難的時候,他只能依靠自己。', example_pinyin = 'yùdào kùnnán de shíhou, tā zhǐ néng yīkào zìjǐ。', example_vietnamese = 'Khi gặp khó khăn, anh ấy chỉ có thể dựa vào chính mình.' WHERE level = 'B1' AND hanzi = '依靠' AND pinyin = 'yīkào' AND vietnamese = 'Nhờ vào, dựa vào';
UPDATE public.dictionary_words SET example_hanzi = '我們一塊兒去看電影吧。', example_pinyin = 'wǒmen yíkuàir qù kàn diànyǐng ba。', example_vietnamese = 'Chúng ta cùng nhau đi xem phim đi.' WHERE level = 'B1' AND hanzi = '一塊/一塊兒' AND pinyin = 'yīkuài/yíkuàir' AND vietnamese = 'Một khối';
UPDATE public.dictionary_words SET example_hanzi = '只要你平安,這一切都值得。', example_pinyin = 'zhǐyào nǐ píngān, zhè yíqiè dōu zhíde。', example_vietnamese = 'Chỉ cần bạn bình an, tất cả những điều này đều xứng đáng.' WHERE level = 'B1' AND hanzi = '一切' AND pinyin = 'yīqiè' AND vietnamese = 'Tất cả, mọi thứ';
UPDATE public.dictionary_words SET example_hanzi = '他一向對學生很有耐心。', example_pinyin = 'tā yíxiàng duì xuéshēng hěn yǒu nàixīn。', example_vietnamese = 'Anh ấy luôn luôn kiên nhẫn với học sinh.' WHERE level = 'B1' AND hanzi = '一向' AND pinyin = 'yīxiàng' AND vietnamese = 'Gần đây, thời gian qua';
UPDATE public.dictionary_words SET example_hanzi = '這兩件衣服的顏色一樣。', example_pinyin = 'zhè liǎng jiàn yīfu de yánsè yíyàng。', example_vietnamese = 'Màu sắc của hai chiếc áo này giống nhau.' WHERE level = 'B1' AND hanzi = '一樣' AND pinyin = 'yīyàng' AND vietnamese = 'Như nhau, giống nhau';
UPDATE public.dictionary_words SET example_hanzi = '時間已晚,我們該回家了。', example_pinyin = 'shíjiān yǐ wǎn, wǒmen gāi huíjiā le。', example_vietnamese = 'Trời đã khuya rồi, chúng ta nên về nhà thôi.' WHERE level = 'B1' AND hanzi = '已' AND pinyin = 'yĭ' AND vietnamese = 'Đã';
UPDATE public.dictionary_words SET example_hanzi = '政府提出新政策,以改善交通問題。', example_pinyin = 'zhèngfǔ tíchū xīn zhèngcè, yǐ gǎishàn jiāotōng wèntí。', example_vietnamese = 'Chính phủ đưa ra chính sách mới nhằm cải thiện vấn đề giao thông.' WHERE level = 'B1' AND hanzi = '以' AND pinyin = 'yĭ' AND vietnamese = 'Để, nhằm';
UPDATE public.dictionary_words SET example_hanzi = '畢業以後,他就出國留學了。', example_pinyin = 'bìyè yǐhòu, tā jiù chūguó liúxué le。', example_vietnamese = 'Sau khi tốt nghiệp, anh ấy đã ra nước ngoài du học.' WHERE level = 'B1' AND hanzi = '以後' AND pinyin = 'yĭhòu' AND vietnamese = 'Về sau, sau đó';
UPDATE public.dictionary_words SET example_hanzi = '開學以來,他每天都準時到校。', example_pinyin = 'kāixué yǐlái, tā měi tiān dōu zhǔnshí dàoxiào。', example_vietnamese = 'Từ khi khai giảng đến nay, ngày nào cậu ấy cũng đến trường đúng giờ.' WHERE level = 'B1' AND hanzi = '以來' AND pinyin = 'yĭlái' AND vietnamese = 'Trước nay';
UPDATE public.dictionary_words SET example_hanzi = '出門前記得關好窗戶,以免下雨弄濕家裡。', example_pinyin = 'chūmén qián jìde guān hǎo chuānghu, yǐmiǎn xiàyǔ nòng shī jiālǐ。', example_vietnamese = 'Trước khi ra ngoài nhớ đóng cửa sổ cho kỹ, để tránh mưa làm ướt trong nhà.' WHERE level = 'B1' AND hanzi = '以免' AND pinyin = 'yĭmiăn' AND vietnamese = 'Để tránh khỏi';
UPDATE public.dictionary_words SET example_hanzi = '請在三天以內回覆這封信。', example_pinyin = 'qǐng zài sān tiān yǐnèi huífù zhè fēng xìn。', example_vietnamese = 'Xin hãy trả lời bức thư này trong vòng ba ngày.' WHERE level = 'B1' AND hanzi = '以內' AND pinyin = 'yĭnèi' AND vietnamese = 'Trong vòng';
UPDATE public.dictionary_words SET example_hanzi = '以前這裡是一片稻田。', example_pinyin = 'yǐqián zhè lǐ shì yí piàn dàotián。', example_vietnamese = 'Trước đây nơi này là một cánh đồng lúa.' WHERE level = 'B1' AND hanzi = '以前' AND pinyin = 'yĭqián' AND vietnamese = 'Trước đây';
UPDATE public.dictionary_words SET example_hanzi = '這個活動需要十八歲以上才能參加。', example_pinyin = 'zhè ge huódòng xūyào shíbā suì yǐshàng cái néng cānjiā。', example_vietnamese = 'Hoạt động này cần đủ mười tám tuổi trở lên mới được tham gia.' WHERE level = 'B1' AND hanzi = '以上' AND pinyin = 'yĭshàng' AND vietnamese = 'Trở lên';
UPDATE public.dictionary_words SET example_hanzi = '除了中文以外,他還會說日文。', example_pinyin = 'chúle zhōngwén yǐwài, tā hái huì shuō rìwén。', example_vietnamese = 'Ngoài tiếng Trung ra, anh ấy còn biết nói tiếng Nhật.' WHERE level = 'B1' AND hanzi = '以外' AND pinyin = 'yĭwài' AND vietnamese = 'Ngoài ra';
UPDATE public.dictionary_words SET example_hanzi = '我以為今天是星期五,沒想到是星期四。', example_pinyin = 'wǒ yǐwéi jīntiān shì xīngqīwǔ, méi xiǎngdào shì xīngqīsì。', example_vietnamese = 'Tôi cứ tưởng hôm nay là thứ sáu, không ngờ lại là thứ năm.' WHERE level = 'B1' AND hanzi = '以為' AND pinyin = 'yĭwéi' AND vietnamese = 'Cho rằng, cho là';
UPDATE public.dictionary_words SET example_hanzi = '五歲以下的小孩可以免費入場。', example_pinyin = 'wǔ suì yǐxià de xiǎohái kěyǐ miǎnfèi rùchǎng。', example_vietnamese = 'Trẻ em từ năm tuổi trở xuống được vào cửa miễn phí.' WHERE level = 'B1' AND hanzi = '以下' AND pinyin = 'yĭxià' AND vietnamese = 'Trở xuống';
UPDATE public.dictionary_words SET example_hanzi = '一般來說,夏天的水果比較便宜。', example_pinyin = 'yìbānláishuō, xiàtiān de shuǐguǒ bǐjiào piányi。', example_vietnamese = 'Nói chung, trái cây mùa hè thường rẻ hơn.' WHERE level = 'B1' AND hanzi = '一般來說' AND pinyin = 'yìbānláishuō' AND vietnamese = 'Nói chung';
UPDATE public.dictionary_words SET example_hanzi = '這道菜可以再加一點兒鹽。', example_pinyin = 'zhè dào cài kěyǐ zài jiā yìdiǎnr yán。', example_vietnamese = 'Món này có thể cho thêm một chút muối nữa.' WHERE level = 'B1' AND hanzi = '一點/一點兒' AND pinyin = 'yìdiǍn/yìdiǍnr' AND vietnamese = 'Một chút';
UPDATE public.dictionary_words SET example_hanzi = '他一方面想出國唸書,一方面又捨不得離開家人。', example_pinyin = 'tā yìfāngmiàn xiǎng chūguó niànshū, yìfāngmiàn yòu shěbude líkāi jiārén。', example_vietnamese = 'Một mặt anh ấy muốn ra nước ngoài học, mặt khác lại không nỡ rời xa gia đình.' WHERE level = 'B1' AND hanzi = '一方面' AND pinyin = 'yìfāngmiàn' AND vietnamese = 'Một mặt thì…';
UPDATE public.dictionary_words SET example_hanzi = '這個星期一連下了好幾天的雨。', example_pinyin = 'zhè ge xīngqí yìlián xià le hǎo jǐ tiān de yǔ。', example_vietnamese = 'Tuần này trời mưa liên tiếp mấy ngày liền.' WHERE level = 'B1' AND hanzi = '一連' AND pinyin = 'yìlián' AND vietnamese = 'Liên tiếp, không ngừng';
UPDATE public.dictionary_words SET example_hanzi = '她把一生都奉獻給了教育工作。', example_pinyin = 'tā bǎ yìshēng dōu fèngxiàn gěi le jiàoyù gōngzuò。', example_vietnamese = 'Bà đã cống hiến cả đời mình cho công việc giáo dục.' WHERE level = 'B1' AND hanzi = '一生' AND pinyin = 'yìshēng' AND vietnamese = 'Suốt đời, cả đời';
UPDATE public.dictionary_words SET example_hanzi = '這個名字我一時想不起來。', example_pinyin = 'zhè ge míngzi wǒ yìshí xiǎng bù qǐlái。', example_vietnamese = 'Cái tên này tôi nhất thời không nhớ ra được.' WHERE level = 'B1' AND hanzi = '一時' AND pinyin = 'yìshí' AND vietnamese = 'Một lúc, nhất thời';
UPDATE public.dictionary_words SET example_hanzi = '大家一同舉杯慶祝生日。', example_pinyin = 'dàjiā yìtóng jǔbēi qìngzhù shēngrì。', example_vietnamese = 'Mọi người cùng nhau nâng ly chúc mừng sinh nhật.' WHERE level = 'B1' AND hanzi = '一同' AND pinyin = 'yìtóng' AND vietnamese = 'Cùng, chung';
UPDATE public.dictionary_words SET example_hanzi = '對這個計畫,你有什麼意見?', example_pinyin = 'duì zhè ge jìhuà, nǐ yǒu shénme yìjiàn?', example_vietnamese = 'Bạn có ý kiến gì về kế hoạch này không?' WHERE level = 'B1' AND hanzi = '意見' AND pinyin = 'yìjiàn' AND vietnamese = 'Ý kiến';
UPDATE public.dictionary_words SET example_hanzi = '昨天路上發生了一場車禍意外。', example_pinyin = 'zuótiān lùshang fāshēng le yì chǎng chēhuò yìwài。', example_vietnamese = 'Hôm qua trên đường xảy ra một vụ tai nạn giao thông bất ngờ.' WHERE level = 'B1' AND hanzi = '意外' AND pinyin = 'yìwài' AND vietnamese = 'Bất ngờ, không ngờ';
UPDATE public.dictionary_words SET example_hanzi = '這次旅行對我來說很有意義。', example_pinyin = 'zhè cì lǚxíng duì wǒ láishuō hěn yǒu yìyì。', example_vietnamese = 'Chuyến đi này rất có ý nghĩa đối với tôi.' WHERE level = 'B1' AND hanzi = '意義' AND pinyin = 'yìyì' AND vietnamese = 'Ý nghĩa';
UPDATE public.dictionary_words SET example_hanzi = '今天天空很陰,好像快要下雨了。', example_pinyin = 'jīntiān tiānkōng hěn yīn, hǎoxiàng kuài yào xiàyǔ le。', example_vietnamese = 'Hôm nay trời rất âm u, hình như sắp mưa rồi.' WHERE level = 'B1' AND hanzi = '陰' AND pinyin = 'yīn' AND vietnamese = 'Âm';
UPDATE public.dictionary_words SET example_hanzi = '他平常很用功,因此考試成績一直很好。', example_pinyin = 'tā píngcháng hěn yònggōng, yīncǐ kǎoshì chéngjì yìzhí hěn hǎo。', example_vietnamese = 'Anh ấy thường ngày rất chăm chỉ, vì vậy điểm thi luôn tốt.' WHERE level = 'B1' AND hanzi = '因此' AND pinyin = 'yīncĭ' AND vietnamese = 'Vì vậy, do đó';
UPDATE public.dictionary_words SET example_hanzi = '他花了不少錢買了一套音響。', example_pinyin = 'tā huā le bùshǎo qián mǎi le yí tào yīnxiǎng。', example_vietnamese = 'Anh ấy đã tốn không ít tiền để mua một bộ dàn âm thanh.' WHERE level = 'B1' AND hanzi = '音響' AND pinyin = 'yīnxiăng' AND vietnamese = 'Âm thanh, giọng';
UPDATE public.dictionary_words SET example_hanzi = '這個新聞引起了大家的討論。', example_pinyin = 'zhè ge xīnwén yǐnqǐ le dàjiā de tǎolùn。', example_vietnamese = 'Tin tức này đã gây nên cuộc thảo luận của mọi người.' WHERE level = 'B1' AND hanzi = '引起' AND pinyin = 'yĭnqĭ' AND vietnamese = 'Gây nên, dẫn tới';
UPDATE public.dictionary_words SET example_hanzi = '老師一叫他的名字,他馬上應了一聲。', example_pinyin = 'lǎoshī yí jiào tā de míngzi, tā mǎshàng yīng le yì shēng。', example_vietnamese = 'Vừa khi giáo viên gọi tên cậu ấy, cậu liền đáp lời ngay.' WHERE level = 'B1' AND hanzi = '應' AND pinyin = 'yīng' AND vietnamese = 'Trả lời, đáp lời';
UPDATE public.dictionary_words SET example_hanzi = '你應該多喝水,對身體比較好。', example_pinyin = 'nǐ yīnggāi duō hē shuǐ, duì shēntǐ bǐjiào hǎo。', example_vietnamese = 'Bạn nên uống nhiều nước hơn, tốt cho sức khỏe.' WHERE level = 'B1' AND hanzi = '應該' AND pinyin = 'yīnggāi' AND vietnamese = 'Nên';
UPDATE public.dictionary_words SET example_hanzi = '新郎今天穿西裝顯得特別英俊。', example_pinyin = 'xīnláng jīntiān chuān xīzhuāng xiǎnde tèbié yīngjùn。', example_vietnamese = 'Hôm nay chú rể mặc vest trông đặc biệt đẹp trai.' WHERE level = 'B1' AND hanzi = '英俊' AND pinyin = 'yīngjùn' AND vietnamese = 'Tài năng xuất chúng';
UPDATE public.dictionary_words SET example_hanzi = '蔬菜和水果都含有豐富的營養。', example_pinyin = 'shūcài hàn shuǐguǒ dōu hán yǒu fēngfù de yíngyǎng。', example_vietnamese = 'Rau và trái cây đều chứa nhiều chất dinh dưỡng.' WHERE level = 'B1' AND hanzi = '營養' AND pinyin = 'yíngyăng' AND vietnamese = 'Chất dinh dưỡng';
UPDATE public.dictionary_words SET example_hanzi = '這部影片得到了很高的評價。', example_pinyin = 'zhè bù yǐngpiàn dé dào le hěn gāo de píngjià。', example_vietnamese = 'Bộ phim này nhận được đánh giá rất cao.' WHERE level = 'B1' AND hanzi = '影片' AND pinyin = 'yĭngpiàn' AND vietnamese = 'Phim nhựa';
UPDATE public.dictionary_words SET example_hanzi = '每個人都擁有追求幸福的權利。', example_pinyin = 'měi ge rén dōu yǒngyǒu zhuīqiú xìngfú de quánlì。', example_vietnamese = 'Mỗi người đều có quyền theo đuổi hạnh phúc.' WHERE level = 'B1' AND hanzi = '擁有' AND pinyin = 'yŏngyŏu' AND vietnamese = 'Có, hàm chứa';
UPDATE public.dictionary_words SET example_hanzi = '請用中文回答這個問題。', example_pinyin = 'qǐng yòng zhōngwén huídá zhè ge wèntí。', example_vietnamese = 'Xin hãy dùng tiếng Trung để trả lời câu hỏi này.' WHERE level = 'B1' AND hanzi = '用' AND pinyin = 'yòng' AND vietnamese = 'Dùng, sử dụng';
UPDATE public.dictionary_words SET example_hanzi = '老師詳細說明了這個語法的用法。', example_pinyin = 'lǎoshī xiángxì shuōmíng le zhè ge yǔfǎ de yòngfǎ。', example_vietnamese = 'Giáo viên đã giải thích chi tiết cách dùng của ngữ pháp này.' WHERE level = 'B1' AND hanzi = '用法' AND pinyin = 'yòngfă' AND vietnamese = 'Cách dùng';
UPDATE public.dictionary_words SET example_hanzi = '這學期他比以前更用功了。', example_pinyin = 'zhè xuéqī tā bǐ yǐqián gèng yònggōng le。', example_vietnamese = 'Học kỳ này cậu ấy chăm chỉ hơn trước.' WHERE level = 'B1' AND hanzi = '用功' AND pinyin = 'yònggōng' AND vietnamese = 'Cố gắng, chăm chỉ';
UPDATE public.dictionary_words SET example_hanzi = '這家店賣各種生活用品。', example_pinyin = 'zhè jiā diàn mài gè zhǒng shēnghuó yòngpǐn。', example_vietnamese = 'Cửa hàng này bán các loại đồ dùng sinh hoạt.' WHERE level = 'B1' AND hanzi = '用品' AND pinyin = 'yòngpĭn' AND vietnamese = 'Đồ dùng, vật dụng';
UPDATE public.dictionary_words SET example_hanzi = '誠實是他最大的優點。', example_pinyin = 'chéngshí shì tā zuì dà de yōudiǎn。', example_vietnamese = 'Trung thực là ưu điểm lớn nhất của anh ấy.' WHERE level = 'B1' AND hanzi = '優點' AND pinyin = 'yōudiăn' AND vietnamese = 'Ưu điểm';
UPDATE public.dictionary_words SET example_hanzi = '她是班上最優秀的學生。', example_pinyin = 'tā shì bān shàng zuì yōuxiù de xuéshēng。', example_vietnamese = 'Cô ấy là học sinh ưu tú nhất trong lớp.' WHERE level = 'B1' AND hanzi = '優秀' AND pinyin = 'yōuxiù' AND vietnamese = 'Ưu tú';
UPDATE public.dictionary_words SET example_hanzi = '他說話很幽默,大家都喜歡跟他聊天。', example_pinyin = 'tā shuōhuà hěn yōumò, dàjiā dōu xǐhuan gēn tā liáotiān。', example_vietnamese = 'Anh ấy nói chuyện rất hài hước, mọi người đều thích trò chuyện với anh.' WHERE level = 'B1' AND hanzi = '幽默' AND pinyin = 'yōumò' AND vietnamese = 'Hài hước';
UPDATE public.dictionary_words SET example_hanzi = '他從小就喜歡收集各國的郵票。', example_pinyin = 'tā cóng xiǎo jiù xǐhuan shōují gè guó de yóupiào。', example_vietnamese = 'Anh ấy thích sưu tầm tem của các nước từ nhỏ.' WHERE level = 'B1' AND hanzi = '郵票' AND pinyin = 'yóupiào' AND vietnamese = 'Tem';
UPDATE public.dictionary_words SET example_hanzi = '我喜歡吃水果,尤其是芒果。', example_pinyin = 'wǒ xǐhuan chī shuǐguǒ, yóuqí shì mángguǒ。', example_vietnamese = 'Tôi thích ăn trái cây, nhất là xoài.' WHERE level = 'B1' AND hanzi = '尤其' AND pinyin = 'yóuqí' AND vietnamese = 'Nhất là, đặc biệt là…';
UPDATE public.dictionary_words SET example_hanzi = '這個景點每年都吸引大批遊客前來。', example_pinyin = 'zhè ge jǐngdiǎn měi nián dōu xīyǐn dàpī yóukè qiánlái。', example_vietnamese = 'Điểm du lịch này mỗi năm đều thu hút đông đảo du khách đến thăm.' WHERE level = 'B1' AND hanzi = '遊客' AND pinyin = 'yóukè' AND vietnamese = 'Du khách';
UPDATE public.dictionary_words SET example_hanzi = '這家飯店有一個很大的游泳池。', example_pinyin = 'zhè jiā fàndiàn yǒu yí ge hěn dà de yóuyǒngchí。', example_vietnamese = 'Khách sạn này có một hồ bơi rất lớn.' WHERE level = 'B1' AND hanzi = '游泳池' AND pinyin = 'yóuyŏngchí' AND vietnamese = 'Hồ bơi, bể bơi';
UPDATE public.dictionary_words SET example_hanzi = '由於天氣不好,比賽只好延期。', example_pinyin = 'yóuyú tiānqì bù hǎo, bǐsài zhǐhǎo yánqī。', example_vietnamese = 'Do thời tiết không tốt nên trận đấu đành phải hoãn lại.' WHERE level = 'B1' AND hanzi = '由於' AND pinyin = 'yóuyú' AND vietnamese = 'Bởi vì';
UPDATE public.dictionary_words SET example_hanzi = '今天的考試有點兒難。', example_pinyin = 'jīntiān de kǎoshì yǒudiǎnr nán。', example_vietnamese = 'Bài thi hôm nay hơi khó.' WHERE level = 'B1' AND hanzi = '"有(一)點/ 有(一)點兒"' AND pinyin = 'yǒu(yì)diăn/ yǒu(yì)di' AND vietnamese = 'Hơi hơi, một chút';
UPDATE public.dictionary_words SET example_hanzi = '班上的學生,有的喜歡唱歌,有的喜歡畫畫。', example_pinyin = 'bān shàng de xuéshēng, yǒude xǐhuan chànggē, yǒude xǐhuan huàhuà。', example_vietnamese = 'Học sinh trong lớp, có bạn thích hát, có bạn thích vẽ tranh.' WHERE level = 'B1' AND hanzi = '有的' AND pinyin = 'yǒude' AND vietnamese = 'Có';
UPDATE public.dictionary_words SET example_hanzi = '這家餐廳的牛肉麵很有名。', example_pinyin = 'zhè jiā cāntīng de niúròumiàn hěn yǒumíng。', example_vietnamese = 'Món mì bò của nhà hàng này rất nổi tiếng.' WHERE level = 'B1' AND hanzi = '有名' AND pinyin = 'yǒumíng' AND vietnamese = 'Nổi tiếng';
UPDATE public.dictionary_words SET example_hanzi = '他家很有錢,住在一棟大房子裡。', example_pinyin = 'tā jiā hěn yǒuqián, zhù zài yí dòng dà fángzi lǐ。', example_vietnamese = 'Gia đình anh ấy rất giàu có, sống trong một căn nhà lớn.' WHERE level = 'B1' AND hanzi = '有錢' AND pinyin = 'yǒuqián' AND vietnamese = 'Có tiền';
UPDATE public.dictionary_words SET example_hanzi = '這個方法對減肥很有效。', example_pinyin = 'zhè ge fāngfǎ duì jiǎnféi hěn yǒuxiào。', example_vietnamese = 'Phương pháp này rất hiệu quả đối với việc giảm cân.' WHERE level = 'B1' AND hanzi = '有效' AND pinyin = 'yŏuxiào' AND vietnamese = 'Có hiệu quả';
UPDATE public.dictionary_words SET example_hanzi = '這部小說的故事情節很有意思。', example_pinyin = 'zhè bù xiǎoshuō de gùshi qíngjié hěn yǒuyìsi。', example_vietnamese = 'Tình tiết câu chuyện trong cuốn tiểu thuyết này rất thú vị.' WHERE level = 'B1' AND hanzi = '有意思' AND pinyin = 'yǒuyìsi' AND vietnamese = 'Thú vị';
UPDATE public.dictionary_words SET example_hanzi = '這兩個國家之間的友誼已經維持了很多年。', example_pinyin = 'zhè liǎng ge guójiā zhījiān de yǒuyì yǐjīng wéichí le hěn duō nián。', example_vietnamese = 'Tình hữu nghị giữa hai nước này đã được duy trì nhiều năm nay.' WHERE level = 'B1' AND hanzi = '友誼' AND pinyin = 'yŏuyì' AND vietnamese = 'Hữu nghị';
UPDATE public.dictionary_words SET example_hanzi = '他覺得肚子餓了,於是就去買了一個便當。', example_pinyin = 'tā juéde dùzi è le, yúshì jiù qù mǎi le yí ge biàndāng。', example_vietnamese = 'Anh ấy cảm thấy đói bụng, thế là liền đi mua một hộp cơm.' WHERE level = 'B1' AND hanzi = '於是' AND pinyin = 'yúshì' AND vietnamese = 'Thế là';
UPDATE public.dictionary_words SET example_hanzi = '這場比賽是台灣隊與日本隊的對決。', example_pinyin = 'zhè chǎng bǐsài shì táiwān duì yǔ rìběn duì de duìjué。', example_vietnamese = 'Trận đấu này là cuộc đối đầu giữa đội Đài Loan và đội Nhật Bản.' WHERE level = 'B1' AND hanzi = '與' AND pinyin = 'yǔ' AND vietnamese = 'Với';
UPDATE public.dictionary_words SET example_hanzi = '環境保護與經濟發展同樣重要。', example_pinyin = 'huánjìng bǎohù yǔ jīngjì fāzhǎn tóngyàng zhòngyào。', example_vietnamese = 'Bảo vệ môi trường và phát triển kinh tế đều quan trọng như nhau.' WHERE level = 'B1' AND hanzi = '與' AND pinyin = 'yǔ' AND vietnamese = 'và, cùng với';
UPDATE public.dictionary_words SET example_hanzi = '她手上戴著一個玉做的手鐲。', example_pinyin = 'tā shǒushàng dài zhe yí ge yù zuò de shǒuzhuó。', example_vietnamese = 'Trên tay cô ấy đeo một chiếc vòng làm bằng ngọc.' WHERE level = 'B1' AND hanzi = '玉' AND pinyin = 'yù' AND vietnamese = 'Ngọc, ngọc thạch';
UPDATE public.dictionary_words SET example_hanzi = '媽媽煮了一鍋玉米湯。', example_pinyin = 'māma zhǔ le yì guō yùmǐ tāng。', example_vietnamese = 'Mẹ đã nấu một nồi súp ngô.' WHERE level = 'B1' AND hanzi = '玉米' AND pinyin = 'yùmi' AND vietnamese = 'Cây ngô, bắp';
UPDATE public.dictionary_words SET example_hanzi = '老師已經預備好明天上課要用的教材。', example_pinyin = 'lǎoshī yǐjīng yùbèi hǎo míngtiān shàngkè yào yòng de jiàocái。', example_vietnamese = 'Giáo viên đã chuẩn bị sẵn tài liệu dùng cho tiết học ngày mai.' WHERE level = 'B1' AND hanzi = '預備' AND pinyin = 'yùbèi' AND vietnamese = 'Dự bị';
UPDATE public.dictionary_words SET example_hanzi = '上課前記得先預習課文。', example_pinyin = 'shàngkè qián jìde xiān yùxí kèwén。', example_vietnamese = 'Trước khi vào lớp nhớ ôn bài trước bài khóa.' WHERE level = 'B1' AND hanzi = '預習' AND pinyin = 'yùxí' AND vietnamese = 'Ôn trước, chuẩn bị bài';
UPDATE public.dictionary_words SET example_hanzi = '我昨天在路上遇到了一個老朋友。', example_pinyin = 'wǒ zuótiān zài lù shàng yùdào le yí ge lǎo péngyou。', example_vietnamese = 'Hôm qua tôi tình cờ gặp một người bạn cũ trên đường.' WHERE level = 'B1' AND hanzi = '遇到' AND pinyin = 'yùdào' AND vietnamese = 'Gặp phải';
UPDATE public.dictionary_words SET example_hanzi = '月亮今晚又圓又亮。', example_pinyin = 'yuèliang jīnwǎn yòu yuán yòu liàng。', example_vietnamese = 'Tối nay trăng vừa tròn vừa sáng.' WHERE level = 'B1' AND hanzi = '圓' AND pinyin = 'yuán' AND vietnamese = 'Hình tròn';
UPDATE public.dictionary_words SET example_hanzi = '公司決定給全體員工加薪。', example_pinyin = 'gōngsī juédìng gěi quántǐ yuángōng jiāxīn。', example_vietnamese = 'Công ty quyết định tăng lương cho toàn thể nhân viên.' WHERE level = 'B1' AND hanzi = '員工' AND pinyin = 'yuángōng' AND vietnamese = 'Công nhân, viên chức';
UPDATE public.dictionary_words SET example_hanzi = '對不起,你可以原諒我這一次嗎?', example_pinyin = 'duìbùqǐ, nǐ kěyǐ yuánliàng wǒ zhè yí cì ma?', example_vietnamese = 'Xin lỗi, bạn có thể tha thứ cho tôi lần này không?' WHERE level = 'B1' AND hanzi = '原諒' AND pinyin = 'yuánliàng' AND vietnamese = 'Tha thứ, thứ lỗi';
UPDATE public.dictionary_words SET example_hanzi = '這場火災的原因還在調查中。', example_pinyin = 'zhè chǎng huǒzāi de yuányīn hái zài diàochá zhōng。', example_vietnamese = 'Nguyên nhân của vụ hỏa hoạn này vẫn đang được điều tra.' WHERE level = 'B1' AND hanzi = '原因' AND pinyin = 'yuányīn' AND vietnamese = 'Nguyên nhân';
UPDATE public.dictionary_words SET example_hanzi = '他從小的願望就是當一位醫生。', example_pinyin = 'tā cóng xiǎo de yuànwàng jiù shì dāng yí wèi yīshēng。', example_vietnamese = 'Nguyện vọng từ nhỏ của anh ấy là trở thành bác sĩ.' WHERE level = 'B1' AND hanzi = '願望' AND pinyin = 'yuànwàng' AND vietnamese = 'Nguyện vọng';
UPDATE public.dictionary_words SET example_hanzi = '爺爺喜歡在院子裡種花。', example_pinyin = 'yéye xǐhuan zài yuànzi lǐ zhòng huā。', example_vietnamese = 'Ông thích trồng hoa trong sân.' WHERE level = 'B1' AND hanzi = '院子' AND pinyin = 'yuànzi' AND vietnamese = 'Sân trong';
UPDATE public.dictionary_words SET example_hanzi = '從這裡到火車站約需要二十分鐘。', example_pinyin = 'cóng zhèlǐ dào huǒchēzhàn yuē xūyào èrshí fēnzhōng。', example_vietnamese = 'Từ đây đến ga xe lửa khoảng cần hai mươi phút.' WHERE level = 'B1' AND hanzi = '約' AND pinyin = 'yuē' AND vietnamese = 'Cân';
UPDATE public.dictionary_words SET example_hanzi = '她今晚有一個重要的約會。', example_pinyin = 'tā jīnwǎn yǒu yí ge zhòngyào de yuēhuì。', example_vietnamese = 'Tối nay cô ấy có một cuộc hẹn quan trọng.' WHERE level = 'B1' AND hanzi = '約會' AND pinyin = 'yuēhuì' AND vietnamese = 'Hẹn hò';
UPDATE public.dictionary_words SET example_hanzi = '他們約會三個月後就決定結婚了。', example_pinyin = 'tāmen yuēhuì sān ge yuè hòu jiù juédìng jiéhūn le。', example_vietnamese = 'Sau khi hẹn hò được ba tháng, họ đã quyết định kết hôn.' WHERE level = 'B1' AND hanzi = '約會' AND pinyin = 'yuēhuì' AND vietnamese = 'Hẹn gặp';
UPDATE public.dictionary_words SET example_hanzi = '天氣越來越冷了。', example_pinyin = 'tiānqì yuè lái yuè lěng le。', example_vietnamese = 'Thời tiết ngày càng lạnh hơn.' WHERE level = 'B1' AND hanzi = '越' AND pinyin = 'yuè' AND vietnamese = 'Vượt qua';
