UPDATE public.dictionary_words SET example_hanzi = '他每天睡前都有閱讀的習慣。', example_pinyin = 'tā měitiān shuì qián dōu yǒu yuèdú de xíguàn。', example_vietnamese = 'Anh ấy có thói quen đọc sách mỗi tối trước khi ngủ.' WHERE level = 'B1' AND hanzi = '閱讀' AND pinyin = 'yuèdú' AND vietnamese = 'Xem, đọc';
UPDATE public.dictionary_words SET example_hanzi = '這個樂團明天晚上有一場演出。', example_pinyin = 'zhè ge yuètuán míngtiān wǎnshàng yǒu yì chǎng yǎnchū。', example_vietnamese = 'Dàn nhạc này có một buổi biểu diễn vào tối mai.' WHERE level = 'B1' AND hanzi = '樂團' AND pinyin = 'yuètuán' AND vietnamese = 'Dàn nhạc, ban nhạc';
UPDATE public.dictionary_words SET example_hanzi = '這次能中獎,真是運氣好。', example_pinyin = 'zhè cì néng zhòng jiǎng, zhēn shì yùnqì hǎo。', example_vietnamese = 'Lần này trúng thưởng được, thật là may mắn.' WHERE level = 'B1' AND hanzi = '運氣' AND pinyin = 'yùnqì' AND vietnamese = 'Vận may';
UPDATE public.dictionary_words SET example_hanzi = '我爸爸現在在客廳看電視。', example_pinyin = 'wǒ bàba xiànzài zài kètīng kàn diànshì。', example_vietnamese = 'Bố tôi hiện đang ở phòng khách xem tivi.' WHERE level = 'B1' AND hanzi = '在' AND pinyin = 'zài' AND vietnamese = 'Tồn tại, sống, ở';
UPDATE public.dictionary_words SET example_hanzi = '別太在意別人怎麼說你。', example_pinyin = 'bié tài zàiyì biérén zěnme shuō nǐ。', example_vietnamese = 'Đừng quá để ý người khác nói gì về bạn.' WHERE level = 'B1' AND hanzi = '在意' AND pinyin = 'zàiyì' AND vietnamese = 'Để ý';
UPDATE public.dictionary_words SET example_hanzi = '成功的關鍵在於堅持不放棄。', example_pinyin = 'chénggōng de guānjiàn zàiyú jiānchí bú fàngqì。', example_vietnamese = 'Chìa khóa của thành công nằm ở việc kiên trì không bỏ cuộc.' WHERE level = 'B1' AND hanzi = '在於' AND pinyin = 'zàiyú' AND vietnamese = 'ở chỗ';
UPDATE public.dictionary_words SET example_hanzi = '他今天比平常早一個小時起床。', example_pinyin = 'tā jīntiān bǐ píngcháng zǎo yí ge xiǎoshí qǐchuáng。', example_vietnamese = 'Hôm nay anh ấy dậy sớm hơn thường ngày một tiếng.' WHERE level = 'B1' AND hanzi = '早' AND pinyin = 'zăo' AND vietnamese = 'Sớm';
UPDATE public.dictionary_words SET example_hanzi = '祝你早日康復。', example_pinyin = 'zhù nǐ zǎorì kāngfù。', example_vietnamese = 'Chúc bạn sớm bình phục.' WHERE level = 'B1' AND hanzi = '早日' AND pinyin = 'zăorì' AND vietnamese = 'Trước kia';
UPDATE public.dictionary_words SET example_hanzi = '你這樣熬夜,早晚會累壞身體的。', example_pinyin = 'nǐ zhèyàng áoyè, zǎowǎn huì lèi huài shēntǐ de。', example_vietnamese = 'Bạn thức khuya như thế này, sớm muộn gì cũng sẽ làm hại sức khỏe đấy.' WHERE level = 'B1' AND hanzi = '早晚' AND pinyin = 'zăowăn' AND vietnamese = 'Sớm tối';
UPDATE public.dictionary_words SET example_hanzi = '這場大雨造成了嚴重的淹水。', example_pinyin = 'zhè chǎng dàyǔ zàochéng le yánzhòng de yānshuǐ。', example_vietnamese = 'Trận mưa lớn này đã gây ra tình trạng ngập lụt nghiêm trọng.' WHERE level = 'B1' AND hanzi = '造成' AND pinyin = 'zàochéng' AND vietnamese = 'Tạo thành';
