UPDATE public.dictionary_words SET example_hanzi = '照顧家人是每個人的責任。', example_pinyin = 'zhàogù jiārén shì měi ge rén de zérèn。', example_vietnamese = 'Chăm sóc gia đình là trách nhiệm của mỗi người.' WHERE level = 'B1' AND hanzi = '責任' AND pinyin = 'zérèn' AND vietnamese = 'Trách nhiệm';
UPDATE public.dictionary_words SET example_hanzi = '這個月公司的業績增加了不少。', example_pinyin = 'zhè ge yuè gōngsī de yèjì zēngjiā le bùshǎo。', example_vietnamese = 'Tháng này doanh thu công ty tăng thêm không ít.' WHERE level = 'B1' AND hanzi = '增加' AND pinyin = 'zēngjiā' AND vietnamese = 'Tăng thêm';
UPDATE public.dictionary_words SET example_hanzi = '媽媽在廚房炸雞排給我們吃。', example_pinyin = 'māma zài chúfáng zhá jīpái gěi wǒmen chī。', example_vietnamese = 'Mẹ đang chiên gà cho chúng tôi ăn trong bếp.' WHERE level = 'B1' AND hanzi = '炸' AND pinyin = 'zhà/zhá' AND vietnamese = 'Chiên, rán';
UPDATE public.dictionary_words SET example_hanzi = '農夫每天一大早就去果園摘蘋果。', example_pinyin = 'nóngfū měitiān yí dàzǎo jiù qù guǒyuán zhāi píngguǒ。', example_vietnamese = 'Người nông dân mỗi ngày dậy thật sớm để đi hái táo trong vườn.' WHERE level = 'B1' AND hanzi = '摘' AND pinyin = 'zhāi' AND vietnamese = 'Hái, bẻ, ngắt';
UPDATE public.dictionary_words SET example_hanzi = '下一站就是台北車站了。', example_pinyin = 'xià yí zhàn jiù shì táiběi chēzhàn le。', example_vietnamese = 'Trạm tiếp theo chính là ga Đài Bắc rồi.' WHERE level = 'B1' AND hanzi = '站' AND pinyin = 'zhàn' AND vietnamese = 'Trạm';
UPDATE public.dictionary_words SET example_hanzi = '這個問題我們暫時先不討論。', example_pinyin = 'zhè ge wèntí wǒmen zhànshí xiān bù tǎolùn。', example_vietnamese = 'Vấn đề này chúng ta tạm thời chưa bàn tới.' WHERE level = 'B1' AND hanzi = '暫時' AND pinyin = 'zhànshí' AND vietnamese = 'Tạm thời';
UPDATE public.dictionary_words SET example_hanzi = '沒有人希望戰爭發生。', example_pinyin = 'méi yǒu rén xīwàng zhànzhēng fāshēng。', example_vietnamese = 'Không ai mong muốn chiến tranh xảy ra cả.' WHERE level = 'B1' AND hanzi = '戰爭' AND pinyin = 'zhànzhēng' AND vietnamese = 'Chiến tranh';
UPDATE public.dictionary_words SET example_hanzi = '哥哥比我長兩歲。', example_pinyin = 'gēge bǐ wǒ zhǎng liǎng suì。', example_vietnamese = 'Anh trai lớn hơn tôi hai tuổi.' WHERE level = 'B1' AND hanzi = '長' AND pinyin = 'zhǎng' AND vietnamese = 'Lớn';
UPDATE public.dictionary_words SET example_hanzi = '小孩子長大以後想當老師。', example_pinyin = 'xiǎo háizi zhǎngdà yǐhòu xiǎng dāng lǎoshī。', example_vietnamese = 'Đứa trẻ nhỏ muốn trở thành giáo viên sau khi lớn lên.' WHERE level = 'B1' AND hanzi = '長大' AND pinyin = 'zhǎngdà' AND vietnamese = 'Cao lớn';
UPDATE public.dictionary_words SET example_hanzi = '學語言最重要的是掌握基本文法。', example_pinyin = 'xué yǔyán zuì zhòngyào de shì zhǎngwò jīběn wénfǎ。', example_vietnamese = 'Điều quan trọng nhất khi học ngôn ngữ là nắm vững ngữ pháp cơ bản.' WHERE level = 'B1' AND hanzi = '掌握' AND pinyin = 'zhăngwò' AND vietnamese = 'Nắm bắt';
