UPDATE public.dictionary_words SET example_hanzi = '這家店的招牌是用手寫的。', example_pinyin = 'zhè jiā diàn de zhāopái shì yòng shǒu xiě de。', example_vietnamese = 'Bảng hiệu của cửa hàng này được viết bằng tay.' WHERE level = 'B1' AND hanzi = '招牌' AND pinyin = 'zhāopái' AND vietnamese = 'Bảng hiệu';
UPDATE public.dictionary_words SET example_hanzi = '老闆找給我五十塊錢。', example_pinyin = 'lǎobǎn zhǎo gěi wǒ wǔshí kuài qián。', example_vietnamese = 'Ông chủ trả lại tiền thừa cho tôi năm mươi đồng.' WHERE level = 'B1' AND hanzi = '找錢' AND pinyin = 'zhǎoqián' AND vietnamese = 'Trả lại tiền thừa';
