UPDATE public.dictionary_words SET example_hanzi = '陽光照進房間,感覺特別溫暖。', example_pinyin = 'yángguāng zhào jìn fángjiān, gǎnjué tèbié wēnnuǎn。', example_vietnamese = 'Ánh nắng chiếu vào phòng, cảm giác đặc biệt ấm áp.' WHERE level = 'B1' AND hanzi = '照' AND pinyin = 'zhào' AND vietnamese = 'Chiếu rọi';
UPDATE public.dictionary_words SET example_hanzi = '他大學主修的是哲學。', example_pinyin = 'tā dàxué zhǔxiū de shì zhéxué。', example_vietnamese = 'Ngành chính anh ấy học ở đại học là triết học.' WHERE level = 'B1' AND hanzi = '哲學' AND pinyin = 'zhéxué' AND vietnamese = 'Triết học';
UPDATE public.dictionary_words SET example_hanzi = '這裡的風景真美。', example_pinyin = 'zhèlǐ de fēngjǐng zhēn měi。', example_vietnamese = 'Phong cảnh ở đây thật đẹp.' WHERE level = 'B1' AND hanzi = '這裏' AND pinyin = 'zhèlĭ' AND vietnamese = 'ở đây, nơi đây';
UPDATE public.dictionary_words SET example_hanzi = '這下子麻煩大了,手機掉進水裡了。', example_pinyin = 'zhèxiàzi máfan dà le, shǒujī diào jìn shuǐ lǐ le。', example_vietnamese = 'Lần này thì rắc rối to rồi, điện thoại rơi xuống nước mất rồi.' WHERE level = 'B1' AND hanzi = '這下子' AND pinyin = 'zhèxiàzi' AND vietnamese = 'Lúc này';
UPDATE public.dictionary_words SET example_hanzi = '你別這樣對他說話。', example_pinyin = 'nǐ bié zhèyàng duì tā shuōhuà。', example_vietnamese = 'Bạn đừng nói chuyện với anh ấy như thế này.' WHERE level = 'B1' AND hanzi = '這樣' AND pinyin = 'zhèyàng' AND vietnamese = 'Như thế này';
UPDATE public.dictionary_words SET example_hanzi = '你這樣子一直生氣對身體不好。', example_pinyin = 'nǐ zhèyàngzi yìzhí shēngqì duì shēntǐ bù hǎo。', example_vietnamese = 'Bạn cứ giận dữ như thế mãi thì không tốt cho sức khỏe đâu.' WHERE level = 'B1' AND hanzi = '這樣子' AND pinyin = 'zhèyàngzi' AND vietnamese = 'Như thế';
UPDATE public.dictionary_words SET example_hanzi = '事情怎麼會變成這樣子?', example_pinyin = 'shìqíng zěnme huì biàn chéng zhèyàngzi?', example_vietnamese = 'Sao sự việc lại trở thành như thế này chứ?' WHERE level = 'B1' AND hanzi = '這樣子' AND pinyin = 'zhèyàngzi' AND vietnamese = 'Như thế này';
UPDATE public.dictionary_words SET example_hanzi = '真的嗎?你明天真的要出國了?', example_pinyin = 'zhēnde ma? nǐ míngtiān zhēnde yào chūguó le?', example_vietnamese = 'Thật à? Ngày mai bạn thật sự sẽ ra nước ngoài à?' WHERE level = 'B1' AND hanzi = '真的' AND pinyin = 'zhēnde' AND vietnamese = 'Có thật không?';
UPDATE public.dictionary_words SET example_hanzi = '科學家一生都在追求真理。', example_pinyin = 'kēxuéjiā yìshēng dōu zài zhuīqiú zhēnlǐ。', example_vietnamese = 'Nhà khoa học cả đời đều đi tìm kiếm chân lý.' WHERE level = 'B1' AND hanzi = '真理' AND pinyin = 'zhēnlĭ' AND vietnamese = 'Chân lý';
UPDATE public.dictionary_words SET example_hanzi = '這部電影是根據真實故事改編的。', example_pinyin = 'zhè bù diànyǐng shì gēnjù zhēnshí gùshi gǎibiān de。', example_vietnamese = 'Bộ phim này được chuyển thể từ một câu chuyện có thật.' WHERE level = 'B1' AND hanzi = '真實' AND pinyin = 'zhēnshí' AND vietnamese = 'Chân thực';
UPDATE public.dictionary_words SET example_hanzi = '這麼熱的天氣,真是讓人受不了。', example_pinyin = 'zhème rè de tiānqì, zhēnshì ràng rén shòu bù liǎo。', example_vietnamese = 'Thời tiết nóng thế này, thật là khiến người ta không chịu nổi.' WHERE level = 'B1' AND hanzi = '真是' AND pinyin = 'zhēnshì' AND vietnamese = 'Thật là!';
UPDATE public.dictionary_words SET example_hanzi = '我是真心想幫你解決問題。', example_pinyin = 'wǒ shì zhēnxīn xiǎng bāng nǐ jiějué wèntí。', example_vietnamese = 'Tôi thật lòng muốn giúp bạn giải quyết vấn đề.' WHERE level = 'B1' AND hanzi = '真心' AND pinyin = 'zhēnxīn' AND vietnamese = 'Thật lòng';
UPDATE public.dictionary_words SET example_hanzi = '我現在才真正了解他的想法。', example_pinyin = 'wǒ xiànzài cái zhēnzhèng liǎojiě tā de xiǎngfǎ。', example_vietnamese = 'Bây giờ tôi mới thực sự hiểu được suy nghĩ của anh ấy.' WHERE level = 'B1' AND hanzi = '真正' AND pinyin = 'zhēnzhèng' AND vietnamese = 'Chân chính';
