UPDATE public.dictionary_words SET example_hanzi = '這張照片對我來說非常珍貴。', example_pinyin = 'zhè zhāng zhàopiàn duì wǒ láishuō fēicháng zhēnguì。', example_vietnamese = 'Bức ảnh này đối với tôi vô cùng quý giá.' WHERE level = 'B1' AND hanzi = '珍貴' AND pinyin = 'zhēnguì' AND vietnamese = 'Quý giá';
UPDATE public.dictionary_words SET example_hanzi = '他整個晚上都在準備明天的報告。', example_pinyin = 'tā zhěng ge wǎnshàng dōu zài zhǔnbèi míngtiān de bàogào。', example_vietnamese = 'Anh ấy dành trọn cả buổi tối để chuẩn bị báo cáo cho ngày mai.' WHERE level = 'B1' AND hanzi = '整' AND pinyin = 'zhěng' AND vietnamese = 'Trọn, cả';
UPDATE public.dictionary_words SET example_hanzi = '週末我都會整理房間。', example_pinyin = 'zhōumò wǒ dōu huì zhěnglǐ fángjiān。', example_vietnamese = 'Cuối tuần tôi thường thu dọn phòng.' WHERE level = 'B1' AND hanzi = '整理' AND pinyin = 'zhěnglĭ' AND vietnamese = 'Thu xếp, thu dọn';
UPDATE public.dictionary_words SET example_hanzi = '他的書桌總是整理得很整齊。', example_pinyin = 'tā de shūzhuō zǒngshì zhěnglǐ de hěn zhěngqí。', example_vietnamese = 'Bàn học của cậu ấy lúc nào cũng được thu dọn rất ngăn nắp.' WHERE level = 'B1' AND hanzi = '整齊' AND pinyin = 'zhěngqí' AND vietnamese = 'Ngăn nắp, ngay ngắn';
UPDATE public.dictionary_words SET example_hanzi = '我正要出門的時候,電話響了。', example_pinyin = 'wǒ zhèng yào chūmén de shíhou, diànhuà xiǎng le。', example_vietnamese = 'Đúng lúc tôi đang chuẩn bị ra khỏi nhà thì điện thoại reo.' WHERE level = 'B1' AND hanzi = '正' AND pinyin = 'zhèng' AND vietnamese = 'Chính';
UPDATE public.dictionary_words SET example_hanzi = '檢查結果顯示一切都很正常。', example_pinyin = 'jiǎnchá jiéguǒ xiǎnshì yíqiè dōu hěn zhèngcháng。', example_vietnamese = 'Kết quả kiểm tra cho thấy mọi thứ đều bình thường.' WHERE level = 'B1' AND hanzi = '正常' AND pinyin = 'zhèngcháng' AND vietnamese = 'Bình thường';
UPDATE public.dictionary_words SET example_hanzi = '你這個答案是正確的。', example_pinyin = 'nǐ zhè ge dá''àn shì zhèngquè de。', example_vietnamese = 'Đáp án này của bạn là chính xác.' WHERE level = 'B1' AND hanzi = '正確' AND pinyin = 'zhèngquè' AND vietnamese = 'Chính xác';
UPDATE public.dictionary_words SET example_hanzi = '他們下個月就要正式結婚了。', example_pinyin = 'tāmen xià ge yuè jiù yào zhèngshì jiéhūn le。', example_vietnamese = 'Tháng sau họ sẽ chính thức kết hôn.' WHERE level = 'B1' AND hanzi = '正式' AND pinyin = 'zhèngshì' AND vietnamese = 'Chính thức';
UPDATE public.dictionary_words SET example_hanzi = '這張照片可以證明我昨天真的在現場。', example_pinyin = 'zhè zhāng zhàopiàn kěyǐ zhèngmíng wǒ zuótiān zhēnde zài xiànchǎng。', example_vietnamese = 'Bức ảnh này có thể chứng minh hôm qua tôi thật sự có mặt tại hiện trường.' WHERE level = 'B1' AND hanzi = '證明' AND pinyin = 'zhèngmíng' AND vietnamese = 'Chứng minh';
UPDATE public.dictionary_words SET example_hanzi = '他考到了一張中文能力證書。', example_pinyin = 'tā kǎo dào le yì zhāng zhōngwén nénglì zhèngshū。', example_vietnamese = 'Anh ấy đã thi được một tấm chứng chỉ năng lực tiếng Trung.' WHERE level = 'B1' AND hanzi = '證書' AND pinyin = 'zhèngshū' AND vietnamese = 'Giấy chứng nhận, chứng chỉ';
UPDATE public.dictionary_words SET example_hanzi = '桌上有三支筆。', example_pinyin = 'zhuō shàng yǒu sān zhī bǐ。', example_vietnamese = 'Trên bàn có ba cây bút.' WHERE level = 'B1' AND hanzi = '支' AND pinyin = 'zhī' AND vietnamese = 'Chống, đỡ';
