UPDATE public.dictionary_words SET example_hanzi = '他們兩個人之間的感情很好。', example_pinyin = 'tāmen liǎng ge rén zhījiān de gǎnqíng hěn hǎo。', example_vietnamese = 'Tình cảm giữa hai người họ rất tốt.' WHERE level = 'B1' AND hanzi = '之間' AND pinyin = 'zhījiān' AND vietnamese = 'Giữa';
UPDATE public.dictionary_words SET example_hanzi = '出門之前記得帶雨傘。', example_pinyin = 'chūmén zhīqián jìde dài yǔsǎn。', example_vietnamese = 'Trước khi ra ngoài nhớ mang theo dù.' WHERE level = 'B1' AND hanzi = '之前' AND pinyin = 'zhīqián' AND vietnamese = 'Trước khi';
