UPDATE public.dictionary_words SET example_hanzi = '他一直工作,直到深夜才回家。', example_pinyin = 'tā yìzhí gōngzuò, zhídào shēnyè cái huíjiā。', example_vietnamese = 'Anh ấy làm việc liên tục, đến tận khuya mới về nhà.' WHERE level = 'B1' AND hanzi = '直到' AND pinyin = 'zhídào' AND vietnamese = 'Đến tận khi';
UPDATE public.dictionary_words SET example_hanzi = '這部電影真的很值得一看。', example_pinyin = 'zhè bù diànyǐng zhēnde hěn zhíde yí kàn。', example_vietnamese = 'Bộ phim này thật sự rất đáng xem.' WHERE level = 'B1' AND hanzi = '值得' AND pinyin = 'zhíde' AND vietnamese = 'Xứng đáng';
