UPDATE public.dictionary_words SET example_hanzi = '她家陽台種了很多植物。', example_pinyin = 'tā jiā yángtái zhòng le hěn duō zhíwù。', example_vietnamese = 'Ban công nhà cô ấy trồng rất nhiều cây cối.' WHERE level = 'B1' AND hanzi = '植物' AND pinyin = 'zhíwù' AND vietnamese = 'Thực vật';
UPDATE public.dictionary_words SET example_hanzi = '這間銀行的職員態度很親切。', example_pinyin = 'zhè jiān yínháng de zhíyuán tàidù hěn qīnqiè。', example_vietnamese = 'Thái độ của nhân viên ngân hàng này rất thân thiện.' WHERE level = 'B1' AND hanzi = '職員' AND pinyin = 'zhíyuán' AND vietnamese = 'Nhân viên chức';
UPDATE public.dictionary_words SET example_hanzi = '他用手指著地圖上的位置。', example_pinyin = 'tā yòng shǒu zhǐ zhe dìtú shàng de wèizhi。', example_vietnamese = 'Anh ấy dùng tay chỉ vào vị trí trên bản đồ.' WHERE level = 'B1' AND hanzi = '指' AND pinyin = 'zhĭ' AND vietnamese = 'Chỉ trỏ';
UPDATE public.dictionary_words SET example_hanzi = '我不是生氣,只是有點累。', example_pinyin = 'wǒ bú shì shēngqì, zhǐshì yǒu diǎn lèi。', example_vietnamese = 'Tôi không giận, chỉ là hơi mệt thôi.' WHERE level = 'B1' AND hanzi = '只是' AND pinyin = 'zhĭshì' AND vietnamese = 'Chỉ là';
UPDATE public.dictionary_words SET example_hanzi = '只要你努力,一定會成功的。', example_pinyin = 'zhǐyào nǐ nǔlì, yídìng huì chénggōng de。', example_vietnamese = 'Chỉ cần bạn cố gắng, chắc chắn sẽ thành công.' WHERE level = 'B1' AND hanzi = '只要' AND pinyin = 'zhǐyào' AND vietnamese = 'Chỉ cần, miễn là';
UPDATE public.dictionary_words SET example_hanzi = '教室裡只有三個學生在唸書。', example_pinyin = 'jiàoshì lǐ zhǐyǒu sān ge xuéshēng zài niànshū。', example_vietnamese = 'Trong lớp học chỉ có ba học sinh đang học bài.' WHERE level = 'B1' AND hanzi = '只有' AND pinyin = 'zhĭyǒu' AND vietnamese = 'Chỉ có';
UPDATE public.dictionary_words SET example_hanzi = '只有努力唸書,才能考上好大學。', example_pinyin = 'zhǐyǒu nǔlì niànshū, cái néng kǎo shàng hǎo dàxué。', example_vietnamese = 'Chỉ có chăm chỉ học bài mới có thể thi đỗ vào đại học tốt.' WHERE level = 'B1' AND hanzi = '只有' AND pinyin = 'zhĭyŏu' AND vietnamese = 'Chỉ có';
UPDATE public.dictionary_words SET example_hanzi = '這家公司的休假制度很完善。', example_pinyin = 'zhè jiā gōngsī de xiūjià zhìdù hěn wánshàn。', example_vietnamese = 'Chế độ nghỉ phép của công ty này rất hoàn thiện.' WHERE level = 'B1' AND hanzi = '制度' AND pinyin = 'zhìdù' AND vietnamese = 'Chế độ';
UPDATE public.dictionary_words SET example_hanzi = '這句話充滿了人生的智慧。', example_pinyin = 'zhè jù huà chōngmǎn le rénshēng de zhìhuì。', example_vietnamese = 'Câu nói này chứa đựng đầy trí tuệ về cuộc sống.' WHERE level = 'B1' AND hanzi = '智慧' AND pinyin = 'zhìhuì' AND vietnamese = 'Trí tuệ';
UPDATE public.dictionary_words SET example_hanzi = '這個工作至少需要三年的經驗。', example_pinyin = 'zhè ge gōngzuò zhìshǎo xūyào sān nián de jīngyàn。', example_vietnamese = 'Công việc này ít nhất cần ba năm kinh nghiệm.' WHERE level = 'B1' AND hanzi = '至少' AND pinyin = 'zhìshăo' AND vietnamese = 'Chí ít, ít nhất';
