UPDATE public.dictionary_words SET example_hanzi = '我家就在這條街的正中。', example_pinyin = 'wǒ jiā jiù zài zhè tiáo jiē de zhèng zhōng。', example_vietnamese = 'Nhà tôi nằm ngay giữa con phố này.' WHERE level = 'B1' AND hanzi = '中' AND pinyin = 'zhōng' AND vietnamese = 'Trung tâm';
UPDATE public.dictionary_words SET example_hanzi = '台灣中部有很多好玩的景點。', example_pinyin = 'táiwān zhōngbù yǒu hěn duō hǎowán de jǐngdiǎn。', example_vietnamese = 'Miền trung Đài Loan có rất nhiều điểm du lịch thú vị.' WHERE level = 'B1' AND hanzi = '中部' AND pinyin = 'zhōngbù' AND vietnamese = 'Phần giữa';
UPDATE public.dictionary_words SET example_hanzi = '今天中午我們吃中餐好不好?', example_pinyin = 'jīntiān zhōngwǔ wǒmen chī zhōngcān hǎo bù hǎo?', example_vietnamese = 'Trưa nay chúng ta ăn món Trung Hoa nhé, được không?' WHERE level = 'B1' AND hanzi = '中餐' AND pinyin = 'zhōngcān' AND vietnamese = 'Món ăn Trung Quốc';
UPDATE public.dictionary_words SET example_hanzi = '經過三年的努力,他終於考上了理想的大學。', example_pinyin = 'jīngguò sān nián de nǔlì, tā zhōngyú kǎo shàng le lǐxiǎng de dàxué。', example_vietnamese = 'Sau ba năm nỗ lực, cuối cùng anh ấy đã thi đỗ vào trường đại học mơ ước.' WHERE level = 'B1' AND hanzi = '終於' AND pinyin = 'zhōngyú' AND vietnamese = 'Cuối cùng';
