UPDATE public.dictionary_words SET example_hanzi = '爸爸在後院種了幾棵樹。', example_pinyin = 'bàba zài hòuyuàn zhòng le jǐ kē shù。', example_vietnamese = 'Bố trồng vài cây trong sân sau.' WHERE level = 'B1' AND hanzi = '種' AND pinyin = 'zhòng' AND vietnamese = 'Tập trung';
UPDATE public.dictionary_words SET example_hanzi = '老師把這課的重點整理給我們。', example_pinyin = 'lǎoshī bǎ zhè kè de zhòngdiǎn zhěnglǐ gěi wǒmen。', example_vietnamese = 'Giáo viên tổng hợp trọng điểm của bài học này cho chúng tôi.' WHERE level = 'B1' AND hanzi = '重點' AND pinyin = 'zhòngdiăn' AND vietnamese = 'Trọng điểm';
UPDATE public.dictionary_words SET example_hanzi = '這家公司很重視員工的意見。', example_pinyin = 'zhè jiā gōngsī hěn zhòngshì yuángōng de yìjiàn。', example_vietnamese = 'Công ty này rất coi trọng ý kiến của nhân viên.' WHERE level = 'B1' AND hanzi = '重視' AND pinyin = 'zhòngshì' AND vietnamese = 'Coi trọng';
UPDATE public.dictionary_words SET example_hanzi = '學校周圍有很多便利商店。', example_pinyin = 'xuéxiào zhōuwéi yǒu hěn duō biànlì shāngdiàn。', example_vietnamese = 'Xung quanh trường học có rất nhiều cửa hàng tiện lợi.' WHERE level = 'B1' AND hanzi = '周圍' AND pinyin = 'zhōuwéi' AND vietnamese = 'Xung quanh, chu vi';
UPDATE public.dictionary_words SET example_hanzi = '他個性很主動,總是先跟別人打招呼。', example_pinyin = 'tā gèxìng hěn zhǔdòng, zǒngshì xiān gēn biérén dǎzhāohu。', example_vietnamese = 'Tính cách anh ấy rất chủ động, luôn chào hỏi người khác trước.' WHERE level = 'B1' AND hanzi = '主動' AND pinyin = 'zhŭdòng' AND vietnamese = 'Chủ động';
UPDATE public.dictionary_words SET example_hanzi = '她是一位忙碌的家庭主婦。', example_pinyin = 'tā shì yí wèi mánglù de jiātíng zhǔfù。', example_vietnamese = 'Cô ấy là một bà nội trợ bận rộn.' WHERE level = 'B1' AND hanzi = '主婦' AND pinyin = 'zhŭfù' AND vietnamese = 'Bà chủ';
UPDATE public.dictionary_words SET example_hanzi = '我的主管對這個企劃很滿意。', example_pinyin = 'wǒ de zhǔguǎn duì zhè ge qǐhuà hěn mǎnyì。', example_vietnamese = 'Cấp trên của tôi rất hài lòng với bản kế hoạch này.' WHERE level = 'B1' AND hanzi = '主管' AND pinyin = 'zhŭguăn' AND vietnamese = 'Chủ quản';
UPDATE public.dictionary_words SET example_hanzi = '這隻狗一直在等主人回家。', example_pinyin = 'zhè zhī gǒu yìzhí zài děng zhǔrén huíjiā。', example_vietnamese = 'Con chó này cứ chờ chủ nhân về nhà mãi.' WHERE level = 'B1' AND hanzi = '主人' AND pinyin = 'zhǔrén' AND vietnamese = 'Chủ nhân, chủ sở hữu';
UPDATE public.dictionary_words SET example_hanzi = '他是我們學校的教務主任。', example_pinyin = 'tā shì wǒmen xuéxiào de jiàowù zhǔrèn。', example_vietnamese = 'Ông ấy là chủ nhiệm giáo vụ của trường chúng tôi.' WHERE level = 'B1' AND hanzi = '主任' AND pinyin = 'zhǔrèn' AND vietnamese = 'Chủ nhiệm';
UPDATE public.dictionary_words SET example_hanzi = '這次會議的主題是環境保護。', example_pinyin = 'zhè cì huìyì de zhǔtí shì huánjìng bǎohù。', example_vietnamese = 'Chủ đề của cuộc họp lần này là bảo vệ môi trường.' WHERE level = 'B1' AND hanzi = '主題' AND pinyin = 'zhŭtí' AND vietnamese = 'Chủ đề';
UPDATE public.dictionary_words SET example_hanzi = '我學中文主要是為了工作。', example_pinyin = 'wǒ xué zhōngwén zhǔyào shì wèile gōngzuò。', example_vietnamese = 'Tôi học tiếng Trung chủ yếu là vì công việc.' WHERE level = 'B1' AND hanzi = '主要' AND pinyin = 'zhǔyào' AND vietnamese = 'Chủ yếu, chính';
UPDATE public.dictionary_words SET example_hanzi = '米飯是台灣人的主要食物。', example_pinyin = 'mǐfàn shì táiwān rén de zhǔyào shíwù。', example_vietnamese = 'Cơm là thức ăn chủ yếu của người Đài Loan.' WHERE level = 'B1' AND hanzi = '主要' AND pinyin = 'zhŭyào' AND vietnamese = 'Chủ yếu';
UPDATE public.dictionary_words SET example_hanzi = '這個主意不錯,我們可以試試看。', example_pinyin = 'zhè ge zhǔyì bú cuò, wǒmen kěyǐ shìshi kàn。', example_vietnamese = 'Ý tưởng này không tồi, chúng ta có thể thử xem.' WHERE level = 'B1' AND hanzi = '主意' AND pinyin = 'zhǔyì' AND vietnamese = 'Chủ ý, biện pháp';
UPDATE public.dictionary_words SET example_hanzi = '祝你生日快樂!', example_pinyin = 'zhù nǐ shēngrì kuàilè!', example_vietnamese = 'Chúc bạn sinh nhật vui vẻ!' WHERE level = 'B1' AND hanzi = '祝' AND pinyin = 'zhù' AND vietnamese = 'Chúc';
UPDATE public.dictionary_words SET example_hanzi = '謝謝大家給我的祝福。', example_pinyin = 'xièxie dàjiā gěi wǒ de zhùfú。', example_vietnamese = 'Cảm ơn mọi người đã gửi lời chúc phúc đến tôi.' WHERE level = 'B1' AND hanzi = '祝福' AND pinyin = 'zhùfú' AND vietnamese = 'Lời chúc';
UPDATE public.dictionary_words SET example_hanzi = '我由衷祝福你們白頭偕老。', example_pinyin = 'wǒ yóuzhōng zhùfú nǐmen báitóuxiélǎo。', example_vietnamese = 'Tôi thành tâm chúc phúc cho hai bạn bạc đầu răng long.' WHERE level = 'B1' AND hanzi = '祝福' AND pinyin = 'zhùfú' AND vietnamese = 'Chúc phúc';
UPDATE public.dictionary_words SET example_hanzi = '他主動出手相助,解決了我們的難題。', example_pinyin = 'tā zhǔdòng chūshǒu xiāngzhù, jiějué le wǒmen de nántí。', example_vietnamese = 'Anh ấy chủ động ra tay giúp đỡ, giải quyết được khó khăn của chúng tôi.' WHERE level = 'B1' AND hanzi = '助' AND pinyin = 'zhù' AND vietnamese = 'Giúp đỡ, giúp';
UPDATE public.dictionary_words SET example_hanzi = '她是經理的私人助理。', example_pinyin = 'tā shì jīnglǐ de sīrén zhùlǐ。', example_vietnamese = 'Cô ấy là trợ lý riêng của giám đốc.' WHERE level = 'B1' AND hanzi = '助理' AND pinyin = 'zhùlĭ' AND vietnamese = 'Trợ lí, giúp việc';
UPDATE public.dictionary_words SET example_hanzi = '這位作家因這本小說而著名。', example_pinyin = 'zhè wèi zuòjiā yīn zhè běn xiǎoshuō ér zhùmíng。', example_vietnamese = 'Nhà văn này nổi tiếng nhờ cuốn tiểu thuyết này.' WHERE level = 'B1' AND hanzi = '著名' AND pinyin = 'zhùmíng' AND vietnamese = 'Nổi danh';
UPDATE public.dictionary_words SET example_hanzi = '貓很會抓老鼠。', example_pinyin = 'māo hěn huì zhuā lǎoshǔ。', example_vietnamese = 'Mèo rất giỏi bắt chuột.' WHERE level = 'B1' AND hanzi = '抓' AND pinyin = 'zhuā' AND vietnamese = 'Cầm nắm, bắt';
UPDATE public.dictionary_words SET example_hanzi = '考試的時候要專心,不要分心。', example_pinyin = 'kǎoshì de shíhou yào zhuānxīn, bú yào fēnxīn。', example_vietnamese = 'Khi thi cần chuyên tâm, đừng để bị phân tâm.' WHERE level = 'B1' AND hanzi = '專心' AND pinyin = 'zhuānxīn' AND vietnamese = 'Chuyên tâm, chăm chú';
UPDATE public.dictionary_words SET example_hanzi = '這位醫生的態度非常專業。', example_pinyin = 'zhè wèi yīshēng de tàidù fēicháng zhuānyè。', example_vietnamese = 'Thái độ của vị bác sĩ này rất chuyên nghiệp.' WHERE level = 'B1' AND hanzi = '專業' AND pinyin = 'zhuānyè' AND vietnamese = 'Chuyên nghiệp';
UPDATE public.dictionary_words SET example_hanzi = '他今天的精神狀態看起來不太好。', example_pinyin = 'tā jīntiān de jīngshén zhuàngtài kàn qǐlái bú tài hǎo。', example_vietnamese = 'Hôm nay trạng thái tinh thần của anh ấy trông có vẻ không tốt lắm.' WHERE level = 'B1' AND hanzi = '狀態' AND pinyin = 'zhuàngtài' AND vietnamese = 'Trạng thái';
UPDATE public.dictionary_words SET example_hanzi = '每個人都有追求夢想的權利。', example_pinyin = 'měi ge rén dōu yǒu zhuīqiú mèngxiǎng de quánlì。', example_vietnamese = 'Mỗi người đều có quyền theo đuổi ước mơ của mình.' WHERE level = 'B1' AND hanzi = '追求' AND pinyin = 'zhuīqiú' AND vietnamese = 'Theo đuổi';
UPDATE public.dictionary_words SET example_hanzi = '開會的時候請大家準時到場。', example_pinyin = 'kāihuì de shíhou qǐng dàjiā zhǔnshí dàochǎng。', example_vietnamese = 'Khi họp xin mọi người có mặt đúng giờ.' WHERE level = 'B1' AND hanzi = '準時' AND pinyin = 'zhŭnshí' AND vietnamese = 'Đúng giờ';
UPDATE public.dictionary_words SET example_hanzi = '她笑著跟我們打招呼。', example_pinyin = 'tā xiào zhe gēn wǒmen dǎ zhāohu。', example_vietnamese = 'Cô ấy vừa cười vừa chào chúng tôi.' WHERE level = 'B1' AND hanzi = '著' AND pinyin = 'zhuó' AND vietnamese = 'Đang';
UPDATE public.dictionary_words SET example_hanzi = '我還需要一些資料才能完成報告。', example_pinyin = 'wǒ hái xūyào yìxiē zīliào cái néng wánchéng bàogào。', example_vietnamese = 'Tôi vẫn cần thêm một số tài liệu mới có thể hoàn thành báo cáo.' WHERE level = 'B1' AND hanzi = '資料' AND pinyin = 'zīliào' AND vietnamese = 'Tư liệu, tài liệu';
UPDATE public.dictionary_words SET example_hanzi = '我們應該好好珍惜地球的自然資源。', example_pinyin = 'wǒmen yīnggāi hǎohǎo zhēnxī dìqiú de zìrán zīyuán。', example_vietnamese = 'Chúng ta nên trân trọng tài nguyên thiên nhiên của trái đất.' WHERE level = 'B1' AND hanzi = '資源' AND pinyin = 'zīyuán' AND vietnamese = 'Nguồn tài nguyên';
UPDATE public.dictionary_words SET example_hanzi = '請你仔細檢查這份文件。', example_pinyin = 'qǐng nǐ zǐxì jiǎnchá zhè fèn wénjiàn。', example_vietnamese = 'Xin bạn hãy kiểm tra kỹ lưỡng tài liệu này.' WHERE level = 'B1' AND hanzi = '仔細' AND pinyin = 'zĭxì' AND vietnamese = 'Tỉ mỉ';
UPDATE public.dictionary_words SET example_hanzi = '自從搬到台北以後,他就很少回老家了。', example_pinyin = 'zìcóng bān dào táiběi yǐhòu, tā jiù hěn shǎo huí lǎojiā le。', example_vietnamese = 'Từ khi chuyển đến Đài Bắc, anh ấy rất ít khi về quê.' WHERE level = 'B1' AND hanzi = '自從' AND pinyin = 'zìcóng' AND vietnamese = 'Từ khi, từ lúc';
UPDATE public.dictionary_words SET example_hanzi = '這台洗衣機洗完會自動關機。', example_pinyin = 'zhè tái xǐyījī xǐ wán huì zìdòng guānjī。', example_vietnamese = 'Chiếc máy giặt này giặt xong sẽ tự động tắt máy.' WHERE level = 'B1' AND hanzi = '自動' AND pinyin = 'zìdòng' AND vietnamese = 'Tự động';
UPDATE public.dictionary_words SET example_hanzi = '她化的妝看起來很自然。', example_pinyin = 'tā huà de zhuāng kàn qǐlái hěn zìrán。', example_vietnamese = 'Lớp trang điểm của cô ấy trông rất tự nhiên.' WHERE level = 'B1' AND hanzi = '自然' AND pinyin = 'zìrán' AND vietnamese = 'Tự nhiên';
UPDATE public.dictionary_words SET example_hanzi = '政府設立了專線幫助有自殺念頭的人。', example_pinyin = 'zhèngfǔ shèlì le zhuānxiàn bāngzhù yǒu zìshā niàntou de rén。', example_vietnamese = 'Chính phủ đã thiết lập đường dây nóng để giúp đỡ những người có ý định tự tử.' WHERE level = 'B1' AND hanzi = '自殺' AND pinyin = 'zìshā' AND vietnamese = 'Tự tử';
UPDATE public.dictionary_words SET example_hanzi = '這次得獎讓他更有自信了。', example_pinyin = 'zhè cì dé jiǎng ràng tā gèng yǒu zìxìn le。', example_vietnamese = 'Lần đoạt giải này khiến anh ấy tự tin hơn.' WHERE level = 'B1' AND hanzi = '自信' AND pinyin = 'zìxìn' AND vietnamese = 'Tự tin';
UPDATE public.dictionary_words SET example_hanzi = '每個人都應該享有言論自由。', example_pinyin = 'měi ge rén dōu yīnggāi xiǎngyǒu yánlùn zìyóu。', example_vietnamese = 'Mỗi người đều nên được hưởng quyền tự do ngôn luận.' WHERE level = 'B1' AND hanzi = '自由' AND pinyin = 'zìyóu' AND vietnamese = 'Sự tự do';
UPDATE public.dictionary_words SET example_hanzi = '退休以後,他的生活變得很自由。', example_pinyin = 'tuìxiū yǐhòu, tā de shēnghuó biàn de hěn zìyóu。', example_vietnamese = 'Sau khi nghỉ hưu, cuộc sống của ông trở nên rất tự do.' WHERE level = 'B1' AND hanzi = '自由' AND pinyin = 'zìyóu' AND vietnamese = 'Tự do';
UPDATE public.dictionary_words SET example_hanzi = '在家裡穿睡衣最自在了。', example_pinyin = 'zài jiā lǐ chuān shuìyī zuì zìzài le。', example_vietnamese = 'Ở nhà mặc đồ ngủ là thoải mái nhất.' WHERE level = 'B1' AND hanzi = '自在' AND pinyin = 'zìzài' AND vietnamese = 'An nhàn, thanh thản';
UPDATE public.dictionary_words SET example_hanzi = '世界上有很多不同的宗教。', example_pinyin = 'shìjiè shàng yǒu hěn duō bù tóng de zōngjiào。', example_vietnamese = 'Trên thế giới có rất nhiều tôn giáo khác nhau.' WHERE level = 'B1' AND hanzi = '宗教' AND pinyin = 'zōngjiào' AND vietnamese = 'Tôn giáo, đạo';
UPDATE public.dictionary_words SET example_hanzi = '總而言之,這次的計畫失敗了。', example_pinyin = 'zǒngéryánzhī, zhè cì de jìhuà shībài le。', example_vietnamese = 'Tóm lại, kế hoạch lần này đã thất bại.' WHERE level = 'B1' AND hanzi = '總而言之' AND pinyin = 'zǒngéryánzhī' AND vietnamese = 'Tóm lại';
UPDATE public.dictionary_words SET example_hanzi = '忙了一整天,工作總算做完了。', example_pinyin = 'máng le yì zhěng tiān, gōngzuò zǒngsuàn zuò wán le。', example_vietnamese = 'Bận rộn cả một ngày, công việc cuối cùng cũng làm xong.' WHERE level = 'B1' AND hanzi = '總算' AND pinyin = 'zǒngsuàn' AND vietnamese = 'Cuối cùng cũng…';
UPDATE public.dictionary_words SET example_hanzi = '總統今天發表了重要的談話。', example_pinyin = 'zǒngtǒng jīntiān fābiǎo le zhòngyào de tánhuà。', example_vietnamese = 'Hôm nay tổng thống đã phát biểu bài nói chuyện quan trọng.' WHERE level = 'B1' AND hanzi = '總統' AND pinyin = 'zǒngtǒng' AND vietnamese = 'Tổng thống';
UPDATE public.dictionary_words SET example_hanzi = '總之,只要你開心就好。', example_pinyin = 'zǒngzhī, zhǐyào nǐ kāixīn jiù hǎo。', example_vietnamese = 'Nói chung, chỉ cần bạn vui là được.' WHERE level = 'B1' AND hanzi = '總之' AND pinyin = 'zǒngzhī' AND vietnamese = 'Nói chung, tóm lại';
UPDATE public.dictionary_words SET example_hanzi = '吃完晚飯,我們去公園走走吧。', example_pinyin = 'chī wán wǎnfàn, wǒmen qù gōngyuán zǒuzou ba。', example_vietnamese = 'Ăn tối xong, chúng ta đi công viên dạo một chút đi.' WHERE level = 'B1' AND hanzi = '走走' AND pinyin = 'zǒuzou' AND vietnamese = 'Đi dạo, tản bộ';
UPDATE public.dictionary_words SET example_hanzi = '老師把全班分成五組。', example_pinyin = 'lǎoshī bǎ quánbān fēn chéng wǔ zǔ。', example_vietnamese = 'Giáo viên chia cả lớp thành năm nhóm.' WHERE level = 'B1' AND hanzi = '組' AND pinyin = 'zŭ' AND vietnamese = 'Tổ, nhóm';
UPDATE public.dictionary_words SET example_hanzi = '我的祖父今年已經九十歲了。', example_pinyin = 'wǒ de zǔfù jīnnián yǐjīng jiǔshí suì le。', example_vietnamese = 'Ông nội tôi năm nay đã chín mươi tuổi rồi.' WHERE level = 'B1' AND hanzi = '祖父' AND pinyin = 'zŭfù' AND vietnamese = 'Ông nội';
UPDATE public.dictionary_words SET example_hanzi = '祖母常常說以前的故事給我們聽。', example_pinyin = 'zǔmǔ chángcháng shuō yǐqián de gùshi gěi wǒmen tīng。', example_vietnamese = 'Bà nội thường kể chuyện ngày xưa cho chúng tôi nghe.' WHERE level = 'B1' AND hanzi = '祖母' AND pinyin = 'zŭmŭ' AND vietnamese = 'Bà nội';
UPDATE public.dictionary_words SET example_hanzi = '每年過年,我們都會祭拜祖先。', example_pinyin = 'měi nián guònián, wǒmen dōu huì jìbài zǔxiān。', example_vietnamese = 'Mỗi năm ăn Tết, chúng tôi đều cúng bái tổ tiên.' WHERE level = 'B1' AND hanzi = '祖先' AND pinyin = 'zŭxiān' AND vietnamese = 'Tổ tiên';
UPDATE public.dictionary_words SET example_hanzi = '小弟弟嘴裡塞滿了糖果。', example_pinyin = 'xiǎo dìdi zuǐ lǐ sāi mǎn le tángguǒ。', example_vietnamese = 'Miệng của cậu em nhỏ nhét đầy kẹo.' WHERE level = 'B1' AND hanzi = '嘴' AND pinyin = 'zuĭ' AND vietnamese = 'Miệng';
UPDATE public.dictionary_words SET example_hanzi = '他昨晚喝醉了,睡到中午才起床。', example_pinyin = 'tā zuówǎn hē zuì le, shuì dào zhōngwǔ cái qǐchuáng。', example_vietnamese = 'Tối qua anh ấy uống say, ngủ đến trưa mới dậy.' WHERE level = 'B1' AND hanzi = '醉' AND pinyin = 'zuì' AND vietnamese = 'Say, say rượu';
UPDATE public.dictionary_words SET example_hanzi = '最初我對這份工作沒什麼興趣。', example_pinyin = 'zuìchū wǒ duì zhè fèn gōngzuò méi shénme xìngqù。', example_vietnamese = 'Ban đầu tôi không có hứng thú gì với công việc này.' WHERE level = 'B1' AND hanzi = '最初' AND pinyin = 'zuìchū' AND vietnamese = 'Ban đầu';
UPDATE public.dictionary_words SET example_hanzi = '這個房間最多只能住四個人。', example_pinyin = 'zhè ge fángjiān zuìduō zhǐ néng zhù sì ge rén。', example_vietnamese = 'Phòng này nhiều nhất chỉ có thể ở được bốn người.' WHERE level = 'B1' AND hanzi = '最多' AND pinyin = 'zuìduō' AND vietnamese = 'Nhiều nhất';
UPDATE public.dictionary_words SET example_hanzi = '你最好早一點出發,免得塞車。', example_pinyin = 'nǐ zuìhǎo zǎo yì diǎn chūfā, miǎnde sāichē。', example_vietnamese = 'Bạn tốt nhất nên xuất phát sớm một chút, để tránh kẹt xe.' WHERE level = 'B1' AND hanzi = '最好' AND pinyin = 'zuìhǎo' AND vietnamese = 'Tốt nhất';
UPDATE public.dictionary_words SET example_hanzi = '經過討論,大家最後決定一起去海邊。', example_pinyin = 'jīngguò tǎolùn, dàjiā zuìhòu juédìng yìqǐ qù hǎibiān。', example_vietnamese = 'Sau khi thảo luận, cuối cùng mọi người quyết định cùng nhau đi biển.' WHERE level = 'B1' AND hanzi = '最後' AND pinyin = 'zuìhòu' AND vietnamese = 'Cuối cùng';
UPDATE public.dictionary_words SET example_hanzi = '他得到了今年的最佳演員獎。', example_pinyin = 'tā dé dào le jīnnián de zuìjiā yǎnyuán jiǎng。', example_vietnamese = 'Anh ấy đã đoạt giải Diễn viên xuất sắc nhất năm nay.' WHERE level = 'B1' AND hanzi = '最佳' AND pinyin = 'zuìjiā' AND vietnamese = 'Tốt nhất';
UPDATE public.dictionary_words SET example_hanzi = '學生都很尊敬這位老師。', example_pinyin = 'xuéshēng dōu hěn zūnjìng zhè wèi lǎoshī。', example_vietnamese = 'Học sinh đều rất tôn kính vị giáo viên này.' WHERE level = 'B1' AND hanzi = '尊敬' AND pinyin = 'zūnjìng' AND vietnamese = 'Tôn kính';
UPDATE public.dictionary_words SET example_hanzi = '他決定自己創業,作自己的老闆。', example_pinyin = 'tā juédìng zìjǐ chuàngyè, zuò zìjǐ de lǎobǎn。', example_vietnamese = 'Anh ấy quyết định tự khởi nghiệp, làm chủ của chính mình.' WHERE level = 'B1' AND hanzi = '作' AND pinyin = 'zuò' AND vietnamese = 'Làm';
UPDATE public.dictionary_words SET example_hanzi = '這幅畫是他最滿意的作品。', example_pinyin = 'zhè fú huà shì tā zuì mǎnyì de zuòpǐn。', example_vietnamese = 'Bức tranh này là tác phẩm anh ấy hài lòng nhất.' WHERE level = 'B1' AND hanzi = '作品' AND pinyin = 'zuòpĭn' AND vietnamese = 'Tác phẩm';
UPDATE public.dictionary_words SET example_hanzi = '這本書的作者是一位台灣作家。', example_pinyin = 'zhè běn shū de zuòzhě shì yí wèi táiwān zuòjiā。', example_vietnamese = 'Tác giả của cuốn sách này là một nhà văn Đài Loan.' WHERE level = 'B1' AND hanzi = '作者' AND pinyin = 'zuòzhě' AND vietnamese = 'Tác giả';
UPDATE public.dictionary_words SET example_hanzi = '遠處有一座高山。', example_pinyin = 'yuǎnchù yǒu yí zuò gāoshān。', example_vietnamese = 'Ở nơi xa có một ngọn núi cao.' WHERE level = 'B1' AND hanzi = '座' AND pinyin = 'zuò' AND vietnamese = 'Chỗ ngồi';
UPDATE public.dictionary_words SET example_hanzi = '這道菜的做法其實很簡單。', example_pinyin = 'zhè dào cài de zuòfǎ qíshí hěn jiǎndān。', example_vietnamese = 'Cách làm món này thực ra rất đơn giản.' WHERE level = 'B1' AND hanzi = '做/作法' AND pinyin = 'zuòfă' AND vietnamese = 'Cách làm, phương pháp';
UPDATE public.dictionary_words SET example_hanzi = '我昨晚做夢夢到自己在飛。', example_pinyin = 'wǒ zuówǎn zuòmèng mèng dào zìjǐ zài fēi。', example_vietnamese = 'Tối qua tôi nằm mơ thấy mình đang bay.' WHERE level = 'B1' AND hanzi = '做夢' AND pinyin = 'zuòmèng' AND vietnamese = 'Nằm mơ';
UPDATE public.dictionary_words SET example_hanzi = '誠實是做人最基本的道理。', example_pinyin = 'chéngshí shì zuòrén zuì jīběn de dàolǐ。', example_vietnamese = 'Trung thực là đạo lý cơ bản nhất của việc làm người.' WHERE level = 'B1' AND hanzi = '做人' AND pinyin = 'zuòrén' AND vietnamese = 'Làm người';
UPDATE public.dictionary_words SET example_hanzi = '他做事一向很細心。', example_pinyin = 'tā zuòshì yíxiàng hěn xìxīn。', example_vietnamese = 'Anh ấy làm việc luôn luôn cẩn thận.' WHERE level = 'B1' AND hanzi = '做事' AND pinyin = 'zuòshì' AND vietnamese = 'Làm việc';
UPDATE public.dictionary_words SET example_hanzi = '科學家正在研究太空中有沒有其他生命。', example_pinyin = 'kē xué jiā zhèng zài yán jiū tài kōng zhōng yǒu méi yǒu qí tā shēng mìng。', example_vietnamese = 'Các nhà khoa học đang nghiên cứu xem trong vũ trụ có sự sống khác hay không.' WHERE level = 'B2' AND hanzi = '太空' AND pinyin = 'tàikōng' AND vietnamese = 'vũ trụ';
UPDATE public.dictionary_words SET example_hanzi = '夜市裡有一個賣小吃的攤子，生意很好。', example_pinyin = 'yè shì lǐ yǒu yí gè mài xiǎo chī de tān zi, shēng yì hěn hǎo。', example_vietnamese = 'Trong chợ đêm có một sạp bán đồ ăn vặt, buôn bán rất tốt.' WHERE level = 'B2' AND hanzi = '攤子' AND pinyin = 'tānzi' AND vietnamese = 'sạp, quầy (hàng)';
UPDATE public.dictionary_words SET example_hanzi = '她從小就學彈鋼琴，現在彈得非常好。', example_pinyin = 'tā cóng xiǎo jiù xué tán gāng qín, xiàn zài tán de fēi cháng hǎo。', example_vietnamese = 'Cô ấy học đàn piano từ nhỏ, bây giờ đánh rất giỏi.' WHERE level = 'B2' AND hanzi = '彈' AND pinyin = 'tán' AND vietnamese = 'đánh, gảy (đàn)';
UPDATE public.dictionary_words SET example_hanzi = '雙方為了這筆生意談判了好幾個小時。', example_pinyin = 'shuāng fāng wèi le zhè bǐ shēng yì tán pàn le hǎo jǐ gè xiǎo shí。', example_vietnamese = 'Hai bên đã đàm phán mấy tiếng đồng hồ vì thương vụ này.' WHERE level = 'B2' AND hanzi = '談判' AND pinyin = 'tánpàn' AND vietnamese = 'đàm phán';
UPDATE public.dictionary_words SET example_hanzi = '客廳地上鋪了一條漂亮的毯子。', example_pinyin = 'kè tīng dì shang pū le yì tiáo piào liang de tǎn zi。', example_vietnamese = 'Trên sàn phòng khách trải một tấm thảm đẹp.' WHERE level = 'B2' AND hanzi = '毯子' AND pinyin = 'tănzi' AND vietnamese = 'tấm thảm';
UPDATE public.dictionary_words SET example_hanzi = '警察先派人去探一下那棟房子的情況。', example_pinyin = 'jǐng chá xiān pài rén qù tàn yí xià nà dòng fáng zi de qíng kuàng。', example_vietnamese = 'Cảnh sát trước tiên cử người đi thăm dò tình hình căn nhà đó.' WHERE level = 'B2' AND hanzi = '探' AND pinyin = 'tàn' AND vietnamese = 'thăm dò';
UPDATE public.dictionary_words SET example_hanzi = '過年的時候，他特地回老家探親。', example_pinyin = 'guò nián de shí hou, tā tè dì huí lǎo jiā tàn qīn。', example_vietnamese = 'Vào dịp Tết, anh ấy đặc biệt về quê để thăm người thân.' WHERE level = 'B2' AND hanzi = '探親' AND pinyin = 'tànqīn' AND vietnamese = 'thăm người thân';
UPDATE public.dictionary_words SET example_hanzi = '這篇論文主要探討氣候變遷對農業的影響。', example_pinyin = 'zhè piān lùn wén zhǔ yào tàn tǎo qì hòu biàn qiān duì nóng yè de yǐng xiǎng。', example_vietnamese = 'Bài luận văn này chủ yếu thảo luận nghiên cứu về ảnh hưởng của biến đổi khí hậu đối với nông nghiệp.' WHERE level = 'B2' AND hanzi = '探討' AND pinyin = 'tàntăo' AND vietnamese = 'nghiên cứu thảo luận';
UPDATE public.dictionary_words SET example_hanzi = '我明天要去一趟銀行辦事情。', example_pinyin = 'wǒ míng tiān yào qù yí tàng yín háng bàn shì qing。', example_vietnamese = 'Ngày mai tôi phải đi một chuyến đến ngân hàng để giải quyết việc.' WHERE level = 'B2' AND hanzi = '趟' AND pinyin = 'tàng' AND vietnamese = 'lần, chuyến';
UPDATE public.dictionary_words SET example_hanzi = '小心別被熱湯燙到手。', example_pinyin = 'xiǎo xīn bié bèi rè tāng tàng dào shǒu。', example_vietnamese = 'Cẩn thận kẻo bị canh nóng làm bỏng tay.' WHERE level = 'B2' AND hanzi = '燙' AND pinyin = 'tàng' AND vietnamese = 'phỏng, bỏng';
UPDATE public.dictionary_words SET example_hanzi = '這件襯衫皺了，要拿去燙一下。', example_pinyin = 'zhè jiàn chèn shān zhòu le, yào ná qù tàng yí xià。', example_vietnamese = 'Cái áo sơ mi này bị nhăn rồi, phải đem đi ủi một chút.' WHERE level = 'B2' AND hanzi = '燙' AND pinyin = 'tàng' AND vietnamese = 'là, ủi';
UPDATE public.dictionary_words SET example_hanzi = '他從口袋裡掏出一把鑰匙。', example_pinyin = 'tā cóng kǒu dài lǐ tāo chū yì bǎ yào shi。', example_vietnamese = 'Anh ấy móc từ trong túi ra một chùm chìa khóa.' WHERE level = 'B2' AND hanzi = '掏' AND pinyin = 'tāo' AND vietnamese = 'móc, đào';
UPDATE public.dictionary_words SET example_hanzi = '小偷一看到警察就拔腿就逃。', example_pinyin = 'xiǎo tōu yí kàn dào jǐng chá jiù bá tuǐ jiù táo。', example_vietnamese = 'Tên trộm vừa nhìn thấy cảnh sát liền vội vàng bỏ chạy.' WHERE level = 'B2' AND hanzi = '逃' AND pinyin = 'táo' AND vietnamese = 'trốn chạy';
UPDATE public.dictionary_words SET example_hanzi = '遇到問題應該面對，不應該一直逃避。', example_pinyin = 'yù dào wèn tí yīng gāi miàn duì, bù yīng gāi yì zhí táo bì。', example_vietnamese = 'Gặp vấn đề nên đối mặt, không nên cứ mãi trốn tránh.' WHERE level = 'B2' AND hanzi = '逃避' AND pinyin = 'táobì' AND vietnamese = 'trốn tránh';
UPDATE public.dictionary_words SET example_hanzi = '犯人趁大家不注意的時候偷偷逃走了。', example_pinyin = 'fàn rén chèn dà jiā bú zhù yì de shí hou tōu tōu táo zǒu le。', example_vietnamese = 'Tên phạm nhân đã lén lút chạy trốn khi mọi người không để ý.' WHERE level = 'B2' AND hanzi = '逃走' AND pinyin = 'táozŏu' AND vietnamese = 'chạy trốn';
UPDATE public.dictionary_words SET example_hanzi = '這家店賣的陶瓷花瓶都是手工做的。', example_pinyin = 'zhè jiā diàn mài de táo cí huā píng dōu shì shǒu gōng zuò de。', example_vietnamese = 'Những chiếc bình hoa gốm sứ mà cửa hàng này bán đều được làm thủ công.' WHERE level = 'B2' AND hanzi = '陶瓷' AND pinyin = 'táocí' AND vietnamese = 'gốm sứ';
UPDATE public.dictionary_words SET example_hanzi = '這個小孩很淘氣，常常把家裡弄得亂七八糟。', example_pinyin = 'zhè ge xiǎo hái hěn táo qì, cháng cháng bǎ jiā lǐ nòng de luàn qī bā zāo。', example_vietnamese = 'Đứa trẻ này rất nghịch ngợm, thường xuyên làm nhà cửa lộn xộn.' WHERE level = 'B2' AND hanzi = '淘氣' AND pinyin = 'táoqì' AND vietnamese = 'tinh nghịch';
UPDATE public.dictionary_words SET example_hanzi = '這顆桃子又甜又多汁，很好吃。', example_pinyin = 'zhè kē táo zi yòu tián yòu duō zhī, hěn hǎo chī。', example_vietnamese = 'Quả đào này vừa ngọt vừa nhiều nước, rất ngon.' WHERE level = 'B2' AND hanzi = '桃子' AND pinyin = 'táozi' AND vietnamese = 'quả đào';
UPDATE public.dictionary_words SET example_hanzi = '他向老闆討了幾天假，回家陪父母。', example_pinyin = 'tā xiàng lǎo bǎn tǎo le jǐ tiān jià, huí jiā péi fù mǔ。', example_vietnamese = 'Anh ấy xin ông chủ mấy ngày nghỉ để về nhà ở bên bố mẹ.' WHERE level = 'B2' AND hanzi = '討' AND pinyin = 'tăo' AND vietnamese = 'thỉnh cầu, xin';
UPDATE public.dictionary_words SET example_hanzi = '我上個月買了一套新家具。', example_pinyin = 'wǒ shàng ge yuè mǎi le yí tào xīn jiā jù。', example_vietnamese = 'Tháng trước tôi mua một bộ nội thất mới.' WHERE level = 'B2' AND hanzi = '套' AND pinyin = 'tào' AND vietnamese = 'bộ';
UPDATE public.dictionary_words SET example_hanzi = '下雨了，他趕緊把塑膠袋套在背包上。', example_pinyin = 'xià yǔ le, tā gǎn jǐn bǎ sù jiāo dài tào zài bēi bāo shàng。', example_vietnamese = 'Trời mưa rồi, anh ấy vội vàng trùm túi nilon lên ba lô.' WHERE level = 'B2' AND hanzi = '套' AND pinyin = 'tào' AND vietnamese = 'trùm ngoài, bọc ngoài';
UPDATE public.dictionary_words SET example_hanzi = '今天的考試特別難，大家都寫不完。', example_pinyin = 'jīn tiān de kǎo shì tè bié nán, dà jiā dōu xiě bù wán。', example_vietnamese = 'Bài thi hôm nay đặc biệt khó, mọi người đều không làm kịp hết.' WHERE level = 'B2' AND hanzi = '特別' AND pinyin = 'tèbié' AND vietnamese = 'đặc biệt';
UPDATE public.dictionary_words SET example_hanzi = '這座城市最大的特點就是交通方便。', example_pinyin = 'zhè zuò chéng shì zuì dà de tè diǎn jiù shì jiāo tōng fāng biàn。', example_vietnamese = 'Đặc điểm lớn nhất của thành phố này chính là giao thông thuận tiện.' WHERE level = 'B2' AND hanzi = '特點' AND pinyin = 'tèdiăn' AND vietnamese = 'đặc điểm';
UPDATE public.dictionary_words SET example_hanzi = '他從來沒有跟我提過這件事。', example_pinyin = 'tā cóng lái méi yǒu gēn wǒ tí guò zhè jiàn shì。', example_vietnamese = 'Anh ấy chưa bao giờ nhắc đến chuyện này với tôi.' WHERE level = 'B2' AND hanzi = '提' AND pinyin = 'tí' AND vietnamese = 'đề cập, nói đến';
UPDATE public.dictionary_words SET example_hanzi = '一提起那場車禍，他就忍不住掉眼淚。', example_pinyin = 'yì tí qǐ nà chǎng chē huò, tā jiù rěn bú zhù diào yǎn lèi。', example_vietnamese = 'Vừa nhắc đến vụ tai nạn xe đó, anh ấy liền không kìm được nước mắt.' WHERE level = 'B2' AND hanzi = '提起' AND pinyin = 'tíqĭ' AND vietnamese = 'nhắc nhở';
UPDATE public.dictionary_words SET example_hanzi = '因為颱風要來，會議提前到明天舉行。', example_pinyin = 'yīn wèi tái fēng yào lái, huì yì tí qián dào míng tiān jǔ xíng。', example_vietnamese = 'Vì bão sắp đến nên cuộc họp được tổ chức sớm hơn, dời lên ngày mai.' WHERE level = 'B2' AND hanzi = '提前' AND pinyin = 'tíqián' AND vietnamese = 'trước thời hạn';
UPDATE public.dictionary_words SET example_hanzi = '謝謝你提醒我，不然我差點忘記帶護照。', example_pinyin = 'xiè xie nǐ tí xǐng wǒ, bù rán wǒ chà diǎn wàng jì dài hù zhào。', example_vietnamese = 'Cảm ơn bạn đã nhắc tôi, không thì tôi suýt quên mang hộ chiếu.' WHERE level = 'B2' AND hanzi = '提醒' AND pinyin = 'tíxĭng' AND vietnamese = 'nhắc nhở';
UPDATE public.dictionary_words SET example_hanzi = '為了避開塞車，我們決定提早出發。', example_pinyin = 'wèi le bì kāi sāi chē, wǒ men jué dìng tí zǎo chū fā。', example_vietnamese = 'Để tránh kẹt xe, chúng tôi quyết định xuất phát sớm hơn.' WHERE level = 'B2' AND hanzi = '提早' AND pinyin = 'tízăo' AND vietnamese = 'sớm hơn, trước thời hạn';
UPDATE public.dictionary_words SET example_hanzi = '這份考卷一共有三十題。', example_pinyin = 'zhè fèn kǎo juàn yí gòng yǒu sān shí tí。', example_vietnamese = 'Bài thi này tổng cộng có ba mươi câu.' WHERE level = 'B2' AND hanzi = '題' AND pinyin = 'tí' AND vietnamese = 'đề mục';
UPDATE public.dictionary_words SET example_hanzi = '護士幫病人量了體溫，發現有點發燒。', example_pinyin = 'hù shi bāng bìng rén liáng le tǐ wēn, fā xiàn yǒu diǎn fā shāo。', example_vietnamese = 'Y tá đo thân nhiệt cho bệnh nhân và phát hiện hơi sốt.' WHERE level = 'B2' AND hanzi = '體溫' AND pinyin = 'tĭwēn' AND vietnamese = 'nhiệt độ cơ thể';
UPDATE public.dictionary_words SET example_hanzi = '這次旅行讓我體驗到不同的文化。', example_pinyin = 'zhè cì lǚ xíng ràng wǒ tǐ yàn dào bù tóng de wén huà。', example_vietnamese = 'Chuyến du lịch này cho tôi trải nghiệm những nền văn hóa khác nhau.' WHERE level = 'B2' AND hanzi = '體驗' AND pinyin = 'tǐyàn' AND vietnamese = 'trải nghiệm';
UPDATE public.dictionary_words SET example_hanzi = '大家都說他是音樂天才，五歲就會作曲。', example_pinyin = 'dà jiā dōu shuō tā shì yīn yuè tiān cái, wǔ suì jiù huì zuò qǔ。', example_vietnamese = 'Mọi người đều nói anh ấy là thiên tài âm nhạc, mới năm tuổi đã biết sáng tác.' WHERE level = 'B2' AND hanzi = '天才' AND pinyin = 'tiāncái' AND vietnamese = 'thiên tài';
UPDATE public.dictionary_words SET example_hanzi = '傍晚的天空被染成一片橘紅色。', example_pinyin = 'bàng wǎn de tiān kōng bèi rǎn chéng yí piàn jú hóng sè。', example_vietnamese = 'Bầu trời lúc chiều tà nhuộm thành một màu cam đỏ.' WHERE level = 'B2' AND hanzi = '天空' AND pinyin = 'tiānkōng' AND vietnamese = 'bầu trời';
UPDATE public.dictionary_words SET example_hanzi = '這種化妝品標榜使用天然的成分。', example_pinyin = 'zhè zhǒng huà zhuāng pǐn biāo bǎng shǐ yòng tiān rán de chéng fèn。', example_vietnamese = 'Loại mỹ phẩm này quảng cáo là sử dụng thành phần tự nhiên.' WHERE level = 'B2' AND hanzi = '天然' AND pinyin = 'tiānrán' AND vietnamese = 'thiên nhiên';
UPDATE public.dictionary_words SET example_hanzi = '弟弟對天文很感興趣，常常用望遠鏡看星星。', example_pinyin = 'dì di duì tiān wén hěn gǎn xìng qù, cháng cháng yòng wàng yuǎn jìng kàn xīng xing。', example_vietnamese = 'Em trai rất hứng thú với thiên văn học, thường xuyên dùng kính viễn vọng ngắm sao.' WHERE level = 'B2' AND hanzi = '天文' AND pinyin = 'tiānwén' AND vietnamese = 'thiên văn';
UPDATE public.dictionary_words SET example_hanzi = '她的想法太天真了，現實沒有那麼簡單。', example_pinyin = 'tā de xiǎng fǎ tài tiān zhēn le, xiàn shí méi yǒu nà me jiǎn dān。', example_vietnamese = 'Suy nghĩ của cô ấy quá ngây thơ, thực tế không đơn giản như vậy.' WHERE level = 'B2' AND hanzi = '天真' AND pinyin = 'tiānzhēn' AND vietnamese = 'ngây thơ';
UPDATE public.dictionary_words SET example_hanzi = '他的家庭世代都信仰天主教。', example_pinyin = 'tā de jiā tíng shì dài dōu xìn yǎng tiān zhǔ jiào。', example_vietnamese = 'Gia đình anh ấy nhiều đời đều theo đạo Thiên Chúa.' WHERE level = 'B2' AND hanzi = '天主教' AND pinyin = 'tiānzhŭjiào' AND vietnamese = 'đạo Thiên Chúa';
UPDATE public.dictionary_words SET example_hanzi = '火車經過鄉下，窗外是一片綠色的田野。', example_pinyin = 'huǒ chē jīng guò xiāng xià, chuāng wài shì yí piàn lǜ sè de tián yě。', example_vietnamese = 'Tàu hỏa chạy qua vùng quê, ngoài cửa sổ là một cánh đồng xanh mướt.' WHERE level = 'B2' AND hanzi = '田野' AND pinyin = 'tiányě' AND vietnamese = 'đồng ruộng';
UPDATE public.dictionary_words SET example_hanzi = '媽媽正在市場裡仔細挑水果。', example_pinyin = 'mā ma zhèng zài shì chǎng lǐ zǐ xì tiāo shuǐ guǒ。', example_vietnamese = 'Mẹ đang cẩn thận chọn trái cây trong chợ.' WHERE level = 'B2' AND hanzi = '挑' AND pinyin = 'tiāo' AND vietnamese = 'khều, khêu';
UPDATE public.dictionary_words SET example_hanzi = '挑選禮物的時候，要考慮對方喜歡什麼。', example_pinyin = 'tiāo xuǎn lǐ wù de shí hou, yào kǎo lǜ duì fāng xǐ huan shén me。', example_vietnamese = 'Khi chọn quà, phải suy nghĩ xem đối phương thích gì.' WHERE level = 'B2' AND hanzi = '挑選' AND pinyin = 'tiāoxuăn' AND vietnamese = 'chọn lựa';
UPDATE public.dictionary_words SET example_hanzi = '這條街兩旁種滿了櫻花樹。', example_pinyin = 'zhè tiáo jiē liǎng páng zhòng mǎn le yīng huā shù。', example_vietnamese = 'Hai bên con phố này trồng đầy hoa anh đào.' WHERE level = 'B2' AND hanzi = '條' AND pinyin = 'tiáo' AND vietnamese = 'cành, nhánh';
UPDATE public.dictionary_words SET example_hanzi = '兩國簽署了一份貿易條約。', example_pinyin = 'liǎng guó qiān shǔ le yí fèn mào yì tiáo yuē。', example_vietnamese = 'Hai nước đã ký kết một hiệp ước thương mại.' WHERE level = 'B2' AND hanzi = '條約' AND pinyin = 'tiáoyuē' AND vietnamese = 'điều ước';
UPDATE public.dictionary_words SET example_hanzi = '公司決定把他調到台北分店工作。', example_pinyin = 'gōng sī jué dìng bǎ tā tiáo dào tái běi fēn diàn gōng zuò。', example_vietnamese = 'Công ty quyết định điều anh ấy đến làm việc tại chi nhánh Đài Bắc.' WHERE level = 'B2' AND hanzi = '調' AND pinyin = 'tiáo' AND vietnamese = 'điều động, phân phối';
UPDATE public.dictionary_words SET example_hanzi = '老師根據學生的程度調整了上課進度。', example_pinyin = 'lǎo shī gēn jù xué shēng de chéng dù tiáo zhěng le shàng kè jìn dù。', example_vietnamese = 'Giáo viên đã điều chỉnh tiến độ dạy học dựa theo trình độ học sinh.' WHERE level = 'B2' AND hanzi = '調整' AND pinyin = 'tiáozhěng' AND vietnamese = 'điều chỉnh';
UPDATE public.dictionary_words SET example_hanzi = '他從小練習跳高，運動會常常拿第一名。', example_pinyin = 'tā cóng xiǎo liàn xí tiào gāo, yùn dòng huì cháng cháng ná dì yī míng。', example_vietnamese = 'Anh ấy tập nhảy cao từ nhỏ, hội thao thường xuyên đứng nhất.' WHERE level = 'B2' AND hanzi = '跳高' AND pinyin = 'tiàogāo' AND vietnamese = 'nhảy cao';
UPDATE public.dictionary_words SET example_hanzi = '體育課今天要測驗跳遠。', example_pinyin = 'tǐ yù kè jīn tiān yào cè yàn tiào yuǎn。', example_vietnamese = 'Tiết thể dục hôm nay sẽ kiểm tra môn nhảy xa.' WHERE level = 'B2' AND hanzi = '跳遠' AND pinyin = 'tiàoyuăn' AND vietnamese = 'nhảy xa';
UPDATE public.dictionary_words SET example_hanzi = '這個服務生很貼心，主動幫客人拉椅子。', example_pinyin = 'zhè ge fú wù shēng hěn tiē xīn, zhǔ dòng bāng kè rén lā yǐ zi。', example_vietnamese = 'Người phục vụ này rất chu đáo, chủ động kéo ghế giúp khách.' WHERE level = 'B2' AND hanzi = '貼心' AND pinyin = 'tiēxīn' AND vietnamese = 'thân mật';
UPDATE public.dictionary_words SET example_hanzi = '因為下大雨，比賽只好暫時停止。', example_pinyin = 'yīn wèi xià dà yǔ, bǐ sài zhǐ hǎo zàn shí tíng zhǐ。', example_vietnamese = 'Vì trời mưa to nên trận đấu đành phải tạm dừng.' WHERE level = 'B2' AND hanzi = '停止' AND pinyin = 'tíngzhĭ' AND vietnamese = 'đình chỉ';
UPDATE public.dictionary_words SET example_hanzi = '軍人站得挺直，一動也不動。', example_pinyin = 'jūn rén zhàn de tǐng zhí, yí dòng yě bú dòng。', example_vietnamese = 'Người lính đứng thẳng người, không nhúc nhích một chút nào.' WHERE level = 'B2' AND hanzi = '挺' AND pinyin = 'tĭng' AND vietnamese = 'thẳng, ngay thẳng';
UPDATE public.dictionary_words SET example_hanzi = '孕婦挺著肚子，走路有點辛苦。', example_pinyin = 'yùn fù tǐng zhe dù zi, zǒu lù yǒu diǎn xīn kǔ。', example_vietnamese = 'Người phụ nữ mang thai ưỡn bụng đi lại, có chút vất vả.' WHERE level = 'B2' AND hanzi = '挺' AND pinyin = 'tĭng' AND vietnamese = 'ưỡn, ngửa ra';
UPDATE public.dictionary_words SET example_hanzi = '昨天半夜他突然打了一通電話給我。', example_pinyin = 'zuó tiān bàn yè tā tú rán dǎ le yì tōng diàn huà gěi wǒ。', example_vietnamese = 'Nửa đêm hôm qua anh ấy đột nhiên gọi cho tôi một cuộc điện thoại.' WHERE level = 'B2' AND hanzi = '通' AND pinyin = 'tōng' AND vietnamese = 'hồi, trận';
UPDATE public.dictionary_words SET example_hanzi = '這條路前面施工，不通了。', example_pinyin = 'zhè tiáo lù qián miàn shī gōng, bù tōng le。', example_vietnamese = 'Con đường này phía trước đang thi công, không thông được nữa.' WHERE level = 'B2' AND hanzi = '通' AND pinyin = 'tōng' AND vietnamese = 'thông';
UPDATE public.dictionary_words SET example_hanzi = '我通常早上七點起床。', example_pinyin = 'wǒ tōng cháng zǎo shang qī diǎn qǐ chuáng。', example_vietnamese = 'Tôi thường thức dậy lúc bảy giờ sáng.' WHERE level = 'B2' AND hanzi = '通常' AND pinyin = 'tōngcháng' AND vietnamese = 'thông thường';
UPDATE public.dictionary_words SET example_hanzi = '這個法案已經在國會通過了。', example_pinyin = 'zhè ge fǎ àn yǐ jīng zài guó huì tōng guò le。', example_vietnamese = 'Dự luật này đã được thông qua tại quốc hội.' WHERE level = 'B2' AND hanzi = '通過' AND pinyin = 'tōngguò' AND vietnamese = 'thông qua';
UPDATE public.dictionary_words SET example_hanzi = '他們分開後一直靠寫信通信。', example_pinyin = 'tā men fēn kāi hòu yì zhí kào xiě xìn tōng xìn。', example_vietnamese = 'Sau khi chia tay, họ vẫn liên lạc thư từ với nhau.' WHERE level = 'B2' AND hanzi = '通信' AND pinyin = 'tōngxìn' AND vietnamese = 'thư từ qua lại';
UPDATE public.dictionary_words SET example_hanzi = '這個地區的通訊設備比較落後。', example_pinyin = 'zhè ge dì qū de tōng xùn shè bèi bǐ jiào luò hòu。', example_vietnamese = 'Thiết bị viễn thông ở khu vực này khá lạc hậu.' WHERE level = 'B2' AND hanzi = '通訊' AND pinyin = 'tōngxùn' AND vietnamese = 'thông tin';
UPDATE public.dictionary_words SET example_hanzi = '我們同住一間宿舍，感情很好。', example_pinyin = 'wǒ men tóng zhù yì jiān sù shè, gǎn qíng hěn hǎo。', example_vietnamese = 'Chúng tôi cùng ở chung một ký túc xá, tình cảm rất tốt.' WHERE level = 'B2' AND hanzi = '同' AND pinyin = 'tóng' AND vietnamese = 'giống nhau';
UPDATE public.dictionary_words SET example_hanzi = '大家意見不同，吵了起來。', example_pinyin = 'dà jiā yì jiàn bù tóng, chǎo le qǐ lái。', example_vietnamese = 'Mọi người ý kiến không giống nhau nên đã cãi nhau.' WHERE level = 'B2' AND hanzi = '同' AND pinyin = 'tóng' AND vietnamese = 'cùng nhau';
UPDATE public.dictionary_words SET example_hanzi = '演講的最後，他呼籲海外同胞支持家鄉的建設。', example_pinyin = 'yǎn jiǎng de zuì hòu, tā hū yù hǎi wài tóng bāo zhī chí jiā xiāng de jiàn shè。', example_vietnamese = 'Cuối bài diễn thuyết, ông kêu gọi đồng bào ở nước ngoài ủng hộ xây dựng quê hương.' WHERE level = 'B2' AND hanzi = '同胞' AND pinyin = 'tóngbāo' AND vietnamese = 'anh chị em ruột';
UPDATE public.dictionary_words SET example_hanzi = '這部電影描述了一對同志伴侶的生活。', example_pinyin = 'zhè bù diàn yǐng miáo shù le yí duì tóng zhì bàn lǚ de shēng huó。', example_vietnamese = 'Bộ phim này miêu tả cuộc sống của một cặp đôi đồng tính.' WHERE level = 'B2' AND hanzi = '同志' AND pinyin = 'tóngzhì' AND vietnamese = 'đồng chí';
UPDATE public.dictionary_words SET example_hanzi = '這座雕像是用銅做的。', example_pinyin = 'zhè zuò diāo xiàng shì yòng tóng zuò de。', example_vietnamese = 'Bức tượng này được làm bằng đồng.' WHERE level = 'B2' AND hanzi = '銅' AND pinyin = 'tóng' AND vietnamese = 'đồng (kim loại)';
UPDATE public.dictionary_words SET example_hanzi = '他提了一桶水去澆花。', example_pinyin = 'tā tí le yì tǒng shuǐ qù jiāo huā。', example_vietnamese = 'Anh ấy xách một thùng nước đi tưới hoa.' WHERE level = 'B2' AND hanzi = '桶' AND pinyin = 'tǒng' AND vietnamese = 'thùng';
UPDATE public.dictionary_words SET example_hanzi = '根據統計，今年遊客人數增加了一倍。', example_pinyin = 'gēn jù tǒng jì, jīn nián yóu kè rén shù zēng jiā le yí bèi。', example_vietnamese = 'Theo thống kê, số lượng du khách năm nay đã tăng gấp đôi.' WHERE level = 'B2' AND hanzi = '統計' AND pinyin = 'tǒngjì' AND vietnamese = 'thống kê';
UPDATE public.dictionary_words SET example_hanzi = '公司要求所有員工穿統一的制服。', example_pinyin = 'gōng sī yāo qiú suǒ yǒu yuán gōng chuān tǒng yī de zhì fú。', example_vietnamese = 'Công ty yêu cầu tất cả nhân viên mặc đồng phục thống nhất.' WHERE level = 'B2' AND hanzi = '統一' AND pinyin = 'tǒngyī' AND vietnamese = 'thống nhất';
UPDATE public.dictionary_words SET example_hanzi = '這個地區曾經被外國統治了好幾十年。', example_pinyin = 'zhè ge dì qū céng jīng bèi wài guó tǒng zhì le hǎo jǐ shí nián。', example_vietnamese = 'Khu vực này từng bị nước ngoài thống trị mấy chục năm.' WHERE level = 'B2' AND hanzi = '統治' AND pinyin = 'tǒngzhì' AND vietnamese = 'thống trị';
UPDATE public.dictionary_words SET example_hanzi = '考完試後，我們去唱歌唱得很痛快。', example_pinyin = 'kǎo wán shì hòu, wǒ men qù chàng gē chàng de hěn tòng kuai。', example_vietnamese = 'Sau khi thi xong, chúng tôi đi hát rất thỏa thích.' WHERE level = 'B2' AND hanzi = '痛快' AND pinyin = 'tòngkuai' AND vietnamese = 'vui vẻ';
UPDATE public.dictionary_words SET example_hanzi = '弟弟偷偷把我的蛋糕吃掉了。', example_pinyin = 'dì di tōu tōu bǎ wǒ de dàn gāo chī diào le。', example_vietnamese = 'Em trai lén lút ăn mất bánh kem của tôi.' WHERE level = 'B2' AND hanzi = '偷/偷偷' AND pinyin = 'tōu/tōutōu' AND vietnamese = 'vụng trộm, lén lút';
UPDATE public.dictionary_words SET example_hanzi = '農場裡養了十頭牛。', example_pinyin = 'nóng chǎng lǐ yǎng le shí tóu niú。', example_vietnamese = 'Trong trang trại nuôi mười con bò.' WHERE level = 'B2' AND hanzi = '頭' AND pinyin = 'tóu' AND vietnamese = 'đầu';
UPDATE public.dictionary_words SET example_hanzi = '他頭腦很清楚，做事很有條理。', example_pinyin = 'tā tóu nǎo hěn qīng chu, zuò shì hěn yǒu tiáo lǐ。', example_vietnamese = 'Đầu óc anh ấy rất tỉnh táo, làm việc rất có logic.' WHERE level = 'B2' AND hanzi = '頭腦' AND pinyin = 'tóunăo' AND vietnamese = 'đầu óc, tư duy';
UPDATE public.dictionary_words SET example_hanzi = '選舉那天，大家都去投票。', example_pinyin = 'xuǎn jǔ nà tiān, dà jiā dōu qù tóu piào。', example_vietnamese = 'Ngày bầu cử, mọi người đều đi bỏ phiếu.' WHERE level = 'B2' AND hanzi = '投票' AND pinyin = 'tóupiào' AND vietnamese = 'bỏ phiếu';
UPDATE public.dictionary_words SET example_hanzi = '政府投入大量資金改善交通建設。', example_pinyin = 'zhèng fǔ tóu rù dà liàng zī jīn gǎi shàn jiāo tōng jiàn shè。', example_vietnamese = 'Chính phủ đầu tư một lượng lớn vốn để cải thiện xây dựng giao thông.' WHERE level = 'B2' AND hanzi = '投入' AND pinyin = 'tóurù' AND vietnamese = 'đi vào';
UPDATE public.dictionary_words SET example_hanzi = '敵軍彈盡糧絕，最後只好投降。', example_pinyin = 'dí jūn dàn jìn liáng jué, zuì hòu zhǐ hǎo tóu xiáng。', example_vietnamese = 'Quân địch hết đạn hết lương, cuối cùng đành phải đầu hàng.' WHERE level = 'B2' AND hanzi = '投降' AND pinyin = 'tóuxiáng' AND vietnamese = 'đầu hàng';
UPDATE public.dictionary_words SET example_hanzi = '這是一筆高風險高報酬的投資。', example_pinyin = 'zhè shì yì bǐ gāo fēng xiǎn gāo bào chóu de tóu zī。', example_vietnamese = 'Đây là một khoản đầu tư rủi ro cao nhưng lợi nhuận cũng cao.' WHERE level = 'B2' AND hanzi = '投資' AND pinyin = 'tóuzī' AND vietnamese = 'đầu tư';
UPDATE public.dictionary_words SET example_hanzi = '雨太大了，鞋子都濕透了。', example_pinyin = 'yǔ tài dà le, xié zi dōu shī tòu le。', example_vietnamese = 'Mưa to quá, giày đều ướt sũng cả.' WHERE level = 'B2' AND hanzi = '透' AND pinyin = 'tòu' AND vietnamese = 'thẩm thấu, thấm qua';
UPDATE public.dictionary_words SET example_hanzi = '我是透過朋友介紹才認識他的。', example_pinyin = 'wǒ shì tòu guò péng you jiè shào cái rèn shi tā de。', example_vietnamese = 'Tôi quen anh ấy là thông qua sự giới thiệu của bạn bè.' WHERE level = 'B2' AND hanzi = '透過' AND pinyin = 'tòuguò' AND vietnamese = 'qua';
UPDATE public.dictionary_words SET example_hanzi = '爺爺年紀大了，頭髮都禿了。', example_pinyin = 'yé ye nián jì dà le, tóu fa dōu tū le。', example_vietnamese = 'Ông nội tuổi đã cao, tóc đã hói cả.' WHERE level = 'B2' AND hanzi = '禿' AND pinyin = 'tū' AND vietnamese = 'trọc, trụi';
UPDATE public.dictionary_words SET example_hanzi = '他在這次比賽中表現得特別突出。', example_pinyin = 'tā zài zhè cì bǐ sài zhōng biǎo xiàn de tè bié tū chū。', example_vietnamese = 'Anh ấy thể hiện đặc biệt nổi bật trong cuộc thi lần này.' WHERE level = 'B2' AND hanzi = '突出' AND pinyin = 'túchū' AND vietnamese = 'xông ra, nhô ra';
UPDATE public.dictionary_words SET example_hanzi = '這項研究是醫學史上的重大突破。', example_pinyin = 'zhè xiàng yán jiū shì yī xué shǐ shàng de zhòng dà tū pò。', example_vietnamese = 'Nghiên cứu này là một đột phá quan trọng trong lịch sử y học.' WHERE level = 'B2' AND hanzi = '突破' AND pinyin = 'túpò' AND vietnamese = 'sự đột phá';
UPDATE public.dictionary_words SET example_hanzi = '他終於突破了自己的紀錄。', example_pinyin = 'tā zhōng yú tū pò le zì jǐ de jì lù。', example_vietnamese = 'Cuối cùng anh ấy đã phá được kỷ lục của chính mình.' WHERE level = 'B2' AND hanzi = '突破' AND pinyin = 'túpò' AND vietnamese = 'đột phá';
UPDATE public.dictionary_words SET example_hanzi = '學好語言最有效的途徑就是多練習說。', example_pinyin = 'xué hǎo yǔ yán zuì yǒu xiào de tú jìng jiù shì duō liàn xí shuō。', example_vietnamese = 'Con đường hiệu quả nhất để học tốt ngôn ngữ chính là luyện nói nhiều.' WHERE level = 'B2' AND hanzi = '途徑' AND pinyin = 'tújìng' AND vietnamese = 'con đường, đường lối';
UPDATE public.dictionary_words SET example_hanzi = '這間圖書館收藏了許多珍貴的圖書。', example_pinyin = 'zhè jiān tú shū guǎn shōu cáng le xǔ duō zhēn guì de tú shū。', example_vietnamese = 'Thư viện này lưu giữ rất nhiều sách quý giá.' WHERE level = 'B2' AND hanzi = '圖書' AND pinyin = 'túshū' AND vietnamese = 'con dấu, con mộc';
UPDATE public.dictionary_words SET example_hanzi = '領包裹的時候要蓋圖章。', example_pinyin = 'lǐng bāo guǒ de shí hou yào gài tú zhāng。', example_vietnamese = 'Khi nhận bưu kiện phải đóng dấu.' WHERE level = 'B2' AND hanzi = '圖章' AND pinyin = 'túzhāng' AND vietnamese = 'dấu ấn, dấu mộc';
UPDATE public.dictionary_words SET example_hanzi = '請不要隨地吐痰。', example_pinyin = 'qǐng bú yào suí dì tǔ tán。', example_vietnamese = 'Xin đừng khạc nhổ bừa bãi.' WHERE level = 'B2' AND hanzi = '吐' AND pinyin = 'tŭ' AND vietnamese = 'nhổ, nhả';
UPDATE public.dictionary_words SET example_hanzi = '桌上放了一團毛線。', example_pinyin = 'zhuō shang fàng le yì tuán máo xiàn。', example_vietnamese = 'Trên bàn đặt một cuộn len.' WHERE level = 'B2' AND hanzi = '團' AND pinyin = 'tuán' AND vietnamese = 'hình tròn';
UPDATE public.dictionary_words SET example_hanzi = '全班同學團結一心，終於贏了比賽。', example_pinyin = 'quán bān tóng xué tuán jié yì xīn, zhōng yú yíng le bǐ sài。', example_vietnamese = 'Cả lớp đoàn kết một lòng, cuối cùng đã giành chiến thắng.' WHERE level = 'B2' AND hanzi = '團結' AND pinyin = 'tuánjié' AND vietnamese = 'đoàn kết';
UPDATE public.dictionary_words SET example_hanzi = '政府積極推動環保政策。', example_pinyin = 'zhèng fǔ jī jí tuī dòng huán bǎo zhèng cè。', example_vietnamese = 'Chính phủ tích cực thúc đẩy chính sách bảo vệ môi trường.' WHERE level = 'B2' AND hanzi = '推動' AND pinyin = 'tuīdòng' AND vietnamese = 'thúc đẩy';
UPDATE public.dictionary_words SET example_hanzi = '人民起義，推翻了腐敗的政權。', example_pinyin = 'rén mín qǐ yì, tuī fān le fǔ bài de zhèng quán。', example_vietnamese = 'Nhân dân khởi nghĩa, lật đổ chính quyền tham nhũng.' WHERE level = 'B2' AND hanzi = '推翻' AND pinyin = 'tuīfān' AND vietnamese = 'lật đổ';
UPDATE public.dictionary_words SET example_hanzi = '學校正在推廣閱讀活動。', example_pinyin = 'xué xiào zhèng zài tuī guǎng yuè dú huó dòng。', example_vietnamese = 'Trường học đang quảng bá hoạt động đọc sách.' WHERE level = 'B2' AND hanzi = '推廣' AND pinyin = 'tuīguăng' AND vietnamese = 'mở rộng';
UPDATE public.dictionary_words SET example_hanzi = '他嚇得往後退了一步。', example_pinyin = 'tā xià de wǎng hòu tuì le yí bù。', example_vietnamese = 'Anh ấy sợ đến mức lùi lại một bước.' WHERE level = 'B2' AND hanzi = '退' AND pinyin = 'tuì' AND vietnamese = 'lui, lùi';
UPDATE public.dictionary_words SET example_hanzi = '因為受傷，他決定退出這次比賽。', example_pinyin = 'yīn wèi shòu shāng, tā jué dìng tuì chū zhè cì bǐ sài。', example_vietnamese = 'Vì bị thương, anh ấy quyết định rút khỏi cuộc thi lần này.' WHERE level = 'B2' AND hanzi = '退出' AND pinyin = 'tuìchū' AND vietnamese = 'rút khỏi';
UPDATE public.dictionary_words SET example_hanzi = '這件衣服尺寸不合，我想退回去。', example_pinyin = 'zhè jiàn yī fu chǐ cùn bù hé, wǒ xiǎng tuì huí qù。', example_vietnamese = 'Chiếc áo này không vừa size, tôi muốn trả lại.' WHERE level = 'B2' AND hanzi = '退回' AND pinyin = 'tuìhuí' AND vietnamese = 'trả lại';
UPDATE public.dictionary_words SET example_hanzi = '藥丸太大了，他吞不下去。', example_pinyin = 'yào wán tài dà le, tā tūn bú xià qu。', example_vietnamese = 'Viên thuốc to quá, anh ấy không nuốt được.' WHERE level = 'B2' AND hanzi = '吞' AND pinyin = 'tūn' AND vietnamese = 'nuốt, ngốn';
UPDATE public.dictionary_words SET example_hanzi = '他把沉重的行李箱拖到車站。', example_pinyin = 'tā bǎ chén zhòng de xíng li xiāng tuō dào chē zhàn。', example_vietnamese = 'Anh ấy kéo chiếc vali nặng đến bến xe.' WHERE level = 'B2' AND hanzi = '拖' AND pinyin = 'tuō' AND vietnamese = 'kéo, dắt';
UPDATE public.dictionary_words SET example_hanzi = '進門前請先換上拖鞋。', example_pinyin = 'jìn mén qián qǐng xiān huàn shàng tuō xié。', example_vietnamese = 'Trước khi vào cửa xin hãy thay dép lê.' WHERE level = 'B2' AND hanzi = '拖鞋' AND pinyin = 'tuōxié' AND vietnamese = 'dép lê';
UPDATE public.dictionary_words SET example_hanzi = '這家托兒所離我家很近，很方便。', example_pinyin = 'zhè jiā tuō ér suǒ lí wǒ jiā hěn jìn, hěn fāng biàn。', example_vietnamese = 'Nhà trẻ này gần nhà tôi, rất tiện lợi.' WHERE level = 'B2' AND hanzi = '托兒所' AND pinyin = 'tuōérsuŏ' AND vietnamese = 'nhà trẻ';
UPDATE public.dictionary_words SET example_hanzi = '病人已經脫離危險期了。', example_pinyin = 'bìng rén yǐ jīng tuō lí wéi xiǎn qī le。', example_vietnamese = 'Bệnh nhân đã thoát khỏi giai đoạn nguy hiểm rồi.' WHERE level = 'B2' AND hanzi = '脫離' AND pinyin = 'tuōlí' AND vietnamese = 'thoát ly';
UPDATE public.dictionary_words SET example_hanzi = '這樣安排比較妥當，大家都沒有意見。', example_pinyin = 'zhè yàng ān pái bǐ jiào tuǒ dang, dà jiā dōu méi yǒu yì jiàn。', example_vietnamese = 'Sắp xếp như vậy khá thỏa đáng, mọi người đều không có ý kiến gì.' WHERE level = 'B2' AND hanzi = '妥當' AND pinyin = 'tuǒdang' AND vietnamese = 'thỏa đáng';
UPDATE public.dictionary_words SET example_hanzi = '這件事情已經得到妥善的處理。', example_pinyin = 'zhè jiàn shì qing yǐ jīng dé dào tuǒ shàn de chǔ lǐ。', example_vietnamese = 'Việc này đã được xử lý ổn thỏa.' WHERE level = 'B2' AND hanzi = '妥善' AND pinyin = 'tuŏshàn' AND vietnamese = 'ổn thỏa';
UPDATE public.dictionary_words SET example_hanzi = '為了和平，雙方最後願意妥協。', example_pinyin = 'wèi le hé píng, shuāng fāng zuì hòu yuàn yì tuǒ xié。', example_vietnamese = 'Vì hòa bình, cuối cùng hai bên sẵn lòng thỏa hiệp.' WHERE level = 'B2' AND hanzi = '妥協' AND pinyin = 'tuŏxié' AND vietnamese = 'thỏa hiệp';
UPDATE public.dictionary_words SET example_hanzi = '哇，這件禮物真的太漂亮了！', example_pinyin = 'wā, zhè jiàn lǐ wù zhēn de tài piào liang le!', example_vietnamese = 'Ồ, món quà này thật sự quá đẹp!' WHERE level = 'B2' AND hanzi = '哇' AND pinyin = 'wā' AND vietnamese = 'oa oa, oe oe (từ tượng thanh)';
UPDATE public.dictionary_words SET example_hanzi = '工人正在路邊挖一個大洞。', example_pinyin = 'gōng rén zhèng zài lù biān wā yí gè dà dòng。', example_vietnamese = 'Công nhân đang đào một cái hố lớn ở bên đường.' WHERE level = 'B2' AND hanzi = '挖' AND pinyin = 'wā' AND vietnamese = 'đào, khoét';
UPDATE public.dictionary_words SET example_hanzi = '這幅畫掛歪了，幫我扶正一下。', example_pinyin = 'zhè fú huà guà wāi le, bāng wǒ fú zhèng yí xià。', example_vietnamese = 'Bức tranh này treo bị lệch rồi, giúp tôi chỉnh lại cho ngay.' WHERE level = 'B2' AND hanzi = '歪' AND pinyin = 'wāi' AND vietnamese = 'nghiêng, lệch';
UPDATE public.dictionary_words SET example_hanzi = '這台機器的外部看起來沒什麼問題。', example_pinyin = 'zhè tái jī qì de wài bù kàn qǐ lái méi shén me wèn tí。', example_vietnamese = 'Phần bên ngoài của cái máy này nhìn có vẻ không có vấn đề gì.' WHERE level = 'B2' AND hanzi = '外部' AND pinyin = 'wàibù' AND vietnamese = 'phần ngoài, vẻ ngoài';
UPDATE public.dictionary_words SET example_hanzi = '爸爸外出開會，晚上才會回來。', example_pinyin = 'bà ba wài chū kāi huì, wǎn shang cái huì huí lai。', example_vietnamese = 'Bố đi ra ngoài họp, tối mới về.' WHERE level = 'B2' AND hanzi = '外出' AND pinyin = 'wàichū' AND vietnamese = 'đi chơi';
UPDATE public.dictionary_words SET example_hanzi = '他是外地人，來這裡工作才兩年。', example_pinyin = 'tā shì wài dì rén, lái zhè lǐ gōng zuò cái liǎng nián。', example_vietnamese = 'Anh ấy là người từ nơi khác đến, mới làm việc ở đây được hai năm.' WHERE level = 'B2' AND hanzi = '外地' AND pinyin = 'wàidì' AND vietnamese = 'nơi khác, vùng khác';
UPDATE public.dictionary_words SET example_hanzi = '這款手機外觀設計得很時尚。', example_pinyin = 'zhè kuǎn shǒu jī wài guān shè jì de hěn shí shàng。', example_vietnamese = 'Mẫu điện thoại này có thiết kế bề ngoài rất thời trang.' WHERE level = 'B2' AND hanzi = '外觀' AND pinyin = 'wàiguān' AND vietnamese = 'bề ngoài';
UPDATE public.dictionary_words SET example_hanzi = '修理電腦我完全外行，還是找專家吧。', example_pinyin = 'xiū lǐ diàn nǎo wǒ wán quán wài háng, hái shi zhǎo zhuān jiā ba。', example_vietnamese = 'Sửa máy tính thì tôi hoàn toàn không rành, thôi tìm chuyên gia đi.' WHERE level = 'B2' AND hanzi = '外行' AND pinyin = 'wàiháng' AND vietnamese = 'không chuyên môn, ngoài nghề';
UPDATE public.dictionary_words SET example_hanzi = '出國前記得先換一些外匯。', example_pinyin = 'chū guó qián jì de xiān huàn yì xiē wài huì。', example_vietnamese = 'Trước khi ra nước ngoài nhớ đổi một ít ngoại tệ.' WHERE level = 'B2' AND hanzi = '外匯' AND pinyin = 'wàihuì' AND vietnamese = 'ngoại hối';
UPDATE public.dictionary_words SET example_hanzi = '兩國之間的外交關係最近改善了不少。', example_pinyin = 'liǎng guó zhī jiān de wài jiāo guān xi zuì jìn gǎi shàn le bù shǎo。', example_vietnamese = 'Quan hệ ngoại giao giữa hai nước gần đây đã được cải thiện nhiều.' WHERE level = 'B2' AND hanzi = '外交' AND pinyin = 'wàijiāo' AND vietnamese = 'ngoại giao';
UPDATE public.dictionary_words SET example_hanzi = '這件事引起了外界很大的關注。', example_pinyin = 'zhè jiàn shì yǐn qǐ le wài jiè hěn dà de guān zhù。', example_vietnamese = 'Việc này đã thu hút sự quan tâm rất lớn từ bên ngoài.' WHERE level = 'B2' AND hanzi = '外界' AND pinyin = 'wàijiè' AND vietnamese = 'bên ngoài';
UPDATE public.dictionary_words SET example_hanzi = '他因為骨折，被送到外科開刀。', example_pinyin = 'tā yīn wèi gǔ zhé, bèi sòng dào wài kē kāi dāo。', example_vietnamese = 'Vì bị gãy xương, anh ấy được đưa đến khoa ngoại để phẫu thuật.' WHERE level = 'B2' AND hanzi = '外科' AND pinyin = 'wàikē' AND vietnamese = 'ngoại khoa';
UPDATE public.dictionary_words SET example_hanzi = '外頭在下雨，你出門記得帶傘。', example_pinyin = 'wài tou zài xià yǔ, nǐ chū mén jì de dài sǎn。', example_vietnamese = 'Bên ngoài đang mưa, ra ngoài nhớ mang theo ô.' WHERE level = 'B2' AND hanzi = '外頭' AND pinyin = 'wàitou' AND vietnamese = 'bề ngoài';
UPDATE public.dictionary_words SET example_hanzi = '這條山路又彎又窄，開車要小心。', example_pinyin = 'zhè tiáo shān lù yòu wān yòu zhǎi, kāi chē yào xiǎo xīn。', example_vietnamese = 'Con đường núi này vừa quanh co vừa hẹp, lái xe phải cẩn thận.' WHERE level = 'B2' AND hanzi = '彎' AND pinyin = 'wān' AND vietnamese = 'cong, ngoằn ngoèo';
UPDATE public.dictionary_words SET example_hanzi = '他彎腰撿起掉在地上的錢包。', example_pinyin = 'tā wān yāo jiǎn qǐ diào zài dì shang de qián bāo。', example_vietnamese = 'Anh ấy cúi người nhặt lên chiếc ví rơi trên đất.' WHERE level = 'B2' AND hanzi = '彎腰' AND pinyin = 'wānyāo' AND vietnamese = 'cúi gập người';
UPDATE public.dictionary_words SET example_hanzi = '手術完畢後，病人被送回病房休息。', example_pinyin = 'shǒu shù wán bì hòu, bìng rén bèi sòng huí bìng fáng xiū xi。', example_vietnamese = 'Sau khi phẫu thuật hoàn tất, bệnh nhân được đưa về phòng bệnh nghỉ ngơi.' WHERE level = 'B2' AND hanzi = '完畢' AND pinyin = 'wánbì' AND vietnamese = 'hoàn tất';
UPDATE public.dictionary_words SET example_hanzi = '這套系統的功能還不夠完善。', example_pinyin = 'zhè tào xì tǒng de gōng néng hái bú gòu wán shàn。', example_vietnamese = 'Chức năng của hệ thống này vẫn chưa đủ hoàn thiện.' WHERE level = 'B2' AND hanzi = '完善' AND pinyin = 'wánshàn' AND vietnamese = 'hoàn thiện';
UPDATE public.dictionary_words SET example_hanzi = '這是一份完整的報告，資料非常齊全。', example_pinyin = 'zhè shì yí fèn wán zhěng de bào gào, zī liào fēi cháng qí quán。', example_vietnamese = 'Đây là một bản báo cáo hoàn chỉnh, tư liệu rất đầy đủ.' WHERE level = 'B2' AND hanzi = '完整' AND pinyin = 'wánzhěng' AND vietnamese = 'toàn vẹn';
UPDATE public.dictionary_words SET example_hanzi = '別生氣，我只是開個玩笑而已。', example_pinyin = 'bié shēng qì, wǒ zhǐ shì kāi ge wán xiào ér yǐ。', example_vietnamese = 'Đừng giận, tôi chỉ đùa một chút thôi.' WHERE level = 'B2' AND hanzi = '玩笑' AND pinyin = 'wánxiào' AND vietnamese = 'vui đùa';
UPDATE public.dictionary_words SET example_hanzi = '身為晚輩，我們應該尊敬長輩。', example_pinyin = 'shēn wéi wǎn bèi, wǒ men yīng gāi zūn jìng zhǎng bèi。', example_vietnamese = 'Là hàng con cháu, chúng ta nên tôn kính người lớn tuổi.' WHERE level = 'B2' AND hanzi = '晚輩' AND pinyin = 'wănbèi' AND vietnamese = 'thế hệ sau, hậu bối';
UPDATE public.dictionary_words SET example_hanzi = '這班公車是往台北車站的方向。', example_pinyin = 'zhè bān gōng chē shì wǎng tái běi chē zhàn de fāng xiàng。', example_vietnamese = 'Chuyến xe buýt này đi theo hướng về ga Đài Bắc.' WHERE level = 'B2' AND hanzi = '往' AND pinyin = 'wăng' AND vietnamese = 'hướng về';
UPDATE public.dictionary_words SET example_hanzi = '她站在窗邊，望著遠方發呆。', example_pinyin = 'tā zhàn zài chuāng biān, wàng zhe yuǎn fāng fā dāi。', example_vietnamese = 'Cô ấy đứng bên cửa sổ, nhìn về phía xa mà thẫn thờ.' WHERE level = 'B2' AND hanzi = '望' AND pinyin = 'wàng' AND vietnamese = 'trông, nhìn (xa)';
UPDATE public.dictionary_words SET example_hanzi = '環境污染對人類健康造成很大的威脅。', example_pinyin = 'huán jìng wū rǎn duì rén lèi jiàn kāng zào chéng hěn dà de wēi xié。', example_vietnamese = 'Ô nhiễm môi trường gây ra mối đe dọa rất lớn đối với sức khỏe con người.' WHERE level = 'B2' AND hanzi = '威脅' AND pinyin = 'wēixié' AND vietnamese = 'sự uy hiếp';
UPDATE public.dictionary_words SET example_hanzi = '歹徒拿刀威脅店員交出現金。', example_pinyin = 'dǎi tú ná dāo wēi xié diàn yuán jiāo chū xiàn jīn。', example_vietnamese = 'Tên côn đồ cầm dao đe dọa nhân viên cửa hàng đưa tiền mặt ra.' WHERE level = 'B2' AND hanzi = '威脅' AND pinyin = 'wēixié' AND vietnamese = 'uy hiếp';
UPDATE public.dictionary_words SET example_hanzi = '很多人圍在一起看熱鬧。', example_pinyin = 'hěn duō rén wéi zài yì qǐ kàn rè nao。', example_vietnamese = 'Rất nhiều người vây quanh nhau xem náo nhiệt.' WHERE level = 'B2' AND hanzi = '圍' AND pinyin = 'wéi' AND vietnamese = 'vây, bao vây';
UPDATE public.dictionary_words SET example_hanzi = '闖紅燈是違反交通規則的行為。', example_pinyin = 'chuǎng hóng dēng shì wéi fǎn jiāo tōng guī zé de xíng wéi。', example_vietnamese = 'Vượt đèn đỏ là hành vi vi phạm luật giao thông.' WHERE level = 'B2' AND hanzi = '違反' AND pinyin = 'wéifăn' AND vietnamese = 'trái với';
UPDATE public.dictionary_words SET example_hanzi = '大家應該一起維護公共環境的整潔。', example_pinyin = 'dà jiā yīng gāi yì qǐ wéi hù gōng gòng huán jìng de zhěng jié。', example_vietnamese = 'Mọi người nên cùng nhau giữ gìn sự sạch sẽ của môi trường công cộng.' WHERE level = 'B2' AND hanzi = '維護' AND pinyin = 'wéihù' AND vietnamese = 'giữ gìn, bảo vệ';
UPDATE public.dictionary_words SET example_hanzi = '醫生建議我每天補充維他命Ｃ。', example_pinyin = 'yī shēng jiàn yì wǒ měi tiān bǔ chōng wéi tā mìng C。', example_vietnamese = 'Bác sĩ khuyên tôi mỗi ngày nên bổ sung vitamin C.' WHERE level = 'B2' AND hanzi = '維他命' AND pinyin = 'wéitāmìng' AND vietnamese = 'vitamin';
UPDATE public.dictionary_words SET example_hanzi = '這家公司正面臨財務危機。', example_pinyin = 'zhè jiā gōng sī zhèng miàn lín cái wù wéi jī。', example_vietnamese = 'Công ty này đang đối mặt với khủng hoảng tài chính.' WHERE level = 'B2' AND hanzi = '危機' AND pinyin = 'wéijī' AND vietnamese = 'nguy cơ';
UPDATE public.dictionary_words SET example_hanzi = '你這樣要求真的讓我很為難。', example_pinyin = 'nǐ zhè yàng yāo qiú zhēn de ràng wǒ hěn wéi nán。', example_vietnamese = 'Bạn yêu cầu như vậy thật sự khiến tôi rất khó xử.' WHERE level = 'B2' AND hanzi = '為難' AND pinyin = 'wéinán' AND vietnamese = 'khó xử';
UPDATE public.dictionary_words SET example_hanzi = '他是我唯一信任的朋友。', example_pinyin = 'tā shì wǒ wéi yī xìn rèn de péng you。', example_vietnamese = 'Anh ấy là người bạn duy nhất mà tôi tin tưởng.' WHERE level = 'B2' AND hanzi = '唯一' AND pinyin = 'wéiyī' AND vietnamese = 'duy nhất';
UPDATE public.dictionary_words SET example_hanzi = '小狗一看到主人就搖尾巴。', example_pinyin = 'xiǎo gǒu yí kàn dào zhǔ rén jiù yáo wěi ba。', example_vietnamese = 'Chú chó con vừa thấy chủ liền vẫy đuôi.' WHERE level = 'B2' AND hanzi = '尾巴' AND pinyin = 'wěiba' AND vietnamese = 'cái đuôi';
UPDATE public.dictionary_words SET example_hanzi = '被老闆誤會後，她覺得很委屈。', example_pinyin = 'bèi lǎo bǎn wù huì hòu, tā jué de hěn wěi qū。', example_vietnamese = 'Sau khi bị ông chủ hiểu lầm, cô ấy cảm thấy rất tủi thân.' WHERE level = 'B2' AND hanzi = '委屈' AND pinyin = 'wěiqū' AND vietnamese = 'tủi thân';
UPDATE public.dictionary_words SET example_hanzi = '他委託律師處理這件財產糾紛。', example_pinyin = 'tā wěi tuō lǜ shī chǔ lǐ zhè jiàn cái chǎn jiū fēn。', example_vietnamese = 'Anh ấy ủy thác cho luật sư xử lý vụ tranh chấp tài sản này.' WHERE level = 'B2' AND hanzi = '委託' AND pinyin = 'wěituō' AND vietnamese = 'ủy thác';
UPDATE public.dictionary_words SET example_hanzi = '她被選為學生會的委員。', example_pinyin = 'tā bèi xuǎn wéi xué shēng huì de wěi yuán。', example_vietnamese = 'Cô ấy được bầu làm ủy viên hội học sinh.' WHERE level = 'B2' AND hanzi = '委員' AND pinyin = 'wěiyuán' AND vietnamese = 'ủy viên';
UPDATE public.dictionary_words SET example_hanzi = '此案至今未破，警方仍在調查。', example_pinyin = 'cǐ àn zhì jīn wèi pò, jǐng fāng réng zài diào chá。', example_vietnamese = 'Vụ án này đến nay vẫn chưa được phá, cảnh sát vẫn đang điều tra.' WHERE level = 'B2' AND hanzi = '未' AND pinyin = 'wèi' AND vietnamese = 'vị, chưa, không';
UPDATE public.dictionary_words SET example_hanzi = '他今年三十五歲，還是未婚。', example_pinyin = 'tā jīn nián sān shí wǔ suì, hái shi wèi hūn。', example_vietnamese = 'Năm nay anh ấy ba mươi lăm tuổi mà vẫn chưa kết hôn.' WHERE level = 'B2' AND hanzi = '未婚' AND pinyin = 'wèihūn' AND vietnamese = 'chưa cưới';
UPDATE public.dictionary_words SET example_hanzi = '這家餐廳位於市中心，交通很方便。', example_pinyin = 'zhè jiā cān tīng wèi yú shì zhōng xīn, jiāo tōng hěn fāng biàn。', example_vietnamese = 'Nhà hàng này nằm ở trung tâm thành phố, giao thông rất thuận tiện.' WHERE level = 'B2' AND hanzi = '位於' AND pinyin = 'wèiyú' AND vietnamese = 'nằm ở';
UPDATE public.dictionary_words SET example_hanzi = '這湯的味兒有點怪，是不是放錯調味料了？', example_pinyin = 'zhè tāng de wèir yǒu diǎn guài, shì bu shì fàng cuò tiáo wèi liào le?', example_vietnamese = 'Vị của món canh này có chút lạ, có phải cho nhầm gia vị không?' WHERE level = 'B2' AND hanzi = '味/味兒' AND pinyin = 'wèi/wèir' AND vietnamese = 'vị';
UPDATE public.dictionary_words SET example_hanzi = '這家店煮菜都不加味精。', example_pinyin = 'zhè jiā diàn zhǔ cài dōu bù jiā wèi jīng。', example_vietnamese = 'Quán này nấu ăn đều không cho bột ngọt.' WHERE level = 'B2' AND hanzi = '味精' AND pinyin = 'wèijīng' AND vietnamese = 'bột ngọt';
UPDATE public.dictionary_words SET example_hanzi = '我不明白他為何突然離職。', example_pinyin = 'wǒ bù míng bai tā wèi hé tú rán lí zhí。', example_vietnamese = 'Tôi không hiểu vì sao anh ấy đột nhiên nghỉ việc.' WHERE level = 'B2' AND hanzi = '為何' AND pinyin = 'wèihé' AND vietnamese = 'vì sao';
UPDATE public.dictionary_words SET example_hanzi = '這家餐廳的廚房非常衛生。', example_pinyin = 'zhè jiā cān tīng de chú fáng fēi cháng wèi shēng。', example_vietnamese = 'Nhà bếp của nhà hàng này rất sạch sẽ vệ sinh.' WHERE level = 'B2' AND hanzi = '衛生' AND pinyin = 'wèishēng' AND vietnamese = 'vệ sinh';
UPDATE public.dictionary_words SET example_hanzi = '家裡的衛生紙用完了，要再買。', example_pinyin = 'jiā lǐ de wèi shēng zhǐ yòng wán le, yào zài mǎi。', example_vietnamese = 'Giấy vệ sinh trong nhà đã dùng hết, phải mua thêm.' WHERE level = 'B2' AND hanzi = '衛生紙' AND pinyin = 'wèishēngzhĭ' AND vietnamese = 'giấy vệ sinh';
UPDATE public.dictionary_words SET example_hanzi = '這顆人造衛星負責傳送電視訊號。', example_pinyin = 'zhè kē rén zào wèi xīng fù zé chuán sòng diàn shì xùn hào。', example_vietnamese = 'Vệ tinh nhân tạo này chịu trách nhiệm truyền tín hiệu truyền hình.' WHERE level = 'B2' AND hanzi = '衛星' AND pinyin = 'wèixīng' AND vietnamese = 'vệ tinh nhân tạo';
UPDATE public.dictionary_words SET example_hanzi = '市長親自到醫院慰問受傷的消防員。', example_pinyin = 'shì zhǎng qīn zì dào yī yuàn wèi wèn shòu shāng de xiāo fáng yuán。', example_vietnamese = 'Thị trưởng đích thân đến bệnh viện thăm hỏi lính cứu hỏa bị thương.' WHERE level = 'B2' AND hanzi = '慰問' AND pinyin = 'wèiwèn' AND vietnamese = 'thăm hỏi';
UPDATE public.dictionary_words SET example_hanzi = '他個性溫和，很少跟人起爭執。', example_pinyin = 'tā gè xìng wēn hé, hěn shǎo gēn rén qǐ zhēng zhí。', example_vietnamese = 'Tính cách anh ấy ôn hòa, hiếm khi tranh cãi với người khác.' WHERE level = 'B2' AND hanzi = '溫和' AND pinyin = 'wēnhé' AND vietnamese = 'ôn hòa';
UPDATE public.dictionary_words SET example_hanzi = '中文的文法跟越南文不太一樣。', example_pinyin = 'zhōng wén de wén fǎ gēn yuè nán wén bú tài yí yàng。', example_vietnamese = 'Ngữ pháp tiếng Trung không hoàn toàn giống với tiếng Việt.' WHERE level = 'B2' AND hanzi = '文法' AND pinyin = 'wénfă' AND vietnamese = 'ngữ pháp, văn phạm';
UPDATE public.dictionary_words SET example_hanzi = '開學前媽媽帶我去買文具。', example_pinyin = 'kāi xué qián mā ma dài wǒ qù mǎi wén jù。', example_vietnamese = 'Trước khi khai giảng mẹ dẫn tôi đi mua văn phòng phẩm.' WHERE level = 'B2' AND hanzi = '文具' AND pinyin = 'wénjù' AND vietnamese = 'văn phòng phẩm';
UPDATE public.dictionary_words SET example_hanzi = '現在找工作，文憑不再是唯一的條件。', example_pinyin = 'xiàn zài zhǎo gōng zuò, wén píng bú zài shì wéi yī de tiáo jiàn。', example_vietnamese = 'Bây giờ tìm việc, bằng cấp không còn là điều kiện duy nhất nữa.' WHERE level = 'B2' AND hanzi = '文憑' AND pinyin = 'wénpíng' AND vietnamese = 'văn bằng';
UPDATE public.dictionary_words SET example_hanzi = '博物館展出了許多古代文物。', example_pinyin = 'bó wù guǎn zhǎn chū le xǔ duō gǔ dài wén wù。', example_vietnamese = 'Bảo tàng trưng bày rất nhiều di vật văn hóa cổ đại.' WHERE level = 'B2' AND hanzi = '文物' AND pinyin = 'wénwù' AND vietnamese = 'di vật văn hóa';
UPDATE public.dictionary_words SET example_hanzi = '她喜歡參加學校的文藝表演。', example_pinyin = 'tā xǐ huan cān jiā xué xiào de wén yì biǎo yǎn。', example_vietnamese = 'Cô ấy thích tham gia biểu diễn văn nghệ của trường.' WHERE level = 'B2' AND hanzi = '文藝' AND pinyin = 'wényì' AND vietnamese = 'văn nghệ';
UPDATE public.dictionary_words SET example_hanzi = '夏天蚊子特別多，要記得噴防蚊液。', example_pinyin = 'xià tiān wén zi tè bié duō, yào jì de pēn fáng wén yè。', example_vietnamese = 'Mùa hè muỗi đặc biệt nhiều, phải nhớ xịt thuốc chống muỗi.' WHERE level = 'B2' AND hanzi = '蚊子' AND pinyin = 'wénzi' AND vietnamese = 'con muỗi';
UPDATE public.dictionary_words SET example_hanzi = '這種魚的吻部特別尖長。', example_pinyin = 'zhè zhǒng yú de wěn bù tè bié jiān cháng。', example_vietnamese = 'Phần mõm của loài cá này đặc biệt nhọn và dài.' WHERE level = 'B2' AND hanzi = '吻' AND pinyin = 'wěn' AND vietnamese = 'mõm (động vật)';
UPDATE public.dictionary_words SET example_hanzi = '電影結束前，男主角輕輕吻了女主角一下。', example_pinyin = 'diàn yǐng jié shù qián, nán zhǔ jué qīng qīng wěn le nǚ zhǔ jué yí xià。', example_vietnamese = 'Trước khi phim kết thúc, nam chính khẽ hôn nữ chính một cái.' WHERE level = 'B2' AND hanzi = '吻' AND pinyin = 'wěn' AND vietnamese = 'hôn';
UPDATE public.dictionary_words SET example_hanzi = '這張桌子有點不穩，一碰就搖晃。', example_pinyin = 'zhè zhāng zhuō zi yǒu diǎn bù wěn, yí pèng jiù yáo huàng。', example_vietnamese = 'Cái bàn này hơi không vững, vừa chạm vào là lung lay.' WHERE level = 'B2' AND hanzi = '穩' AND pinyin = 'wěn' AND vietnamese = 'ổn định, vững';
UPDATE public.dictionary_words SET example_hanzi = '兩人第一次見面就熱情地握了手。', example_pinyin = 'liǎng rén dì yī cì jiàn miàn jiù rè qíng de wò le shǒu。', example_vietnamese = 'Hai người gặp nhau lần đầu đã nồng nhiệt bắt tay nhau.' WHERE level = 'B2' AND hanzi = '握' AND pinyin = 'wò' AND vietnamese = 'nắm, bắt, cầm';
UPDATE public.dictionary_words SET example_hanzi = '這間房子有三個臥房，很適合一家人住。', example_pinyin = 'zhè jiān fáng zi yǒu sān gè wò fáng, hěn shì hé yì jiā rén zhù。', example_vietnamese = 'Căn nhà này có ba phòng ngủ, rất thích hợp cho cả gia đình ở.' WHERE level = 'B2' AND hanzi = '臥房' AND pinyin = 'wòfáng' AND vietnamese = 'phòng ngủ';
UPDATE public.dictionary_words SET example_hanzi = '工廠排放廢水，嚴重污染了這條河流。', example_pinyin = 'gōng chǎng pái fàng fèi shuǐ, yán zhòng wū rǎn le zhè tiáo hé liú。', example_vietnamese = 'Nhà máy xả nước thải, làm ô nhiễm nghiêm trọng con sông này.' WHERE level = 'B2' AND hanzi = '汙/污染' AND pinyin = 'wūrăn' AND vietnamese = 'ô nhiễm';
UPDATE public.dictionary_words SET example_hanzi = '面對這樣的結果，他也只能無可奈何地接受。', example_pinyin = 'miàn duì zhè yàng de jié guǒ, tā yě zhǐ néng wú kě nài hé de jiē shòu。', example_vietnamese = 'Đối mặt với kết quả như vậy, anh ấy cũng đành phải bất lực chấp nhận.' WHERE level = 'B2' AND hanzi = '無可奈何' AND pinyin = 'wúkěnàihé' AND vietnamese = 'không biết làm thế nào';
UPDATE public.dictionary_words SET example_hanzi = '無論天氣好不好，我們都會準時出發。', example_pinyin = 'wú lùn tiān qì hǎo bu hǎo, wǒ men dōu huì zhǔn shí chū fā。', example_vietnamese = 'Bất kể thời tiết tốt hay không, chúng tôi đều sẽ xuất phát đúng giờ.' WHERE level = 'B2' AND hanzi = '無論' AND pinyin = 'wúlùn' AND vietnamese = 'bất kể, bất luận';
UPDATE public.dictionary_words SET example_hanzi = '他對朋友的請求拒絕得十分無情。', example_pinyin = 'tā duì péng you de qǐng qiú jù jué de shí fēn wú qíng。', example_vietnamese = 'Anh ấy từ chối yêu cầu của bạn bè một cách rất vô tình.' WHERE level = 'B2' AND hanzi = '無情' AND pinyin = 'wúqíng' AND vietnamese = 'vô tình';
UPDATE public.dictionary_words SET example_hanzi = '這座城市每天都有無數遊客前來參觀。', example_pinyin = 'zhè zuò chéng shì měi tiān dōu yǒu wú shù yóu kè qián lái cān guān。', example_vietnamese = 'Thành phố này mỗi ngày đều có vô số du khách đến tham quan.' WHERE level = 'B2' AND hanzi = '無數' AND pinyin = 'wúshù' AND vietnamese = 'vô số';
UPDATE public.dictionary_words SET example_hanzi = '網路資源幾乎是無限的。', example_pinyin = 'wǎng lù zī yuán jī hū shì wú xiàn de。', example_vietnamese = 'Tài nguyên mạng gần như là vô hạn.' WHERE level = 'B2' AND hanzi = '無限' AND pinyin = 'wúxiàn' AND vietnamese = 'vô hạn';
UPDATE public.dictionary_words SET example_hanzi = '我是無意中聽到他們的談話。', example_pinyin = 'wǒ shì wú yì zhōng tīng dào tā men de tán huà。', example_vietnamese = 'Tôi tình cờ nghe được cuộc trò chuyện của họ.' WHERE level = 'B2' AND hanzi = '無意' AND pinyin = 'wúyì' AND vietnamese = 'vô ý';
UPDATE public.dictionary_words SET example_hanzi = '警方在嫌犯家中搜出大量武器。', example_pinyin = 'jǐng fāng zài xián fàn jiā zhōng sōu chū dà liàng wǔ qì。', example_vietnamese = 'Cảnh sát lục soát được một lượng lớn vũ khí trong nhà nghi phạm.' WHERE level = 'B2' AND hanzi = '武器' AND pinyin = 'wŭqì' AND vietnamese = 'vũ khí';
UPDATE public.dictionary_words SET example_hanzi = '他從小學習中國武術，身手很敏捷。', example_pinyin = 'tā cóng xiǎo xué xí zhōng guó wǔ shù, shēn shǒu hěn mǐn jié。', example_vietnamese = 'Anh ấy học võ thuật Trung Quốc từ nhỏ, thân thủ rất nhanh nhẹn.' WHERE level = 'B2' AND hanzi = '武術' AND pinyin = 'wŭshù' AND vietnamese = 'võ thuật';
UPDATE public.dictionary_words SET example_hanzi = '他們隨著音樂跳起舞來。', example_pinyin = 'tā men suí zhe yīn yuè tiào qǐ wǔ lái。', example_vietnamese = 'Họ nhảy múa theo tiếng nhạc.' WHERE level = 'B2' AND hanzi = '舞' AND pinyin = 'wŭ' AND vietnamese = 'vũ, khiêu vũ';
UPDATE public.dictionary_words SET example_hanzi = '她從小學習舞蹈，現在是職業舞者。', example_pinyin = 'tā cóng xiǎo xué xí wǔ dào, xiàn zài shì zhí yè wǔ zhě。', example_vietnamese = 'Cô ấy học múa từ nhỏ, bây giờ là vũ công chuyên nghiệp.' WHERE level = 'B2' AND hanzi = '舞蹈' AND pinyin = 'wŭdào' AND vietnamese = 'điệu múa, vũ đạo';
UPDATE public.dictionary_words SET example_hanzi = '燈光一亮，演員們走上舞台。', example_pinyin = 'dēng guāng yí liàng, yǎn yuán men zǒu shàng wǔ tái。', example_vietnamese = 'Đèn vừa sáng lên, các diễn viên bước lên sân khấu.' WHERE level = 'B2' AND hanzi = '舞台/臺' AND pinyin = 'wŭtái' AND vietnamese = 'sân khấu';
UPDATE public.dictionary_words SET example_hanzi = '這家舞廳每週末都有現場樂團演奏。', example_pinyin = 'zhè jiā wǔ tīng měi zhōu mò dōu yǒu xiàn chǎng yuè tuán yǎn zòu。', example_vietnamese = 'Vũ trường này mỗi cuối tuần đều có ban nhạc biểu diễn trực tiếp.' WHERE level = 'B2' AND hanzi = '舞廳' AND pinyin = 'wŭtīng' AND vietnamese = 'phòng nhảy';
UPDATE public.dictionary_words SET example_hanzi = '請勿在此拍照。', example_pinyin = 'qǐng wù zài cǐ pāi zhào。', example_vietnamese = 'Xin đừng chụp ảnh ở đây.' WHERE level = 'B2' AND hanzi = '勿' AND pinyin = 'wù' AND vietnamese = 'chớ, đừng, không nên';
UPDATE public.dictionary_words SET example_hanzi = '他對物理很有興趣，將來想當科學家。', example_pinyin = 'tā duì wù lǐ hěn yǒu xìng qù, jiāng lái xiǎng dāng kē xué jiā。', example_vietnamese = 'Anh ấy rất hứng thú với vật lý, tương lai muốn làm nhà khoa học.' WHERE level = 'B2' AND hanzi = '物理' AND pinyin = 'wùlĭ' AND vietnamese = 'vật lý';
UPDATE public.dictionary_words SET example_hanzi = '現代人生活富裕，不只追求物質上的滿足。', example_pinyin = 'xiàn dài rén shēng huó fù yù, bù zhǐ zhuī qiú wù zhí shàng de mǎn zú。', example_vietnamese = 'Người hiện đại sống sung túc, không chỉ theo đuổi sự thỏa mãn về vật chất.' WHERE level = 'B2' AND hanzi = '物質' AND pinyin = 'wùzhí' AND vietnamese = 'vật chất';
UPDATE public.dictionary_words SET example_hanzi = '他誤把鹽當成糖加進咖啡裡。', example_pinyin = 'tā wù bǎ yán dāng chéng táng jiā jìn kā fēi lǐ。', example_vietnamese = 'Anh ấy nhầm cho muối vào cà phê tưởng là đường.' WHERE level = 'B2' AND hanzi = '誤' AND pinyin = 'wù' AND vietnamese = 'lầm, sai';
UPDATE public.dictionary_words SET example_hanzi = '這個決定誤了公司的商機。', example_pinyin = 'zhè ge jué dìng wù le gōng sī de shāng jī。', example_vietnamese = 'Quyết định này đã làm lỡ cơ hội kinh doanh của công ty.' WHERE level = 'B2' AND hanzi = '誤' AND pinyin = 'wù' AND vietnamese = 'lỡ tay';
UPDATE public.dictionary_words SET example_hanzi = '因為天氣不好，班機誤點了兩個小時。', example_pinyin = 'yīn wèi tiān qì bù hǎo, bān jī wù diǎn le liǎng gè xiǎo shí。', example_vietnamese = 'Vì thời tiết xấu, chuyến bay trễ giờ mất hai tiếng.' WHERE level = 'B2' AND hanzi = '誤點' AND pinyin = 'wùdiăn' AND vietnamese = 'trễ giờ';
UPDATE public.dictionary_words SET example_hanzi = '你誤會我的意思了，我不是那個意思。', example_pinyin = 'nǐ wù huì wǒ de yì si le, wǒ bú shì nà ge yì si。', example_vietnamese = 'Bạn hiểu lầm ý tôi rồi, tôi không có ý đó.' WHERE level = 'B2' AND hanzi = '誤會' AND pinyin = 'wùhuì' AND vietnamese = 'hiểu lầm';
UPDATE public.dictionary_words SET example_hanzi = '今天早上霧很大，能見度很低。', example_pinyin = 'jīn tiān zǎo shang wù hěn dà, néng jiàn dù hěn dī。', example_vietnamese = 'Sáng nay sương mù dày đặc, tầm nhìn rất thấp.' WHERE level = 'B2' AND hanzi = '霧' AND pinyin = 'wù' AND vietnamese = 'sương mù';
UPDATE public.dictionary_words SET example_hanzi = '他穿著一套深色西裝去面試。', example_pinyin = 'tā chuān zhe yí tào shēn sè xī zhuāng qù miàn shì。', example_vietnamese = 'Anh ấy mặc một bộ com-lê màu tối đi phỏng vấn.' WHERE level = 'B2' AND hanzi = '西裝' AND pinyin = 'xīzhuāng' AND vietnamese = 'âu phục';
UPDATE public.dictionary_words SET example_hanzi = '深深吸一口氣，你會覺得比較放鬆。', example_pinyin = 'shēn shēn xī yì kǒu qì, nǐ huì jué de bǐ jiào fàng sōng。', example_vietnamese = 'Hít thật sâu một hơi, bạn sẽ cảm thấy thư giãn hơn.' WHERE level = 'B2' AND hanzi = '吸' AND pinyin = 'xī' AND vietnamese = 'hút, hít';
UPDATE public.dictionary_words SET example_hanzi = '我們應該從失敗中吸取教訓。', example_pinyin = 'wǒ men yīng gāi cóng shī bài zhōng xī qǔ jiào xùn。', example_vietnamese = 'Chúng ta nên rút ra bài học từ thất bại.' WHERE level = 'B2' AND hanzi = '吸取' AND pinyin = 'xīqŭ' AND vietnamese = 'rút ra, hấp thụ';
UPDATE public.dictionary_words SET example_hanzi = '吸食毒品會嚴重傷害身體。', example_pinyin = 'xī shí dú pǐn huì yán zhòng shāng hài shēn tǐ。', example_vietnamese = 'Hút chích ma túy sẽ gây tổn hại nghiêm trọng đến cơ thể.' WHERE level = 'B2' AND hanzi = '吸食' AND pinyin = 'xīshí' AND vietnamese = 'hút, húp';
UPDATE public.dictionary_words SET example_hanzi = '這裡是公共場所，禁止吸菸。', example_pinyin = 'zhè lǐ shì gōng gòng chǎng suǒ, jìn zhǐ xī yān。', example_vietnamese = 'Đây là nơi công cộng, cấm hút thuốc.' WHERE level = 'B2' AND hanzi = '吸菸' AND pinyin = 'xīyān' AND vietnamese = 'hút thuốc';
UPDATE public.dictionary_words SET example_hanzi = '婆婆對這個媳婦非常滿意。', example_pinyin = 'pó po duì zhè ge xí fù fēi cháng mǎn yì。', example_vietnamese = 'Mẹ chồng rất hài lòng về cô con dâu này.' WHERE level = 'B2' AND hanzi = '媳婦' AND pinyin = 'xífù' AND vietnamese = 'con dâu';
UPDATE public.dictionary_words SET example_hanzi = '下個月我要去喝朋友的喜酒。', example_pinyin = 'xià ge yuè wǒ yào qù hē péng you de xǐ jiǔ。', example_vietnamese = 'Tháng sau tôi phải đi dự rượu cưới của bạn.' WHERE level = 'B2' AND hanzi = '喜酒' AND pinyin = 'xĭjiŭ' AND vietnamese = 'rượu cưới';
UPDATE public.dictionary_words SET example_hanzi = '這部喜劇電影讓全場笑個不停。', example_pinyin = 'zhè bù xǐ jù diàn yǐng ràng quán chǎng xiào ge bù tíng。', example_vietnamese = 'Bộ phim hài này khiến cả rạp cười không ngớt.' WHERE level = 'B2' AND hanzi = '喜劇' AND pinyin = 'xǐjù' AND vietnamese = 'hài kịch';
UPDATE public.dictionary_words SET example_hanzi = '這是這位作家最新出版的系列小說。', example_pinyin = 'zhè shì zhè wèi zuò jiā zuì xīn chū bǎn de xì liè xiǎo shuō。', example_vietnamese = 'Đây là bộ tiểu thuyết theo series mới nhất mà nhà văn này xuất bản.' WHERE level = 'B2' AND hanzi = '系列' AND pinyin = 'xìliè' AND vietnamese = 'hàng loạt';
UPDATE public.dictionary_words SET example_hanzi = '人體是由無數個細胞組成的。', example_pinyin = 'rén tǐ shì yóu wú shù gè xì bāo zǔ chéng de。', example_vietnamese = 'Cơ thể con người được cấu thành từ vô số tế bào.' WHERE level = 'B2' AND hanzi = '細胞' AND pinyin = 'xìbāo' AND vietnamese = 'tế bào';
UPDATE public.dictionary_words SET example_hanzi = '簽合約之前要仔細確認每一個細節。', example_pinyin = 'qiān hé yuē zhī qián yào zǐ xì què rèn měi yí gè xì jié。', example_vietnamese = 'Trước khi ký hợp đồng phải xác nhận kỹ từng chi tiết.' WHERE level = 'B2' AND hanzi = '細節' AND pinyin = 'xìjié' AND vietnamese = 'tình tiết, chi tiết';
UPDATE public.dictionary_words SET example_hanzi = '洗手可以有效減少細菌感染。', example_pinyin = 'xǐ shǒu kě yǐ yǒu xiào jiǎn shǎo xì jùn gǎn rǎn。', example_vietnamese = 'Rửa tay có thể giảm hiệu quả sự lây nhiễm vi khuẩn.' WHERE level = 'B2' AND hanzi = '細菌' AND pinyin = 'xìjùn' AND vietnamese = 'vi trùng';
UPDATE public.dictionary_words SET example_hanzi = '這些細小的差異一般人很難發現。', example_pinyin = 'zhè xiē xì xiǎo de chā yì yì bān rén hěn nán fā xiàn。', example_vietnamese = 'Những khác biệt nhỏ bé này người bình thường rất khó phát hiện.' WHERE level = 'B2' AND hanzi = '細小' AND pinyin = 'xìxiăo' AND vietnamese = 'nhỏ bé';
UPDATE public.dictionary_words SET example_hanzi = '他因為一場意外而瞎了一隻眼睛。', example_pinyin = 'tā yīn wèi yì chǎng yì wài ér xiā le yì zhī yǎn jing。', example_vietnamese = 'Anh ấy bị mù một mắt vì một tai nạn.' WHERE level = 'B2' AND hanzi = '瞎' AND pinyin = 'xiā' AND vietnamese = 'mù lòa';
UPDATE public.dictionary_words SET example_hanzi = '這道菜用新鮮的蝦子做的，很好吃。', example_pinyin = 'zhè dào cài yòng xīn xiān de xiā zi zuò de, hěn hǎo chī。', example_vietnamese = 'Món ăn này được làm từ tôm tươi, rất ngon.' WHERE level = 'B2' AND hanzi = '蝦(子)' AND pinyin = 'xiā(zi)' AND vietnamese = 'con cóc';
UPDATE public.dictionary_words SET example_hanzi = '媽媽用蝦米和高麗菜炒了一道菜。', example_pinyin = 'mā ma yòng xiā mǐ hàn gāo lì cài chǎo le yí dào cài。', example_vietnamese = 'Mẹ dùng tôm khô và bắp cải xào một món ăn.' WHERE level = 'B2' AND hanzi = '蝦米' AND pinyin = 'xiāmi' AND vietnamese = 'tôm nhỏ, tép';
UPDATE public.dictionary_words SET example_hanzi = '他想事情的時候習慣摸下巴。', example_pinyin = 'tā xiǎng shì qing de shí hou xí guàn mō xià ba。', example_vietnamese = 'Khi suy nghĩ, anh ấy có thói quen sờ cằm.' WHERE level = 'B2' AND hanzi = '下巴' AND pinyin = 'xiàba' AND vietnamese = 'cằm, hàm';
UPDATE public.dictionary_words SET example_hanzi = '最近氣溫明顯下降了許多。', example_pinyin = 'zuì jìn qì wēn míng xiǎn xià jiàng le xǔ duō。', example_vietnamese = 'Gần đây nhiệt độ đã giảm xuống rõ rệt.' WHERE level = 'B2' AND hanzi = '下降' AND pinyin = 'xiàjiàng' AND vietnamese = 'hạ thấp';
UPDATE public.dictionary_words SET example_hanzi = '貓從樹上慢慢爬了下來。', example_pinyin = 'māo cóng shù shàng màn màn pá le xià lái。', example_vietnamese = 'Con mèo từ từ bò xuống từ trên cây.' WHERE level = 'B2' AND hanzi = '下來' AND pinyin = 'xiàlái' AND vietnamese = 'xuống';
UPDATE public.dictionary_words SET example_hanzi = '爺爺每天下午都跟鄰居下棋。', example_pinyin = 'yé ye měi tiān xià wǔ dōu gēn lín jū xià qí。', example_vietnamese = 'Ông nội mỗi buổi chiều đều chơi cờ với hàng xóm.' WHERE level = 'B2' AND hanzi = '下棋' AND pinyin = 'xiàqí' AND vietnamese = 'chơi cờ, đánh cờ';
UPDATE public.dictionary_words SET example_hanzi = '雖然很累，但他還是堅持跑下去。', example_pinyin = 'suī rán hěn lèi, dàn tā hái shi jiān chí pǎo xià qu。', example_vietnamese = 'Tuy rất mệt nhưng anh ấy vẫn kiên trì chạy tiếp.' WHERE level = 'B2' AND hanzi = '下去' AND pinyin = 'xiàqu' AND vietnamese = 'xuống phía dưới';
UPDATE public.dictionary_words SET example_hanzi = '我們約三點一起喝下午茶。', example_pinyin = 'wǒ men yuē sān diǎn yì qǐ hē xià wǔ chá。', example_vietnamese = 'Chúng tôi hẹn ba giờ cùng nhau uống trà chiều.' WHERE level = 'B2' AND hanzi = '下午茶' AND pinyin = 'xiàwŭchá' AND vietnamese = 'trà chiều';
UPDATE public.dictionary_words SET example_hanzi = '這條河的下游水質比較混濁。', example_pinyin = 'zhè tiáo hé de xià yóu shuǐ zhì bǐ jiào hún zhuó。', example_vietnamese = 'Chất lượng nước ở hạ lưu con sông này khá đục.' WHERE level = 'B2' AND hanzi = '下游' AND pinyin = 'xiàyóu' AND vietnamese = 'hạ lưu';
UPDATE public.dictionary_words SET example_hanzi = '夏季的台灣又熱又潮濕。', example_pinyin = 'xià jì de tái wān yòu rè yòu cháo shī。', example_vietnamese = 'Mùa hè ở Đài Loan vừa nóng vừa ẩm.' WHERE level = 'B2' AND hanzi = '夏季' AND pinyin = 'xiàjì' AND vietnamese = 'mùa hè';
UPDATE public.dictionary_words SET example_hanzi = '這家醫院的醫療設備非常先進。', example_pinyin = 'zhè jiā yī yuàn de yī liáo shè bèi fēi cháng xiān jìn。', example_vietnamese = 'Thiết bị y tế của bệnh viện này rất tiên tiến.' WHERE level = 'B2' AND hanzi = '先進' AND pinyin = 'xiānjìn' AND vietnamese = 'tiên tiến';
UPDATE public.dictionary_words SET example_hanzi = '這種情況鮮少發生。', example_pinyin = 'zhè zhǒng qíng kuàng xiān shǎo fā shēng。', example_vietnamese = 'Tình huống như thế này hiếm khi xảy ra.' WHERE level = 'B2' AND hanzi = '鮮' AND pinyin = 'xiān' AND vietnamese = 'ít, hiếm';
UPDATE public.dictionary_words SET example_hanzi = '他送了一束鮮花給女朋友。', example_pinyin = 'tā sòng le yí shù xiān huā gěi nǚ péng you。', example_vietnamese = 'Anh ấy tặng một bó hoa tươi cho bạn gái.' WHERE level = 'B2' AND hanzi = '鮮花' AND pinyin = 'xiānhuā' AND vietnamese = 'hoa tươi';
UPDATE public.dictionary_words SET example_hanzi = '我每天早上都喝一杯鮮奶。', example_pinyin = 'wǒ měi tiān zǎo shang dōu hē yì bēi xiān nǎi。', example_vietnamese = 'Mỗi sáng tôi đều uống một ly sữa tươi.' WHERE level = 'B2' AND hanzi = '鮮奶' AND pinyin = 'xiānnăi' AND vietnamese = 'sữa tươi';
UPDATE public.dictionary_words SET example_hanzi = '傷口不斷流出鮮血，必須馬上止血。', example_pinyin = 'shāng kǒu bú duàn liú chū xiān xiě, bì xū mǎ shàng zhǐ xuè。', example_vietnamese = 'Vết thương không ngừng chảy máu tươi, phải cầm máu ngay lập tức.' WHERE level = 'B2' AND hanzi = '鮮血' AND pinyin = 'xiānxiě' AND vietnamese = 'máu tươi';
UPDATE public.dictionary_words SET example_hanzi = '退休以後，他每天都很閒。', example_pinyin = 'tuì xiū yǐ hòu, tā měi tiān dōu hěn xián。', example_vietnamese = 'Sau khi nghỉ hưu, mỗi ngày anh ấy đều rất rảnh rỗi.' WHERE level = 'B2' AND hanzi = '閒' AND pinyin = 'xián' AND vietnamese = 'nhàn, rỗi';
UPDATE public.dictionary_words SET example_hanzi = '她嫌這件衣服太貴，沒有買。', example_pinyin = 'tā xián zhè jiàn yī fu tài guì, méi yǒu mǎi。', example_vietnamese = 'Cô ấy chê chiếc áo này quá đắt nên không mua.' WHERE level = 'B2' AND hanzi = '嫌' AND pinyin = 'xián' AND vietnamese = 'nghi ngờ';
UPDATE public.dictionary_words SET example_hanzi = '聽到這個消息，他顯得特別緊張。', example_pinyin = 'tīng dào zhè ge xiāo xi, tā xiǎn de tè bié jǐn zhāng。', example_vietnamese = 'Nghe được tin này, anh ấy tỏ ra đặc biệt căng thẳng.' WHERE level = 'B2' AND hanzi = '顯得' AND pinyin = 'xiănde' AND vietnamese = 'lộ ra';
UPDATE public.dictionary_words SET example_hanzi = '顯然，他對這個結果並不滿意。', example_pinyin = 'xiǎn rán, tā duì zhè ge jié guǒ bìng bù mǎn yì。', example_vietnamese = 'Rõ ràng là anh ấy không hài lòng với kết quả này.' WHERE level = 'B2' AND hanzi = '顯然' AND pinyin = 'xiănrán' AND vietnamese = 'hiển nhiên';
UPDATE public.dictionary_words SET example_hanzi = '研究結果顯示，運動有助於改善睡眠。', example_pinyin = 'yán jiū jié guǒ xiǎn shì, yùn dòng yǒu zhù yú gǎi shàn shuì mián。', example_vietnamese = 'Kết quả nghiên cứu cho thấy vận động giúp cải thiện giấc ngủ.' WHERE level = 'B2' AND hanzi = '顯示' AND pinyin = 'xiănshì' AND vietnamese = 'biểu thị, tỏ ra';
UPDATE public.dictionary_words SET example_hanzi = '這種藥對治療感冒有顯著的效果。', example_pinyin = 'zhè zhǒng yào duì zhì liáo gǎn mào yǒu xiǎn zhù de xiào guǒ。', example_vietnamese = 'Loại thuốc này có hiệu quả rõ rệt trong việc điều trị cảm cúm.' WHERE level = 'B2' AND hanzi = '顯著' AND pinyin = 'xiănzhù' AND vietnamese = 'hiển thị';
UPDATE public.dictionary_words SET example_hanzi = '這位教授現任該系的系主任。', example_pinyin = 'zhè wèi jiào shòu xiàn rèn gāi xì de xì zhǔ rèn。', example_vietnamese = 'Vị giáo sư này hiện đang giữ chức trưởng khoa của khoa đó.' WHERE level = 'B2' AND hanzi = '現' AND pinyin = 'xiàn' AND vietnamese = 'hiện nay';
UPDATE public.dictionary_words SET example_hanzi = '警察很快就趕到車禍現場。', example_pinyin = 'jǐng chá hěn kuài jiù gǎn dào chē huò xiàn chǎng。', example_vietnamese = 'Cảnh sát nhanh chóng đến hiện trường vụ tai nạn xe.' WHERE level = 'B2' AND hanzi = '現場' AND pinyin = 'xiànchăng' AND vietnamese = 'hiện trường';
UPDATE public.dictionary_words SET example_hanzi = '家裡剛好有現成的材料，可以馬上煮飯。', example_pinyin = 'jiā lǐ gāng hǎo yǒu xiàn chéng de cái liào, kě yǐ mǎ shàng zhǔ fàn。', example_vietnamese = 'Trong nhà vừa hay có sẵn nguyên liệu, có thể nấu cơm ngay.' WHERE level = 'B2' AND hanzi = '現成' AND pinyin = 'xiànchéng' AND vietnamese = 'sẵn có';
UPDATE public.dictionary_words SET example_hanzi = '這家店只收現金，不能刷卡。', example_pinyin = 'zhè jiā diàn zhǐ shōu xiàn jīn, bù néng shuā kǎ。', example_vietnamese = 'Cửa hàng này chỉ nhận tiền mặt, không quẹt thẻ được.' WHERE level = 'B2' AND hanzi = '現金' AND pinyin = 'xiànjīn' AND vietnamese = 'tiền mặt';
UPDATE public.dictionary_words SET example_hanzi = '我很羨慕他能說五種語言。', example_pinyin = 'wǒ hěn xiàn mù tā néng shuō wǔ zhǒng yǔ yán。', example_vietnamese = 'Tôi rất ngưỡng mộ việc anh ấy có thể nói được năm thứ tiếng.' WHERE level = 'B2' AND hanzi = '羨慕' AND pinyin = 'xiànmù' AND vietnamese = 'hâm mộ';
UPDATE public.dictionary_words SET example_hanzi = '這個停車場限制車輛高度不能超過兩公尺。', example_pinyin = 'zhè ge tíng chē chǎng xiàn zhì chē liàng gāo dù bù néng chāo guò liǎng gōng chǐ。', example_vietnamese = 'Bãi đỗ xe này hạn chế chiều cao xe không được vượt quá hai mét.' WHERE level = 'B2' AND hanzi = '限制' AND pinyin = 'xiànzhì' AND vietnamese = 'hạn chế';
UPDATE public.dictionary_words SET example_hanzi = '這對老夫妻相伴走過五十年。', example_pinyin = 'zhè duì lǎo fū qī xiāng bàn zǒu guò wǔ shí nián。', example_vietnamese = 'Cặp vợ chồng già này đã cùng nhau sát cánh đi qua năm mươi năm.' WHERE level = 'B2' AND hanzi = '相' AND pinyin = 'xiāng' AND vietnamese = 'lẫn nhau, cùng nhau';
UPDATE public.dictionary_words SET example_hanzi = '我跟室友相處得很融洽。', example_pinyin = 'wǒ gēn shì yǒu xiāng chǔ de hěn róng qià。', example_vietnamese = 'Tôi sống chung với bạn cùng phòng rất hòa hợp.' WHERE level = 'B2' AND hanzi = '相處' AND pinyin = 'xiāngchŭ' AND vietnamese = 'sống chung với nhau';
UPDATE public.dictionary_words SET example_hanzi = '這次考試的難度相當高。', example_pinyin = 'zhè cì kǎo shì de nán dù xiāng dāng gāo。', example_vietnamese = 'Độ khó của kỳ thi lần này khá cao.' WHERE level = 'B2' AND hanzi = '相當' AND pinyin = 'xiāngdāng' AND vietnamese = 'tương đương';
UPDATE public.dictionary_words SET example_hanzi = '團隊合作需要相互信任。', example_pinyin = 'tuán duì hé zuò xū yào xiāng hù xìn rèn。', example_vietnamese = 'Làm việc nhóm cần có sự tin tưởng lẫn nhau.' WHERE level = 'B2' AND hanzi = '相互' AND pinyin = 'xiānghù' AND vietnamese = 'lẫn nhau';
UPDATE public.dictionary_words SET example_hanzi = '這一家人相親相愛，感情非常好。', example_pinyin = 'zhè yì jiā rén xiāng qīn xiāng ài, gǎn qíng fēi cháng hǎo。', example_vietnamese = 'Gia đình này yêu thương nhau, tình cảm rất tốt.' WHERE level = 'B2' AND hanzi = '相親相愛' AND pinyin = 'xiāngqīnxiāngài' AND vietnamese = 'tương thân tương ái';
UPDATE public.dictionary_words SET example_hanzi = '這對雙胞胎長得非常相似。', example_pinyin = 'zhè duì shuāng bāo tāi zhǎng de fēi cháng xiāng sì。', example_vietnamese = 'Cặp song sinh này trông rất giống nhau.' WHERE level = 'B2' AND hanzi = '相似' AND pinyin = 'xiāngsì' AND vietnamese = 'tương tự';
UPDATE public.dictionary_words SET example_hanzi = '他訂了一箱蘋果，準備送給朋友。', example_pinyin = 'tā dìng le yì xiāng píng guǒ, zhǔn bèi sòng gěi péng you。', example_vietnamese = 'Anh ấy đặt một thùng táo, chuẩn bị tặng cho bạn bè.' WHERE level = 'B2' AND hanzi = '箱' AND pinyin = 'xiāng' AND vietnamese = 'rương, hòm';
UPDATE public.dictionary_words SET example_hanzi = '夜市裡烤香腸的味道讓人忍不住想吃。', example_pinyin = 'yè shì lǐ kǎo xiāng cháng de wèi dào ràng rén rěn bú zhù xiǎng chī。', example_vietnamese = 'Mùi xúc xích nướng ở chợ đêm khiến người ta không kìm được muốn ăn.' WHERE level = 'B2' AND hanzi = '香腸' AND pinyin = 'xiāngcháng' AND vietnamese = 'lạp xưởng';
UPDATE public.dictionary_words SET example_hanzi = '他退休後搬到鄉村過悠閒的生活。', example_pinyin = 'tā tuì xiū hòu bān dào xiāng cūn guò yōu xián de shēng huó。', example_vietnamese = 'Sau khi nghỉ hưu, anh ấy chuyển về nông thôn sống cuộc sống thong thả.' WHERE level = 'B2' AND hanzi = '鄉村' AND pinyin = 'xiāngcūn' AND vietnamese = 'nông thôn';
UPDATE public.dictionary_words SET example_hanzi = '想不到我們會在這種場合重逢。', example_pinyin = 'xiǎng bu dào wǒ men huì zài zhè zhǒng chǎng hé chóng féng。', example_vietnamese = 'Không ngờ chúng ta lại gặp lại nhau trong hoàn cảnh như thế này.' WHERE level = 'B2' AND hanzi = '想不到' AND pinyin = 'xiăngbudào' AND vietnamese = 'không ngờ tới';
UPDATE public.dictionary_words SET example_hanzi = '出國留學後，他很想念家鄉的味道。', example_pinyin = 'chū guó liú xué hòu, tā hěn xiǎng niàn jiā xiāng de wèi dào。', example_vietnamese = 'Sau khi ra nước ngoài du học, anh ấy rất nhớ hương vị quê nhà.' WHERE level = 'B2' AND hanzi = '想念' AND pinyin = 'xiăngniàn' AND vietnamese = 'tưởng niệm, nhớ nhung';
UPDATE public.dictionary_words SET example_hanzi = '週末我喜歡待在家裡享受安靜的時光。', example_pinyin = 'zhōu mò wǒ xǐ huan dāi zài jiā lǐ xiǎng shòu ān jìng de shí guāng。', example_vietnamese = 'Cuối tuần tôi thích ở nhà tận hưởng khoảng thời gian yên tĩnh.' WHERE level = 'B2' AND hanzi = '享受' AND pinyin = 'xiăngshòu' AND vietnamese = 'hưởng thụ, tận hưởng';
UPDATE public.dictionary_words SET example_hanzi = '正式員工可以享有完整的福利。', example_pinyin = 'zhèng shì yuán gōng kě yǐ xiǎng yǒu wán zhěng de fú lì。', example_vietnamese = 'Nhân viên chính thức có thể được hưởng đầy đủ phúc lợi.' WHERE level = 'B2' AND hanzi = '享有' AND pinyin = 'xiăngyŏu' AND vietnamese = 'được hưởng (quyền lợi…)';
UPDATE public.dictionary_words SET example_hanzi = '許多民眾響應政府的節能政策。', example_pinyin = 'xǔ duō mín zhòng xiǎng yìng zhèng fǔ de jié néng zhèng cè。', example_vietnamese = 'Rất nhiều người dân hưởng ứng chính sách tiết kiệm năng lượng của chính phủ.' WHERE level = 'B2' AND hanzi = '響應' AND pinyin = 'xiăngyìng' AND vietnamese = 'hưởng ứng';
UPDATE public.dictionary_words SET example_hanzi = '動物園裡有兩隻大象。', example_pinyin = 'dòng wù yuán lǐ yǒu liǎng zhī dà xiàng。', example_vietnamese = 'Trong sở thú có hai con voi.' WHERE level = 'B2' AND hanzi = '象' AND pinyin = 'xiàng' AND vietnamese = 'con voi';
UPDATE public.dictionary_words SET example_hanzi = '這張相片是我們全家去年出遊時拍的。', example_pinyin = 'zhè zhāng xiàng piàn shì wǒ men quán jiā qù nián chū yóu shí pāi de。', example_vietnamese = 'Tấm ảnh này là chụp lúc cả gia đình tôi đi chơi năm ngoái.' WHERE level = 'B2' AND hanzi = '相片/相片兒' AND pinyin = 'xiàngpiàn/xiàngpi' AND vietnamese = 'ảnh chụp (người)';
UPDATE public.dictionary_words SET example_hanzi = '媽媽一直安排我去相親。', example_pinyin = 'mā ma yì zhí ān pái wǒ qù xiàng qīn。', example_vietnamese = 'Mẹ cứ liên tục sắp xếp cho tôi đi xem mắt.' WHERE level = 'B2' AND hanzi = '相親' AND pinyin = 'xiàngqīn' AND vietnamese = 'gặp mặt, xem mắt';
UPDATE public.dictionary_words SET example_hanzi = '他家就住在這條巷子裡。', example_pinyin = 'tā jiā jiù zhù zài zhè tiáo xiàng zi lǐ。', example_vietnamese = 'Nhà anh ấy chính là nằm trong con hẻm này.' WHERE level = 'B2' AND hanzi = '巷(子)' AND pinyin = 'xiàng(zi)' AND vietnamese = 'ngõ, hẻm';
UPDATE public.dictionary_words SET example_hanzi = '他向來準時，今天遲到一定有原因。', example_pinyin = 'tā xiàng lái zhǔn shí, jīn tiān chí dào yí dìng yǒu yuán yīn。', example_vietnamese = 'Anh ấy từ trước đến nay luôn đúng giờ, hôm nay trễ chắc chắn có lý do.' WHERE level = 'B2' AND hanzi = '向來' AND pinyin = 'xiànglái' AND vietnamese = 'từ trước đến nay';
UPDATE public.dictionary_words SET example_hanzi = '公司最近在進行一個新的開發項目。', example_pinyin = 'gōng sī zuì jìn zài jìn xíng yí gè xīn de kāi fā xiàng mù。', example_vietnamese = 'Gần đây công ty đang triển khai một dự án phát triển mới.' WHERE level = 'B2' AND hanzi = '項目' AND pinyin = 'xiàngmù' AND vietnamese = 'hạng mục';
UPDATE public.dictionary_words SET example_hanzi = '他的怒氣過了一會兒就消了。', example_pinyin = 'tā de nù qì guò le yí huìr jiù xiāo le。', example_vietnamese = 'Cơn giận của anh ấy qua một lúc thì tan biến.' WHERE level = 'B2' AND hanzi = '消' AND pinyin = 'xiāo' AND vietnamese = 'biến mất';
UPDATE public.dictionary_words SET example_hanzi = '運動可以有效消除壓力。', example_pinyin = 'yùn dòng kě yǐ yǒu xiào xiāo chú yā lì。', example_vietnamese = 'Vận động có thể xóa bỏ áp lực một cách hiệu quả.' WHERE level = 'B2' AND hanzi = '消除' AND pinyin = 'xiāochú' AND vietnamese = 'trừ khử';
UPDATE public.dictionary_words SET example_hanzi = '這個城市的消費水準比較高。', example_pinyin = 'zhè ge chéng shì de xiāo fèi shuǐ zhǔn bǐ jiào gāo。', example_vietnamese = 'Mức chi tiêu ở thành phố này khá cao.' WHERE level = 'B2' AND hanzi = '消費' AND pinyin = 'xiāofèi' AND vietnamese = 'chi phí';
UPDATE public.dictionary_words SET example_hanzi = '越來越多人選擇在網路上消費。', example_pinyin = 'yuè lái yuè duō rén xuǎn zé zài wǎng lù shàng xiāo fèi。', example_vietnamese = 'Ngày càng có nhiều người chọn tiêu dùng trên mạng.' WHERE level = 'B2' AND hanzi = '消費' AND pinyin = 'xiāofèi' AND vietnamese = 'tiêu dùng';
UPDATE public.dictionary_words SET example_hanzi = '吃太快容易造成消化不良。', example_pinyin = 'chī tài kuài róng yì zào chéng xiāo huà bù liáng。', example_vietnamese = 'Ăn quá nhanh dễ gây ra khó tiêu.' WHERE level = 'B2' AND hanzi = '消化' AND pinyin = 'xiāohuà' AND vietnamese = 'tiêu hóa';
UPDATE public.dictionary_words SET example_hanzi = '失敗後他變得很消極，不想再嘗試。', example_pinyin = 'shī bài hòu tā biàn de hěn xiāo jí, bù xiǎng zài cháng shì。', example_vietnamese = 'Sau khi thất bại, anh ấy trở nên tiêu cực, không muốn thử lại nữa.' WHERE level = 'B2' AND hanzi = '消極' AND pinyin = 'xiāojí' AND vietnamese = 'tiêu cực';
UPDATE public.dictionary_words SET example_hanzi = '醫生用藥物消滅體內的病菌。', example_pinyin = 'yī shēng yòng yào wù xiāo miè tǐ nèi de bìng jūn。', example_vietnamese = 'Bác sĩ dùng thuốc tiêu diệt vi khuẩn gây bệnh trong cơ thể.' WHERE level = 'B2' AND hanzi = '消滅' AND pinyin = 'xiāomiè' AND vietnamese = 'tiêu diệt';
UPDATE public.dictionary_words SET example_hanzi = '那隻貓突然消失在巷子裡，再也沒出現過。', example_pinyin = 'nà zhī māo tú rán xiāo shī zài xiàng zi lǐ, zài yě méi chū xiàn guò。', example_vietnamese = 'Con mèo đó đột nhiên biến mất trong con hẻm, không bao giờ xuất hiện lại nữa.' WHERE level = 'B2' AND hanzi = '消失' AND pinyin = 'xiāoshī' AND vietnamese = 'tan biến';
UPDATE public.dictionary_words SET example_hanzi = '我們半夜肚子餓，決定出去吃宵夜。', example_pinyin = 'wǒ men bàn yè dù zi è, jué dìng chū qù chī xiāo yè。', example_vietnamese = 'Nửa đêm chúng tôi đói bụng, quyết định ra ngoài ăn đồ khuya.' WHERE level = 'B2' AND hanzi = '消/宵夜' AND pinyin = 'xiāoyè' AND vietnamese = 'đồ ăn khuya';
UPDATE public.dictionary_words SET example_hanzi = '這款新產品上市後銷路很好。', example_pinyin = 'zhè kuǎn xīn chǎn pǐn shàng shì hòu xiāo lù hěn hǎo。', example_vietnamese = 'Sản phẩm mới này sau khi ra mắt có đầu ra tiêu thụ rất tốt.' WHERE level = 'B2' AND hanzi = '銷路' AND pinyin = 'xiāolù' AND vietnamese = 'nguồn tiêu thụ';
UPDATE public.dictionary_words SET example_hanzi = '這家公司主要銷售電子產品。', example_pinyin = 'zhè jiā gōng sī zhǔ yào xiāo shòu diàn zǐ chǎn pǐn。', example_vietnamese = 'Công ty này chủ yếu bán các sản phẩm điện tử.' WHERE level = 'B2' AND hanzi = '銷售' AND pinyin = 'xiāoshòu' AND vietnamese = 'tiêu thụ';
UPDATE public.dictionary_words SET example_hanzi = '小朋友舉手說他想上廁所小便。', example_pinyin = 'xiǎo péng you jǔ shǒu shuō tā xiǎng shàng cè suǒ xiǎo biàn。', example_vietnamese = 'Đứa trẻ giơ tay nói nó muốn đi vệ sinh tiểu tiện.' WHERE level = 'B2' AND hanzi = '小便' AND pinyin = 'xiăobiàn' AND vietnamese = 'tiểu tiện';